window.THEME_LABELS = {"kutiamoyo": "Kutia moyo", "shukrani": "Shukrani", "baraka": "Baraka", "faraja": "Faraja", "upendo": "Upendo", "furaha": "Furaha", "amani": "Amani", "uvumilivu": "Uvumilivu", "utuwema": "Utu wema", "uaminifu": "Uaminifu", "upole": "Upole", "kiasi": "Kiasi", "imani": "Imani", "tumaini": "Tumaini", "usalama": "Usalama"};
window.VERSES = {"kutiamoyo": [{"r": "Wagalatia 6:9", "t": "Tena tusichoke katika kutenda mema; maana tutavuna kwa wakati wake, tusipozimia roho."}, {"r": "Mathayo 19:26", "t": "Yesu akawakazia macho, akawaambia, Kwa wanadamu hilo haliwezekani; bali kwa Mungu yote yawezekana."}, {"r": "Waefeso 3:20", "t": "Basi atukuzwe yeye awezaye kufanya mambo ya ajabu mno kuliko yote tuyaombayo au tuyawazayo, kwa kadiri ya nguvu itendayo kazi ndani yetu;"}, {"r": "Zaburi 55:22", "t": "Umtwike Bwana mzigo wako naye atakutegemeza, Hatamwacha mwenye haki aondoshwe milele."}, {"r": "Zaburi 34:18", "t": "Bwana yu karibu nao waliovunjika moyo, Na waliopondeka roho huwaokoa."}, {"r": "Waefeso 6:10", "t": "Hatimaye, mzidi kuwa hodari katika Bwana na katika uweza wa nguvu zake."}, {"r": "Waebrania 4:16", "t": "Basi na tukikaribie kiti cha neema kwa ujasiri, ili tupewe rehema, na kupata neema ya kutusaidia wakati wa mahitaji."}, {"r": "Mithali 27:17", "t": "Chuma hunoa chuma; Ndivyo mtu aunoavyo uso wa rafiki yake."}, {"r": "Waebrania 10:24", "t": "tukaangaliane sisi kwa sisi na kuhimizana katika upendo na kazi nzuri;"}, {"r": "Mhubiri 4:9", "t": "Afadhali kuwa wawili kuliko mmoja; Maana wapata ijara njema kwa kazi yao."}, {"r": "Zaburi 27:14", "t": "Umngoje Bwana, uwe hodari, Upige moyo konde, naam, umngoje Bwana."}, {"r": "Wafilipi 1:6", "t": "Nami niliaminilo ndilo hili, ya kwamba yeye aliyeanza kazi njema mioyoni mwenu ataimaliza hata siku ya Kristo Yesu;"}, {"r": "Mithali 18:21", "t": "Mauti na uzima huwa katika uwezo wa ulimi; Na wao waupendao watakula matunda yake."}, {"r": "1 Wakorintho 16:13", "t": "Kesheni, simameni imara katika Imani, fanyeni kiume, mkawe hodari."}, {"r": "Marko 10:27", "t": "Yesu akawakazia macho, akasema, Kwa wanadamu haiwezekani, bali kwa Mungu sivyo; maana yote yawezekana kwa Mungu."}, {"r": "Yoshua 1:9", "t": "Je! Si mimi niliyekuamuru? Uwe hodari na moyo wa ushujaa; usiogope wala usifadhaike; kwa kuwa Bwana, Mungu wako, yu pamoja nawe kila uendako."}, {"r": "Kumbukumbu la Torati 31:6", "t": "Iweni hodari na moyo wa ushujaa, msiogope wala msiwahofu; kwa maana Bwana, Mungu wako, yeye ndiye anayekwenda pamoja nawe, hatakupungukia wala kukuacha."}, {"r": "Mathayo 11:28", "t": "Njoni kwangu, ninyi nyote msumbukao na wenye kulemewa na mizigo, nami nitawapumzisha."}, {"r": "Zaburi 31:24", "t": "Iweni hodari, mpige moyo konde, Ninyi nyote mnaomngoja Bwana."}, {"r": "Luka 1:37", "t": "kwa kuwa hakuna neno lisilowezekana kwa Mungu."}, {"r": "Wakolosai 3:23", "t": "Lo lote mfanyalo, lifanyeni kwa moyo, kama kwa Bwana, wala si kwa wanadamu,"}, {"r": "Mithali 3:6", "t": "Katika njia zako zote mkiri yeye, Naye atayanyosha mapito yako."}, {"r": "1 Petro 5:7", "t": "huku mkimtwika yeye fadhaa zenu zote, kwa maana yeye hujishughulisha sana kwa mambo yenu."}, {"r": "Mithali 3:5", "t": "Mtumaini Bwana kwa moyo wako wote, Wala usizitegemee akili zako mwenyewe;"}, {"r": "2 Wakorintho 4:16", "t": "Kwa hiyo hatulegei; bali ijapokuwa utu wetu wa nje unachakaa, lakini utu wetu wa ndani unafanywa upya siku kwa siku."}, {"r": "Wafilipi 4:13", "t": "Nayaweza mambo yote katika yeye anitiaye nguvu."}, {"r": "Mithali 12:25", "t": "Uzito katika moyo wa mtu huuinamisha; Bali neno jema huufurahisha."}, {"r": "Zaburi 46:1", "t": "Mungu kwetu sisi ni kimbilio na nguvu, Msaada utakaoonekana tele wakati wa mateso."}, {"r": "2 Wakorintho 12:9", "t": "Naye akaniambia, Neema yangu yakutosha; maana uweza wangu hutimilika katika udhaifu. Basi nitajisifia udhaifu wangu kwa furaha nyingi, ili uweza wa Kristo ukae juu yangu."}, {"r": "Mithali 16:24", "t": "Maneno yapendezayo ni kama sega la asali; Ni tamu nafsini, na afya mifupani."}, {"r": "2 Wakorintho 1:4", "t": "atufarijiye katika dhiki zetu zote ili nasi tupate kuwafariji wale walio katika dhiki za namna zote, kwa faraja hizo, tunazofarijiwa na Mungu."}, {"r": "2 Timotheo 1:7", "t": "Maana Mungu hakutupa roho ya woga, bali ya nguvu na ya upendo na ya moyo wa kiasi."}, {"r": "Isaya 40:31", "t": "bali wao wamngojeao Bwana watapata nguvu mpya; watapanda juu kwa mbawa kama tai; watapiga mbio, wala hawatachoka; watakwenda kwa miguu, wala hawatazimia."}, {"r": "2 Wakorintho 1:3", "t": "Na ahimidiwe Mungu, Baba wa Bwana wetu Yesu Kristo, Baba wa rehema, Mungu wa faraja yote;"}, {"r": "Zaburi 147:3", "t": "Huwaponya waliopondeka moyo, Na kuziganga jeraha zao."}, {"r": "Mhubiri 4:10", "t": "Kwa maana wakianguka, mmoja wao atamwinua mwenzake; lakini ole wake aliye peke yake aangukapo, wala hana mwingine wa kumwinua!"}, {"r": "Isaya 41:10", "t": "usiogope, kwa maana mimi ni pamoja nawe; usifadhaike, kwa maana mimi ni Mungu wako; nitakutia nguvu, naam, nitakusaidia, naam, nitakushika kwa mkono wa kuume wa haki yangu."}, {"r": "Waebrania 12:1", "t": "Basi na sisi pia, kwa kuwa tunazungukwa na wingu kubwa la mashahidi namna hii, na tuweke kando kila mzigo mzito, na dhambi ile ituzingayo kwa upesi; na tupige mbio kwa saburi katika yale mashindano yaliyowekwa mbele yetu,"}, {"r": "1 Wathesalonike 5:11", "t": "Basi, farijianeni na kujengana kila mtu na mwenzake, vile vile kama mnavyofanya."}, {"r": "Yeremia 29:11", "t": "Maana nayajua mawazo ninayowawazia ninyi, asema Bwana, ni mawazo ya amani wala si ya mabaya, kuwapa ninyi tumaini siku zenu za mwisho."}, {"r": "Isaya 43:2", "t": "Upitapo katika maji mengi nitakuwa pamoja nawe; na katika mito, haitakugharikisha; uendapo katika moto, hutateketea; wala mwali wa moto hautakuunguza."}, {"r": "Warumi 8:37", "t": "Lakini katika mambo hayo yote tunashinda, na zaidi ya kushinda, kwa yeye aliyetupenda."}, {"r": "Warumi 8:28", "t": "Nasi twajua ya kuwa katika mambo yote Mungu hufanya kazi pamoja na wale wampendao katika kuwapatia mema, yaani, wale walioitwa kwa kusudi lake."}, {"r": "1 Wakorintho 15:58", "t": "Basi, ndugu zangu wapendwa, mwimarike, msitikisike, mkazidi sana kutenda kazi ya Bwana sikuzote, kwa kuwa mwajua ya kwamba taabu yenu siyo bure katika Bwana."}, {"r": "Isaya 40:29", "t": "Huwapa nguvu wazimiao, humwongezea nguvu yeye asiyekuwa na uwezo."}, {"r": "Yohana 16:33", "t": "Hayo nimewaambieni mpate kuwa na amani ndani yangu. Ulimwenguni mnayo dhiki; lakini jipeni moyo; mimi nimeushinda ulimwengu."}, {"r": "1 Mambo ya Nyakati 22:13", "t": "Ndipo utakapofanikiwa, ukiangalia kuzitenda amri, na hukumu, Bwana alizomwagizia Musa juu ya Israeli; uwe hodari, na wa moyo mkuu; usiogope wala usifadhaike."}, {"r": "Mathayo 14:27", "t": "Mara Yesu alinena, akawaambia, Jipeni moyo ni mimi; msiogope."}, {"r": "Matendo ya Mitume 27:22", "t": "Sasa nawapeni shauri, iweni na moyo mkuu, kwa maana hapana hata nafsi mmoja miongoni mwenu atakayepotea, ila merikebu tu."}, {"r": "Zaburi 48:13", "t": "Tieni moyoni boma zake, Yafikirini majumba yake, Mpate kuwaambia kizazi kitakachokuja."}, {"r": "Matendo ya Mitume 13:43", "t": "Sinagogi ilipofumukana, Wayahudi na waongofu watauwa wengi wakashikamana na Paulo na Barnaba; ambao, wakisema nao, wakawatia moyo kudumu katika neema ya Mungu."}, {"r": "1 Wathesalonike 5:14", "t": "Ndugu, twawasihi, waonyeni wale wasiokaa kwa utaratibu; watieni moyo walio dhaifu; watieni nguvu wanyonge; vumilieni na watu wote."}, {"r": "Marko 10:49", "t": "Yesu akasimama akasema, Mwiteni. Wakamwita yule kipofu, wakamwambia, Jipe moyo; inuka, anakuita."}, {"r": "1 Mambo ya Nyakati 28:20", "t": "Kisha Daudi akamwambia Sulemani mwanawe, Uwe hodari, mwenye moyo mkuu, ukatende hivyo; usiogope wala usifadhaike; kwa kuwa Bwana, Mungu, Mungu wangu, yu pamoja nawe; yeye hatakupungukia wala kukuacha, hata itakapomalizika kazi yote ya huo utumishi wa nyumba ya Bwana."}, {"r": "2 Samueli 10:12", "t": "Uwe hodari, tukajitie moyo mkuu, kwa ajili ya watu wetu, na kwa ajili ya miji ya Mungu wetu; naye Bwana afanye yaliyo mema machoni pake."}, {"r": "Mhubiri 1:17", "t": "Nikatia moyo wangu ili kuijua hekima, na kujua wazimu na upumbavu; nikatambua ya kwamba hayo yote nayo ni kujilisha upepo."}, {"r": "Mhubiri 7:2", "t": "Heri kuiendea nyumba ya matanga, Kuliko kuiendea nyumba ya karamu. Kwa maana huo ndio mwisho wa wanadamu wote, naye aliye hai atautia moyoni mwake."}, {"r": "Isaya 41:6", "t": "Wakasaidiana, kila mtu na mwenzake, kila mtu akamwambia ndugu yake; Uwe na moyo mkuu."}, {"r": "Isaya 35:4", "t": "Waambieni walio na moyo wa hofu, Jipeni moyo, msiogope; tazama, Mungu wenu atakuja na kisasi, na malipo ya Mungu; atakuja na kuwaokoa ninyi."}, {"r": "Kumbukumbu la Torati 31:23", "t": "Akamwagiza Yoshua, mwana wa Nuni, akamwambia, Uwe hodari na moyo mkuu, kwa kuwa utawapeleka wana wa Israeli katika nchi niliyowaapia; nami nitakuwa pamoja nawe."}, {"r": "1 Mambo ya Nyakati 19:13", "t": "Uwe hodari, tukajitie moyo mkuu kwa ajili ya watu wetu, na kwa ajili ya miji ya Mungu wetu; naye Bwana afanye yaliyo mema machoni pake."}, {"r": "Luka 15:17", "t": "Alipozingatia moyoni mwake, alisema, Ni watumishi wangapi wa baba yangu wanaokula chakula na kusaza, na mimi hapa ninakufa kwa njaa."}, {"r": "Isaya 41:7", "t": "Seremala akamtia moyo mfua dhahabu, na yeye alainishaye kwa nyundo akamhimiza yule apigaye fuawe, akiisifu kazi ya kuunga, akisema, Ni kazi njema; naye akaikaza kwa misumari isitikisike."}, {"r": "2 Wakorintho 7:16", "t": "Nafurahi, kwa sababu katika kila neno nina moyo mkuu kwa ajili yenu."}, {"r": "2 Timotheo 2:1", "t": "Basi wewe, mwanangu, uwe hodari katika neema iliyo katika Kristo Yesu."}, {"r": "Isaya 36:15", "t": "wala msimwache Hezekia kuwatia moyo wa kumtumaini Bwana; akisema, Bwana bila shaka atatuokoa, mji huu hautatiwa katika mkono wa mfalme wa Ashuru."}, {"r": "Mhubiri 1:13", "t": "Nikatia moyo wangu ili kuyatafuta yote yanayotendeka chini ya mbingu, na kuyavumbua kwa hekima; ni taabu kubwa ambayo Mungu amewapa wanadamu, ili kutaabika ndani yake."}, {"r": "2 Wakorintho 5:6", "t": "Basi siku zote tuna moyo mkuu; tena twajua ya kuwa, wakati tuwapo hapa katika mwili, tunakaa mbali na Bwana."}, {"r": "Mhubiri 8:9", "t": "Mambo hayo yote nimeyaona, nikatia moyo wangu katika kila kazi iliyofanyika chini ya jua. Kuna wakati ambapo mtu mmoja anayo mamlaka juu ya mwenziwe kwa hasira yake."}, {"r": "2 Wakorintho 9:2", "t": "Maana najua utayari wenu, ninaojisifia kwa ajili yenu kwa Wamakedonia, kwamba Akaya ilikuwa tayari tangu mwaka mzima; na bidii yenu imewatia moyo wengi wao."}, {"r": "Hagai 2:4", "t": "Lakini sasa uwe hodari, Ee Zerubabeli, asema Bwana; nawe uwe hodari, Ee Yoshua, mwana wa Yehosadaki, kuhani mkuu, nanyi iweni hodari, enyi watu wote wa nchi hii, asema Bwana; mkafanye kazi, kwa kuwa mimi ni pamoja nanyi, asema Bwana wa majeshi;"}, {"r": "1 Wathesalonike 2:11", "t": "vile vile, kama mjuavyo, jinsi tulivyomwonya kila mmoja wenu kama baba awaonyavyo watoto wake mwenyewe, tukiwatia moyo na kushuhudia;"}, {"r": "1 Wakorintho 14:3", "t": "Bali yeye ahutubuye, asema na watu maneno ya kuwajenga, na kuwafariji, na kuwatia moyo."}, {"r": "Mathayo 9:2", "t": "Na tazama, wakamletea mtu mwenye kupooza, amelala kitandani; naye Yesu, alipoiona imani yao, alimwambia yule mwenye kupooza, Jipe moyo mkuu, mwanangu, umesamehewa dhambi zako."}, {"r": "Amosi 2:16", "t": "Naye mwenye moyo mkuu miongoni mwa mashujaa Atakimbia uchi siku ile, asema Bwana."}, {"r": "Malaki 2:2", "t": "Kama hamtaki kusikia, na kama hamtaki kuitia moyoni, ili kulitukuza jina langu, asema Bwana wa majeshi, basi nitawapelekeeni laana, nami nitazilaani baraka zenu; naam, nimekwisha kuzilaani, kwa sababu hamyatii haya moyoni."}, {"r": "2 Mambo ya Nyakati 32:7", "t": "Iweni hodari, na wa moyo mkuu, msiogope, wala msifadhaike kwa sababu ya mfalme wa Ashuru, wala kwa majeshi yote walio pamoja naye; kwa maana yupo mkuu pamoja nasi kuliko aliye pamoja naye;"}, {"r": "Mhubiri 9:1", "t": "Na kwa ajili ya hayo yote, nikatia moyo wangu katika kuyatafutatafuta haya; ya kuwa wenye haki, na wenye hekima, pamoja na matendo yao yote, wamo mkononi mwa Mungu; kwamba ni pendo au kwamba ni chuki, mwanadamu hajui; mambo yote yawapita."}, {"r": "2 Wakorintho 5:8", "t": "Lakini tuna moyo mkuu; nasi tunaona ni afadhali kutokuwamo katika mwili na kukaa pamoja na Bwana."}, {"r": "Mhubiri 8:16", "t": "Mimi nilipotia moyo wangu katika kuijua hekima, na kuuona utumishi uliofanyika juu ya nchi, (maana kuna asiyepata usingizi kwa macho yake mchana wala usiku);"}, {"r": "Yeremia 23:18", "t": "Maana, ni nani aliyesimama katika baraza la Bwana, hata akalifahamu neno lake na kulisikia? Ni nani aliyelitia moyoni neno langu, na kulisikia?"}, {"r": "Mathayo 9:22", "t": "Yesu akageuka, akamwona, akamwambia, Jipe moyo mkuu, binti yangu; imani yako imekuponya. Yule mwanamke akapona tangu saa ile."}, {"r": "Matendo ya Mitume 23:11", "t": "Usiku ule Bwana akasimama karibu naye, akasema, Uwe na moyo mkuu; kwa sababu, kama ulivyonishuhudia habari zangu Yerusalemu, imekupasa kunishuhudia vivyo hivyo Rumi nako."}, {"r": "Zaburi 68:28", "t": "Ee Mungu, uziamuru nguvu zako; Ee Mungu, uwe hodari uliyetufanyia makuu."}, {"r": "Isaya 41:22", "t": "Wayatangaze na kutujulisha yatakayokuwa; watuonyeshe mambo ya zamani, ni mambo gani, tukapate kuyatia moyoni, tukajue mwisho wake; au wamdhihirishie yatakayotokea baadaye."}], "shukrani": [{"r": "2 Wakorintho 9:15", "t": "Mungu ashukuriwe kwa sababu ya kipawa chake, tusichoweza kukisifu kama ipasavyo."}, {"r": "Zaburi 50:14", "t": "Mtolee Mungu dhabihu za kushukuru; Mtimizie Aliye juu nadhiri zako."}, {"r": "Zaburi 106:1", "t": "Haleluya. Mshukuruni Bwana kwa kuwa ni mwema, Kwa maana fadhili zake ni za milele."}, {"r": "1 Wakorintho 15:57", "t": "Lakini Mungu na ashukuriwe atupaye kushinda kwa Bwana wetu Yesu Kristo."}, {"r": "Wafilipi 1:3", "t": "Namshukuru Mungu wangu kila niwakumbukapo,"}, {"r": "1 Mambo ya Nyakati 16:34", "t": "Mshukuruni Bwana kwa kuwa ni mwema; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 107:1", "t": "Mshukuruni Bwana kwa kuwa ni mwema, Kwa maana fadhili zake ni za milele."}, {"r": "Yakobo 1:17", "t": "Kila kutoa kuliko kwema, na kila kitolewacho kilicho kamili, hutoka juu, hushuka kwa Baba wa mianga; kwake hakuna kubadilika, wala kivuli cha kugeukageuka."}, {"r": "Wakolosai 3:15", "t": "Na amani ya Kristo iamue mioyoni mwenu; ndiyo mliyoitiwa katika mwili mmoja; tena iweni watu wa shukrani."}, {"r": "Zaburi 138:1", "t": "Nitakushukuru kwa moyo wangu wote, Mbele ya miungu nitakuimbia zaburi."}, {"r": "Zaburi 136:26", "t": "Mshukuruni Mungu wa mbingu; Kwa maana fadhili zake ni za milele."}, {"r": "Waefeso 1:16", "t": "siachi kutoa shukrani kwa ajili yenu; nikiwakumbuka katika sala zangu,"}, {"r": "Waefeso 5:20", "t": "na kumshukuru Mungu Baba sikuzote kwa mambo yote, katika jina lake Bwana wetu Yesu Kristo;"}, {"r": "Zaburi 34:1", "t": "Nitamhimidi Bwana kila wakati, Sifa zake zi kinywani mwangu daima."}, {"r": "2 Wakorintho 2:14", "t": "Ila Mungu ashukuriwe, anayetushangiliza daima katika Kristo, na kuidhihirisha harufu ya kumjua yeye kila mahali kwa kazi yetu."}, {"r": "Zaburi 118:29", "t": "Mshukuruni Bwana kwa kuwa ni mwema, Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 136:1", "t": "Mshukuruni Bwana kwa kuwa ni mwema; Kwa maana fadhili zake ni za milele."}, {"r": "1 Wathesalonike 5:18", "t": "shukuruni kwa kila jambo; maana hayo ni mapenzi ya Mungu kwenu katika Kristo Yesu."}, {"r": "Warumi 1:8", "t": "Kwanza namshukuru Mungu wangu katika Yesu Kristo kwa ajili yenu nyote, kwa kuwa imani yenu inahubiriwa katika dunia nzima."}, {"r": "Zaburi 118:1", "t": "Haleluya. Mshukuruni Bwana kwa kuwa ni mwema, Kwa maana fadhili zake ni za milele."}, {"r": "Filemoni 1:4", "t": "Namshukuru Mungu wangu sikuzote, nikikukumbuka katika maombi yangu;"}, {"r": "Zaburi 103:2", "t": "Ee nafsi yangu, umhimidi Bwana, Wala usizisahau fadhili zake zote."}, {"r": "Zaburi 9:1", "t": "Nitamshukuru Bwana kwa moyo wangu wote; Nitayasimulia matendo yako yote ya ajabu;"}, {"r": "Waebrania 13:15", "t": "Basi, kwa njia yake yeye, na tumpe Mungu dhabihu ya sifa daima, yaani, tunda la midomo iliungamayo jina lake."}, {"r": "Zaburi 100:4", "t": "Ingieni malangoni mwake kwa kushukuru; Nyuani mwake kwa kusifu; Mshukuruni, lihimidini jina lake;"}, {"r": "Wakolosai 3:17", "t": "Na kila mfanyalo, kwa neno au kwa tendo, fanyeni yote katika jina la Bwana Yesu, mkimshukuru Mungu Baba kwa yeye."}, {"r": "Zaburi 75:1", "t": "Ee Mungu, twakushukuru. Twakushukuru kwa kuwa Jina lako li karibu; Watu huyasimulia matendo yako ya ajabu."}, {"r": "Isaya 12:4", "t": "Na katika siku hiyo mtasema, Mshukuruni Bwana, liitieni jina lake; Yatangazeni matendo yake kati ya mataifa, Litajeni jina lake kuwa limetukuka."}, {"r": "Wakolosai 4:2", "t": "Dumuni sana katika kuomba, mkikesha katika kuomba huku na shukrani;"}, {"r": "Wafilipi 4:6", "t": "Msijisumbue kwa neno lo lote; bali katika kila neno kwa kusali na kuomba, pamoja na kushukuru, haja zenu na zijulikane na Mungu."}, {"r": "Zaburi 92:1", "t": "Ni neno jema kumshukuru Bwana, Na kuliimbia jina lako, Ee Uliye juu."}, {"r": "Wakolosai 2:7", "t": "wenye shina na wenye kujengwa katika yeye; mmefanywa imara kwa imani, kama mlivyofundishwa; mkizidi kutoa shukrani."}, {"r": "2 Wathesalonike 1:3", "t": "Ndugu, imetupasa kumshukuru Mungu sikuzote kwa ajili yenu, kama ilivyo wajibu, kwa kuwa imani yenu inazidi sana, na upendo wa kila mtu kwenu kwa mwenzake umekuwa mwingi."}, {"r": "Zaburi 95:2", "t": "Tuje mbele zake kwa shukrani, Tumfanyie shangwe kwa zaburi."}, {"r": "1 Wakorintho 1:4", "t": "Namshukuru Mungu sikuzote kwa ajili yenu, kwa sababu ya neema ya Mungu mliyopewa katika Kristo Yesu;"}, {"r": "Yohana 6:23", "t": "(Walakini zikaja mashua nyingine kutoka Tiberia mpaka karibu na mahali pale walipokula mikate, wakati Bwana aliposhukuru.)"}, {"r": "Yohana 6:11", "t": "Basi Yesu akaitwaa ile mikate, akashukuru, akawagawia walioketi; na kadhalika katika wale samaki kwa kadiri walivyotaka."}, {"r": "2 Wakorintho 9:11", "t": "mkitajirishwa katika vitu vyote mpate kuwa na ukarimu wote, umpatiao Mungu shukrani kwa kazi yetu."}, {"r": "Luka 22:19", "t": "Akatwaa mkate, akashukuru, akaumega, akawapa, akisema, [Huu ndio mwili wangu unaotolewa kwa ajili yenu; fanyeni hivi kwa ukumbusho wangu."}, {"r": "1 Wathesalonike 3:9", "t": "Maana ni shukrani gani tuwezayo kumlipa Mungu kwa ajili yenu, kwa furaha ile yote tunayoifurahia, kwa sababu yenu mbele za Mungu wetu;"}, {"r": "Zaburi 52:9", "t": "Nitakushukuru milele kwa maana umetenda; Nitalingojea jina lako kwa kuwa ni jema; Mbele ya wacha Mungu wako."}, {"r": "Ufunuo wa Yohana 7:12", "t": "wakisema, Amina; Baraka na utukufu na hekima na shukrani na heshima na uweza na nguvu zina Mungu wetu hata milele na milele. Amina."}, {"r": "Zaburi 45:17", "t": "Jina lako nitalifanya kuwa kumbukumbu Katika vizazi vyote. Kwa hiyo mataifa watakushukuru Milele na milele."}, {"r": "Yeremia 33:11", "t": "itasikilikana tena sauti ya furaha na sauti ya shangwe, sauti ya bwana arusi na sauti ya bibi arusi, sauti yao wasemao Mshukuruni Bwana wa majeshi, maana Bwana ni mwema, rehema zake ni za milele; na sauti zao waletao sadaka za shukrani nyumbani kwa Bwana. Kwa kuwa nitawarudisha wafungwa wa nchi hii kama kwanza, asema Bwana."}, {"r": "Mambo ya Walawi 7:12", "t": "Kwamba aitoa kwa ajili ya shukrani, ndipo atakaposongeza pamoja na hiyo sadaka ya shukrani mikate isiyotiwa chachu, iliyoandaliwa na mafuta, na mikate ya kaki isiyochachwa iliyopakwa mafuta, na mikate ya unga mwembamba uliolowama mafuta."}, {"r": "Isaya 12:1", "t": "Na katika siku hiyo utasema, Ee Bwana, nitakushukuru wewe; Kwa kuwa ijapokuwa ulinikasirikia, Hasira yako imegeukia mbali, Nawe unanifariji moyo."}, {"r": "Zaburi 71:22", "t": "Nami nitakushukuru kwa kinanda, Na kweli yako, Ee Mungu wangu. Nitakuimbia Wewe kwa kinubi, Ee Mtakatifu wa Israeli."}, {"r": "Yeremia 30:19", "t": "Tena kwao itasikiwa shukrani, na sauti yao wachangamkao; nami nitawazidisha, wala hawatakuwa wachache; tena nitawatukuza, wala hawatakuwa wanyonge."}, {"r": "Zaburi 35:18", "t": "Nitakushukuru katika kusanyiko kubwa; Nitakusifu kati ya watu wengi."}, {"r": "1 Wakorintho 1:14", "t": "Nashukuru, kwa sababu sikumbatiza mtu kwenu, ila Krispo na Gayo;"}, {"r": "Marko 6:41", "t": "Akaitwaa ile mikate mitano na wale samaki wawili, akatazama mbinguni, akashukuru, akaimega ile mikate, akawapa wanafunzi wake wawaandikie; na wale samaki wawili akawagawia wote."}, {"r": "Zaburi 67:3", "t": "Watu na wakushukuru, Ee Mungu, Watu wote na wakushukuru."}, {"r": "Zaburi 44:8", "t": "Tumejisifia Mungu mchana kutwa, Na jina lako tutalishukuru milele."}, {"r": "Zaburi 107:22", "t": "Na wamtolee dhabihu za kushukuru, Na kuyasimulia matendo yake kwa kuimba."}, {"r": "Zaburi 57:9", "t": "Ee Bwana, nitakushukuru kati ya watu, Nitakuimbia zaburi kati ya mataifa."}, {"r": "Zaburi 147:7", "t": "Mwimbieni Bwana kwa kushukuru, Mwimbieni Mungu wetu kwa kinubi."}, {"r": "Isaya 51:3", "t": "Maana Bwana ameufariji Sayuni; amepafariji mahali pake palipokuwa ukiwa; amefanya jangwa lake kuwa kama bustani ya Edeni, na nyika yake kama bustani ya Bwana; furaha na kicheko zitaonekana ndani yake, kushukuru, na sauti ya kuimba."}, {"r": "Zaburi 69:30", "t": "Nitalisifu jina la Mungu kwa wimbo, Nami nitamtukuza kwa shukrani."}, {"r": "Yohana 11:41", "t": "Basi wakaliondoa lile jiwe. Yesu akainua macho yake juu, akasema, Baba, nakushukuru kwa kuwa umenisikia."}, {"r": "Warumi 15:9", "t": "tena ili Mataifa wamtukuze Mungu kwa ajili ya rehema zake; kama ilivyoandikwa, Kwa hiyo nitakushukuru kati ya Mataifa, Nami nitaliimbia jina lako."}, {"r": "2 Wakorintho 9:12", "t": "Maana utumishi wa huduma hii hauwatimizii watakatifu riziki walizopungukiwa tu, bali huzidi sana kuwa na faida kwa shukrani nyingi apewazo Mungu;"}, {"r": "Zaburi 140:13", "t": "Hakika wenye haki watalishukuru jina lako, Wenye adili watakaa mahali ulipo Wewe."}, {"r": "Zaburi 108:3", "t": "Ee Bwana, nitakushukuru kati ya watu, Nitakuimbia zaburi kati ya mataifa."}, {"r": "Zaburi 97:12", "t": "Enyi wenye haki, mmfurahieni Bwana, Na kulishukuru jina lake takatifu."}, {"r": "1 Wakorintho 14:17", "t": "Maana ni kweli, wewe washukuru vema, bali yule mwingine hajengwi."}, {"r": "Waefeso 5:4", "t": "wala aibu wala maneno ya upuzi wala ubishi; hayo hayapendezi; bali afadhali kushukuru."}, {"r": "Zaburi 54:6", "t": "Kwa ukunjufu wa moyo nitakutolea dhabihu; Ee Bwana, nitalishukuru jina lako, maana ni jema."}, {"r": "1 Wakorintho 10:30", "t": "Ikiwa mimi natumia sehemu yangu kwa shukrani, kwa nini nitukanwe, kwa ajili ya kitu nikishukuriacho?"}, {"r": "Warumi 16:4", "t": "waliokuwa tayari hata kukatwa kichwa kwa ajili ya maisha yangu; ambao ninawashukuru, wala si mimi tu, ila na makanisa ya Mataifa yote pia; nisalimieni na kanisa lililomo katika nyumba yao."}, {"r": "1 Timotheo 4:3", "t": "wakiwazuia watu wasioe, na kuwaamuru wajiepushe na vyakula, ambavyo Mungu aliviumba vipokewe kwa shukrani na walio na imani wenye kuijua hiyo kweli."}, {"r": "Zaburi 18:49", "t": "Basi, Bwana, nitakushukuru kati ya mataifa, Nami nitaliimbia jina lako."}, {"r": "Zaburi 26:7", "t": "Ili niitangaze sauti ya kushukuru, Na kuzisimulia kazi zako za ajabu."}, {"r": "Marko 14:23", "t": "Akatwaa kikombe, akashukuru, akawapa; wakakinywea wote."}, {"r": "Zaburi 56:12", "t": "Ee Mungu, nadhiri zako zi juu yangu; Nitakutolea dhabihu za kushukuru."}, {"r": "Mathayo 15:36", "t": "akaitwaa ile mikate saba na vile visamaki, akashukuru akavimega, akawapa wanafunzi wake, nao wanafunzi wakawapa makutano."}, {"r": "Zaburi 118:21", "t": "Nitakushukuru kwa maana umenijibu, Nawe umekuwa wokovu wangu."}, {"r": "Zaburi 145:10", "t": "Ee Bwana, kazi zako zote zitakushukuru, Na wacha Mungu wako watakuhimidi."}, {"r": "Amosi 4:5", "t": "mkachome sadaka ya shukrani, ya kitu kilichotiwa chachu; mkatangaze sadaka mtoazo kwa hiari na kuzihubiri habari zake; kwa maana ndivyo viwapendezavyo ninyi, enyi wana wa Israeli, asema Bwana MUNGU."}, {"r": "Matendo ya Mitume 24:3", "t": "basi tunayapokea kila wakati na kila mahali, kwa shukrani yote."}, {"r": "Marko 8:6", "t": "Akawaagiza mkutano waketi chini; akaitwaa ile mikate saba, akashukuru, akaimega, akawapa wanafunzi wake wawaandikie; wakawaandikia mkutano."}, {"r": "Zaburi 50:23", "t": "Atoaye dhabihu za kushukuru, Ndiye anayenitukuza. Naye autengenezaye mwenendo wake, Nitamwonyesha wokovu wa Mungu."}, {"r": "Mathayo 26:27", "t": "Akakitwaa kikombe, akashukuru, akawapa, akisema, Nyweni nyote katika hiki;"}, {"r": "Zaburi 118:28", "t": "Ndiwe Mungu wangu, nami nitakushukuru, Ndiwe Mungu wangu, nami nitakutukuza."}, {"r": "Zaburi 67:5", "t": "Watu na wakushukuru, Ee Mungu, Watu wote na wakushukuru."}, {"r": "Zaburi 99:3", "t": "Na walishukuru jina lake kuu la kuhofiwa; Ndiye mtakatifu."}, {"r": "Zaburi 116:17", "t": "Nitakutolea dhabihu ya kushukuru; Na kulitangaza jina la Bwana;"}, {"r": "Zaburi 119:7", "t": "Nitakushukuru kwa unyofu wa moyo, Nikiisha kujifunza hukumu za haki yako"}, {"r": "Zaburi 119:62", "t": "Katikati ya usiku nitaamka nikushukuru, Kwa sababu ya hukumu zako za haki."}, {"r": "Luka 17:9", "t": "Je! Atampa asante yule mtumwa, kwa sababu ameyafanya aliyoagizwa?"}, {"r": "Zaburi 30:4", "t": "Mwimbieni Bwana zaburi, Enyi watauwa wake. Na kufanya shukrani. Kwa kumbukumbu la utakatifu wake."}, {"r": "2 Mambo ya Nyakati 29:31", "t": "Ndipo Hezekia akajibu, akasema, Sasa mmejifanya wakfu kwa Bwana, karibuni mkalete dhabihu na matoleo ya shukrani nyumbani mwa Bwana. Basi kusanyiko wakaleta dhabihu na matoleo ya shukrani; na wote wenye moyo wa ukarimu, wakaleta sadaka za kuteketezwa."}, {"r": "2 Wakorintho 4:15", "t": "Kwa maana mambo yote ni kwa ajili yenu, ili neema hiyo ikiongezwa sana, kwa hao walio wengi shukrani izidishwe, na Mungu atukuzwe."}, {"r": "Zaburi 142:7", "t": "Uitoe nafsi yangu kifungoni. Nipate kulishukuru jina lako. Wenye haki watanizunguka, Kwa kuwa Wewe unanikirimu."}, {"r": "2 Wakorintho 1:11", "t": "ninyi nanyi mkisaidiana nasi kwa ajili yetu katika kuomba, ili, kwa sababu ya ile karama tupewayo sisi kwa msaada wa watu wengi, watu wengi watoe shukrani kwa ajili yetu."}, {"r": "1 Wakorintho 14:16", "t": "Kwa maana wewe ukibariki kwa roho, yeye aketiye katika mahali pa mjinga ataitikaje, Amina, baada ya kushukuru kwako, akiwa hayajui usemayo?"}, {"r": "1 Timotheo 2:1", "t": "Basi, kabla ya mambo yote, nataka dua, na sala, na maombezi, na shukrani, zifanyike kwa ajili ya watu wote;"}, {"r": "Luka 22:17", "t": "Akapokea kikombe, akashukuru, akasema, Twaeni hiki, mgawanye ninyi kwa ninyi;"}, {"r": "Luka 18:11", "t": "Yule Farisayo akasimama akiomba hivi moyoni mwake; Ee Mungu, nakushukuru kwa kuwa mimi si kama watu wengine, wanyang'anyi, wadhalimu, wazinzi, wala kama huyu mtoza ushuru."}, {"r": "1 Timotheo 4:4", "t": "Kwa maana kila kiumbe cha Mungu ni kizuri, wala hakuna cha kukataliwa, kama kikipokewa kwa shukrani;"}, {"r": "Zaburi 138:4", "t": "Ee Bwana, wafalme wote wa dunia watakushukuru, Watakapoyasikia maneno ya kinywa chako."}, {"r": "1 Wakorintho 11:24", "t": "naye akiisha kushukuru akaumega, akasema, Huu ndio mwili wangu ulio kwa ajili yenu; fanyeni hivi kwa ukumbusho wangu."}], "baraka": [{"r": "Zaburi 1:1", "t": "Heri mtu yule asiyekwenda Katika shauri la wasio haki; Wala hakusimama katika njia ya wakosaji; Wala hakuketi barazani pa wenye mizaha."}, {"r": "Hesabu 6:26", "t": "Bwana akuinulie uso wake, na kukupa amani."}, {"r": "Wafilipi 4:23", "t": "Neema ya Bwana Yesu Kristo na iwe pamoja na roho zenu."}, {"r": "Yuda 1:24", "t": "Yeye awezaye kuwalinda ninyi msijikwae, na kuwasimamisha mbele ya utukufu wake bila mawaa katika furaha kuu;"}, {"r": "Mathayo 5:4", "t": "Heri wenye huzuni; Maana hao watafarijika."}, {"r": "Mathayo 5:3", "t": "Heri walio maskini wa roho; Maana ufalme wa mbinguni ni wao."}, {"r": "Zaburi 115:12", "t": "Bwana ametukumbuka, Naye atatubariki sisi. Ataubariki mlango wa Israeli, Ataubariki mlango wa Haruni,"}, {"r": "2 Wakorintho 13:14", "t": "Neema ya Bwana Yesu Kristo, na pendo la Mungu, na ushirika wa Roho Mtakatifu ukae nanyi nyote."}, {"r": "Mithali 10:22", "t": "Baraka ya Bwana hutajirisha, Wala hachanganyi huzuni nayo."}, {"r": "1 Petro 5:10", "t": "Na Mungu wa neema yote, aliyewaita kuingia katika utukufu wake wa milele katika Kristo, mkiisha kuteswa kwa muda kidogo, yeye mwenyewe atawatengeneza, na kuwathibitisha, na kuwatia nguvu."}, {"r": "Kumbukumbu la Torati 28:6", "t": "Utabarikiwa uingiapo, utabarikiwa na utokapo."}, {"r": "3 Yohana 1:2", "t": "Mpenzi naomba ufanikiwe katika mambo yote na kuwa na afya yako, kama vile roho yako ifanikiwavyo."}, {"r": "Mathayo 5:9", "t": "Heri wapatanishi; Maana hao wataitwa wana wa Mungu."}, {"r": "Warumi 15:13", "t": "Basi Mungu wa tumaini na awajaze ninyi furaha yote na amani katika kuamini, mpate kuzidi sana kuwa na tumaini, katika nguvu za Roho Mtakatifu."}, {"r": "Warumi 15:5", "t": "Na Mungu mwenye saburi na faraja awajalie kunia mamoja ninyi kwa ninyi, kwa mfano wa Kristo Yesu;"}, {"r": "Malaki 3:10", "t": "Leteni zaka kamili ghalani, ili kiwemo chakula katika nyumba yangu, mkanijaribu kwa njia hiyo, asema Bwana wa majeshi; mjue kama sitawafungulia madirisha ya mbinguni, na kuwamwagieni baraka, hata isiwepo nafasi ya kutosha, au la."}, {"r": "Wagalatia 6:18", "t": "Ndugu zangu, neema ya Bwana wetu Yesu Kristo na iwe pamoja na roho zenu. Amina."}, {"r": "Mathayo 5:8", "t": "Heri wenye moyo safi; Maana hao watamwona Mungu."}, {"r": "Mathayo 5:7", "t": "Heri wenye rehema; Maana hao watapata rehema."}, {"r": "Zaburi 115:14", "t": "Bwana na awaongeze ninyi, Ninyi na watoto wenu."}, {"r": "Waebrania 13:20", "t": "Basi, Mungu wa amani aliyemleta tena kutoka kwa wafu Mchungaji Mkuu wa kondoo, kwa damu ya agano la milele, yeye Bwana wetu Yesu,"}, {"r": "Zaburi 29:11", "t": "Bwana atawapa watu wake nguvu; Bwana atawabariki watu wake kwa amani."}, {"r": "2 Wakorintho 9:8", "t": "Na Mungu aweza kuwajaza kila neema kwa wingi, ili ninyi, mkiwa na riziki za kila namna siku zote, mpate kuzidi sana katika kila tendo jema;"}, {"r": "Warumi 15:33", "t": "Mungu wa amani na awe pamoja nanyi nyote. Amina."}, {"r": "Yuda 1:25", "t": "Yeye aliye Mungu pekee, Mwokozi wetu kwa Yesu Kristo Bwana wetu; utukufu una yeye, na ukuu, na uwezo, na nguvu, tangu milele, na sasa, na hata milele. Amina."}, {"r": "Waebrania 13:21", "t": "awafanye ninyi kuwa wakamilifu katika kila tendo jema, mpate kuyafanya mapenzi yake, naye akifanya ndani yetu lipendezalo mbele zake, kwa Yesu Kristo; utukufu una yeye milele na milele. Amina."}, {"r": "Zaburi 67:1", "t": "Mungu na atufadhili na kutubariki, Na kutuangazia uso wake."}, {"r": "Waefeso 1:3", "t": "Atukuzwe Mungu, Baba wa Bwana wetu Yesu Kristo, aliyetubariki kwa baraka zote za rohoni, katika ulimwengu wa roho, ndani yake Kristo;"}, {"r": "Mathayo 5:5", "t": "Heri wenye upole; Maana hao watairithi nchi."}, {"r": "Waefeso 3:16", "t": "awajalieni, kwa kadiri ya utajiri wa utukufu wake, kufanywa imara kwa nguvu, kwa kazi ya Roho wake katika utu wa ndani."}, {"r": "Mwanzo 12:2", "t": "nami nitakufanya wewe kuwa taifa kubwa, na kukubariki, na kulikuza jina lako; nawe uwe baraka;"}, {"r": "Yeremia 17:7", "t": "Amebarikiwa mtu yule anayemtegemea Bwana, Ambaye Bwana ni tumaini lake."}, {"r": "Zaburi 112:1", "t": "Haleluya. Heri mtu yule amchaye Bwana, Apendezwaye sana na maagizo yake."}, {"r": "Hesabu 6:25", "t": "Bwana akuangazie nuru za uso wake, na kukufadhili;"}, {"r": "Wafilipi 4:19", "t": "Na Mungu wangu atawajazeni kila mnachokihitaji kwa kadiri ya utajiri wake, katika utukufu, ndani ya Kristo Yesu."}, {"r": "1 Wathesalonike 5:23", "t": "Mungu wa amani mwenyewe awatakase kabisa; nanyi nafsi zenu na roho zenu na miili yenu mhifadhiwe mwe kamili, bila lawama, wakati wa kuja kwake Bwana wetu Yesu Kristo."}, {"r": "Zaburi 84:12", "t": "Ee Bwana wa majeshi, Heri mwanadamu anayekutumaini Wewe."}, {"r": "2 Wathesalonike 3:18", "t": "Neema ya Bwana wetu Yesu Kristo na iwe pamoja nanyi nyote."}, {"r": "2 Wathesalonike 3:16", "t": "Sasa, Bwana wa amani mwenyewe na awape amani daima kwa njia zote. Bwana awe pamoja nanyi nyote."}, {"r": "2 Petro 1:2", "t": "Neema na iwe kwenu na amani iongezwe katika kumjua Mungu na Yesu Bwana wetu."}, {"r": "Mathayo 5:6", "t": "Heri wenye njaa na kiu ya haki; Maana hao watashibishwa."}, {"r": "Zaburi 128:5", "t": "Bwana akubariki toka Sayuni; Uone uheri wa Yerusalemu siku zote za maisha yako;"}, {"r": "Hesabu 6:24", "t": "Bwana akubarikie, na kukulinda;"}, {"r": "2 Mambo ya Nyakati 9:7", "t": "Heri watu wako, na heri hawa watumishi wako, wasimamao mbele yako sikuzote, wakisikia hekima yako."}, {"r": "Mhubiri 4:3", "t": "naam, zaidi ya hao wote nikamwita heri yeye asiyekuwako bado, ambaye hakuyaona mabaya yanayotendeka chini ya jua."}, {"r": "Zaburi 32:2", "t": "Heri Bwana asiyemhesabia upotovu, Ambaye rohoni mwake hamna hila."}, {"r": "Zaburi 89:15", "t": "Heri watu wale waijuao sauti ya shangwe, Ee Bwana, huenenda katika nuru ya uso wako."}, {"r": "Zaburi 37:22", "t": "Maana waliobarikiwa na yeye watairithi nchi, Nao waliolaaniwa na yeye wataharibiwa."}, {"r": "Malaki 3:15", "t": "Na sasa twasema ya kwamba wenye kiburi ndio walio heri; naam, watendao uovu ndio wajengwao; naam, wamjaribuo Mungu ndio waponywao."}, {"r": "Waebrania 11:20", "t": "Kwa imani Isaka akawabariki Yakobo na Esau, hata katika habari ya mambo yatakayokuwa baadaye."}, {"r": "Mathayo 26:26", "t": "Nao walipokuwa wakila Yesu alitwaa mkate, akabariki, akaumega, akawapa wanafunzi wake, akasema, Twaeni, mle; huu ndio mwili wangu"}, {"r": "Wagalatia 3:9", "t": "Basi hao walio wa imani hubarikiwa pamoja na Ibrahimu aliyekuwa mwenye imani."}, {"r": "Luka 1:45", "t": "Naye heri aliyesadiki; kwa maana yatatimizwa aliyoambiwa na Bwana."}, {"r": "Zaburi 65:4", "t": "Heri mtu yule umchaguaye, Na kumkaribisha akae nyuani mwako. Na tushibe wema wa nyumba yako, Patakatifu pa hekalu lako."}, {"r": "Mithali 10:7", "t": "Kuwakumbuka wenye haki huwa na baraka; Bali jina la mtu mwovu litaoza."}, {"r": "Zaburi 65:10", "t": "Matuta yake wayajaza maji; Wapasawazisha palipoinuka, Wailainisha nchi kwa manyunyu; Waibariki mimea yake."}, {"r": "Yakobo 1:12", "t": "Heri mtu astahimiliye majaribu; kwa sababu akiisha kukubaliwa ataipokea taji ya uzima, Bwana aliyowaahidia wampendao."}, {"r": "Malaki 2:2", "t": "Kama hamtaki kusikia, na kama hamtaki kuitia moyoni, ili kulitukuza jina langu, asema Bwana wa majeshi, basi nitawapelekeeni laana, nami nitazilaani baraka zenu; naam, nimekwisha kuzilaani, kwa sababu hamyatii haya moyoni."}, {"r": "Mwanzo 49:26", "t": "Mibaraka ya baba yako Imepita mibaraka ya milima ya kale, Vitu vinavyotamanika vya vilima vya milele; Na vikae juu ya kichwa cha Yusufu, Juu ya utosi wa kichwa chake aliye mkuu kati ya ndugu zake."}, {"r": "Luka 2:34", "t": "Simeoni akawabariki, akamwambia Mariamu mama yake, Tazama, huyu amewekwa kwa kuanguka na kuinuka wengi walio katika Israeli, na kuwa ishara itakayonenewa."}, {"r": "Zaburi 37:26", "t": "Mchana kutwa hufadhili na kukopesha, Na mzao wake hubarikiwa."}, {"r": "Ufunuo wa Yohana 22:7", "t": "Na tazama, naja upesi; heri yeye ayashikaye maneno ya unabii wa kitabu hiki."}, {"r": "Luka 24:30", "t": "Ikawa alipokuwa ameketi nao chakulani, alitwaa mkate, akaubariki, akaumega, akawapa."}, {"r": "Yohana 13:17", "t": "Mkiyajua hayo, heri ninyi mkiyatenda."}, {"r": "Luka 24:50", "t": "Akawaongoza mpaka Bethania, akainua mikono yake akawabariki."}, {"r": "Ayubu 5:17", "t": "Tazama, yu heri mtu yule Mungu amwadhibuye; Kwa hiyo usidharau kurudiwa na huyo Mwenyezi."}, {"r": "Yeremia 20:14", "t": "Na ilaaniwe siku niliyozaliwa, isibarikiwe siku ile aliyonizaa mama yangu."}, {"r": "Isaya 65:23", "t": "Hawatajitaabisha kwa kazi bure, wala hawatazaa kwa taabu; kwa sababu wao ni wazao wa hao waliobarikiwa na Bwana, na watoto wao pamoja nao."}, {"r": "Isaya 32:20", "t": "Heri ninyi mpandao mbegu kando ya maji yote, na kuiacha miguu ya ng'ombe na punda waende ko kote."}, {"r": "Mathayo 13:16", "t": "Lakini, heri macho yenu, kwa kuwa yanaona; na masikio yenu, kwa kuwa yanasikia."}, {"r": "Luka 1:42", "t": "akapaza sauti kwa nguvu akasema, Umebarikiwa wewe katika wanawake, naye mzao wa tumbo lako amebarikiwa."}, {"r": "Wagalatia 3:8", "t": "Na andiko, kwa vile lilivyoona tangu zamani kwamba Mungu atawahesabia haki Mataifa kwa imani, lilimhubiri Ibrahimu habari njema zamani, kusema, Katika wewe Mataifa yote watabarikiwa."}, {"r": "Luka 9:16", "t": "Akaitwaa ile mikate mitano na wale samaki wawili, akatazama juu mbinguni akavibariki, akavimega, akawapa wanafunzi wake ili wawaandikie mkutano."}, {"r": "Isaya 66:3", "t": "Yeye achinjaye ng'ombe ni kama yeye amwuaye mtu; na yeye atoaye dhabihu ya mwanakondoo ni kama yeye avunjaye shingo ya mbwa; na yeye atoaye matoleo ni kama yeye atoaye damu ya nguruwe; na yeye afukizaye uvumba ni kama yeye abarikiye sanamu; naam, wamezichagua njia zao wenyewe, na nafsi zao zafurahia machukizo yao."}, {"r": "Ufunuo wa Yohana 20:6", "t": "Huo ndio ufufuo wa kwanza. Heri, na mtakatifu, ni yeye aliye na sehemu katika ufufuo wa kwanza; juu ya hao mauti ya pili haina nguvu; bali watakuwa makuhani wa Mungu na wa Kristo, nao watatawala pamoja naye hiyo miaka elfu."}, {"r": "Mithali 28:14", "t": "Mwanadamu mwenye kicho yu heri sikuzote; Bali mshupavu wa moyo ataangukia madhara."}, {"r": "Marko 14:21", "t": "Kwa maana Mwana wa Adamu aenda zake kama alivyoandikiwa; lakini ole wake mtu yule ambaye amsaliti Mwana wa Adamu; ingekuwa heri kwake mtu yule kama asingalizaliwa."}, {"r": "Mithali 29:18", "t": "Pasipo maono, watu huacha kujizuia; Bali ana heri mtu yule aishikaye sheria."}, {"r": "Mithali 20:21", "t": "Urithi uliopatikana mwanzo kwa haraka, Mwisho wake, lakini, hautabarikiwa."}, {"r": "1 Petro 3:9", "t": "watu wasiolipa baya kwa baya, au laumu kwa laumu; bali wenye kubariki; kwa sababu hayo ndiyo mliyoitiwa ili mrithi baraka."}, {"r": "Kumbukumbu la Torati 28:8", "t": "Bwana ataiamuru baraka ije juu yako katika ghala zako, na mambo yote utakayotia mkono wako; naye atakubarikia katika nchi akupayo Bwana, Mungu wako."}, {"r": "Mwanzo 12:3", "t": "nami nitawabariki wakubarikio, naye akulaaniye nitamlaani; na katika wewe jamaa zote za dunia watabarikiwa."}, {"r": "Luka 6:22", "t": "Heri ninyi watu watakapowachukia, na kuwatenga, na kuwashutumu, na kulitupa nje jina lenu kama neno ovu, kwa ajili ya Mwana wa Adamu."}, {"r": "Zaburi 45:2", "t": "Wewe u mzuri sana kuliko wanadamu; Neema imemiminiwa midomoni mwako, Kwa hiyo Mungu amekubariki hata milele."}, {"r": "Mithali 22:9", "t": "Mwenye jicho la ukarimu atabarikiwa; Maana huwapa maskini chakula chake."}, {"r": "Yohana 20:29", "t": "Yesu akamwambia, Wewe, kwa kuwa umeniona, umesadiki; wa heri wale wasioona, wakasadiki."}, {"r": "Matendo ya Mitume 3:26", "t": "Mungu, akiisha kumfufua mtumishi wake Yesu, alimtuma kwenu ninyi kwanza, ili kuwabarikia kwa kumwepusha kila mmoja wenu na maovu yake."}, {"r": "Isaya 19:24", "t": "Katika siku hiyo Israeli atakuwa wa tatu pamoja na Misri na Ashuru, watakuwa baraka kati ya dunia;"}, {"r": "Marko 14:22", "t": "Nao walipokuwa wakila, alitwaa mkate, akabariki, akaumega, akawapa, akasema, Twaeni; huu ndio mwili wangu."}, {"r": "Kumbukumbu la Torati 28:3", "t": "Utabarikiwa mjini, utabarikiwa na mashambani."}, {"r": "Mathayo 24:46", "t": "Heri mtumwa yule, ambaye bwana wake ajapo atamkuta akifanya hivyo."}, {"r": "Zaburi 84:4", "t": "Heri wakaao nyumbani mwako, Wanakuhimidi daima."}, {"r": "Zaburi 94:12", "t": "Ee Bwana, heri mtu yule umwadibuye, Na kumfundisha kwa sheria yako;"}, {"r": "Yakobo 1:25", "t": "Lakini aliyeitazama sheria kamilifu iliyo ya uhuru, na kukaa humo, asiwe msikiaji msahaulifu, bali mtendaji wa kazi, huyo atakuwa heri katika kutenda kwake."}, {"r": "Ufunuo wa Yohana 3:15", "t": "Nayajua matendo yako, ya kuwa hu baridi wala hu moto; ingekuwa heri kama ungekuwa baridi au moto."}, {"r": "Hesabu 24:9", "t": "Aliinama, akalala mfano wa simba, Na kama simba mke; ni nani atakayemstusha? Na abarikiwe kila akubarikiye, Na alaaniwe kila akulaaniye."}, {"r": "Isaya 56:2", "t": "Heri afanyaye haya, na mwanadamu ayashikaye sana; azishikaye sabato asizivunje, auzuiaye mkono wake usifanye uovu wo wote."}, {"r": "Ezekieli 34:26", "t": "Nami nitawafanya wao, na mahali palipo pande zote za mlima wangu, kuwa baraka, nami nitaleta manyunyu kwa wakati wake; yatakuwako manyunyu ya baraka."}, {"r": "Mathayo 14:19", "t": "Akawaagiza makutano waketi katika majani; akaitwaa ile mikate mitano na wale samaki wawili, akatazama juu mbinguni, akabariki, akaimega ile mikate, akawapa wanafunzi, wanafunzi wakawapa makutano."}, {"r": "Luka 6:28", "t": "wabarikieni wale ambao wawalaani ninyi, waombeeni wale ambao wawaonea ninyi."}, {"r": "Wagalatia 4:15", "t": "Ku wapi, basi, kule kujiita heri? Maana nawashuhudu kwamba, kama ingaliwezekana, mngaling'oa macho yenu, mkanipa mimi."}, {"r": "Ufunuo wa Yohana 5:12", "t": "wakisema kwa sauti kuu, Astahili MwanaKondoo aliyechinjwa, kuupokea uweza na utajiri na hekima na nguvu na heshima na utukufu na baraka."}, {"r": "Ayubu 29:11", "t": "Maana sikio liliponisikia, ndipo likanibarikia; Na jicho liliponiona, likanishuhudia."}, {"r": "Mhubiri 8:13", "t": "walakini haitakuwa heri kwa mwovu, wala hatazidisha siku zake, zilizo kama kivuli; kwa sababu hana kicho mbele za Mungu."}, {"r": "1 Wakorintho 7:40", "t": "Lakini heri yeye zaidi akikaa kama alivyo; ndivyo nionavyo mimi, nami nadhani ya kuwa mimi nami nina Roho wa Mungu."}, {"r": "Zaburi 3:8", "t": "Wokovu una Bwana; Baraka yako na iwe juu ya watu wako."}, {"r": "Kumbukumbu la Torati 33:1", "t": "Hii ndiyo baraka ya Musa, huyo mtu wa Mungu, aliyowabarikia wana wa Israeli kabla ya kufa kwake."}, {"r": "Warumi 4:8", "t": "Heri mtu yule ambaye Bwana hamhesabii dhambi."}, {"r": "Mithali 8:34", "t": "Ana heri mtu yule anisikilizaye, Akisubiri sikuzote malangoni pangu, Akingoja penye vizingiti vya milango yangu."}, {"r": "Zaburi 112:2", "t": "Wazao wake watakuwa hodari duniani; Kizazi cha wenye adili kitabarikiwa."}, {"r": "Hesabu 14:2", "t": "Kisha wana wa Israeli wote wakamnung'unikia Musa na Haruni; mkutano wote wakawaambia, Ingekuwa heri kama tungalikufa katika nchi ya Misri, au, ingekuwa heri kama tungalikufa katika jangwa hili."}, {"r": "Mhubiri 6:9", "t": "Heri kuona kwa macho, Kuliko kutangatanga kwa tamaa."}, {"r": "Matendo ya Mitume 3:25", "t": "Ninyi mmekuwa watoto wa manabii na wa maagano yale, ambayo Mungu aliagana na baba zenu, akimwambia Ibrahimu, Katika uzao wako kabila zote za ulimwengu zitabarikiwa."}, {"r": "Marko 10:16", "t": "Akawakumbatia, akaweka mikono yake juu yao, akawabarikia."}, {"r": "Zaburi 133:3", "t": "Kama umande wa Hermoni ushukao milimani pa Sayuni. Maana ndiko Bwana alikoamuru baraka, Naam, uzima hata milele."}, {"r": "Zaburi 128:4", "t": "Tazama, atabarikiwa hivyo, yule amchaye Bwana."}, {"r": "Wagalatia 3:14", "t": "ili kwamba baraka ya Ibrahimu iwafikilie Mataifa katika Yesu Kristo, tupate kupokea ahadi ya Roho kwa njia ya imani."}, {"r": "Mithali 16:20", "t": "Atakayelitafakari neno atapata mema; Na kila amwaminiye Bwana ana heri."}, {"r": "Mhubiri 8:12", "t": "Ajapokuwa mwenye dhambi amefanya maovu mara mia, akazidisha siku zake; lakini hata hivyo najua hakika ya kwamba itakuwa heri kwao wamchao Mungu, wenye kicho mbele zake;"}, {"r": "Mithali 3:18", "t": "Yeye ni mti wa uzima kwao wamshikao sana; Ana heri kila mtu ashikamanaye naye."}, {"r": "1 Wakorintho 14:16", "t": "Kwa maana wewe ukibariki kwa roho, yeye aketiye katika mahali pa mjinga ataitikaje, Amina, baada ya kushukuru kwako, akiwa hayajui usemayo?"}, {"r": "Zaburi 107:38", "t": "Naye huwabariki wakaongezeka sana, Wala hayapunguzi makundi yao."}, {"r": "Zaburi 109:28", "t": "Wao walaani, bali Wewe utabariki, Wameondoka wao wakaaibishwa, Bali mtumishi wako atafurahi."}, {"r": "Zaburi 84:5", "t": "Heri ambaye nguvu zake zatoka kwako, Na njia ziendazo Sayuni zimo moyoni mwake."}, {"r": "Zaburi 144:15", "t": "Heri watu wenye hali hiyo, Heri watu wenye Bwana kuwa Mungu wao."}, {"r": "Zaburi 28:9", "t": "Uwaokoe watu wako, uubariki urithi wako, Uwachunge, uwachukue milele."}, {"r": "1 Petro 4:14", "t": "Mkilaumiwa kwa ajili ya jina la Kristo ni heri yenu; kwa kuwa Roho wa utukufu na wa Mungu anawakalia."}, {"r": "Waebrania 12:17", "t": "Maana mwajua ya kuwa hata alipotaka baadaye kuirithi baraka, alikataliwa (maana hakuona nafasi ya kutubu), ijapokuwa aliitafuta sana kwa machozi."}, {"r": "Mithali 10:6", "t": "Baraka humkalia mwenye haki kichwani; Bali jeuri hufunika kinywa chake mtu mwovu."}, {"r": "Ayubu 1:10", "t": "Wewe hukumzingira kwa ukigo pande zote, pamoja na nyumba yake, na vitu vyote alivyo navyo? Kazi za mikono yake umezibarikia, nayo mali yake imeongezeka katika nchi."}, {"r": "Ayubu 42:12", "t": "Basi hivyo Bwana akaubarikia huo mwisho wa Ayubu zaidi ya mwanzo wake; naye alikuwa na kondoo kumi na nne elfu, na ngamia elfu sita, na jozi za ng'ombe elfu, na punda wake elfu."}, {"r": "Yoeli 2:14", "t": "N'nani ajuaye kwamba hatarudi na kugeuka, na kutuachia baraka nyuma yake, naam, sadaka ya unga, na sadaka ya kinywaji, kwa Bwana, Mungu wenu?"}, {"r": "Luka 12:38", "t": "Na akija zamu ya pili, au akija zamu ya tatu, na kuwakuta hivi, heri watumwa hao."}, {"r": "1 Wakorintho 4:12", "t": "kisha twataabika tukifanya kazi kwa mikono yetu wenyewe. Tukitukanwa twabariki, tukiudhiwa twastahimili;"}, {"r": "Ayubu 1:21", "t": "akasema, Mimi nilitoka tumboni mwa mama yangu nili uchi, nami nitarudi tena huko uchi vilevile; Bwana alitoa, na Bwana ametwaa; jina la Bwana na libarikiwe."}, {"r": "Zaburi 128:2", "t": "Taabu ya mikono yako hakika utaila; Utakuwa heri, na kwako kwema."}, {"r": "1 Wakorintho 7:8", "t": "Lakini nawaambia wale wasiooa bado, na wajane, Ni heri wakae kama mimi nilivyo."}, {"r": "Mwanzo 49:28", "t": "Hizo zote ndizo kabila za Israeli kumi na mbili. Na hayo ndiyo aliyowaambia baba yao, na kuwabariki; mmoja mmoja kwa mbaraka wake aliwabariki."}, {"r": "Mithali 22:1", "t": "Heri kuchagua jina jema kuliko mali nyingi; Na neema kuliko fedha na dhahabu."}, {"r": "Mithali 3:13", "t": "Heri mtu yule aonaye hekima, Na mtu yule apataye ufahamu."}, {"r": "Zaburi 137:9", "t": "Heri yeye atakayewakamata wadogo wako, Na kuwaseta wao juu ya mwamba."}, {"r": "Zaburi 32:1", "t": "Heri aliyesamehewa dhambi, Na kusitiriwa makosa yake."}, {"r": "Mathayo 25:34", "t": "Kisha Mfalme atawaambia wale walioko mkono wake wa kuume, Njoni, mliobarikiwa na Baba yangu, urithini ufalme mliowekewa tayari tangu kuumbwa ulimwengu;"}, {"r": "Ufunuo wa Yohana 7:12", "t": "wakisema, Amina; Baraka na utukufu na hekima na shukrani na heshima na uweza na nguvu zina Mungu wetu hata milele na milele. Amina."}, {"r": "Zaburi 118:9", "t": "Ni heri kumkimbilia Bwana. Kuliko kuwatumainia wakuu."}, {"r": "Mwanzo 30:13", "t": "Lea akasema, Ni heri mimi, maana wanawake wataniita heri. Akamwita jina lake Asheri."}, {"r": "2 Samueli 7:29", "t": "basi, sasa, uwe radhi, ukaibarikie nyumba ya mtumwa wako, ipate kudumu milele mbele zako; kwa maana wewe, Ee Bwana MUNGU, umelinena na kwa baraka yako nyumba ya mtumwa wako na ibarikiwe milele."}, {"r": "Mathayo 5:10", "t": "Heri wenye kuudhiwa kwa ajili ya haki; Maana ufalme wa mbinguni ni wao."}, {"r": "Warumi 14:22", "t": "Ile imani uliyo nayo uwe nayo nafsini mwako mbele za Mungu. Heri mtu yule asiyejihukumu nafsi yake katika neno lile analolikubali."}, {"r": "Marko 11:10", "t": "umebarikiwa na ufalme ujao, wa baba yetu Daudi. Hosana juu mbinguni."}, {"r": "Warumi 4:7", "t": "Heri waliosamehewa makosa yao, Na waliositiriwa dhambi zao."}, {"r": "Mithali 28:20", "t": "Mtu mwaminifu atakuwa na baraka tele; Lakini afanyaye haraka kuwa tajiri hakosi ataadhibiwa."}, {"r": "Luka 7:23", "t": "Naye heri mtu ye yote asiyechukizwa nami."}, {"r": "Ayubu 29:13", "t": "Baraka yake yeye aliyekuwa karibu na kupotea ilinijia; Nikaufanya moyo wa mjane kuimba kwa furaha."}, {"r": "1 Wakorintho 10:16", "t": "Kikombe kile cha baraka tukibarikicho, je! Si ushirika wa damu ya Kristo? Mkate ule tuumegao, si ushirika wa mwili wa Kristo?"}, {"r": "Luka 14:14", "t": "nawe utakuwa heri, kwa kuwa hao hawana cha kukulipa; kwa maana utalipwa katika ufufuo wa wenye haki."}, {"r": "Isaya 30:18", "t": "Kwa ajili ya hayo Bwana atangoja, ili awaonee huruma, na kwa ajili ya hayo atatukuzwa, ili awarehemu; kwa maana Bwana ni Mungu wa hukumu; heri wote wamngojao."}, {"r": "1 Petro 3:14", "t": "Lakini mjapoteswa kwa sababu ya haki mna heri. Msiogope kutisha kwao, wala msifadhaike; bali mtakaseni Kristo Bwana mioyoni mwenu."}, {"r": "Ayubu 31:20", "t": "Ikiwa viuno vyake havikunibarikia, Au kama hakupata moto kwa manyoya ya kondoo zangu;"}, {"r": "Mithali 8:32", "t": "Basi, wanangu, nisikilizeni sasa; Maana heri hao wazishikao amri zangu."}, {"r": "Warumi 4:9", "t": "Basi je! Uheri huo ni kwa hao waliotahiriwa, au kwa hao pia wasiotahiriwa? Kwa kuwa twanena ya kwamba kwake Ibrahimu imani yake ilihesabiwa kuwa ni haki."}, {"r": "Zaburi 127:5", "t": "Heri mtu yule Aliyelijaza podo lake hivyo. Naam, hawataona aibu Wanaposema na adui langoni."}, {"r": "Zaburi 112:5", "t": "Heri atendaye fadhili na kukopesha; Atengenezaye mambo yake kwa haki."}, {"r": "Zaburi 21:3", "t": "Maana umemsogezea baraka za heri, Umemvika taji ya dhahabu safi kichwani pake."}, {"r": "Isaya 65:16", "t": "Hata itakuwa yeye atakayejibariki duniani, atajibariki kwa Mungu wa kweli; naye atakayeapa duniani, ataapa kwa Mungu wa kweli. Kwa kuwa taabu za kwanza zimesahauliwa, na kwa kuwa zimefichwa machoni pangu."}, {"r": "Zaburi 33:12", "t": "Heri taifa ambalo Bwana ni Mungu wao, Watu aliowachagua kuwa urithi wake."}, {"r": "Mathayo 11:6", "t": "Naye heri awaye yote asiyechukizwa nami."}, {"r": "Mhubiri 7:1", "t": "Heri sifa njema kuliko marhamu nzuri; Na siku ya kufa kuliko siku ya kuzaliwa."}, {"r": "1 Wafalme 10:8", "t": "Heri watu wako, na heri watumishi hawa wako, wasimamao mbele yako siku zote, wakisikia hekima yako."}, {"r": "Zaburi 118:26", "t": "Na abarikiwe yeye ajaye kwa jina la Bwana; Tumewabarikia toka nyumbani mwa Bwana."}, {"r": "Zaburi 62:4", "t": "Hufanya shauri kumwangusha tu katika cheo chake; Huufurahia uongo. Kwa kinywa chao hubariki; Kwa moyo wao hulaani."}, {"r": "Mithali 3:33", "t": "Laana ya Bwana i katika nyumba ya waovu, Bali huibariki maskani ya mwenye haki."}, {"r": "Mithali 14:21", "t": "Amdharauye mwenzake afanya dhambi; Bali amhurumiaye maskini ana heri."}, {"r": "Hesabu 23:20", "t": "Tazama, nimepewa amri kubariki, Yeye amebariki, nami siwezi kulitangua."}, {"r": "Mathayo 5:11", "t": "Heri ninyi watakapowashutumu na kuwaudhi na kuwanenea kila neno baya kwa uongo, kwa ajili yangu."}, {"r": "Mithali 5:18", "t": "Chemchemi yako ibarikiwe; Nawe umfurahie mke wa ujana wako."}, {"r": "Luka 12:37", "t": "Heri watumwa wale, ambao bwana wao ajapo atawakuta wanakesha. Amin, nawaambieni, atajifunga na kuwakaribisha chakulani, atakuja na kuwahudumia."}, {"r": "Zaburi 115:13", "t": "Atawabariki wamchao Bwana, Wadogo kwa wakubwa."}, {"r": "Zaburi 84:6", "t": "Wakipita kati ya bonde la Vilio, Hulifanya kuwa chemchemi, Naam, mvua ya vuli hulivika baraka"}, {"r": "Yakobo 5:11", "t": "Angalieni, twawaita heri wao waliosubiri. Mmesikia habari ya subira yake Ayubu, mmeuona mwisho wa Bwana ya kwamba Bwana ni mwingi wa rehema, mwenye huruma."}, {"r": "Mwanzo 48:20", "t": "Akawabariki siku ile akasema, Katika ninyi Waisraeli watabariki, wakisema, Mungu na akufanye kama Efraimu na Manase. Akamweka Efraimu mbele ya Manase."}, {"r": "Warumi 15:29", "t": "Nami najua ya kuwa nikija kwenu nitakuja kwa utimilifu wa baraka ya Kristo."}, {"r": "Mithali 11:26", "t": "Awanyimaye watu nafaka, watu watamlaani; Auzaye nafaka, baraka itakuwa kichwani pake."}, {"r": "Mhubiri 7:8", "t": "Heri mwisho wa neno kuliko mwanzo wake, Na mvumilivu rohoni kuliko mwenye roho ya kiburi."}, {"r": "Tito 2:13", "t": "tukilitazamia tumaini lenye baraka na mafunuo ya utukufu wa Kristo Yesu, Mungu mkuu na Mwokozi wetu;"}, {"r": "Yeremia 31:23", "t": "Bwana wa majeshi, Mungu wa Israeli, asema hivi, Watatumia tena neno hili katika nchi ya Yuda, na katika miji yake, nitakapowarudisha mateka yao; Bwana na akubariki, Ee kao la haki, Ee mlima wa utakatifu."}, {"r": "Zaburi 134:3", "t": "Bwana akubariki toka Sayuni, Aliyezifanya mbingu na nchi."}, {"r": "Zaburi 34:8", "t": "Onjeni mwone ya kuwa Bwana yu mwema; Heri mtu yule anayemtumaini."}, {"r": "Isaya 19:25", "t": "kwa kuwa Bwana wa majeshi amewabariki, akisema, Wabarikiwe watu wangu Misri; na wewe Ashuru, kazi ya mikono yangu; na wewe Israeli, urithi wangu."}, {"r": "Zaburi 106:3", "t": "Heri washikao hukumu, Na kutenda haki sikuzote."}, {"r": "Mithali 20:7", "t": "Mwenye haki aendaye katika unyofu wake, Watoto wake wabarikiwa baada yake."}, {"r": "Zaburi 132:15", "t": "Hakika nitavibariki vyakula vyake Wahitaji wake nitawashibisha chakula."}, {"r": "Mwanzo 22:17", "t": "katika kubariki nitakubariki, na katika kuzidisha nitauzidisha uzao wako kama nyota za mbinguni, na kama mchanga ulioko pwani; na uzao wako utamiliki mlango wa adui zao;"}, {"r": "Luka 11:28", "t": "Lakini yeye alisema, Afadhali, heri walisikiao neno la Mungu na kulishika."}, {"r": "Zekaria 8:13", "t": "Kisha itakuwa, kama vile mlivyokuwa laana katika mataifa, Ee nyumba ya Yuda, na nyumba ya Israeli, ndivyo nitakavyowaokoa, nanyi mtakuwa baraka; msiogope, lakini mikono yenu na iwe hodari."}, {"r": "Waebrania 6:7", "t": "Maana nchi inayoinywa mvua inayoinyeshea mara kwa mara, na kuzaa mboga zenye manufaa kwa hao ambao kwa ajili yao yalimwa, hushiriki baraka zitokazo kwa Mungu;"}, {"r": "Mhubiri 4:6", "t": "Heri konzi moja pamoja na utulivu, Kuliko konzi mbili pamoja na taabu;"}, {"r": "Waefeso 6:3", "t": "Upate heri, ukae siku nyingi katika dunia."}, {"r": "Ufunuo wa Yohana 16:15", "t": "(Tazama, naja kama mwivi. Heri akeshaye, na kuyatunza mavazi yake, asiende uchi hata watu wakaione aibu yake.)"}, {"r": "1 Samueli 25:33", "t": "na ibarikiwe busara yako, na ubarikiwe wewe, uliyenizuia hivi leo nisimwage damu, wala kujilipiza kisasi kwa mkono wangu mwenyewe."}, {"r": "Zaburi 21:6", "t": "Maana umemfanya kuwa baraka za milele, Wamfurahisha kwa furaha ya uso wako."}, {"r": "Zaburi 67:7", "t": "Mungu atatubariki sisi; Miisho yote ya dunia itamcha Yeye."}, {"r": "Malaki 3:12", "t": "Na mataifa yote watawaiteni heri; maana mtakuwa nchi ya kupendeza sana, asema Bwana wa majeshi."}, {"r": "Mathayo 26:24", "t": "Mwana wa Adamu aenda zake, kama alivyoandikiwa; lakini ole wake mtu yule ambaye amsaliti Mwana wa Adamu! Ingekuwa heri kwake mtu yule kama asingalizaliwa."}, {"r": "Isaya 65:8", "t": "Bwana asema hivi, Kama vile divai mpya ipatikanavyo katika kichala, na mtu mmoja husema, Usikiharibu kwa maana mna baraka ndani yake; ndivyo nitakavyotenda kwa ajili ya watumishi wangu, ili nisiwaharibu wote."}, {"r": "Yeremia 4:2", "t": "nawe utaapa hivi, Kama Bwana aishivyo, katika kweli, na katika hukumu, na katika haki ndipo mataifa watajibariki katika yeye, nao watajitukuza katika yeye."}, {"r": "Kumbukumbu la Torati 7:13", "t": "naye atakupenda na kukubarikia na kukuongeza tena ataubarikia uzao wa tumbo lako, na uzao wa nchi yako, nafaka zako na divai yako, na mafuta yako, maongeo ya ng'ombe zako, na wadogo wa kondoo zako, katika nchi aliyowaapia baba zako kuwa atakupa."}, {"r": "Zaburi 24:5", "t": "Atapokea baraka kwa Bwana, Na haki kwa Mungu wa wokovu wake."}, {"r": "1 Wakorintho 9:15", "t": "Lakini mimi sikutumia mambo hayo hata moja. Wala siyaandiki hayo ili iwe hivyo kwangu mimi; maana ni heri nife kuliko mtu awaye yote abatilishe huku kujisifu kwangu."}, {"r": "Matendo ya Mitume 26:2", "t": "Najiona nafsi yangu kuwa na heri, Ee mfalme Agripa, kwa kuwa nitajitetea mbele yako leo, katika mambo yale yote niliyoshitakiwa na Wayahudi."}, {"r": "Yeremia 14:11", "t": "Naye Bwana akaniambia, Usiwaombee watu hawa wapate heri."}, {"r": "Zaburi 128:1", "t": "Heri kila mtu amchaye Bwana, Aendaye katika njia yake."}, {"r": "Waebrania 7:7", "t": "Wala haikanushiki kabisa kwamba mdogo hubarikiwa na mkubwa."}, {"r": "Mhubiri 7:2", "t": "Heri kuiendea nyumba ya matanga, Kuliko kuiendea nyumba ya karamu. Kwa maana huo ndio mwisho wa wanadamu wote, naye aliye hai atautia moyoni mwake."}, {"r": "Zaburi 119:1", "t": "Heri walio kamili njia zao, Waendao katika sheria ya Bwana."}, {"r": "Mhubiri 10:17", "t": "Heri kwako, nchi, mfalme wako akiwa mtoto wa watu, Na wakuu wako hula wakati ufaao, Ili makusudi wapate nguvu, wala si kwa ajili ya ulevi."}, {"r": "Zaburi 41:1", "t": "Heri amkumbukaye mnyonge; Bwana atamwokoa siku ya taabu."}, {"r": "Luka 12:43", "t": "Heri mtumwa yule, ambaye bwana wake ajapo atamkuta anafanya hivyo."}, {"r": "Warumi 12:14", "t": "Wabarikini wanaowaudhi; barikini, wala msilaani."}, {"r": "Ufunuo wa Yohana 22:14", "t": "Heri wazifuao nguo zao, wawe na amri kuuendea huo mti wa uzima, na kuingia mjini kwa milango yake."}, {"r": "Zaburi 96:2", "t": "Mwimbieni Bwana, libarikini jina lake, Tangazeni wokovu wake siku kwa siku."}, {"r": "Isaya 3:10", "t": "Waambieni wenye haki ya kuwa watakuwa heri, kwa maana watakula matunda ya matendo yao"}, {"r": "1 Wakorintho 7:1", "t": "Basi kwa habari ya mambo yale mliyoandika, ni heri mwanamume asimguse mwanamke."}, {"r": "Zaburi 67:6", "t": "Nchi imetoa mazao yake MUNGU, Mungu wetu, ametubariki."}, {"r": "Zaburi 72:17", "t": "Jina lake na lidumu milele, Pindi ling'aapo jua jina lake liwe na wazao; Mataifa yote na wajibariki katika yeye, Na kumwita heri."}, {"r": "Zaburi 40:4", "t": "Heri aliyemfanya Bwana kuwa tumaini lake, Wala hakuwaelekea wenye kiburi, Wala hao wanaogeukia uongo."}, {"r": "Isaya 61:9", "t": "Na kizazi chao kitajulikana katika mataifa, na uzao wao katika kabila za watu; wote wawaonao watakiri ya kuwa wao ni kizazi kilichobarikiwa na Bwana."}, {"r": "Luka 24:51", "t": "Ikawa katika kuwabariki, alijitenga nao; akachukuliwa juu mbinguni."}, {"r": "Mithali 27:5", "t": "Lawama ya wazi ni heri, Kuliko upendo uliositirika."}, {"r": "1 Mambo ya Nyakati 17:27", "t": "nawe sasa umekuwa radhi kuibarikia nyumba ya mtumwa wako, ipate kudumu milele mbele zako; kwa maana wewe, Bwana, umebarikia, nayo imebarikiwa milele."}, {"r": "Mwanzo 49:25", "t": "Naam, kwa Mungu wa baba yako atakaye kusaidia; Kwa mibaraka ya mbinguni juu. Mibaraka ya vilindi vilivyo chini, Mibaraka ya maziwa, na ya mimba."}, {"r": "Zaburi 118:8", "t": "Ni heri kumkimbilia Bwana Kuliko kuwatumainia wanadamu."}, {"r": "Luka 6:21", "t": "Heri ninyi mlio na njaa sasa, kwa sababu mtashiba. Heri ninyi mliao sasa, kwa sababu mtacheka."}, {"r": "Waebrania 6:14", "t": "akisema, Hakika yangu kubariki nitakubariki, na kuongeza nitakuongeza."}, {"r": "Matendo ya Mitume 20:35", "t": "Katika mambo yote nimewaonyesha ya kuwa kwa kushika kazi hivi imewapasa kuwasaidia wanyonge, na kuyakumbuka maneno ya Bwana Yesu, jinsi alivyosema mwenyewe, Ni heri kutoa kuliko kupokea."}, {"r": "Zaburi 119:2", "t": "Heri wazitiio shuhuda zake, Wamtafutao kwa moyo wote."}, {"r": "Mithali 24:25", "t": "Bali kwao wakemeao furaha itakuwako; Na baraka ya kufanikiwa itawajilia."}, {"r": "Zaburi 95:7", "t": "Kwa maana ndiye Mungu wetu, Na sisi tu watu wa malisho yake, Na kondoo za mkono wake. Ingekuwa heri leo msikie sauti yake!"}, {"r": "Isaya 44:3", "t": "Kwa maana nitamimina maji juu yake aliye na kiu, na vijito vya maji juu ya mahali pakavu; nitamwaga roho yangu juu ya wazao wako, na baraka yangu juu yao utakaowazaa;"}, {"r": "2 Wakorintho 13:11", "t": "Hatimaye, ndugu, kwaherini; mtimilike, mfarijike, nieni mamoja, mkae katika amani; na Mungu wa upendo na amani atakuwa pamoja nanyi."}, {"r": "Marko 8:7", "t": "Walikuwa na visamaki vichache; akavibarikia, akasema wawaandikie na hivyo pia."}, {"r": "Ufunuo wa Yohana 1:3", "t": "Heri asomaye na wao wayasikiao maneno ya unabii huu, na kuyashika yaliyoandikwa humo; kwa maana wakati u karibu."}, {"r": "Yakobo 3:10", "t": "Katika kinywa kile kile hutoka baraka na laana. Ndugu zangu, haifai mambo hayo kuwa hivyo."}, {"r": "2 Petro 2:21", "t": "Maana ingekuwa heri kwao kama wasingaliijua njia ya haki, kuliko kuijua, kisha kuiacha ile amri takatifu waliyopewa."}], "faraja": [{"r": "1 Petro 5:7", "t": "huku mkimtwika yeye fadhaa zenu zote, kwa maana yeye hujishughulisha sana kwa mambo yenu."}, {"r": "Mathayo 5:4", "t": "Heri wenye huzuni; Maana hao watafarijika."}, {"r": "Zaburi 23:1", "t": "Bwana ndiye mchungaji wangu, Sitapungukiwa na kitu."}, {"r": "Zaburi 34:18", "t": "Bwana yu karibu nao waliovunjika moyo, Na waliopondeka roho huwaokoa."}, {"r": "1 Wathesalonike 5:11", "t": "Basi, farijianeni na kujengana kila mtu na mwenzake, vile vile kama mnavyofanya."}, {"r": "2 Wakorintho 1:3", "t": "Na ahimidiwe Mungu, Baba wa Bwana wetu Yesu Kristo, Baba wa rehema, Mungu wa faraja yote;"}, {"r": "2 Wakorintho 1:4", "t": "atufarijiye katika dhiki zetu zote ili nasi tupate kuwafariji wale walio katika dhiki za namna zote, kwa faraja hizo, tunazofarijiwa na Mungu."}, {"r": "Maombolezo 3:23", "t": "Ni mpya kila siku asubuhi; Uaminifu wako ni mkuu."}, {"r": "1 Wathesalonike 4:18", "t": "Basi, farijianeni kwa maneno hayo."}, {"r": "Ufunuo wa Yohana 21:4", "t": "Naye atafuta kila chozi katika macho yao, wala mauti haitakuwapo tena; wala maombolezo, wala kilio, wala maumivu hayatakuwapo tena; kwa kuwa mambo ya kwanza yamekwisha kupita."}, {"r": "Yeremia 31:13", "t": "Ndipo bikira atafurahi katika kucheza, na vijana na wazee pamoja; maana nitageuza masikitiko yao kuwa furaha, nami nitawafariji, na kuwafurahisha waache huzuni zao."}, {"r": "Zaburi 119:50", "t": "Hii ndiyo faraja yangu katika taabu yangu, Ya kwamba ahadi yako imenihuisha."}, {"r": "Isaya 66:13", "t": "Mfano wa mtu ambaye mama yake amfariji, ndivyo nitakavyowafariji ninyi; nanyi mtafarijiwa katika Yerusalemu."}, {"r": "Mathayo 11:28", "t": "Njoni kwangu, ninyi nyote msumbukao na wenye kulemewa na mizigo, nami nitawapumzisha."}, {"r": "Isaya 43:2", "t": "Upitapo katika maji mengi nitakuwa pamoja nawe; na katika mito, haitakugharikisha; uendapo katika moto, hutateketea; wala mwali wa moto hautakuunguza."}, {"r": "Isaya 40:1", "t": "Watulizeni mioyo, watulizeni mioyo, watu wangu, asema Mungu wenu."}, {"r": "Yohana 14:27", "t": "Amani nawaachieni; amani yangu nawapa; niwapavyo mimi sivyo kama ulimwengu utoavyo. Msifadhaike mioyoni mwenu, wala msiwe na woga."}, {"r": "Zaburi 30:5", "t": "Maana ghadhabu zake ni za kitambo kidogo, Katika radhi yake mna uhai. Huenda kilio huja kukaa usiku, Lakini asubuhi huwa furaha."}, {"r": "Zaburi 55:22", "t": "Umtwike Bwana mzigo wako naye atakutegemeza, Hatamwacha mwenye haki aondoshwe milele."}, {"r": "Maombolezo 3:22", "t": "Ni huruma za Bwana kwamba hatuangamii, Kwa kuwa rehema zake hazikomi."}, {"r": "Zaburi 119:76", "t": "Nakuomba, fadhili zako ziwe faraja kwangu, Sawasawa na ahadi yako kwa mtumishi wako."}, {"r": "Zaburi 94:19", "t": "Katika wingi wa mawazo ya moyoni mwangu, Faraja zako zaifurahisha roho yangu."}, {"r": "Warumi 8:18", "t": "Kwa maana nayahesabu mateso ya wakati huu wa sasa kuwa si kitu kama utukufu ule utakaofunuliwa kwetu."}, {"r": "Zaburi 147:3", "t": "Huwaponya waliopondeka moyo, Na kuziganga jeraha zao."}, {"r": "Isaya 41:10", "t": "usiogope, kwa maana mimi ni pamoja nawe; usifadhaike, kwa maana mimi ni Mungu wako; nitakutia nguvu, naam, nitakusaidia, naam, nitakushika kwa mkono wa kuume wa haki yangu."}, {"r": "Zaburi 23:4", "t": "Naam, nijapopita kati ya bonde la uvuli wa mauti, Sitaogopa mabaya; Kwa maana Wewe upo pamoja nami, Gongo lako na fimbo yako vyanifariji."}, {"r": "Yohana 14:18", "t": "Sitawaacha ninyi yatima; naja kwenu."}, {"r": "Yohana 14:1", "t": "Msifadhaike mioyoni mwenu; mnamwamini Mungu, niaminini na mimi."}, {"r": "Warumi 8:28", "t": "Nasi twajua ya kuwa katika mambo yote Mungu hufanya kazi pamoja na wale wampendao katika kuwapatia mema, yaani, wale walioitwa kwa kusudi lake."}, {"r": "Mithali 15:18", "t": "Mtu wa hasira huchochea ugomvi; Bali asiye mwepesi wa hasira hutuliza mashindano."}, {"r": "Ayubu 15:11", "t": "Je! Utulizi wa Mungu ni mdogo sana kwako, Na hilo neno la upole si kitu kwako?"}, {"r": "2 Wathesalonike 2:17", "t": "awafariji mioyo yenu, na kuwafanya imara katika kila neno na tendo jema."}, {"r": "2 Wakorintho 1:5", "t": "Kwa kuwa kama vile mateso ya Kristo yanavyozidi kwetu, vivyo hivyo faraja yetu inazidi kwa njia ya Kristo."}, {"r": "Isaya 51:3", "t": "Maana Bwana ameufariji Sayuni; amepafariji mahali pake palipokuwa ukiwa; amefanya jangwa lake kuwa kama bustani ya Edeni, na nyika yake kama bustani ya Bwana; furaha na kicheko zitaonekana ndani yake, kushukuru, na sauti ya kuimba."}, {"r": "Zekaria 1:13", "t": "Naye Bwana akamjibu yule malaika aliyesema nami kwa maneno mazuri, maneno yenye faraja."}, {"r": "1 Yohana 5:15", "t": "Na kama tukijua kwamba atusikia, tuombacho chote, twajua kwamba tunazo zile haja tulizomwomba."}, {"r": "2 Wakorintho 7:7", "t": "Wala si kwa kuja kwake tu, bali kwa zile faraja nazo alizofarijiwa kwenu, akituarifu habari ya shauku yenu, na maombolezo yenu, na bidii yenu kwa ajili yangu, hata nikazidi kufurahi."}, {"r": "Isaya 12:1", "t": "Na katika siku hiyo utasema, Ee Bwana, nitakushukuru wewe; Kwa kuwa ijapokuwa ulinikasirikia, Hasira yako imegeukia mbali, Nawe unanifariji moyo."}, {"r": "Zaburi 107:29", "t": "Huituliza dhoruba, ikawa shwari, Mawimbi yake yakanyamaza."}, {"r": "Matendo ya Mitume 19:35", "t": "Na karani wa mji alipokwisha kuwatuliza watu, akasema, Enyi wanaume wa Efeso, ni mtu gani asiyejua ya kuwa mji wa Efeso ni mtunzaji wa hekalu la Artemi, aliye mkuu, na wa kitu kile kilichoanguka kutoka mbinguni?"}, {"r": "Isaya 66:11", "t": "mpate kunyonya, na kushibishwa kwa maziwa ya faraja zake, mpate kukama, na kufurahiwa kwa wingi wa utukufu wake."}, {"r": "Isaya 49:13", "t": "Imbeni, enyi mbingu; ufurahi, Ee nchi; Pazeni sauti ya kuimba, enyi milima; Kwa kuwa Bwana amewafariji watu wake, Naye atawahurumia watu wake walioteswa."}, {"r": "Nahumu 3:7", "t": "Hata itakuwa, wote wakutazamao watakukimbia, wakisema, Ninawi umeharibika; ni nani atakayeuhurumia? Nikutafutie wapi wafariji?"}, {"r": "Wakolosai 4:11", "t": "Na Yesu aitwaye Yusto; hao ni watu wa tohara. Tena hao peke yao ni watendaji wa kazi pamoja nami kwa ajili ya ufalme wa Mungu; nao walikuwa faraja kwangu."}, {"r": "Ayubu 29:25", "t": "Niliwachagulia njia, nikakaa kama mkuu wao. Nikakaa kama mfalme katika jeshi la askari, Mfano wa awafarijiye hao waombolezao."}, {"r": "Warumi 15:5", "t": "Na Mungu mwenye saburi na faraja awajalie kunia mamoja ninyi kwa ninyi, kwa mfano wa Kristo Yesu;"}, {"r": "Matendo ya Mitume 20:12", "t": "Wakamleta yule kijana, yu mzima, wakafarijika faraja kubwa sana."}, {"r": "Mathayo 2:18", "t": "Sauti ilisikiwa Rama, Kilio, na maombolezo mengi, Raheli akiwalilia watoto wake, Asikubali kufarijiwa, kwa kuwa hawako."}, {"r": "Zaburi 71:21", "t": "Laiti ungeniongezea ukuu! Urejee tena na kunifariji moyo."}, {"r": "1 Wakorintho 14:31", "t": "Kwa maana ninyi nyote mwaweza kuhutubu mmoja mmoja, ili wote wapate kujifunza, na wote wafarijiwe."}, {"r": "Isaya 1:24", "t": "Kwa hiyo, asema Bwana, Bwana wa majeshi, Mwenye enzi, wa Israeli, Nitapata faraja kwa hao wanipingao, nitatwaa kisasi kwa adui zangu;"}, {"r": "Ayubu 16:2", "t": "Nimesikia maneno mengi mfano wa hayo; Ninyi nyote ni wafariji wenye kutaabisha."}, {"r": "Warumi 1:12", "t": "yaani, tufarijiane mimi na ninyi, kila mtu kwa imani ya mwenzake, yenu na yangu."}, {"r": "Zaburi 77:2", "t": "Siku ya taabu yangu nalimtafuta Bwana; Mkono wangu ulinyoshwa usiku, haukulegea; Nafsi yangu ilikataa kufarijika."}, {"r": "2 Wakorintho 1:7", "t": "Na tumaini letu kwa ajili yenu ni imara, tukijua ya kuwa kama vile mlivyo washiriki wa yale mateso, vivyo hivyo mmekuwa washiriki wa zile faraja."}, {"r": "Zaburi 86:17", "t": "Unifanyie ishara ya wema, Wanichukiao waione na kuaibishwa. Kwa kuwa Wewe, Bwana, Umenisaidia na kunifariji."}, {"r": "Zaburi 89:9", "t": "Wewe ndiwe ukitawalaye kiburi cha bahari. Mawimbi yake yainukapo wayatuliza Wewe."}, {"r": "Matendo ya Mitume 20:2", "t": "Naye akiisha kupita pande zile na kuwafariji kwa maneno mengi, akafika Uyunani."}, {"r": "Waebrania 6:18", "t": "ili kwa vitu viwili visivyoweza kubadilika, ambavyo katika hivyo Mungu hawezi kusema uongo, tupate faraja iliyo imara, sisi tuliokimbilia kuyashika matumaini yale yawekwayo mbele yetu;"}, {"r": "Maombolezo 2:13", "t": "Nikushuhudie nini? Nikufananishe na nini, Ee Binti Yerusalemu? Nikusawazishe na nini, nipate kukufariji, Ee bikira binti Sayuni? Kwa maana uvunjifu wako ni mkuu kama bahari, Ni nani awezaye kukuponya?"}, {"r": "Matendo ya Mitume 16:40", "t": "Nao wakatoka gerezani wakaingia nyumbani mwa Lidia; na walipokwisha kuonana na ndugu wakawafariji, wakaenda zao."}, {"r": "Wafilipi 2:19", "t": "Walakini natumaini katika Bwana Yesu kumtuma Timotheo afike kwenu karibu, nifarijiwe na mimi, nikiijua hali yenu."}, {"r": "Luka 2:25", "t": "Na tazama, pale Yerusalemu palikuwa na mtu, jina lake Simeoni, naye ni mtu mwenye haki, mcha Mungu, akiitarajia faraja ya Israeli; na Roho Mtakatifu alikuwa juu yake."}, {"r": "Isaya 57:18", "t": "Nimeziona njia zake; nami nitamponya; nitamwongoza pia, nitamrudishia faraja zake, yeye na hao wanaomlilia."}, {"r": "Zekaria 6:8", "t": "Ndipo akaniita, akaniambia akisema, Tazama, wale waendao mpaka nchi ya kaskazini wameituliza roho yangu katika nchi ya kaskazini."}, {"r": "2 Wakorintho 7:6", "t": "Lakini Mungu, mwenye kuwafariji wanyonge, alitufariji kwa kuja kwake Tito."}, {"r": "Yeremia 8:18", "t": "Laiti ningeweza kujifariji, nisione huzuni! Moyo wangu umezimia ndani yangu."}, {"r": "Mithali 16:14", "t": "Hasira ya mfalme ni kama wajumbe wa mauti; Lakini mtu mwenye hekima ataituliza."}, {"r": "Ayubu 21:2", "t": "Yasikizeni sana maneno yangu; Jambo hili na liwe faraja yenu."}, {"r": "Yeremia 44:25", "t": "Bwana wa majeshi, Mungu wa Israeli, asema hivi, Ninyi na wake zenu mmenena kwa vinywa vyenu, na kutimiza kwa mikono yenu, mkisema, Bila shaka tutazitimiza nadhiri zetu tulizoziweka, na kumfukizia uvumba malkia wa mbinguni, na kummiminia sadaka za kinywaji; basi, zithibitisheni nadhiri zenu, zitimizeni nadhiri zenu."}, {"r": "Waefeso 6:22", "t": "ambaye nampeleka kwenu kwa kusudi lilo hilo mpate kuzijua habari zetu, naye awafariji mioyo yenu."}, {"r": "2 Wakorintho 1:6", "t": "Lakini ikiwa sisi tu katika dhiki, ni kwa ajili ya faraja yenu na wokovu wenu; au ikiwa twafarijiwa, ni kwa ajili ya faraja yenu; ambayo hutenda kazi yake kwa kustahimili mateso yale yale tuteswayo na sisi."}, {"r": "Yohana 11:19", "t": "na watu wengi katika Wayahudi walikuwa wamekuja kwa Martha na Mariamu, ili kuwafariji kwa habari ya ndugu yao."}, {"r": "Luka 16:25", "t": "Ibrahimu akasema, Mwanangu, kumbuka ya kwamba wewe uliyapokea mambo mema yako katika maisha yako, na Lazaro vivyo alipata mabaya; na sasa yeye yupo hapa anafarijiwa, na wewe unaumizwa."}, {"r": "Zaburi 39:2", "t": "Nalikuwa sisemi, nalinyamaa kimya, Sina faraja, maumivu yangu yakazidi."}, {"r": "Ayubu 6:10", "t": "Hapo ndipo ningefarijika hata sasa; Naam, ningejikuza katika maumivu yasiyoniacha; Kwa kuwa sikuyakana maneno yake Mtakatifu."}, {"r": "Yeremia 16:7", "t": "wala watu hawatamega mkate kwa ajili yao, wakati wa kuomboleza, ili kuwafariji kwa ajili yao waliokufa; wala watu hawatawapa kikombe cha faraja, wanywe kwa ajili ya baba yao au mama yao."}, {"r": "Matendo ya Mitume 15:31", "t": "Nao walipokwisha kuisoma wakafurahi kwa ajili ya faraja ile."}, {"r": "1 Wakorintho 14:3", "t": "Bali yeye ahutubuye, asema na watu maneno ya kuwajenga, na kuwafariji, na kuwatia moyo."}, {"r": "Isaya 61:2", "t": "Kutangaza mwaka wa Bwana uliokubaliwa, na siku ya kisasi cha Mungu wetu; kuwafariji wote waliao;"}, {"r": "Warumi 15:4", "t": "Kwa kuwa yote yaliyotangulia kuandikwa yaliandikwa ili kutufundisha sisi; ili kwa saburi na faraja ya maandiko tupate kuwa na tumaini."}, {"r": "Ayubu 16:5", "t": "Lakini ningewatia nguvu kwa kinywa changu, Na utuzo wa midomo yangu ungetuliza."}, {"r": "Isaya 54:11", "t": "Ewe uliyeteswa, uliyerushwa na tufani, usiyetulizwa, tazama, nitaweka mawe yako kwa rangi nzuri, nitaweka misingi yako kwa yakuti samawi."}, {"r": "Ayubu 16:6", "t": "Nijapokuwa nanena, huzuni yangu haitulizwi; Nijapokuwa najizuia, nimepunguziwa kitu gani?"}, {"r": "1 Wathesalonike 2:17", "t": "Lakini sisi, ndugu, tukiwa tumefarakana nanyi kwa kitambo, kwa uso si kwa moyo, tulizidi kutamani kwa shauku nyingi kuwaona nyuso zenu."}, {"r": "Zekaria 1:17", "t": "Piga kelele tena, na kusema, Bwana wa majeshi asema hivi, Miji yangu kwa kufanikiwa itaenezwa huko na huko tena; naye Bwana ataufariji Sayuni tena, atauchagua Yerusalemu tena."}, {"r": "1 Wathesalonike 3:2", "t": "Tukamtuma Timotheo ndugu yetu, mtumishi wa Mungu katika Injili ya Kristo, ili kuwafanya ninyi imara na kuwafariji kwa habari ya imani yenu;"}, {"r": "2 Wakorintho 7:13", "t": "Kwa hiyo tulifarijiwa. Tena katika kufarijiwa kwetu tulifurahi sana kupita kiasi kwa sababu ya furaha ya Tito; maana roho yake imeburudishwa na ninyi nyote."}, {"r": "Zaburi 119:52", "t": "Nimezikumbuka hukumu zako za kale, Ee Bwana, nikajifariji."}, {"r": "Wakolosai 4:8", "t": "ambaye nimemtuma kwenu kwa sababu iyo hiyo, ili mjue mambo yetu, naye akawafariji mioyo yenu;"}, {"r": "Maombolezo 1:21", "t": "Wamesikia kwamba napiga kite; Hakuna hata mmoja wa kunifariji; Adui zangu wote wamesikia habari ya mashaka yaliyonipata; Hufurahi kwa kuwa umeyafanya hayo; Utaileta siku ile uliyoitangaza, Nao watakuwa kama mimi."}, {"r": "Mithali 21:14", "t": "Kipawa cha siri hutuliza hasira; Na rushwa bindoni humliza ghadhabu kali."}, {"r": "Isaya 51:12", "t": "Mimi, naam, mimi, ndimi niwafarijiye; wewe u nani hata ukamwogopa mtu atakayekufa, na mwanadamu atakayefanywa kuwa kama majani?"}, {"r": "Matendo ya Mitume 6:14", "t": "maana tumemsikia akisema kwamba Yesu huyo Mnazareti atapaharibu mahali hapa, na kuzibadili desturi tulizopewa na Musa."}, {"r": "Wakolosai 2:2", "t": "ili wafarijiwe mioyo yao, wakiunganishwa katika upendo, wakapate utajiri wote wa kufahamu kwa hakika, wapate kujua kabisa siri ya Mungu, yaani, Kristo;"}, {"r": "Zaburi 131:2", "t": "Hakika nimeituliza nafsi yangu, Na kuinyamazisha. Kama mtoto aliyeachishwa Kifuani mwa mama yake; Kama mtoto aliyeachishwa, Ndivyo roho yangu ilivyo kwangu."}, {"r": "2 Wakorintho 7:4", "t": "Ninao ujasiri mwingi kwenu; naona fahari kuu juu yenu. Nimejaa faraja, katika dhiki yetu yote nimejaa furaha ya kupita kiasi."}, {"r": "Zaburi 69:20", "t": "Laumu imenivunja moyo, Nami ninaugua sana. Nikangoja aje wa kunihurumia, wala hakuna; Na wa kunifariji, wala sikumwona mtu."}, {"r": "Isaya 22:4", "t": "Kwa sababu hiyo nasema, Geuza uso wako usinitazame, nipate kulia kwa uchungu; usijishughulishe kunifariji, kwa ajili ya kuharibika kwake binti ya watu wangu."}, {"r": "Isaya 38:13", "t": "Nalijituliza hata asubuhi; kama simba, aivunja mifupa yangu yote; Tangu mchana hata usiku wanimaliza."}, {"r": "Warumi 6:4", "t": "Basi tulizikwa pamoja naye kwa njia ya ubatizo katika mauti yake, kusudi kama Kristo alivyofufuka katika wafu kwa njia ya utukufu wa Baba, vivyo hivyo na sisi tuenende katika upya wa uzima."}, {"r": "Luka 6:24", "t": "Lakini, ole wenu ninyi mlio na mali, kwa kuwa faraja yenu mmekwisha kuipata."}, {"r": "Yeremia 24:6", "t": "Kwa maana nitawatulizia macho yangu, wapate mema, nami nitawaingiza katika nchi hii tena; nami nitawajenga, wala sitawabomoa; nitawapanda wala sitawang'oa."}, {"r": "Filemoni 1:7", "t": "Maana nalikuwa na furaha nyingi na faraja kwa sababu ya upendo wako, kwa kuwa mioyo ya watakatifu imeburudishwa nawe, ndugu yangu."}, {"r": "1 Wathesalonike 3:7", "t": "Kwa sababu hiyo, ndugu, tulifarijiwa kwa habari zenu, katika msiba na dhiki yetu yote, kwa imani yenu."}, {"r": "Zaburi 65:7", "t": "Wautuliza uvumi wa bahari, Uvumi wa mawimbi yake, Na ghasia ya mataifa;"}, {"r": "Matendo ya Mitume 9:31", "t": "Basi kanisa likapata raha katika Uyahudi wote na Galilaya na Samaria, likajengwa, likiendelea na kuongezeka katika kicho cha Bwana, na faraja ya Roho Mtakatifu."}, {"r": "Isaya 52:9", "t": "Pigeni kelele za furaha, imbeni pamoja, Enyi mahali pa Yerusalemu palipokuwa ukiwa; Kwa kuwa Bwana amewafariji watu wake, Ameukomboa Yerusalemu."}], "upendo": [{"r": "Yohana 15:12", "t": "Amri yangu ndiyo hii, Mpendane, kama nilivyowapenda ninyi."}, {"r": "Yohana 13:35", "t": "Hivyo watu wote watatambua ya kuwa ninyi mmekuwa wanafunzi wangu, mkiwa na upendo ninyi kwa ninyi."}, {"r": "Warumi 12:9", "t": "Pendo na lisiwe na unafiki lichukieni lililo ovu, mkiambatana na lililo jema."}, {"r": "1 Wakorintho 13:13", "t": "Basi, sasa inadumu imani, tumaini, upendo, haya matatu; na katika hayo lililo kuu ni upendo."}, {"r": "Zaburi 103:8", "t": "Bwana amejaa huruma na neema, Haoni hasira upesi, ni mwingi wa fadhili."}, {"r": "Yohana 15:13", "t": "Hakuna aliye na upendo mwingi kuliko huu, wa mtu kuutoa uhai wake kwa ajili ya rafiki zake."}, {"r": "Waefeso 3:19", "t": "na kuujua upendo wake Kristo, upitao ufahamu kwa jinsi ulivyo mwingi, mpate kutimilika kwa utimilifu wote wa Mungu."}, {"r": "1 Yohana 4:7", "t": "Wapenzi, na mpendane; kwa kuwa pendo latoka kwa Mungu, na kila apendaye amezaliwa na Mungu, naye anamjua Mungu."}, {"r": "Warumi 13:8", "t": "Msiwiwe na mtu cho chote, isipokuwa kupendana; kwa maana ampendaye mwenzake ameitimiza sheria."}, {"r": "Zaburi 103:11", "t": "Maana mbingu zilivyoinuka juu ya nchi, Kadiri ile ile rehema zake ni kuu kwa wamchao."}, {"r": "Waefeso 5:2", "t": "mkaenende katika upendo, kama Kristo naye alivyowapenda ninyi tena akajitoa kwa ajili yetu, sadaka na dhabihu kwa Mungu, kuwa harufu ya manukato."}, {"r": "1 Yohana 4:11", "t": "Wapenzi ikiwa Mungu alitupenda sisi hivi, imetupasa na sisi kupendana."}, {"r": "Waefeso 3:17", "t": "Kristo akae mioyoni mwenu kwa imani mkiwa na shina na msingi katika upendo;"}, {"r": "Mithali 17:17", "t": "Rafiki hupenda sikuzote; Na ndugu amezaliwa kwa siku ya taabu."}, {"r": "Warumi 13:10", "t": "Pendo halimfanyii jirani neno baya; basi pendo ndilo utimilifu wa sheria."}, {"r": "Warumi 8:38", "t": "Kwa maana nimekwisha kujua hakika ya kwamba, wala mauti, wala uzima, wala malaika, wala wenye mamlaka, wala yaliyopo, wala yatakayokuwapo, wala wenye uwezo,"}, {"r": "Wakolosai 3:14", "t": "Zaidi ya hayo yote jivikeni upendo, ndio kifungo cha ukamilifu."}, {"r": "1 Petro 4:8", "t": "Zaidi ya yote iweni na juhudi nyingi katika kupendana; kwa sababu upendano husitiri wingi wa dhambi."}, {"r": "1 Yohana 3:1", "t": "Tazameni, ni pendo la namna gani alilotupa Baba, kwamba tuitwe wana wa Mungu; na ndivyo tulivyo. Kwa sababu hii ulimwengu haututambui, kwa kuwa haukumtambua yeye."}, {"r": "1 Yohana 4:19", "t": "Sisi twapenda kwa maana yeye alitupenda sisi kwanza."}, {"r": "Waefeso 3:18", "t": "ili mpate kufahamu pamoja na watakatifu wote jinsi ulivyo upana, na urefu, na kimo, na kina;"}, {"r": "1 Yohana 4:8", "t": "Yeye asiyependa, hakumjua Mungu, kwa maana Mungu ni upendo."}, {"r": "Warumi 12:10", "t": "Kwa pendo la udugu, mpendane ninyi kwa ninyi; kwa heshima mkiwatanguliza wenzenu;"}, {"r": "1 Yohana 3:18", "t": "Watoto wadogo, tusipende kwa neno, wala kwa ulimi, bali kwa tendo na kweli."}, {"r": "Yohana 3:16", "t": "Kwa maana jinsi hii Mungu aliupenda ulimwengu, hata akamtoa Mwanawe pekee, ili kila mtu amwaminiye asipotee, bali awe na uzima wa milele."}, {"r": "Yeremia 31:3", "t": "Bwana alinitokea zamani, akisema, Naam nimekupenda kwa upendo wa milele, ndiyo maana nimekuvuta kwa fadhili zangu."}, {"r": "Wimbo Ulio Bora 8:7", "t": "Maji mengi hayawezi kuuzimisha upendo, Wala mito haiwezi kuuzamisha; Kama mtu angetoa badala ya upendo Mali yote ya nyumbani mwake, Angedharauliwa kabisa."}, {"r": "1 Wakorintho 16:14", "t": "Mambo yenu yote na yatendeke katika upendo."}, {"r": "Mathayo 22:37", "t": "Akamwambia, Mpende Bwana Mungu wako kwa moyo wako wote, na kwa roho yako yote, na kwa akili zako zote."}, {"r": "Mithali 10:12", "t": "Kuchukiana huondokesha fitina; Bali kupendana husitiri makosa yote."}, {"r": "1 Wakorintho 13:8", "t": "Upendo haupungui neno wakati wo wote; bali ukiwapo unabii utabatilika; zikiwapo lugha, zitakoma; yakiwapo maarifa, yatabatilika."}, {"r": "1 Wakorintho 13:7", "t": "huvumilia yote; huamini yote; hutumaini yote; hustahimili yote."}, {"r": "1 Yohana 4:10", "t": "Hili ndilo pendo, si kwamba sisi tulimpenda Mungu, bali kwamba yeye alitupenda sisi, akamtuma Mwanawe kuwa kipatanisho kwa dhambi zetu."}, {"r": "Warumi 5:8", "t": "Bali Mungu aonyesha pendo lake yeye mwenyewe kwetu sisi, kwa kuwa Kristo alikufa kwa ajili yetu, tulipokuwa tungali wenye dhambi."}, {"r": "Mathayo 22:39", "t": "Na ya pili yafanana nayo, nayo ni hii, Mpende jirani yako kama nafsi yako."}, {"r": "Warumi 8:39", "t": "wala yaliyo juu, wala yaliyo chini, wala kiumbe kinginecho chote hakitaweza kututenga na upendo wa Mungu ulio katika Kristo Yesu Bwana wetu."}, {"r": "1 Wakorintho 13:4", "t": "Upendo huvumilia, hufadhili; upendo hauhusudu; upendo hautakabari; haujivuni;"}, {"r": "1 Yohana 4:18", "t": "Katika pendo hamna hofu; lakini pendo lililo kamili huitupa nje hofu, kwa maana hofu ina adhabu; na mwenye hofu hakukamilishwa katika pendo."}, {"r": "Zaburi 136:1", "t": "Mshukuruni Bwana kwa kuwa ni mwema; Kwa maana fadhili zake ni za milele."}, {"r": "Yohana 13:34", "t": "Amri mpya nawapa, Mpendane. Kama vile nilivyowapenda ninyi, nanyi mpendane vivyo hivyo."}, {"r": "1 Yohana 4:16", "t": "Nasi tumelifahamu pendo alilo nalo Mungu kwetu sisi, na kuliamini. Mungu ni upendo, naye akaaye katika pendo, hukaa ndani ya Mungu, na Mungu hukaa ndani yake."}, {"r": "Wimbo Ulio Bora 1:4", "t": "Nivute nyuma yako, na tukimbie; Mfalme ameniingiza vyumbani mwake. Tutafurahi na kukushangilia; Tutazinena pambaja zako kuliko divai; Ndiyo, ina haki wakupende."}, {"r": "Waebrania 13:21", "t": "awafanye ninyi kuwa wakamilifu katika kila tendo jema, mpate kuyafanya mapenzi yake, naye akifanya ndani yetu lipendezalo mbele zake, kwa Yesu Kristo; utukufu una yeye milele na milele. Amina."}, {"r": "Zaburi 135:3", "t": "Msifuni Bwana kwa kuwa Bwana ni mwema, Liimbieni jina lake kwa maana lapendeza."}, {"r": "Luka 7:5", "t": "maana, analipenda taifa letu, naye alitujengea sinagogi."}, {"r": "2 Wakorintho 2:8", "t": "Kwa hiyo nawasihi kumthibitishia upendo wenu."}, {"r": "Isaya 56:4", "t": "Kwa maana Bwana awaambia hivi matowashi, wanaozishika sabato zangu, na kuyachagua mambo yanipendezayo, na kulishika sana agano langu;"}, {"r": "Mathayo 6:5", "t": "Tena msalipo, msiwe kama wanafiki; kwa maana wao wapenda kusali hali wamesimama katika masinagogi na katika pembe za njia, ili waonekane na watu. Amin, nawaambia, Wamekwisha kupata thawabu yao."}, {"r": "Warumi 16:12", "t": "Nisalimieni Trifaina na Trifosa, wenye bidii katika Bwana. Nisalimieni Persisi, mpenzi aliyejitahidi sana katika Bwana."}, {"r": "Ufunuo wa Yohana 2:4", "t": "Lakini nina neno juu yako, ya kwamba umeuacha upendo wako wa kwanza."}, {"r": "Zaburi 119:167", "t": "Nafsi yangu imezishika shuhuda zako, Nami nazipenda mno."}, {"r": "Zaburi 105:22", "t": "Awafunge masheki wake kama apendavyo, Na kuwafundisha wazee wake hekima."}, {"r": "Waefeso 1:4", "t": "kama vile alivyotuchagua katika yeye kabla ya kuwekwa misingi ya ulimwengu, ili tuwe watakatifu, watu wasio na hatia mbele zake katika pendo."}, {"r": "Wimbo Ulio Bora 6:1", "t": "Mpendwa wako amekwenda wapi, Wewe uliye mzuri katika wanawake? Mpendwa wako amegeukia upande upi, Ili tumtafute pamoja nawe?"}, {"r": "Wakolosai 1:19", "t": "Kwa kuwa katika yeye ilipendeza utimilifu wote ukae;"}, {"r": "Luka 11:42", "t": "Lakini, ole wenu, Mafarisayo, kwa kuwa mwatoa zaka za mnanaa na mchicha na kila mboga, na huku mwaacha mambo ya adili, na upendo wa Mungu; iliwapasa kuyafanya hayo ya kwanza, bila kuyaacha hayo ya pili."}, {"r": "Zaburi 37:3", "t": "Umtumaini Bwana ukatende mema, Ukae katika nchi, upendezwe na uaminifu."}, {"r": "Waebrania 13:5", "t": "Msiwe na tabia ya kupenda fedha; mwe radhi na vitu mlivyo navyo; kwa kuwa yeye mwenyewe amesema, Sitakupungukia kabisa, wala sitakuacha kabisa."}, {"r": "Isaya 60:10", "t": "Na wageni watajenga kuta zako, Na wafalme wao watakuhudumu; Maana katika ghadhabu yangu nalikupiga, Lakini katika upendeleo wangu nimekurehemu."}, {"r": "Wimbo Ulio Bora 1:14", "t": "Mpendwa wangu ni kama kishada cha hina, Katika mizabibu huko Engedi."}, {"r": "Wimbo Ulio Bora 2:8", "t": "Sikiliza! Ni mpendwa wangu! Tazama, anakuja, Akiruka milimani, akichachawa vilimani."}, {"r": "1 Timotheo 6:10", "t": "Maana shina moja la mabaya ya kila namna ni kupenda fedha; ambayo wengine hali wakiitamani hiyo wamefarakana na Imani, na kujichoma kwa maumivu mengi."}, {"r": "1 Wakorintho 16:7", "t": "Maana sipendi kuonana nanyi sasa, katika kupita tu, kwa sababu nataraji kukaa kwenu muda kidogo, Bwana akinijalia."}, {"r": "Zaburi 45:7", "t": "Umeipenda haki; Umeichukia dhuluma. Kwa hiyo MUNGU, Mungu wako, amekupaka mafuta, Mafuta ya furaha kuliko wenzako."}, {"r": "Wagalatia 5:6", "t": "Maana katika Kristo Yesu kutahiriwa hakufai neno, wala kutokutahiriwa, bali imani itendayo kazi kwa upendo."}, {"r": "1 Wathesalonike 2:5", "t": "Maana hatukuwa na maneno ya kujipendekeza wakati wo wote, kama mjuavyo, wala maneno ya juujuu ya kuficha choyo; Mungu ni shahidi."}, {"r": "Yohana 14:23", "t": "Yesu akajibu, akamwambia, Mtu akinipenda, atalishika neno langu; na Baba yangu atampenda; nasi tutakuja kwake, na kufanya makao kwake."}, {"r": "2 Timotheo 3:4", "t": "wasaliti, wakaidi, wenye kujivuna, wapendao anasa kuliko kumpenda Mungu;"}, {"r": "Mithali 2:14", "t": "Wafurahio kutenda mabaya; Wapendezwao na upotoe wa waovu;"}, {"r": "Zaburi 99:4", "t": "Nguvu za mfalme nazo zapenda hukumu; Wewe ndiwe uliyeithibitisha adili; Ulifanya hukumu na haki katika Yakobo."}, {"r": "1 Yohana 4:9", "t": "Katika hili pendo la Mungu lilionekana kwetu, kwamba Mungu amemtuma Mwanawe pekee ulimwenguni, ili tupate uzima kwa yeye."}, {"r": "Zekaria 7:14", "t": "Lakini nitawatawanya kwa upepo wa kisulisuli, katikati ya mataifa yote wasiowajua. Basi hivyo ndivyo ilivyokuwa ukiwa nchi baada yao, hata hapakuwa na mtu aliyepita kati yake, wala aliyerudi; maana waliifanya nchi iliyopendeza sana kuwa ukiwa."}, {"r": "1 Timotheo 6:11", "t": "Bali wewe, mtu wa Mungu, uyakimbie mambo hayo; ukafuate haki, utauwa, imani, upendo, saburi, upole."}, {"r": "Mithali 29:3", "t": "Apendaye hekima humfurahisha babaye; Bali ashikamanaye na makahaba hutapanya mali."}, {"r": "2 Wakorintho 13:11", "t": "Hatimaye, ndugu, kwaherini; mtimilike, mfarijike, nieni mamoja, mkae katika amani; na Mungu wa upendo na amani atakuwa pamoja nanyi."}, {"r": "Wagalatia 1:10", "t": "Maana, sasa je! Ni wanadamu ninaowashawishi, au Mungu? Au nataka kuwapendeza wanadamu? Kama ningekuwa hata sasa nawapendeza wanadamu, singekuwa mtumwa wa Kristo."}, {"r": "Yakobo 2:1", "t": "Ndugu zangu, imani ya Bwana wetu Yesu Kristo, Bwana wa utukufu, msiwe nayo kwa kupendelea watu."}, {"r": "Warumi 15:27", "t": "Naam, imewapendeza, tena wamekuwa wadeni wao. Kwa maana ikiwa Mataifa wameyashiriki mambo yao ya roho, imewabidi kuwahudumu kwa mambo yao ya mwili."}, {"r": "Isaya 2:16", "t": "na juu ya merikebu zote za Tarshishi, na juu ya kila taswira ipendezayo."}, {"r": "Isaya 42:1", "t": "Tazama mtumishi wangu nimtegemezaye; mteule wangu, ambaye nafsi yangu imependezwa naye; nimetia roho yangu juu yake; naye atawatolea mataifa hukumu."}, {"r": "Maombolezo 1:19", "t": "Naliwaita hao walionipenda Lakini walinidanganya; Makuhani wangu na wazee wangu Walifariki mjini; Hapo walipokuwa wakitafuta chakula ili kuzihuisha nafsi zao."}, {"r": "Yeremia 22:28", "t": "Je! Mtu huyu, Konia, ni chombo kilichodharauliwa, na kuvunjika? Ni chombo kisichopendeza? Mbona wametupwa, yeye na wazao wake, na kutupwa katika nchi wasiyoijua?"}, {"r": "Yeremia 3:19", "t": "Lakini mimi nalisema, Nitawezaje kukuweka pamoja na watoto, na kukupa nchi ipendezayo, urithi ulio mwema wa mataifa? Nami nikasema, Mtaniita, Baba yangu, wala hamtageuka na kuacha kunifuata."}, {"r": "2 Wathesalonike 2:13", "t": "Lakini imetupasa sisi kumshukuru Mungu sikuzote kwa ajili yenu, ndugu mliopendwa na Bwana, kwa kuwa Mungu amewachagua tangu mwanzo mpate wokovu, katika kutakaswa na Roho, na kuiamini kweli;"}, {"r": "Filemoni 1:5", "t": "nikisikia habari za upendo wako na imani uliyo nayo kwa Bwana Yesu na kwa watakatifu wote;"}, {"r": "Wafilipi 4:8", "t": "Hatimaye, ndugu zangu, mambo yo yote yaliyo ya kweli, yo yote yaliyo ya staha, yo yote yaliyo ya haki, yo yote yaliyo safi, yo yote yenye kupendeza, yo yote yenye sifa njema; ukiwapo wema wo wote, ikiwapo sifa nzuri yo yote, yatafakarini hayo."}, {"r": "2 Yohana 1:6", "t": "Na huu ndio upendo: tuenende kwa kuzifuata amri zake. Hii ndiyo ile amri, kama mlivyosikia tangu mwanzo kwamba mwenende katika hiyo."}, {"r": "Wimbo Ulio Bora 2:2", "t": "Kama nyinyoro kati ya miiba, Kadhalika mpenzi wangu kati ya binti."}, {"r": "Hosea 12:7", "t": "Ni mchuuzi, mizani ya udanganyifu i mkononi mwake; anapenda kudhulumu."}, {"r": "Malaki 2:11", "t": "Yuda ametenda kwa hiana, na chukizo limetendeka katika Israeli, na katika Yerusalemu; maana Yuda ameunajisi utakatifu wa Bwana aupendao, naye amemwoa binti ya mungu mgeni."}, {"r": "Isaya 5:7", "t": "Kwa maana shamba la mizabibu la Bwana wa majeshi ndilo nyumba ya Israeli, na watu wa Yuda ni mche wake wa kupendeza; akatumaini kuona hukumu ya haki, na kumbe! Aliona dhuluma; alitumaini kuona haki, na kumbe! Alisikia kilio."}, {"r": "1 Wafalme 10:9", "t": "Na ahimidiwe Bwana, Mungu wako, aliyependezwa nawe, ili akuweke juu ya kiti cha enzi cha Israeli; kwa kuwa Bwana amewapenda Israeli milele, kwa hiyo amekufanya kuwa mfalme, ufanye hukumu na haki."}, {"r": "Zaburi 119:48", "t": "Na mikono yangu nitayainulia maagizo yako niliyoyapenda, Nami nitazitafakari amri zako."}, {"r": "1 Wathesalonike 2:4", "t": "bali kama vile tulivyopata kibali kwa Mungu tuwekewe amana Injili, ndivyo tunenavyo; si kama wapendezao wanadamu, bali wampendezao Mungu anayetupima mioyo yetu."}, {"r": "Isaya 56:6", "t": "Na wageni, walioandamana na Bwana ili wamhudumu, na kulipenda jina la Bwana, kuwa watumishi wake; kila aishikaye sabato asiivunje, na kulishika sana agano langu;"}, {"r": "Wimbo Ulio Bora 1:13", "t": "Mpendwa wangu ni kama mfuko wa manemane Ukilazwa usiku maziwani mwangu."}, {"r": "1 Timotheo 4:12", "t": "Mtu awaye yote asiudharau ujana wako, bali uwe kielelezo kwao waaminio, katika usemi na mwenendo, na katika upendo na imani na usafi."}, {"r": "Hosea 9:1", "t": "Usifurahi, Israeli, kwa sababu ya furaha, kama hao mataifa; kwa kuwa umezini juu ya Mungu wako, umependa ujira katika kila sakafu ya nafaka."}, {"r": "Wagalatia 1:4", "t": "ambaye alijitoa nafsi yake kwa ajili ya dhambi zetu, ili atuokoe na dunia hii mbovu iliyopo sasa, kama alivyopenda Mungu, Baba yetu."}, {"r": "Isaya 42:21", "t": "Bwana akapendezwa, kwa ajili ya haki yake, kuitukuza sheria, na kuiadhimisha."}, {"r": "Matendo ya Mitume 25:9", "t": "Lakini Festo akitaka kujipendekeza kwa Wayahudi akamjibu Paulo, akisema, Je! Wataka kwenda Yerusalemu, ukahukumiwe huko mbele yangu kwa ajili ya mambo hayo?"}, {"r": "Mathayo 18:14", "t": "Vivyo hivyo haipendezi mbele za Baba yenu aliye mbinguni kwamba mmoja wa wadogo hawa apotee."}, {"r": "Zaburi 109:4", "t": "Badala ya upendo wangu wao hunishitaki, Ijapokuwa naliwaombea."}, {"r": "Yohana 21:17", "t": "Akamwambia mara ya tatu, Simoni wa Yohana, wanipenda? Petro alihuzunika kwa vile alivyomwambia mara ya tatu, Wanipenda? Akamwambia, Bwana, wewe wajua yote; wewe umetambua ya kuwa nakupenda. Yesu akamwambia, Lisha kondoo zangu."}, {"r": "Matendo ya Mitume 6:5", "t": "Neno hili likapendeza machoni pa mkutano wote; wakamchagua Stefano, mtu aliyejaa imani na Roho Mtakatifu, na Filipo, na Prokoro, na Nikanori, na Timoni, na Parmena, na Nikolao mwongofu wa Antiokia;"}, {"r": "1 Wakorintho 1:21", "t": "Kwa maana katika hekima ya Mungu, dunia isipopata kumjua Mungu kwa hekima yake, Mungu alipenda kuwaokoa waaminio kwa upuzi wa lile neno linalohubiriwa."}, {"r": "1 Wakorintho 13:1", "t": "Nijaposema kwa lugha za wanadamu na za malaika, kama sina upendo, nimekuwa shaba iliayo na upatu uvumao."}, {"r": "Yeremia 31:20", "t": "Je! Efraimu siye mwanangu mpendwa? Je! Siye mtoto apendezaye? Maana kila nisemapo neno juu yake, ningali nikimkumbuka sana; kwa sababu hiyo moyo wangu unataabika kwa ajili yake; bila shaka nitamrehemu, asema Bwana."}, {"r": "Warumi 5:5", "t": "na tumaini halitahayarishi; kwa maana pendo la Mungu limekwisha kumiminwa katika mioyo yetu na Roho Mtakatifu tuliyepewa sisi."}, {"r": "Warumi 16:5", "t": "Nisalimieni Epaineto, mpenzi wangu, aliye malimbuko ya Asia kwa Kristo."}, {"r": "Yuda 1:1", "t": "Yuda, mtumwa wa Yesu Kristo, ndugu yake Yakobo, kwa hao walioitwa, waliopendwa katika Mungu Baba, na kuhifadhiwa kwa ajili ya Yesu Kristo."}, {"r": "Hosea 8:8", "t": "Israeli amemezwa; sasa wamo miongoni mwa mataifa kama chombo kisichopendeza."}, {"r": "Ufunuo wa Yohana 2:19", "t": "Nayajua matendo yako na upendo na imani na huduma na subira yako; tena kwamba matendo yako ya mwisho yamezidi yale ya kwanza."}, {"r": "Zaburi 16:3", "t": "Watakatifu waliopo duniani ndio Walio bora, Hao ndio niliopendezwa nao."}, {"r": "Zaburi 35:17", "t": "Bwana, hata lini utatazama? Uiokoe nafsi yangu na maharabu yao, Na mpenzi wangu na wanasimba."}, {"r": "Warumi 15:32", "t": "nipate kufika kwenu kwa furaha, kama apendavyo Mungu, nikapate kupumzika pamoja nanyi."}, {"r": "Wimbo Ulio Bora 3:4", "t": "Kitambo kidogo tu nikiisha kuwaondokea, Nikamwona mpendwa wa nafsi yangu; Nikamshika, nisimwache tena, Hata nilipomleta nyumbani mwa mamangu, Chumbani mwake aliyenizaa."}, {"r": "Warumi 1:10", "t": "siku zote katika sala zangu, nikiomba nije kwenu hivi karibu, Mungu akipenda kuifanikisha safari yangu."}, {"r": "Wimbo Ulio Bora 5:8", "t": "Nawasihi, enyi binti za Yerusalemu, Ninyi mkimwona mpendwa wangu, Ni nini mtakayomwambia? Ya kwamba nazimia kwa mapenzi."}, {"r": "2 Petro 3:15", "t": "Nanyi uhesabuni uvumilivu wa Bwana wetu kuwa ni wokovu, kama vile na ndugu yetu mpenzi Paulo alivyowaandikia kwa hekima aliyopewa;"}, {"r": "Mithali 8:36", "t": "Bali anikosaye hujidhuru nafsi yake mwenyewe, Na wao wanichukiao hupenda mauti."}, {"r": "Warumi 2:11", "t": "kwa maana hakuna upendeleo kwa Mungu."}, {"r": "Mithali 2:10", "t": "Maana hekima itaingia moyoni mwako, Na maarifa yatakupendeza nafsi yako;"}, {"r": "Zaburi 26:8", "t": "Bwana, nimependa makao ya nyumba yako, Na mahali pa maskani ya utukufu wako."}, {"r": "Ayubu 9:3", "t": "Kama akipenda kushindana naye, Hawezi kumjibu neno moja katika elfu."}, {"r": "Zaburi 41:11", "t": "Kwa neno hili nimejua ya kuwa wapendezwa nami, Kwa kuwa adui yangu hasimangi kwa kunishinda."}, {"r": "Habakuki 1:15", "t": "Yeye huwatoa wote kwa ndoana yake, huwakamata katika wavu wake, na kuwakusanya katika juya lake; ndiyo sababu afurahi na kupendezwa."}, {"r": "1 Timotheo 5:14", "t": "Basi napenda wajane, ambao si wazee, waolewe, wazae watoto, wawe na madaraka ya nyumbani; ili wasimpe adui nafasi ya kulaumu."}, {"r": "Yeremia 48:38", "t": "Juu ya dari zote za nyumba za Moabu, na katika njia kuu zake, pana maombolezo, kila mahali; kwa maana nimevunja Moabu kama chombo kisichopendeza, asema Bwana."}, {"r": "Yohana 14:24", "t": "Mtu asiyenipenda, yeye hayashiki maneno yangu; nalo neno mnalolisikia silo langu, ila ni lake Baba aliyenipeleka."}, {"r": "Waebrania 6:10", "t": "Maana Mungu si dhalimu hata aisahau kazi yenu, na pendo lile mlilolidhihirisha kwa jina lake, kwa kuwa mmewahudumia watakatifu, na hata hivi sasa mngali mkiwahudumia."}, {"r": "Zaburi 119:113", "t": "Watu wa kusitasita nawachukia, Lakini sheria yako naipenda."}, {"r": "Yohana 17:23", "t": "Mimi ndani yao, nawe ndani yangu, ili wawe wamekamilika katika umoja; ili ulimwengu ujue ya kuwa ndiwe uliyenituma, ukawapenda wao kama ulivyonipenda mimi."}, {"r": "Yohana 17:26", "t": "Nami naliwajulisha jina lako, tena nitawajulisha hilo; ili pendo lile ulilonipenda mimi liwe ndani yao, nami niwe ndani yao."}, {"r": "Yohana 12:43", "t": "Kwa maana walipenda utukufu wa wanadamu kuliko utukufu wa Mungu."}, {"r": "2 Timotheo 1:7", "t": "Maana Mungu hakutupa roho ya woga, bali ya nguvu na ya upendo na ya moyo wa kiasi."}, {"r": "Mithali 15:12", "t": "Mwenye mzaha hapendi kukaripiwa; Wala yeye hawaendei wenye hekima."}, {"r": "Wimbo Ulio Bora 1:3", "t": "Manukato yako yanukia vizuri; Jina lako ni kama marhamu iliyomiminwa; Kwa hiyo wanawali hukupenda."}, {"r": "1 Wakorintho 4:21", "t": "Mnataka vipi? Nije kwenu na fimbo, au nije katika upendo na roho ya upole?"}, {"r": "Esta 6:6", "t": "Basi Hamani akaingia. Mfalme akamwambia, Afanyiziwe nini yule ambaye mfalme apenda kumheshimu? Hamani akasema moyoni mwake, Ni nani ambaye mfalme apenda kumheshimu kuliko mimi?"}, {"r": "1 Petro 3:8", "t": "Neno la mwisho ni hili; mwe na nia moja, wenye kuhurumiana, wenye kupendana kama ndugu, wasikitikivu, wanyenyekevu;"}, {"r": "Yohana 10:17", "t": "Ndiposa Baba anipenda, kwa sababu nautoa uhai wangu ili niutwae tena."}, {"r": "Wimbo Ulio Bora 4:7", "t": "Mpenzi wangu, u mzuri pia pia, Wala ndani yako hamna ila."}, {"r": "Yohana 14:21", "t": "Yeye aliye na amri zangu, na kuzishika, yeye ndiye anipendaye; naye anipendaye atapendwa na Baba yangu; nami nitampenda na kujidhihirisha kwake."}, {"r": "Mika 6:8", "t": "Ee mwanadamu, yeye amekuonyesha yaliyo mema; na Bwana anataka nini kwako, ila kutenda haki, na kupenda rehema, na kwenda kwa unyenyekevu na Mungu wako!"}, {"r": "Zaburi 109:5", "t": "Wamenichukuza mabaya badala ya mema, Na chuki badala ya upendo wangu."}, {"r": "Yeremia 2:25", "t": "Zuia mguu wako usikose kiatu, na koo yako isiwe na kiu; lakini wewe ulisema, Hapana matumaini kabisa; la, maana nimewapenda wageni, nami nitawafuata."}, {"r": "Zaburi 146:8", "t": "Bwana huwafumbua macho waliopofuka; Bwana huwainua walioinama; Bwana huwapenda wenye haki;"}, {"r": "Warumi 9:25", "t": "Ni kama vile alivyosema katika Hosea, Nitawaita watu wangu wale wasiokuwa watu wangu, Na mpenzi wangu yeye asiyekuwa mpenzi wangu."}, {"r": "Isaya 5:1", "t": "Na nimwimbie mpenzi wangu wimbo wa mpenzi wangu katika habari za shamba lake la mizabibu. Mpenzi wangu alikuwa na shamba la mizabibu, Kilimani penye kuzaa sana;"}, {"r": "2 Samueli 19:6", "t": "kwa kuwa unawapenda wakuchukiao, na unawachukia wakupendao. Maana umetangaza leo ya kuwa wakuu na watumishi wako si kitu kwako; maana leo nimetambua hivi; kama Absalomu angaliishi, na sisi sote tungalikufa leo, ingalikuwa vyema machoni pako."}, {"r": "2 Wakorintho 12:10", "t": "Kwa hiyo napendezwa na udhaifu, na ufidhuli, na misiba, na adha, na shida, kwa ajili ya Kristo. Maana niwapo dhaifu ndipo nilipo na nguvu."}, {"r": "1 Yohana 3:16", "t": "Katika hili tumelifahamu pendo, kwa kuwa yeye aliutoa uhai wake kwa ajili yetu; imetupasa na sisi kuutoa uhai wetu kwa ajili ya hao ndugu."}, {"r": "Wakolosai 3:18", "t": "Ninyi wake, watiini waume zenu, kama ipendezavyo katika Bwana."}, {"r": "Wimbo Ulio Bora 6:2", "t": "Mpendwa wangu ameshukia bustani yake, Kwenye matuta ya rihani; Ili kulisha penye bustani, Ili kuchuma nyinyoro."}, {"r": "Wimbo Ulio Bora 5:6", "t": "Nalimfungulia mpendwa wangu, Lakini mpendwa wangu amegeuka amepita; (Nimezimia nafsi yangu aliponena), Nikamtafuta, nisimpate, Nikamwita, asiniitikie."}, {"r": "1 Wakorintho 10:20", "t": "Sivyo, lakini vitu vile wavitoavyo sadaka wavitoa kwa mashetani, wala si kwa Mungu; nami sipendi ninyi kushirikiana na mashetani. Hamwezi kunywea kikombe cha Bwana na kikombe cha mashetani."}, {"r": "Waefeso 5:1", "t": "Hivyo mfuateni Mungu, kama watoto wanaopendwa;"}, {"r": "Mathayo 3:17", "t": "na tazama, sauti kutoka mbinguni ikisema, Huyu ni Mwanangu, mpendwa wangu, ninayependezwa naye."}, {"r": "Amosi 5:21", "t": "Mimi nazichukia sikukuu zenu, nazidharau, nami sitapendezwa na makutano yenu ya dini."}, {"r": "Wimbo Ulio Bora 5:4", "t": "Mpendwa wangu aliutia mkono wake tunduni, Na moyo wangu ukachomeka kwa ajili yake."}, {"r": "2 Petro 2:13", "t": "Wakipatikana na madhara, ambayo ni ujira wa udhalimu wao, wakidhania kuwa ulevi wakati wa mchana ni anasa; wamekuwa ni mawaa na aibu wakifuata anasa zisizo kiasi katika karamu zao za upendo, wafanyapo karamu pamoja nanyi;"}, {"r": "1 Wakorintho 10:5", "t": "Lakini wengi sana katika wao, Mungu hakupendezwa nao; maana waliangamizwa jangwani."}, {"r": "1 Wakorintho 15:38", "t": "lakini Mungu huipa mwili kama apendavyo, na kila mbegu mwili wake."}, {"r": "Zaburi 119:140", "t": "Neno lako limesafika sana, Kwa hiyo mtumishi wako amelipenda."}, {"r": "Matendo ya Mitume 12:3", "t": "Na akiona ya kuwa imewapendeza Wayahudi akaendelea akamshika na Petro. Siku hizo zilikuwa siku za mikate isiyochachwa."}, {"r": "Zaburi 111:2", "t": "Matendo ya Bwana ni makuu, Yafikiriwa sana na wapendezwao nayo."}, {"r": "1 Petro 1:22", "t": "Mkiisha kujitakasa roho zenu kwa kuitii kweli, hata kuufikilia upendano wa ndugu usio na unafiki, basi jitahidini kupendana kwa moyo."}, {"r": "Yakobo 2:9", "t": "Bali mkiwapendelea watu, mwafanya dhambi na kuhukumiwa na sheria kuwa wakosaji."}, {"r": "3 Yohana 1:9", "t": "Naliliandikia kanisa neno, lakini Diotrefe, apendaye kuwa wa kwanza kati yao, hatukubali."}, {"r": "2 Wakorintho 12:1", "t": "Sina budi kujisifu, ijapokuwa haipendezi; lakini nitafikilia maono na mafunuo ya Bwana."}, {"r": "Zaburi 119:163", "t": "Nimeuchukia uongo, umenikirihi, Sheria yako nimeipenda."}, {"r": "1 Yohana 3:22", "t": "na lo lote tuombalo, twalipokea kwake, kwa kuwa twazishika amri zake, na kuyatenda yapendezayo machoni pake."}, {"r": "3 Yohana 1:1", "t": "Mzee, kwa Gayo mpenzi, nimpendaye katika kweli."}, {"r": "1 Wakorintho 14:1", "t": "Ufuateni upendo, na kutaka sana karama za rohoni, lakini zaidi kwamba mpate kuhutubu."}, {"r": "2 Yohana 1:5", "t": "Na sasa mama, nakuomba, si kwamba nakuandikia amri mpya, bali ile tuliyokuwa nayo tangu mwanzo, kwamba tupendane."}, {"r": "1 Wathesalonike 2:8", "t": "Vivyo hivyo nasi tukiwatumaini kwa upendo mwingi, tuliona furaha kuwapa, si Injili ya Mungu tu, bali na roho zetu pia, kwa sababu mmekuwa wapendwa wetu."}, {"r": "Filemoni 1:16", "t": "tokea sasa, si kama mtumwa, bali zaidi ya mtumwa, ndugu mpendwa; kwangu mimi sana, na kwako wewe zaidi sana, katika mwili na katika Bwana."}, {"r": "Zaburi 73:25", "t": "Ni nani niliye naye mbinguni, Wala duniani sina cha kupendeza ila Wewe."}, {"r": "Tito 2:4", "t": "ili wawatie wanawake vijana akili, wawapende waume zao, na kuwapenda watoto wao;"}, {"r": "Wimbo Ulio Bora 8:14", "t": "Ukimbie, mpendwa wangu, Nawe uwe kama paa, au ayala, Juu ya milima ya manukato."}, {"r": "Mathayo 15:32", "t": "Yesu akawaita wanafunzi wake, akasema, Nawahurumia mkutano, kwa kuwa yapata siku tatu wamekaa pamoja nami, wala hawana kitu cha kula, tena kuwaaga wakifunga sipendi, wasije wakazimia njiani."}, {"r": "Yohana 15:10", "t": "Mkizishika amri zangu, mtakaa katika pendo langu; kama vile mimi nilivyozishika amri za Baba yangu na kukaa katika pendo lake."}, {"r": "Warumi 15:30", "t": "Ndugu zangu, nawasihi kwa Bwana wetu Yesu Kristo, na kwa upendo wa Roho, jitahidini pamoja nami katika maombi yenu kwa ajili yangu mbele za Mungu;"}, {"r": "2 Timotheo 4:10", "t": "Maana Dema aliniacha, akiupenda ulimwengu huu wa sasa, akasafiri kwenda Thesalonike; Kreske amekwenda Galatia; Tito amekwenda Dalmatia."}, {"r": "Matendo ya Mitume 17:20", "t": "Kwa maana unaleta mambo mageni masikioni mwetu, tutapenda kujua, basi, maana ya mambo haya."}, {"r": "Ayubu 10:12", "t": "Umenijazi uhai na upendeleo, Na maangalizi yako yameilinda roho yangu."}, {"r": "1 Timotheo 1:7", "t": "wapenda kuwa waalimu wa sheria, ingawa hawayafahamu wasemayo wala mambo yale wayanenayo kwa uthabiti."}, {"r": "1 Wakorintho 8:1", "t": "Na kwa habari ya vitu vilivyotolewa sadaka kwa sanamu; Twajua ya kuwa sisi sote tuna ujuzi. Ujuzi huleta majivuno, bali upendo hujenga."}, {"r": "Ayubu 27:22", "t": "Kwani Mungu atamtupia asimhurumie; Angependa kuukimbia mkono wake."}, {"r": "Mathayo 24:12", "t": "Na kwa sababu ya kuongezeka maasi, upendo wa wengi utapoa."}, {"r": "1 Petro 5:14", "t": "Salimianeni kwa busu la upendo. Amani na iwe kwenu nyote, mlio katika Kristo. Amina."}, {"r": "Luka 6:35", "t": "Bali wapendeni adui zenu, tendeni mema, na kukopesha msitumaini kupata malipo, na thawabu yenu itakuwa nyingi; nanyi mtakuwa wana wa Aliye juu, kwa kuwa yeye ni mwema kwa wasiomshukuru, na waovu."}, {"r": "Yohana 21:20", "t": "Petro akageuka akamwona yule mwanafunzi aliyependwa na Yesu anafuata; (ndiye huyo aliyeegama kifuani pake wakati wa kula chakula cha jioni, akasema, Bwana, ni nani akusalitiye?)"}, {"r": "1 Timotheo 1:5", "t": "Walakini mwisho wa agizo hilo ni upendo utokao katika moyo safi na dhamiri njema, na imani isiyo na unafiki."}, {"r": "Zaburi 133:1", "t": "Tazama, jinsi ilivyo vema, na kupendeza, Ndugu wakae pamoja, kwa umoja."}, {"r": "Isaya 38:17", "t": "Tazama; nalikuwa na uchungu mwingi kwa ajili ya amani yangu; Lakini kwa kunipenda umeniokoa na shimo la uharibifu; Kwa maana umezitupa dhambi zangu zote nyuma yako."}, {"r": "Zaburi 51:19", "t": "Ndipo utakapopendezwa na dhabihu za haki, Na sadaka za kuteketezwa, na kafara. Ndipo watakapotoa ng'ombe Juu ya madhabahu yako."}, {"r": "1 Wakorintho 16:24", "t": "Pendo langu na liwe pamoja nanyi nyote katika Kristo Yesu."}, {"r": "Yohana 18:39", "t": "Lakini kwenu kuna desturi ya mimi kuwafungulia mtu mmoja wakati wa Pasaka; basi, mwapenda niwafungulie Mfalme wa Wayahudi?"}, {"r": "1 Wathesalonike 5:13", "t": "mkawastahi sana katika upendo, kwa ajili ya kazi zao. Iweni na amani ninyi kwa ninyi."}, {"r": "Yohana 14:28", "t": "Mlisikia ya kwamba mimi naliwaambia, Naenda zangu, tena naja kwenu. Kama mngalinipenda, mngalifurahi kwa sababu naenda kwa Baba, kwa maana Baba ni mkuu kuliko mimi."}, {"r": "1 Yohana 3:11", "t": "Maana, hii ndiyo habari mliyoisikia tangu mwanzo, kwamba tupendane sisi kwa sisi;"}, {"r": "Wimbo Ulio Bora 2:16", "t": "Mpendwa wangu ni wangu, na mimi ni wake; Hulisha kundi lake penye nyinyoro."}, {"r": "Mithali 29:26", "t": "Watu wengi hutafuta upendeleo wa mkuu; Bali hukumu ya kila mtu hutoka kwa Bwana"}, {"r": "Mhubiri 12:10", "t": "Huyo Mhubiri akatafutatafuta ili apate kuona maneno yapendezayo, na yale yaliyoandikwa kwa unyofu, yaani, maneno ya kweli."}, {"r": "2 Wakorintho 5:14", "t": "Maana, upendo wa Kristo watubidisha; maana tumehukumu hivi, ya kwamba mmoja alikufa kwa ajili ya wote, basi walikufa wote;"}, {"r": "Yohana 17:24", "t": "Baba, hao ulionipa nataka wawe pamoja nami po pote nilipo, wapate na kuutazama utukufu wangu ulionipa; kwa maana ulinipenda kabla ya kuwekwa msingi ulimwengu."}, {"r": "Wimbo Ulio Bora 5:5", "t": "Nikaondoka nimfungulie mpendwa wangu; Mikono yangu ilidondoza manemane, Na vidole vyangu matone ya manemane, Penye vipini vya komeo."}, {"r": "Wafilipi 1:16", "t": "Hawa wanamhubiri kwa pendo, wakijua ya kuwa nimewekwa ili niitetee Injili;"}, {"r": "Ayubu 34:33", "t": "Je! Malipo yake yatakuwa kama upendavyo wewe, hata ukayakataa? Kwani yakupasa wewe kuchagua, si mimi; Kwa sababu hiyo sema uyajuayo."}, {"r": "Malaki 1:2", "t": "Nimewapenda ninyi, asema Bwana. Lakini ninyi mwasema, Umetupendaje? Je! Esau siye ndugu yake Yakobo? Asema Bwana; ila nimempenda Yakobo;"}, {"r": "Isaya 58:2", "t": "Walakini wanitafuta kila siku; hupenda kujua njia zangu; kama vile taifa waliotenda haki, wasioacha sheria ya Mungu wao, hutaka kwangu amri za haki; hufurahi kumkaribia Mungu."}, {"r": "Mathayo 11:26", "t": "Naam, Baba, kwa kuwa ndivyo ilivyopendeza mbele zako."}, {"r": "Hosea 9:16", "t": "Efraimu amepigwa; mzizi wao umekauka; hawatazaa matunda; naam, wajapozaa, nitaliua tunda la tumbo lipendwalo sana."}, {"r": "Mithali 9:8", "t": "Usimkaripie mwenye dharau, asije akakuchukia; Mkaripie mwenye hekima, naye atakupenda."}, {"r": "Wakolosai 1:4", "t": "tangu tuliposikia habari za imani yenu katika Kristo Yesu, na upendo mlio nao kwa watakatifu wote;"}, {"r": "Luka 7:47", "t": "Kwa ajili ya hayo nakuambia, Amesamehewa dhambi zake ambazo ni nyingi, kwa kuwa amependa sana; lakini asamehewaye kidogo, huyo hupenda kidogo."}, {"r": "Mithali 24:23", "t": "Haya nayo pia ni maneno ya wenye akili. Kupendelea watu katika hukumu si kwema."}, {"r": "Mithali 15:26", "t": "Mashauri mabaya ni chukizo kwa Bwana; Bali maneno yapendezayo ni safi."}, {"r": "2 Yohana 1:3", "t": "Neema, na rehema, na amani, zitokazo kwa Mungu Baba na kwa Yesu Kristo Mwana wa Baba, zitakuwa pamoja nasi katika kweli na upendo."}, {"r": "Isaya 61:8", "t": "Maana mimi, Bwana, naipenda hukumu ya haki, nauchukia wivi na uovu; nami nitawalipa malipo katika kweli, nitaagana nao agano la milele."}, {"r": "Tito 3:4", "t": "Lakini wema wake Mwokozi wetu Mungu, na upendo wake kwa wanadamu, ulipofunuliwa, alituokoa;"}, {"r": "Zaburi 33:5", "t": "Huzipenda haki na hukumu, Nchi imejaa fadhili za Bwana."}, {"r": "Wimbo Ulio Bora 2:3", "t": "Kama mpera kati ya miti ya msituni, Kadhalika mpendwa wangu kati ya vijana. Naliketi kivulini mwake kwa furaha, Na matunda yake naliyaonja kuwa matamu."}, {"r": "Warumi 14:15", "t": "Na ndugu yako akiingia huzuni kwa sababu ya chakula, umeacha kwenda katika upendo. Kwa chakula chako usimharibu mtu yule ambaye Kristo alikufa kwa ajili yake."}, {"r": "Wakolosai 4:9", "t": "pamoja na Onesimo, ndugu mwaminifu, mpendwa, aliye mtu wa kwenu. Hao watawaarifu mambo yote ya hapa petu."}, {"r": "Warumi 7:19", "t": "Kwa maana lile jema nilipendalo, silitendi; bali lile baya nisilolipenda ndilo nilitendalo."}, {"r": "Yohana 7:17", "t": "Mtu akipenda kuyatenda mapenzi yake, atajua habari ya yale mafunzo, kwamba yatoka kwa Mungu, au kwamba mimi nanena kwa nafsi yangu tu."}, {"r": "Wimbo Ulio Bora 2:17", "t": "Hata jua lipunge, na vivuli vikimbie, Unigeukie, mpendwa wangu, Nawe uwe kama paa, au ayala, Juu ya milima ya Betheri."}, {"r": "Wafilipi 2:12", "t": "Basi, wapendwa wangu, kama vile mlivyotii sikuzote, si wakati mimi nilipokuwapo tu, bali sasa zaidi sana mimi nisipokuwapo, utimizeni wokovu wenu wenyewe kwa kuogopa na kutetemeka."}, {"r": "1 Wakorintho 7:36", "t": "Lakini mtu awaye yote akiona ya kuwa hamtendei mwanamwali wake vipendezavyo, na ikiwa huyo amepita uzuri wa ujana wake, na ikiwapo haja, basi, afanye apendavyo, hatendi dhambi, na awaruhusu waoane."}, {"r": "3 Yohana 1:13", "t": "Nalikuwa na mambo mengi ya kukuandikia, lakini sipendi kukuandikia kwa wino na kalamu."}, {"r": "Zaburi 119:165", "t": "Wana amani nyingi waipendao sheria yako, Wala hawana la kuwakwaza."}, {"r": "Maombolezo 3:33", "t": "Maana moyo wake hapendi kuwatesa wanadamu. Wala kuwahuzunisha."}, {"r": "1 Wakorintho 4:14", "t": "Siyaandiki hayo ili kuwatahayarisha; bali kuwaonya kama watoto niwapendao."}, {"r": "Wimbo Ulio Bora 8:5", "t": "Ni nani huyu apandaye kutoka nyikani, Akimtegemea mpendwa wake? Nalikuamsha chini ya huo mpera; Huko mama yako alikuonea utungu, Aliona utungu aliyekuzaa."}, {"r": "Mithali 21:17", "t": "Mtu apendaye anasa atakuwa maskini; Apendaye mvinyo na mafuta hatakuwa tajiri."}, {"r": "Waefeso 5:25", "t": "Enyi waume, wapendeni wake zenu, kama Kristo naye alivyolipenda Kanisa, akajitoa kwa ajili yake;"}, {"r": "Isaya 1:23", "t": "Wakuu wako ni waasi, na rafiki za wevi; kila mtu hupenda rushwa, hufuata malipo; hawampatii yatima haki yake, wala maneno ya mjane hayawawasilii."}, {"r": "1 Wakorintho 7:35", "t": "Nasema hayo niwafaidie, si kwamba niwategee tanzi, bali kwa ajili ya vile vipendezavyo, tena mpate kumhudumia Bwana pasipo kuvutwa na mambo mengine."}, {"r": "Zaburi 69:36", "t": "Wazao wa watumishi wake watairithi, Nao walipendao jina lake watakaa humo."}, {"r": "Yohana 21:15", "t": "Basi walipokwisha kula, Yesu akamwambia Simoni Petro, Je! Simoni wa Yohana, wewe wanipenda"}, {"r": "2 Wakorintho 1:8", "t": "Maana ndugu, hatupendi, msijue habari ya dhiki ile iliyotupata katika Asia, ya kwamba tulilemewa mno kuliko nguvu zetu, hata tukakata tamaa ya kuishi."}, {"r": "Mathayo 12:18", "t": "Tazama, mtumishi wangu niliyemteua; Mpendwa wangu, moyo wangu uliyependezwa naye; Nitatia roho yangu juu yake, Naye atawatangazia Mataifa hukumu."}, {"r": "Zaburi 84:10", "t": "Hakika siku moja katika nyua zako Ni bora kuliko siku elfu. Ningependa kuwa bawabu nyumbani mwa Mungu wangu, Kuliko kukaa katika hema za uovu."}, {"r": "Marko 1:11", "t": "na sauti ikatoka mbinguni, Wewe ndiwe Mwanangu, mpendwa wangu; nimependezwa nawe."}, {"r": "1 Timotheo 6:2", "t": "Na wale walio na bwana waaminio wasiwadharau kwa kuwa ni ndugu; bali afadhali wawatumikie, kwa sababu hao waishirikio faida ya kazi yao wamekuwa wenye imani na kupendwa. Mambo hayo uyafundishe na kuonya."}, {"r": "Zaburi 127:2", "t": "Kazi yenu ni bure, mnaoamka mapema, Na kukawia kwenda kulala, Na kula chakula cha taabu; Yeye humpa mpenzi wake usingizi."}, {"r": "1 Yohana 2:15", "t": "Msiipende dunia, wala mambo yaliyomo katika dunia. Mtu akiipenda dunia, kumpenda Baba hakumo ndani yake."}, {"r": "Isaya 58:13", "t": "Kama ukigeuza mguu wako usihalifu sabato, usifanye anasa yako siku ya utakatifu wangu; ukiita sabato siku ya furaha, na siku takatifu ya Bwana yenye heshima; ukiitukuza, kwa kutokuzifanya njia zako mwenyewe, wala kuyatafuta yakupendezayo, wala kusema maneno yako mwenyewe;"}, {"r": "2 Petro 2:15", "t": "wakiiacha njia iliyonyoka, wakapotea, wakiifuata njia ya Balaamu, mwana wa Beori, aliyependa ujira wa udhalimu;"}, {"r": "Zaburi 119:97", "t": "Sheria yako naipenda mno ajabu, Ndiyo kutafakari kwangu mchana kutwa."}, {"r": "1 Wakorintho 4:17", "t": "Kwa sababu hii nimemtuma Timotheo kwenu, aliye mwanangu mpendwa, mwaminifu katika Bwana, atakayewakumbusha njia zangu zilizo katika Kristo, kama vile nifundishavyo kila mahali katika kila kanisa."}, {"r": "2 Wakorintho 6:6", "t": "katika kuwa safi, katika elimu, katika uvumilivu, katika utu wema, katika Roho Mtakatifu, katika upendo usio unafiki;"}, {"r": "Warumi 8:37", "t": "Lakini katika mambo hayo yote tunashinda, na zaidi ya kushinda, kwa yeye aliyetupenda."}, {"r": "2 Samueli 1:23", "t": "Sauli na Yonathani walipendwa na kupendeza Maishani wala mautini hawakutengwa; Walikuwa wepesi kuliko tai, Walikuwa hodari kuliko simba."}, {"r": "Mithali 23:26", "t": "Mwanangu, nipe moyo wako; Macho yako yapendezwe na njia zangu."}, {"r": "Zekaria 8:19", "t": "Bwana wa majeshi asema hivi, Saumu ya mwezi wa nne, na saumu ya mwezi wa tano, na saumu ya mwezi wa saba, na saumu ya mwezi wa kumi, zitakuwa furaha na shangwe, na sikukuu za kuchangamkia, kwa nyumba ya Yuda; basi zipendeni kweli na amani."}, {"r": "Isaya 64:11", "t": "Nyumba yetu takatifu, nzuri, walimokusifu baba zetu, imeteketea moto; vitu vyetu vyote vyenye kupendeza vimeharibika."}, {"r": "1 Wakorintho 15:58", "t": "Basi, ndugu zangu wapendwa, mwimarike, msitikisike, mkazidi sana kutenda kazi ya Bwana sikuzote, kwa kuwa mwajua ya kwamba taabu yenu siyo bure katika Bwana."}, {"r": "Yohana 15:9", "t": "Kama vile Baba alivyonipenda mimi, nami nilivyowapenda ninyi, kaeni katika pendo langu."}, {"r": "Yohana 14:15", "t": "Mkinipenda, mtazishika amri zangu."}, {"r": "Warumi 16:18", "t": "Kwa sababu walio hivyo hawamtumikii Bwana wetu Kristo, bali matumbo yao wenyewe; na kwa maneno laini na ya kujipendekeza waidanganya mioyo ya watu wanyofu."}, {"r": "Mithali 28:23", "t": "Amkemeaye mwenzake hatimaye atapata kibali; Zaidi ya mtu ajipendekezaye kwa ulimi wake."}, {"r": "Zaburi 18:19", "t": "Akanitoa akanipeleka panapo nafasi, Aliniponya kwa kuwa alipendezwa nami."}, {"r": "Zaburi 119:132", "t": "Unigeukie, unirehemu mimi, Kama iwahusuvyo walipendao jina lako."}, {"r": "Hosea 10:10", "t": "Wakati nitakapopenda nitawaadhibu; na hao mataifa watakusanyika juu yao, watakapofungwa kwa sababu ya makosa yao mawili."}, {"r": "Warumi 7:20", "t": "Basi kama lile nisilolipenda ndilo nilitendalo, si mimi nafsi yangu nilitendaye, bali ni ile dhambi ikaayo ndani yangu."}, {"r": "2 Wakorintho 2:4", "t": "Maana katika dhiki nyingi na taabu ya moyo niliwaandikia na machozi mengi; si kwamba mhuzunishwe, bali mpate kujua upendo wangu nilio nao kwenu jinsi ulivyo mwingi."}, {"r": "Ayubu 19:19", "t": "Wasiri wangu wote wanichukia; Na hao niliowapenda wamenigeukia."}, {"r": "Hosea 10:11", "t": "Naye Efraimu ni ndama aliyefundishwa, apendaye kupura; lakini nimepitisha kongwa juu ya shingo yake nzuri; nitampandisha mwenye kupanda juu ya Efraimu; Yuda atalima, na Yakobo atavunja madongoa yake."}, {"r": "Filemoni 1:7", "t": "Maana nalikuwa na furaha nyingi na faraja kwa sababu ya upendo wako, kwa kuwa mioyo ya watakatifu imeburudishwa nawe, ndugu yangu."}, {"r": "Wimbo Ulio Bora 1:9", "t": "Mpenzi wangu, nimekulinganisha Na farasi katika magari ya Farao."}, {"r": "1 Samueli 20:17", "t": "Naye Yonathani akamwapisha Daudi mara ya pili, kwa ajili ya upendo aliokuwa nao kwake; kwa maana alimpenda kama alivyoipenda roho yake mwenyewe."}, {"r": "Mithali 26:23", "t": "Midomo ijipendekezayo pamoja na moyo mbaya Ni kama kigae kilichofunikizwa taka za fedha."}, {"r": "Mathayo 5:46", "t": "Maana mkiwapenda wanaowapenda ninyi mwapata thawabu gani? Hata watoza ushuru, je! Nao hawafanyi yayo hayo?"}, {"r": "Waefeso 6:9", "t": "Nanyi, akina bwana, watendeeni wao yayo hayo, mkiacha kuwaogofya, huku mkijua ya kuwa yeye aliye Bwana wao na wenu yuko mbinguni, wala kwake hakuna upendeleo."}, {"r": "Mathayo 11:27", "t": "Akasema, Nimekabidhiwa vyote na baba yangu; wala hakuna amjuaye Mwana, ila Baba; wala hakuna amjuaye Baba, ila Mwana, na ye yote ambaye Mwana apenda kumfunulia."}, {"r": "Wimbo Ulio Bora 7:11", "t": "Njoo, mpendwa wangu, twende mashambani, Tufanye maskani katika vijiji."}, {"r": "Hosea 4:18", "t": "Kileo chao kimegeuka kuwa uchungu; huzini daima; wakuu wake hupenda aibu."}, {"r": "Zaburi 22:8", "t": "Husema, Umtegemee Bwana; na amponye; Na amwokoe sasa, maana apendezwa naye."}, {"r": "1 Wakorintho 10:1", "t": "Kwa maana, ndugu zangu, sipendi mkose kufahamu ya kuwa baba zetu walikuwa wote chini ya wingu; wote wakapita kati ya bahari;"}, {"r": "2 Wathesalonike 3:5", "t": "Bwana awaongoze mioyo yenu mkapate pendo la Mungu, na saburi ya Kristo."}, {"r": "Zaburi 87:2", "t": "Bwana ayapenda malango ya Sayuni Kuliko maskani zote za Yakobo."}, {"r": "Wimbo Ulio Bora 1:16", "t": "Tazama, u mzuri, mpendwa wangu, Wapendeza, na kitanda chetu ni majani;"}, {"r": "Zaburi 45:12", "t": "Na binti Tiro analeta kipawa chake, Nao matajiri wa watu watajipendekeza kwako."}, {"r": "Matendo ya Mitume 26:5", "t": "wakinijua sana tangu mwanzo, kama wakipenda kushuhudia, ya kwamba nalikuwa Farisayo kwa kuifuata madhehebu ya dini yetu iliyo sahihi kabisa."}, {"r": "Yeremia 34:16", "t": "lakini mlighairi, na kulitukana jina langu; kila mtu akamrudisha mtumwa wake na mjakazi wake, ambao mmewaweka huru kama walivyopenda wenyewe, mkawatia utumwani tena, wawe watumwa wenu na wajakazi wenu."}, {"r": "2 Timotheo 3:12", "t": "Naam, na wote wapendao kuishi maisha ya utauwa katika Kristo Yesu wataudhiwa."}, {"r": "Wagalatia 2:20", "t": "Nimesulibiwa pamoja na Kristo; lakini ni hai; wala si mimi tena, bali Kristo yu hai ndani yangu; na uhai nilio nao sasa katika mwili, ninao katika imani ya Mwana wa Mungu, ambaye alinipenda, akajitoa nafsi yake kwa ajili yangu."}, {"r": "Isaya 57:8", "t": "Na nyuma ya milango na miimo umeweka kumbukumbu lako; kwa maana umejifunua nafsi yako kwa ajili ya mwingine, si kwa ajili yangu, ukakwea juu; umekipanua kitanda chako, nawe umefanya maagano na hao; ulikipenda kitanda chao hapo ulipokiona."}, {"r": "Isaya 54:12", "t": "Nami nitaifanya minara yako ya akiki nyekundu, na malango yako ya almasi, na mipaka yako yote ya mawe yapendezayo."}, {"r": "1 Yohana 2:5", "t": "Lakini yeye alishikaye neno lake, katika huyo upendo wa Mungu umekamilika kweli kweli. Katika hili twajua ya kuwa tumo ndani yake."}, {"r": "Zaburi 119:159", "t": "Uangalie niyapendavyo mausia yako, Ee Bwana, unihuishe sawasawa na fadhili zako."}, {"r": "1 Timotheo 1:14", "t": "Na neema ya Bwana wetu ilizidi sana, pamoja na imani na pendo lililo katika Kristo Yesu."}, {"r": "Mithali 9:17", "t": "Maji yaliyoibiwa ni matamu, Na mkate ulioliwa kwa siri hupendeza."}, {"r": "Mithali 30:29", "t": "Kuna watatu wenye mwendo wa kupendeza, Naam, wanne walio na mwendo mzuri."}, {"r": "Ufunuo wa Yohana 3:9", "t": "Tazama, nakupa walio wa sinagogi la Shetani, wasemao kwamba ni Wayahudi, nao sio, bali wasema uongo. Tazama, nitawafanya waje kusujudu mbele ya miguu yako, na kujua ya kuwa nimekupenda."}, {"r": "Mithali 4:3", "t": "Maana nalikuwa mwana kwa baba yangu, Mpole, mpenzi wa pekee wa mama yangu."}, {"r": "Mithali 5:19", "t": "Ni ayala apendaye na paa apendezaye; Maziwa yake yakutoshe sikuzote; Na kwa upendo wake ushangilie daima."}, {"r": "Mithali 21:1", "t": "Moyo wa mfalme huwa katika mkono wa Bwana; Kama mifereji ya maji huugeuza po pote apendapo."}, {"r": "Warumi 15:3", "t": "Kwa maana Kristo naye hakujipendeza mwenyewe; bali kama ilivyoandikwa, Malaumu yao waliokulaumu wewe yalinipata mimi."}, {"r": "Malaki 3:4", "t": "Wakati ule ndipo dhabihu za Yuda na Yerusalemu zitakapopendeza mbele za Bwana, kama katika siku za kale, na kama katika miaka ya zamani."}, {"r": "Waebrania 10:24", "t": "tukaangaliane sisi kwa sisi na kuhimizana katika upendo na kazi nzuri;"}, {"r": "Wakolosai 2:2", "t": "ili wafarijiwe mioyo yao, wakiunganishwa katika upendo, wakapate utajiri wote wa kufahamu kwa hakika, wapate kujua kabisa siri ya Mungu, yaani, Kristo;"}, {"r": "Zaburi 37:28", "t": "Kwa kuwa Bwana hupenda haki, Wala hawaachi watauwa wake. Wao hulindwa milele, Bali mzao wa wasio haki ataharibiwa."}, {"r": "1 Wakorintho 7:7", "t": "Ila nipendalo ni kwamba watu wote wawe kama mimi nilivyo; walakini kila mtu ana karama yake mwenyewe itokayo kwa Mungu, huyu hivi, na huyu hivi."}, {"r": "Yohana 3:19", "t": "Na hii ndiyo hukumu; ya kuwa nuru imekuja ulimwenguni, na watu wakapenda giza kuliko nuru; kwa maana matendo yao yalikuwa maovu."}, {"r": "Zaburi 40:5", "t": "Ee Bwana, Mungu wangu, umefanya kwa wingi Miujiza yako na mawazo yako kwetu; Hakuna awezaye kufananishwa nawe; Kama ningependa kuyatangaza na kuyahubiri, Ni mengi sana hayahesabiki."}, {"r": "1 Wathesalonike 3:12", "t": "Bwana na awaongeze na kuwazidisha katika upendo, ninyi kwa ninyi, na kwa watu wote, kama vile sisi nasi tulivyo kwenu;"}, {"r": "Warumi 7:15", "t": "Maana sijui nifanyalo, kwa sababu lile nilipendalo, silitendi; bali lile nilichukialo ndilo ninalolitenda."}, {"r": "Zaburi 52:4", "t": "Umependa maneno yote ya kupoteza watu, Ewe ulimi wenye hila."}, {"r": "Warumi 1:31", "t": "wasio na ufahamu, wenye kuvunja maagano, wasiopenda jamaa zao, wasio na rehema;"}, {"r": "Yohana 5:35", "t": "Yeye alikuwa taa iwakayo na kung'aa, nanyi mlipenda kuishangilia nuru yake kwa muda."}, {"r": "Yuda 1:21", "t": "jilindeni katika upendo wa Mungu, huku mkingojea rehema ya Bwana wetu Yesu Kristo, hata mpate uzima wa milele."}, {"r": "Luka 3:22", "t": "Roho Mtakatifu akashuka juu yake kwa mfano wa kiwiliwili, kama hua; sauti ikatoka mbinguni, Wewe ndiwe Mwanangu, mpendwa wangu; nimependezwa nawe."}, {"r": "Isaya 47:8", "t": "Sasa, basi, sikia haya, wewe upendaye anasa, ukaaye na kujiona salama, wewe usemaye moyoni mwako, Mimi ndiye, wala hapana mwingine zaidi yangu mimi; sitaketi mfano wa mjane, wala sitajua kufiwa na watoto;"}, {"r": "Zaburi 88:18", "t": "Mpenzi na rafiki umewatenga nami, Nao wanijuao wamo gizani."}, {"r": "Amosi 4:5", "t": "mkachome sadaka ya shukrani, ya kitu kilichotiwa chachu; mkatangaze sadaka mtoazo kwa hiari na kuzihubiri habari zake; kwa maana ndivyo viwapendezavyo ninyi, enyi wana wa Israeli, asema Bwana MUNGU."}, {"r": "Marko 12:6", "t": "Basi alikuwa na mmoja bado, mwana mpendwa wake; huyu naye akamtuma kwao mwisho, akisema, Watamstahi mwanangu."}, {"r": "Mathayo 20:14", "t": "Chukua iliyo yako, uende zako; napenda kumpa huyu wa mwisho sawa na wewe."}, {"r": "Waebrania 10:6", "t": "Sadaka za kuteketezwa na sadaka za dhambi hukupendezwa nazo;"}, {"r": "Yakobo 1:18", "t": "Kwa kupenda kwake mwenyewe alituzaa sisi kwa neno la kweli, tuwe kama limbuko la viumbe vyake."}, {"r": "Mithali 28:21", "t": "Kupendelea watu si kwema; Wala mtu kuasi kwa ajili ya kipande cha mkate."}, {"r": "Yohana 21:16", "t": "Akamwambia tena mara ya pili, Simoni wa Yohana, wanipenda? Akamwambia, Ndiyo, Bwana, wewe wajua kuwa nakupenda. Akamwambia, Chunga kondoo zangu."}, {"r": "Zaburi 38:11", "t": "Wanipendao na rafiki zangu wanasimama mbali na pigo langu; Naam, karibu zangu wamesimama mbali."}, {"r": "Yoeli 3:5", "t": "Kwa kuwa mmetwaa fedha yangu na dhahabu yangu, nanyi mmevichukua vitu vyangu vyema vipendezavyo, na kuviingiza katika hekalu zenu;"}, {"r": "Luka 10:21", "t": "Saa ile ile alishangilia kwa Roho Mtakatifu, akasema, Nakushukuru, Baba, Bwana wa mbingu na nchi, kwa kuwa mambo haya umewaficha wenye hekima na akili; umewafunulia watoto wachanga; Naam, Baba, kwa kuwa ndivyo ilivyokupendeza."}, {"r": "Mithali 17:19", "t": "Apendaye ugomvi hupenda dhambi; Auinuaye sana mlango wake hutafuta uharibifu."}, {"r": "Warumi 16:8", "t": "Nisalimieni Ampliato, mpenzi wangu katika Bwana."}, {"r": "Wimbo Ulio Bora 6:4", "t": "Mpenzi wangu, u mzuri kama Tirza, Mwenye kupendeza kama Yerusalemu, Wa kutisha kama wenye bendera."}, {"r": "2 Wakorintho 13:14", "t": "Neema ya Bwana Yesu Kristo, na pendo la Mungu, na ushirika wa Roho Mtakatifu ukae nanyi nyote."}, {"r": "Zaburi 78:68", "t": "Bali aliichagua kabila ya Yuda, Mlima Sayuni alioupenda."}, {"r": "Wakolosai 3:19", "t": "Ninyi waume, wapendeni wake zenu msiwe na uchungu nao."}, {"r": "Zaburi 5:4", "t": "Maana huwi Mungu apendezwaye na ubaya; Mtu mwovu hatakaa kwako;"}, {"r": "1 Wathesalonike 1:4", "t": "Kwa maana, ndugu mnaopendwa na Mungu, twajua uteule wenu;"}, {"r": "Hosea 9:6", "t": "Kwa maana, tazama, wamekwenda zao ili kukimbia uharibifu, lakini Misri itawakusanya, Nofu itawazika; vitu vyao vya fedha viwapendezavyo, magugu yatavimiliki; miiba itakuwa katika hema zao."}, {"r": "1 Yohana 4:17", "t": "Katika hili pendo limekamilishwa kwetu, ili tuwe na ujasiri katika siku ya hukumu; kwa kuwa, kama yeye alivyo, ndivyo tulivyo na sisi ulimwenguni humu."}, {"r": "Mithali 18:21", "t": "Mauti na uzima huwa katika uwezo wa ulimi; Na wao waupendao watakula matunda yake."}, {"r": "Warumi 1:7", "t": "kwa wote walioko Rumi, wapendwao na Mungu, walioitwa kuwa watakatifu. Neema na iwe kwenu na amani itokayo kwa Mungu Baba yetu, na kwa Bwana Yesu Kristo."}, {"r": "Warumi 8:27", "t": "Na yeye aichunguzaye mioyo aijua nia ya Roho ilivyo, kwa kuwa huwaombea watakatifu kama apendavyo Mungu."}, {"r": "1 Wathesalonike 4:9", "t": "Katika habari ya upendano, hamna haja niwaandikie; maana ninyi wenyewe mmefundishwa na Mungu kupendana."}, {"r": "Esta 6:9", "t": "na yale mavazi na yule farasi akabidhiwe mkononi mmojawapo wa maakida wa mfalme aliye mstahiki; ili makusudi amvike yule ambaye mfalme apenda kumheshimu, na kumrakibisha juu ya farasi kuipitia njia kuu ya mjini, na kupiga mbiu mbele yake, kusema, Hivyo ndivyo atakavyofanyiziwa mtu yule ambaye mfalme apenda kumheshimu."}, {"r": "Hosea 11:4", "t": "Naliwavuta kwa kamba za kibinadamu, kwa mafungo ya upendo; nami nalikuwa kwao kama hao waondoao kongwa tayani mwao, nikaandika chakula mbele yao."}, {"r": "1 Wakorintho 14:19", "t": "lakini katika kanisa napenda kunena maneno matano kwa akili zangu, nipate kuwafundisha wengine, zaidi ya kunena maneno kumi elfu kwa lugha."}, {"r": "Zekaria 8:17", "t": "wala mtu wa kwenu asiwaze mabaya moyoni mwake juu ya jirani yake; wala msipende kiapo cha uongo; maana hayo yote ndiyo niyachukiayo, asema Bwana."}, {"r": "Zaburi 37:23", "t": "Hatua za mtu zaimarishwa na Bwana, Naye aipenda njia yake."}, {"r": "Zaburi 69:13", "t": "Nami maombi yangu nakuomba Wewe, Bwana, Wakati ukupendezao; Ee Mungu, Kwa wingi wa fadhili zako unijibu, Katika kweli ya wokovu wako."}, {"r": "Ayubu 32:21", "t": "Tafadhali, nisiupendelee uso wa mtu; Wala sitajipendekeza kwa mtu ye yote."}, {"r": "Hosea 14:4", "t": "Mimi nitawaponya kurudi nyuma kwao; nitawapenda kwa ukunjufu wa moyo; kwa maana hasira yangu imemwacha."}, {"r": "Nahumu 2:9", "t": "Chukueni nyara za fedha; Chukueni nyara za dhahabu; Kwa maana ni akiba isiyoisha, Fahari ya vyombo vipendezavyo."}, {"r": "Wakolosai 1:7", "t": "kama mlivyofundishwa na Epafra, mjoli wetu mpenzi, aliye mhudumu mwaminifu wa Kristo kwa ajili yenu;"}, {"r": "Wimbo Ulio Bora 6:3", "t": "Mimi ni wake mpendwa wangu, naye ni wangu, Hulisha kundi lake penye nyinyoro."}, {"r": "2 Wakorintho 8:7", "t": "Lakini kama mlivyo na wingi wa mambo yote; imani, na usemi, na elimu, na bidii yote, na upendo wenu kwetu sisi; basi vivyo hivyo mpate wingi wa neema hii pia."}, {"r": "Warumi 1:13", "t": "Lakini, ndugu zangu, sipendi msiwe na habari, ya kuwa mara nyingi nalikusudia kuja kwenu, nikazuiliwa hata sasa, ili nipate kuwa na matunda kwenu ninyi pia kama nilivyo nayo katika Mataifa wengine."}, {"r": "Yohana 15:19", "t": "Kama mngekuwa wa ulimwengu, ulimwengu ungewapenda walio wake; lakini kwa kuwa ninyi si wa ulimwengu, bali mimi naliwachagua katika ulimwengu, kwa sababu hiyo ulimwengu huwachukia."}, {"r": "Wimbo Ulio Bora 2:9", "t": "Mpendwa wangu ni kama paa, au ayala. Tazama, asimama nyuma ya ukuta wetu, Achungulia dirishani, atazama kimiani."}, {"r": "Ayubu 6:27", "t": "Naam, mwapenda kuwapigia kura hao mayatima, Na kufanya biashara ya rafiki yenu."}, {"r": "Yeremia 3:15", "t": "nami nitawapa ninyi wachungaji wanipendezao moyo wangu, watakaowalisha kwa maarifa na fahamu."}, {"r": "Mika 6:7", "t": "Je! Bwana atapendezwa na elfu za kondoo waume, au na elfu kumi za mito ya mafuta? Je! Nimtoe mzaliwa wangu wa kwanza kwa kosa langu, mzao wa mwili wangu kwa dhambi ya roho yangu?"}, {"r": "1 Yohana 3:17", "t": "Lakini mtu akiwa na riziki ya dunia, kisha akamwona ndugu yake ni mhitaji, akamzuilia huruma zake, je! Upendo wa Mungu wakaaje ndani yake huyo?"}, {"r": "2 Timotheo 1:2", "t": "kwa Timotheo, mwanangu mpendwa. Neema na iwe kwako, na rehema, na amani, zitokazo kwa Mungu Baba na kwa Kristo Yesu Bwana wetu."}, {"r": "Isaya 17:10", "t": "Maana umemsahau Mungu wa wokovu wako, wala hukuukumbuka mwamba wa ngome yako; kwa sababu hiyo ulipanda mashamba yapendezayo, na kutia ndani yake mizabibu migeni."}, {"r": "Ufunuo wa Yohana 12:11", "t": "Nao wakamshinda kwa damu ya MwanaKondoo, na kwa neno la ushuhuda wao; ambao hawakupenda maisha yao hata kufa."}, {"r": "Mhubiri 11:7", "t": "Kweli nuru ni tamu, tena ni jambo la kupendeza macho kutazama jua."}, {"r": "Isaya 43:4", "t": "Kwa kuwa ulikuwa wa thamani machoni pangu, na mwenye kuheshimiwa, nami nimekupenda; kwa sababu hiyo nitatoa watu kwa ajili yako; na kabila za watu kwa ajili ya maisha yako."}, {"r": "Mathayo 10:37", "t": "Apendaye baba au mama kuliko mimi, hanistahili; wala apendaye mwana au binti kuliko mimi, hanistahili."}, {"r": "Tito 2:2", "t": "ya kwamba wazee wawe wenye kiasi, wastahivu, wenye busara, wazima katika imani na katika upendo na katika saburi."}, {"r": "Wimbo Ulio Bora 5:10", "t": "Mpendwa wangu ni mweupe, tena mwekundu, Mashuhuri miongoni mwa elfu kumi;"}, {"r": "2 Wakorintho 8:24", "t": "Basi waonyesheni mbele ya makanisa hakika ya upendo wenu, na ya kujisifu kwetu kwa ajili yenu."}, {"r": "Isaya 4:2", "t": "Siku hiyo chipukizi la Bwana litakuwa zuri, lenye utukufu, na matunda ya nchi yatakuwa mema sana, na kupendeza, kwa ajili ya Waisraeli wale waliookoka."}, {"r": "1 Wakorintho 12:8", "t": "Maana mtu mmoja kwa Roho apewa neno la hekima; na mwingine neno la maarifa, apendavyo Roho yeye yule;"}, {"r": "Marko 15:15", "t": "Pilato akipenda kuwaridhisha makutano, akawafungulia Baraba; akamtoa Yesu, baada ya kumpiga mijeledi, ili asulibiwe."}, {"r": "Yuda 1:12", "t": "Watu hawa ni miamba yenye hatari katika karamu zenu za upendo walapo karamu pamoja nanyi, wakijilisha pasipo hofu; ni mawingu yasiyo na maji, yachukuliwayo na upepo; ni miti iliyopukutika, isiyo na matunda, iliyokufa mara mbili, na kung'olewa kabisa;"}, {"r": "Luka 20:46", "t": "Jilindeni na waandishi, wapendao kutembea wamevaa mavazi marefu, na kusalimiwa masokoni, na kuketi mbele katika masinagogi, na viti vya mbele karamuni."}, {"r": "Mithali 17:9", "t": "Afunikaye kosa hutafuta kupendwa; Bali yeye akashifuye neno hutenga rafiki."}, {"r": "Hosea 9:15", "t": "Uovu wao wote u katika Gilgali; maana huko naliwachukia; kwa sababu ya uovu wa matendo yao nitawafukuza watoke katika nyumba yangu; sitawapenda tena; wakuu wao wote ni waasi."}, {"r": "Yeremia 2:2", "t": "Enenda ukalie masikioni mwa Yerusalemu, ukisema, Bwana asema hivi, Nakukumbuka, hisani ya ujana wako, upendo wa wakati wa uposo wako; Jinsi ulivyonifuata huko jangwani, katika nchi isiyopandwa mbegu."}, {"r": "Wimbo Ulio Bora 7:9", "t": "Na kinywa chako kama divai iliyo bora, Kwa mpendwa wangu inashuka taratibu, Ikitiririka midomoni mwao walalao."}, {"r": "Warumi 16:9", "t": "Nisalimieni Urbano, mtenda kazi pamoja nami katika Kristo, na Stakisi, mpenzi wangu."}, {"r": "Zaburi 119:47", "t": "Nami nitajifurahisha sana kwa maagizo yako, Ambayo nimeyapenda."}, {"r": "1 Petro 1:17", "t": "Na ikiwa mnamwita Baba, yeye ahukumuye kila mtu pasipo upendeleo, kwa kadiri ya kazi yake, enendeni kwa hofu katika wakati wenu wa kukaa hapa kama wageni."}, {"r": "1 Yohana 3:23", "t": "Na hii ndiyo amri yake, kwamba tuliamini jina la Mwana wake Yesu Kristo, na kupendana sisi kwa sisi, kama alivyotupa amri."}, {"r": "Waefeso 2:4", "t": "Lakini Mungu, kwa kuwa ni mwingi wa rehema, kwa mapenzi yake makuu aliyotupenda;"}, {"r": "Mithali 13:15", "t": "Ufahamu mwema huleta upendeleo; Bali njia ya haini huparuza."}, {"r": "Luka 11:43", "t": "Ole wenu, Mafarisayo, kwa kuwa mwapenda kuketi mbele katika masinagogi, na kusalimiwa masokoni."}, {"r": "Luka 4:6", "t": "Ibilisi akamwambia, Nitakupa wewe enzi hii yote, na fahari yake, kwa kuwa imo mikononi mwangu, nami humpa ye yote kama nipendavyo."}, {"r": "Zaburi 36:2", "t": "Kwa maana hujipendekeza machoni pake Kuwa upotovu wake hautaonekana na kuchukiwa."}, {"r": "2 Petro 1:7", "t": "na katika utauwa wenu upendano wa ndugu, na katika upendano wa ndugu, upendo."}, {"r": "Zaburi 5:9", "t": "Maana vinywani mwao hamna uaminifu; Mtima wao ni shimo tupu, koo lao ni kaburi wazi, Ulimi wao hujipendekeza."}, {"r": "Wakolosai 3:25", "t": "Maana adhulumuye atapata mapato ya udhalimu wake, wala hakuna upendeleo."}, {"r": "Zaburi 70:4", "t": "Washangilie, wakufurahie, Wote wakutafutao. Waupendao wokovu wako Waseme daima, Atukuzwe Mungu."}, {"r": "Mathayo 17:5", "t": "Alipokuwa katika kusema, tazama, wingu jeupe likawatia uvuli; na tazama, sauti ikatoka katika lile wingu, ikasema, Huyu ni Mwanangu, mpendwa wangu, ninayependezwa naye; msikieni yeye."}, {"r": "3 Yohana 1:11", "t": "Mpenzi, usiuige ubaya, bali uige wema. Yeye atendaye mema ni wa Mungu, bali yeye atendaye mabaya hakumwona Mungu."}, {"r": "1 Yohana 4:12", "t": "Hakuna mtu aliyemwona Mungu wakati wo wote. Tukipendana, Mungu hukaa ndani yetu, na pendo lake limekamilika ndani yetu."}, {"r": "Mhubiri 9:11", "t": "Nikarudi, na kuona chini ya jua, ya kwamba si wenye mbio washindao katika michezo, wala si walio hodari washindao vitani, wala si wenye hekima wapatao chakula, wala si watu wa ufahamu wapatao mali, wala wenye ustadi wapatao upendeleo; lakini wakati na bahati huwapata wote."}, {"r": "Warumi 15:1", "t": "Basi imetupasa sisi tulio na nguvu kuuchukua udhaifu wao wasio na nguvu, wala haitupasi kujipendeza wenyewe."}, {"r": "Mithali 12:1", "t": "Kila apendaye mafundisho hupenda maarifa; Bali yeye achukiaye kulaumiwa ni kama mnyama."}, {"r": "Zaburi 119:127", "t": "Ndiyo maana nimeyapenda maagizo yako, Kuliko dhahabu, naam, dhahabu iliyo safi."}, {"r": "2 Timotheo 4:8", "t": "baada ya hayo nimewekewa taji ya haki, ambayo Bwana, mhukumu mwenye haki, atanipa siku ile; wala si mimi tu, bali na watu wote pia waliopenda kufunuliwa kwake."}, {"r": "Waefeso 6:23", "t": "Amani na iwe kwa ndugu, na pendo, pamoja na imani, zitokazo kwa Mungu Baba na kwa Bwana Yesu Kristo."}, {"r": "Mithali 14:35", "t": "Upendeleo wa mfalme humwelekea mtumwa atendaye kwa busara; Bali ghadhabu yake itakuwa juu yake aletaye aibu."}, {"r": "Yohana 16:27", "t": "kwa maana Baba mwenyewe awapenda kwa kuwa ninyi mmenipenda mimi, na kusadiki ya kwamba mimi nalitoka kwa Baba."}, {"r": "Mithali 29:5", "t": "Mwenye kujipendekeza kwa jirani yake, Hutandika wavu ili kuitega miguu yake."}, {"r": "Zaburi 119:119", "t": "Wabaya wa nchi pia umewaondoa kama takataka, Ndiyo maana nimezipenda shuhuda zako."}, {"r": "1 Yohana 3:14", "t": "Sisi tunajua ya kuwa tumepita toka mautini kuingia uzimani, kwa maana twawapenda ndugu. Yeye asiyependa, akaa katika mauti."}, {"r": "1 Wathesalonike 5:8", "t": "Lakini sisi tulio wa mchana, tuwe na kiasi, hali tukijivika kifuani imani na upendo, na chapeo yetu iwe tumaini la wokovu."}, {"r": "Warumi 11:25", "t": "Kwa maana, ndugu zangu, sipendi msiijue siri hii, ili msijione kuwa wenye akili; ya kwamba kwa sehemu ugumu umewapata Israeli, mpaka utimilifu wa Mataifa uwasili."}, {"r": "Mithali 27:5", "t": "Lawama ya wazi ni heri, Kuliko upendo uliositirika."}, {"r": "1 Timotheo 3:3", "t": "si mtu wa kuzoelea ulevi, si mpiga watu; bali awe mpole; si mtu wa kujadiliana, wala asiwe mwenye kupenda fedha;"}, {"r": "Yeremia 12:7", "t": "Nimeiacha nyumba yangu, nimeutupa urithi wangu; nimemtia mpenzi wangu katika mikono ya adui zake."}, {"r": "Mithali 16:24", "t": "Maneno yapendezayo ni kama sega la asali; Ni tamu nafsini, na afya mifupani."}, {"r": "3 Yohana 1:2", "t": "Mpenzi naomba ufanikiwe katika mambo yote na kuwa na afya yako, kama vile roho yako ifanikiwavyo."}, {"r": "2 Yohana 1:1", "t": "Mzee, kwa mama mteule na watoto wake niwapendao katika kweli; wala si mimi peke yangu, bali na wote waijuao ile kweli;"}, {"r": "Wakolosai 3:20", "t": "Ninyi watoto, watiini wazazi wenu katika mambo yote; maana jambo hili lapendeza katika Bwana."}, {"r": "Malaki 2:9", "t": "Kwa sababu hiyo mimi nami nimewafanya ninyi kuwa kitu cha kudharauliwa, na unyonge, mbele ya watu wote, kama vile ninyi msivyozishika njia zangu, bali mmewapendelea watu katika sheria."}, {"r": "1 Yohana 5:2", "t": "Katika hili twajua kwamba twawapenda watoto wa Mungu, tumpendapo Mungu, na kuzishika amri zake."}, {"r": "Warumi 15:26", "t": "maana imewapendeza watu wa Makedonia na Akaya kufanya changizo kwa ajili ya watakatifu huko Yerusalemu walio maskini."}, {"r": "Waefeso 5:28", "t": "Vivyo hivyo imewapasa waume nao kuwapenda wake zao kama miili yao wenyewe. Ampendaye mkewe hujipenda mwenyewe."}, {"r": "2 Mambo ya Nyakati 9:8", "t": "Na ahimidiwe Bwana, Mungu wako, aliyependezwa nawe, ili akuweke juu ya kiti chake cha enzi, kuwa mfalme wake Bwana, Mungu wako; kwa kuwa Mungu wako amewapenda Israeli, kuwathibitisha milele, kwa hiyo amekufanya kuwa mfalme juu yao, ufanye hukumu na haki."}, {"r": "Mithali 20:13", "t": "Usipende usingizi usije ukawa maskini; Fumbua macho yako nawe utashiba chakula."}, {"r": "Mithali 12:2", "t": "Mtu mwema atapata upendeleo kwa Bwana; Bali mtu wa hila atahukumiwa naye."}, {"r": "Wakolosai 4:14", "t": "Luka, yule tabibu mpendwa, na Dema, wanawasalimu."}, {"r": "Wimbo Ulio Bora 5:9", "t": "Mpendwa wa namna gani ni mpendwa wako, Wewe uliye mzuri katika wanawake, Mpendwa wa namna gani ni mpendwa wako, Hata wewe utusihi hivyo?"}, {"r": "Zaburi 52:3", "t": "Umependa mabaya kuliko mema, Na uongo kuliko kusema kweli."}, {"r": "1 Wakorintho 10:33", "t": "vile vile kama mimi niwapendezavyo watu wote katika mambo yote, nisitake faida yangu mwenyewe, ila faida yao walio wengi, wapate kuokolewa."}, {"r": "Zaburi 12:2", "t": "Husemezana yasiyofaa kila mtu na mwenziwe, Wenye midomo ya kujipendekeza; Husemezana kwa mioyo ya unafiki;"}, {"r": "Wimbo Ulio Bora 7:13", "t": "Mitunguja hutoa harufu yake; Juu ya milango yetu yako matunda mazuri, Mapya na ya kale, ya kila namna, Niliyokuwekea, mpendwa wangu."}, {"r": "Zaburi 106:24", "t": "Wakaidharau nchi ile ya kupendeza, Wala hawakuliamini neno lake."}, {"r": "2 Timotheo 3:11", "t": "na upendo, na saburi; tena na adha zangu na mateso, mambo yaliyonipata katika Antiokia, katika Ikonio, na katika Listra, kila namna ya adha niliyoistahimili, naye Bwana aliniokoa katika hayo yote."}, {"r": "Malaki 3:12", "t": "Na mataifa yote watawaiteni heri; maana mtakuwa nchi ya kupendeza sana, asema Bwana wa majeshi."}, {"r": "Waefeso 4:16", "t": "Katika yeye mwili wote ukiungamanishwa na kushikanishwa kwa msaada wa kila kiungo, kwa kadiri ya utendaji wa kila sehemu moja moja, huukuza mwili upate kujijenga wenyewe katika upendo."}, {"r": "Mithali 22:11", "t": "Apendaye usafi wa moyo, na neema ya midomo; Mfalme atakuwa rafiki yake."}, {"r": "Luka 10:22", "t": "Akasema, Nimekabidhiwa vyote na Baba yangu, wala hakuna amjuaye Mwana ila Baba; wala hakuna amjuaye Baba ila Mwana, na ye yote ambaye Mwana apenda kumfunulia."}, {"r": "1 Timotheo 2:15", "t": "Walakini ataokolewa kwa uzazi wake, kama wakidumu katika imani na upendo na utakaso, pamoja na moyo wa kiasi."}, {"r": "Mithali 24:4", "t": "Na kwa maarifa vyumba vyake hujazwa Vitu vyote vya thamani na vya kupendeza."}, {"r": "Ufunuo wa Yohana 22:15", "t": "Huko nje wako mbwa, na wachawi, na wazinzi, na wauaji, na hao waabuduo sanamu, na kila mtu apendaye uongo na kuufanya."}, {"r": "Matendo ya Mitume 2:47", "t": "wakimsifu Mungu, na kuwapendeza watu wote. Bwana akalizidisha kanisa kila siku kwa wale waliokuwa wakiokolewa."}, {"r": "Mithali 26:28", "t": "Ulimi unenao uongo huwachukia wale uliowajeruhi; Na kinywa cha kujipendekeza hutenda uharibifu."}, {"r": "Mathayo 20:15", "t": "Si halali yangu kutumia vilivyo vyangu kama nipendavyo? Au jicho lako limekuwa ovu kwa sababu ya mimi kuwa mwema?"}, {"r": "Yuda 1:16", "t": "Watu hawa ni wenye kunung'unika, wenye kulalamika, waendao kwa tamaa zao, na vinywa vyao vyanena maneno makuu mno ya kiburi, wakipendelea watu wenye cheo kwa ajili ya faida."}, {"r": "Luka 16:14", "t": "Basi Mafarisayo, ambao wenyewe ni wapenda fedha, waliyasikia hayo yote, wakamdhihaki."}, {"r": "Mithali 8:21", "t": "Niwarithishe mali wale wanipendao, Tena nipate kuzijaza hazina zao."}, {"r": "Wagalatia 5:13", "t": "Maana ninyi, ndugu, mliitwa mpate uhuru; lakini uhuru wenu usiwe sababu ya kuufuata mwili, bali tumikianeni kwa upendo."}, {"r": "Zaburi 84:1", "t": "Maskani zako zapendeza kama nini, Ee Bwana wa majeshi!"}, {"r": "Mithali 15:17", "t": "Chakula cha mboga penye mapendano; Ni bora kuliko ng'ombe aliyenona pamoja na kuchukiana."}, {"r": "Wakolosai 1:8", "t": "naye alitueleza upendo wenu katika Roho."}, {"r": "Waefeso 6:6", "t": "wala si kwa utumwa wa macho tu kama wajipendekazao kwa wanadamu bali kama watumwa wa Kristo, mkitenda yampendezayo Mungu kwa moyo;"}, {"r": "Wimbo Ulio Bora 1:15", "t": "Tazama, u mzuri, mpenzi wangu, U mzuri, macho yako ni kama ya hua."}, {"r": "2 Wakorintho 11:11", "t": "Kwa nini? Je! Ni kwa sababu siwapendi ninyi? Mungu anajua."}, {"r": "Hosea 13:15", "t": "Ajapokuwa yeye ni mwenye kuzaa sana kati ya ndugu zake, upepo wa mashariki utakuja, hiyo pumzi ya Bwana itokayo upande wa nyikani, na kijito chake cha maji kitakauka, na chemchemi yake itakaushwa; yeye atateka nyara hazina ya vyombo vyote vipendezavyo."}, {"r": "2 Wakorintho 12:15", "t": "Nami kwa furaha nyingi nitatapanya, tena nitatapanywa kwa ajili ya roho zenu. Je! Kadiri nizidivyo kuwapenda sana, ninapungukiwa kupendwa?"}, {"r": "Waefeso 4:15", "t": "Lakini tuishike kweli katika upendo na kukua hata tumfikie yeye katika yote, yeye aliye kichwa, Kristo."}, {"r": "Wakolosai 3:22", "t": "Ninyi watumwa, watiini hao ambao kwa mwili ni bwana zenu, katika mambo yote, si kwa utumwa wa macho, kama wajipendekezao kwa wanadamu, bali kwa unyofu wa moyo, mkimcha Bwana."}, {"r": "Yohana 3:8", "t": "Upepo huvuma upendako, na sauti yake waisikia, lakini hujui unakotoka wala unakokwenda; kadhalika na hali yake kila mtu aliyezaliwa kwa Roho."}, {"r": "Wimbo Ulio Bora 5:1", "t": "Naingia bustanini mwangu, umbu langu, bibi arusi, Nachuma manemane yangu na rihani, Nala sega la asali na asali yangu, Nanywa divai yangu na maziwa. Kaleni, rafiki zangu, kanyweni, Naam, nyweni sana, wapendwa wangu."}, {"r": "Waefeso 4:2", "t": "kwa unyenyekevu wote na upole, kwa uvumilivu, mkichukuliana katika upendo;"}, {"r": "2 Petro 1:17", "t": "Maana alipata kwa Mungu Baba heshima na utukufu, hapo alipoletewa sauti iliyotoka katika utukufu mkuu, Huyu ni Mwanangu, mpendwa wangu, ninayependezwa naye."}, {"r": "2 Samueli 1:26", "t": "Nimesikitika kwa ajili yako, Yonathani, ndugu yangu, Ulikuwa ukinipendeza sana; Upendo wako kwangu ulikuwa wa ajabu, Kupita upendo wa wanawake."}, {"r": "Wimbo Ulio Bora 1:7", "t": "Nijulishe, ee mpendwa wa nafsi yangu, Ni wapi utakapolisha kundi lako, Ni wapi utakapolilaza adhuhuri. Kwa nini niwe kama aliyefungiwa kidoto, Karibu na makundi ya wenzako?"}, {"r": "2 Timotheo 1:13", "t": "Shika kielelezo cha maneno yenye uzima uliyoyasikia kwangu, katika imani na upendo ulio katika Kristo Yesu."}, {"r": "Yohana 13:1", "t": "Basi, kabla ya sikukuu ya Pasaka, Yesu, hali akijua ya kuwa saa yake imefika, atakayotoka katika ulimwengu kwenda kwa Baba, naye ali amewapenda watu wake katika ulimwengu, aliwapenda upeo."}, {"r": "Ayubu 19:14", "t": "Watu wa mbari yangu wamekoma, Na rafiki zangu niwapendao wamenisahau."}, {"r": "Wimbo Ulio Bora 3:1", "t": "Usiku kitandani nalimtafuta mpendwa wa nafsi yangu, Nalimtafuta, nisimpate."}, {"r": "Ufunuo wa Yohana 3:19", "t": "Wote niwapendao mimi nawakemea, na kuwarudi; basi uwe na bidii, ukatubu."}, {"r": "Yuda 1:2", "t": "Mwongezewe rehema na amani na upendano."}, {"r": "Wimbo Ulio Bora 4:16", "t": "Amka, kaskazi; nawe uje, kusi; Vumeni juu ya bustani yangu, Manukato ya bustani yatokee. Mpendwa wangu na aingie bustanini mwake, Akayale matunda yake mazuri."}, {"r": "Zaburi 11:5", "t": "Bwana humjaribu mwenye haki; Bali nafsi yake humchukia asiye haki, Na mwenye kupenda udhalimu."}, {"r": "Wimbo Ulio Bora 5:16", "t": "Kinywa chake kimejaa maneno matamu, Ndiye mzuri sana pia pia. Ni huyu mpendwa wangu, ni huyu rafiki yangu, Enyi binti za Yerusalemu."}, {"r": "Ayubu 32:22", "t": "Kwani mimi sijui kujipendekeza; Au Muumba wangu angeniondoa kwa upesi."}, {"r": "Ayubu 13:8", "t": "Je! Mtamwonyesha yeye upendeleo? Mtamtetea Mungu?"}, {"r": "Yohana 5:42", "t": "Walakini nimewajua ninyi ya kuwa hamna upendo wa Mungu ndani yenu."}, {"r": "Zaburi 12:3", "t": "Bwana ataikata midomo yote ya kujipendekeza, Nao ulimi unenao maneno ya kiburi;"}, {"r": "Marko 9:7", "t": "Kisha likatokea wingu, likawatia uvuli; sauti ikatoka katika lile wingu, Huyu ni Mwanangu, mpendwa wangu, msikieni yeye."}, {"r": "Yeremia 27:5", "t": "Mimi nimeiumba dunia hii, wanadamu na wanyama walio juu ya uso wa nchi, kwa uweza wangu mkuu, na kwa mkono wangu ulionyoshwa; nami nawapa watu kama inipendezavyo."}, {"r": "2 Petro 3:9", "t": "Bwana hakawii kuitimiza ahadi yake, kama wengine wanavyokudhani kukawia, bali huvumilia kwenu, maana hapendi mtu ye yote apotee, bali wote wafikilie toba."}, {"r": "1 Wathesalonike 1:3", "t": "Wala hatuachi kuikumbuka kazi yenu ya imani, na taabu yenu ya upendo, na saburi yenu ya tumaini lililo katika Bwana wetu Yesu Kristo, mbele za Mungu Baba yetu."}, {"r": "Tito 3:15", "t": "Watu wote walio pamoja nami wakusalimu. Tusalimie wale watupendao katika imani. Neema na iwe pamoja nanyi nyote."}, {"r": "Wimbo Ulio Bora 7:10", "t": "Mimi ni wake mpendwa wangu, Na shauku yake ni juu yangu."}, {"r": "Zaburi 147:10", "t": "Hapendezwi na nguvu za farasi, Wala hairidhii miguu ya mtu."}, {"r": "Wakolosai 1:27", "t": "ambao Mungu alipenda kuwajulisha jinsi ulivyo utajiri wa utukufu wa siri hii katika Mataifa, nao ni Kristo ndani yenu, tumaini la utukufu"}, {"r": "Yohana 8:42", "t": "Yesu akawaambia, Kama Mungu angekuwa baba yenu, mngenipenda mimi; kwa maana nalitoka kwa Mungu, nami nimekuja; wala sikuja kwa nafsi yangu, bali yeye ndiye aliyenituma."}, {"r": "Zaburi 18:1", "t": "Wewe, Bwana, nguvu zangu, nakupenda sana;"}, {"r": "1 Timotheo 5:21", "t": "Nakuagiza mbele za Mungu, na mbele za Kristo Yesu, na mbele za malaika wateule, uyatende hayo pasipo kuhukumu kwa haraka; usifanye neno lo lote kwa upendeleo."}, {"r": "Zaburi 34:12", "t": "Ni nani mtu yule apendezwaye na uzima, Apendaye siku nyingi apate kuona mema?"}, {"r": "Mhubiri 5:10", "t": "Apendaye fedha hatashiba fedha, Wala apendaye wingi hatashiba nyongeza."}, {"r": "Waefeso 6:21", "t": "Basi ninyi nanyi mpate kuzijua habari zangu, ni hali gani, Tikiko, ndugu mpendwa, mhudumu mwaminifu katika Bwana, atawajulisheni mambo yote;"}, {"r": "2 Wathesalonike 1:3", "t": "Ndugu, imetupasa kumshukuru Mungu sikuzote kwa ajili yenu, kama ilivyo wajibu, kwa kuwa imani yenu inazidi sana, na upendo wa kila mtu kwenu kwa mwenzake umekuwa mwingi."}, {"r": "1 Wakorintho 11:13", "t": "Je! Inapendeza mwanamke amwombe Mungu asipofunikwa kichwa?"}, {"r": "Matendo ya Mitume 13:22", "t": "Na alipokwisha kumwondoa huyo, akamwinua Daudi awe mfalme wao ambaye alimshuhudia, akisema, Nimemwona Daudi, mwana wa Yese, mtu anayeupendeza moyo wangu, atakayefanya mapenzi yangu yote."}, {"r": "Zaburi 122:6", "t": "Utakieni Yerusalemu amani; Na wafanikiwe wakupendao;"}, {"r": "Zaburi 40:16", "t": "Washangilie, wakufurahie, Wote wakutafutao. Waupendao wokovu wako Waseme daima, Atukuzwe Bwana."}, {"r": "1 Petro 2:17", "t": "Waheshimuni watu wote. Wapendeni ndugu. Mcheni Mungu. Mpeni heshima mfalme."}, {"r": "2 Wakorintho 8:8", "t": "Sineni ili kuwaamuru, bali kwa bidii ya watu wengine nijaribu unyofu wa upendo wenu."}, {"r": "3 Yohana 1:6", "t": "waliokushuhudia upendo wako mbele ya kanisa; utafanya vizuri ukiwasafirisha kama ipasavyo kwa Mungu."}, {"r": "Mhubiri 9:1", "t": "Na kwa ajili ya hayo yote, nikatia moyo wangu katika kuyatafutatafuta haya; ya kuwa wenye haki, na wenye hekima, pamoja na matendo yao yote, wamo mkononi mwa Mungu; kwamba ni pendo au kwamba ni chuki, mwanadamu hajui; mambo yote yawapita."}, {"r": "Matendo ya Mitume 2:26", "t": "Kwa hiyo moyo wangu ukapendezewa, ulimi wangu ukafurahi; Tena mwili wangu nao utakaa katika matumaini."}, {"r": "Mithali 19:8", "t": "Apataye hekima hujipenda nafsi yake; Ashikaye ufahamu atapata mema."}, {"r": "Wimbo Ulio Bora 2:13", "t": "Mtini wapevusha tini zake, Na mizabibu inachanua, Inatoa harufu yake nzuri; Ondoka, mpenzi wangu, mzuri wangu, uje zako."}, {"r": "Isaya 56:10", "t": "Walinzi wake ni vipofu, wote pia hawana maarifa; wote ni mbwa walio bubu, hawawezi kulia; huota ndoto, hulala, hupenda usingizi."}, {"r": "1 Wakorintho 12:11", "t": "lakini kazi hizi zote huzitenda Roho huyo mmoja, yeye yule, akimgawia kila mtu peke yake kama apendavyo yeye."}, {"r": "Wafilipi 1:9", "t": "Na hii ndiyo dua yangu, kwamba pendo lenu lizidi kuwa jingi sana, katika hekima na ufahamu wote;"}, {"r": "Waebrania 1:9", "t": "Umependa haki, umechukia maasi; Kwa hiyo Mungu, Mungu wako, amekutia mafuta, Mafuta ya shangwe kupita wenzio."}, {"r": "Wafilipi 4:1", "t": "Basi, ndugu zangu, wapendwa wangu, ninaowaonea shauku, furaha yangu, na taji yangu, hivyo simameni imara katika Bwana, wapenzi wangu."}, {"r": "Wakolosai 1:13", "t": "Naye alituokoa katika nguvu za giza, akatuhamisha na kutuingiza katika ufalme wa Mwana wa pendo lake;"}, {"r": "Luka 6:32", "t": "Maana mkiwapenda wale wawapendao ninyi, mwaonyesha fadhili gani? Kwa kuwa hata wenye dhambi huwapenda wale wawapendao."}, {"r": "Yeremia 51:9", "t": "Tungependa kuuponya Babeli, Lakini haukuponyeka; Mwacheni, nasi twendeni zetu, Kila mtu hata nchi yake mwenyewe; Maana hukumu yake inafika hata mbinguni, Nayo imeinuliwa kufikilia mawinguni."}, {"r": "Matendo ya Mitume 10:34", "t": "Petro akafumbua kinywa chake, akasema, Hakika natambua ya kuwa Mungu hana upendeleo;"}, {"r": "Wimbo Ulio Bora 3:2", "t": "Nikasema, Haya, niondoke nizunguke mjini, Katika njia zake na viwanjani, Nimtafute mpendwa wa nafsi yangu. Nikamtafuta, nisimpate."}, {"r": "Zaburi 119:5", "t": "Ningependa njia zangu ziwe thabiti, Nizitii amri zako."}, {"r": "Wimbo Ulio Bora 4:1", "t": "Tazama, u mzuri, mpenzi wangu, U mzuri, macho yako ni kama ya hua, Nyuma ya barakoa yako. Nywele zako ni kama kundi la mbuzi, Wakijilaza mbavuni pa mlima Gileadi."}, {"r": "Mithali 8:17", "t": "Nawapenda wale wanipendao, Na wale wanitafutao kwa bidii wataniona."}, {"r": "Isaya 21:4", "t": "Moyo wangu unapigapiga, utisho umenitaabisha, gizagiza la jioni nilipendalo limegeuka likanitetemesha."}, {"r": "Mika 3:2", "t": "Ninyi mnaoyachukia mema, na kuyapenda mabaya; ninyi mnaowachuna watu ngozi yao, na nyama mifupani mwao."}, {"r": "Zaburi 51:16", "t": "Maana hupendezwi na dhabihu, au ningeitoa, Wewe huridhii sadaka ya kuteketezwa."}, {"r": "Warumi 7:16", "t": "Lakini kama nikilitenda lile nisilolipenda, naikiri ile sheria ya kuwa ni njema."}, {"r": "1 Wathesalonike 3:6", "t": "Lakini Timotheo alipotujia hivi sasa kutoka kwenu, alituletea habari njema za imani yenu na upendo wenu, na ya kwamba mnatukumbuka vema siku zote; mkitamani kutuona sisi vile vile kama sisi kuwaona ninyi."}, {"r": "2 Timotheo 2:22", "t": "Lakini zikimbie tamaa za ujanani; ukafuate haki, na imani, na upendo, na amani, pamoja na wale wamwitao Bwana kwa moyo safi."}, {"r": "1 Wakorintho 13:3", "t": "Tena nikitoa mali zangu zote kuwalisha maskini, tena nikijitoa mwili wangu niungue moto, kama sina upendo, hainifaidii kitu."}, {"r": "Filemoni 1:9", "t": "lakini, kwa ajili ya upendo nakusihi, kwa kuwa ni kama nilivyo, Paulo mzee, na sasa mfungwa wa Kristo Yesu pia."}, {"r": "Yeremia 5:31", "t": "Manabii wanatabiri uongo, na makuhani wanatawala kwa msaada wa hao; na watu wangu wanapenda mambo yawe hivyo. Nanyi mtafanya nini mwisho wake?"}, {"r": "2 Wathesalonike 2:10", "t": "na katika madanganyo yote ya udhalimu kwa hao wanaopotea; kwa sababu hawakukubali kuipenda ile kweli, wapate kuokolewa."}, {"r": "Ufunuo wa Yohana 20:9", "t": "Wakapanda juu ya upana wa nchi, wakaizingira kambi ya watakatifu, na mji huo uliopendwa. Moto ukashuka kutoka mbinguni, ukawala."}, {"r": "Yohana 15:17", "t": "Haya nawaamuru ninyi, mpate kupendana."}, {"r": "Waebrania 2:4", "t": "Mungu naye akishuhudu pamoja nao kwa ishara na ajabu na nguvu za namna nyingi, na kwa magawanyo ya Roho Mtakatifu, kama alivyopenda mwenyewe."}, {"r": "Waefeso 5:4", "t": "wala aibu wala maneno ya upuzi wala ubishi; hayo hayapendezi; bali afadhali kushukuru."}, {"r": "Wimbo Ulio Bora 8:6", "t": "Nitie kama muhuri moyoni mwako, Kama muhuri juu ya mkono wako; Kwa maana upendo una nguvu kama mauti, Na wivu ni mkali kama ahera. Mwako wake ni mwako wa moto, Na miali yake ni miali ya Yahu."}, {"r": "Yeremia 14:10", "t": "Bwana awaambia watu hawa hivi, Hivyo ndivyo walivyopenda kutangatanga; hawakuizuia miguu yao; basi, Bwana hawakubali; sasa ataukumbuka uovu wao, atawapatiliza dhambi zao."}, {"r": "Mithali 7:18", "t": "Haya, na tushibe upendo hata asubuhi, Tujifurahishe nafsi zetu kwa mahaba."}, {"r": "Wakolosai 4:7", "t": "Tikiko, ndugu mpendwa, mtumishi mwaminifu, mjoli wangu katika Bwana, atawaarifu mambo yangu yote;"}, {"r": "Zaburi 119:35", "t": "Uniendeshe katika mapito ya maagizo yako, Kwa maana nimependezwa nayo."}, {"r": "Wimbo Ulio Bora 3:3", "t": "Walinzi wazungukao mjini waliniona; Je! Mmemwona mpendwa wa nafsi yangu?"}, {"r": "Yeremia 30:14", "t": "Wote wakupendao wamekusahau; hawakutafuti; maana nimekujeruhi kwa jeraha ya adui, kwa adhabu ya mtu mkatili; kwa sababu ya ukubwa wa uovu wako, kwa sababu dhambi zako zilikuwa zimeongezeka."}, {"r": "Wimbo Ulio Bora 5:2", "t": "Nalikuwa nimelala, lakini moyo wangu u macho, Sikiliza! Mpendwa wangu anabisha! Nifungulie, umbu langu, mpenzi wangu, Hua wangu, mkamilifu wangu, Kwa maana kichwa changu kimelowa umande, Nywele zangu zina manyunyu ya usiku."}, {"r": "Sefania 3:17", "t": "Bwana, Mungu wako, yu katikati yako shujaa awezaye kuokoa; Atakushangilia kwa furaha kuu, Atakutuliza katika upendo wake, Atakufurahia kwa kuimba."}, {"r": "Amosi 5:15", "t": "Yachukieni mabaya; yapendeni mema; mkaithibitishe haki langoni; yamkini kwamba Bwana, Mungu wa majeshi, atawafanyia fadhili mabaki ya Yusufu."}, {"r": "1 Wakorintho 13:2", "t": "Tena nijapokuwa na unabii, na kujua siri zote na maarifa yote, nijapokuwa na imani timilifu kiasi cha kuweza kuhamisha milima, kama sina upendo, si kitu mimi."}, {"r": "Yakobo 4:15", "t": "Badala ya kusema, Bwana akipenda, tutakuwa hai na kufanya hivi au hivi."}, {"r": "Yohana 12:25", "t": "Yeye aipendaye nafsi yake ataiangamiza; naye aichukiaye nafsi yake katika ulimwengu huu ataisalimisha hata uzima wa milele."}, {"r": "1 Petro 3:10", "t": "Kwa maana, Atakaye kupenda maisha, Na kuona siku njema, Auzuie ulimi wake usinene mabaya, Na midomo yake isiseme hila."}, {"r": "Luka 20:13", "t": "Basi, bwana wa shamba la mizabibu alisema, Nifanyeje? Nitamtuma mwanangu, mpendwa wangu; yamkini watamheshimu yeye."}, {"r": "Waebrania 13:1", "t": "Upendano wa ndugu na udumu."}, {"r": "2 Petro 1:20", "t": "Mkijua neno hili kwanza, ya kwamba hakuna unabii katika maandiko upatao kufasiriwa kama apendavyo mtu fulani tu."}, {"r": "Zaburi 147:1", "t": "Haleluya. Msifuni Bwana; Maana ni vema kumwimbia Mungu wetu, Maana kwapendeza, kusifu ni kuzuri."}, {"r": "Zaburi 40:6", "t": "Dhabihu na matoleo hukupendezwa nazo, Masikio yangu umeyazibua, Kafara na sadaka za dhambi hukuzitaka."}, {"r": "Mithali 3:17", "t": "Njia zake ni njia za kupendeza sana, Na mapito yake yote ni amani."}, {"r": "Zaburi 91:14", "t": "Kwa kuwa amekaza kunipenda Nitamwokoa; na kumweka palipo juu, Kwa kuwa amenijua Jina langu."}, {"r": "Kutoka 35:29", "t": "Wana wa Israeli wakaleta sadaka za kumpa Bwana kwa moyo wa kupenda; wote, waume kwa wake, ambao mioyo yao iliwafanya kuwa wapenda kuleta kwa hiyo kazi, ambayo Bwana aliamuru ifanywe kwa mkono wa Musa."}], "furaha": [{"r": "Sefania 3:17", "t": "Bwana, Mungu wako, yu katikati yako shujaa awezaye kuokoa; Atakushangilia kwa furaha kuu, Atakutuliza katika upendo wake, Atakufurahia kwa kuimba."}, {"r": "1 Wathesalonike 5:16", "t": "Furahini siku zote;"}, {"r": "Yohana 15:11", "t": "Hayo nimewaambia, ili furaha yangu iwe ndani yenu, na furaha yenu itimizwe."}, {"r": "Zaburi 28:7", "t": "Bwana ni nguvu zangu na ngao yangu. Moyo wangu umemtumaini, Nami nimesaidiwa; Basi, moyo wangu unashangilia, Na kwa wimbo wangu nitamshukuru."}, {"r": "Yohana 16:24", "t": "Hata sasa hamkuomba neno kwa jina langu; ombeni, nanyi mtapata; furaha yenu iwe timilifu."}, {"r": "Zaburi 16:11", "t": "Utanijulisha njia ya uzima; Mbele za uso wako ziko furaha tele; Na katika mkono wako wa kuume Mna mema ya milele."}, {"r": "Yohana 16:22", "t": "Basi ninyi hivi sasa mna huzuni; lakini mimi nitawaona tena; na mioyo yenu itafurahi, na furaha yenu hakuna awaondoleaye."}, {"r": "Zaburi 51:12", "t": "Unirudishie furaha ya wokovu wako; Unitegemeze kwa roho ya wepesi."}, {"r": "Zaburi 30:5", "t": "Maana ghadhabu zake ni za kitambo kidogo, Katika radhi yake mna uhai. Huenda kilio huja kukaa usiku, Lakini asubuhi huwa furaha."}, {"r": "Isaya 55:12", "t": "Maana mtatoka kwa furaha, Mtaongozwa kwa amani; Mbele yenu milima na vilima vitatoa nyimbo; Na miti yote ya kondeni itapiga makofi."}, {"r": "Mithali 17:22", "t": "Moyo uliochangamka ni dawa nzuri; Bali roho iliyopondeka huikausha mifupa."}, {"r": "Habakuki 3:18", "t": "Walakini nitamfurahia Bwana Nitamshangilia Mungu wa wokovu wangu."}, {"r": "Warumi 12:12", "t": "kwa tumaini, mkifurahi; katika dhiki, mkisubiri; katika kusali, mkidumu;"}, {"r": "Wafilipi 4:4", "t": "Furahini katika Bwana sikuzote; tena nasema, Furahini."}, {"r": "Zaburi 32:11", "t": "Mfurahieni Bwana; Shangilieni, enyi wenye haki Pigeni vigelegele vya furaha; Ninyi nyote mlio wanyofu wa moyo."}, {"r": "Zaburi 97:12", "t": "Enyi wenye haki, mmfurahieni Bwana, Na kulishukuru jina lake takatifu."}, {"r": "Zaburi 5:11", "t": "Nao wote wanaokukimbilia watafurahi; Watapiga daima kelele za furaha. Kwa kuwa Wewe unawahifadhi, Walipendao jina lako watakufurahia."}, {"r": "Warumi 14:17", "t": "Maana ufalme wa Mungu si kula wala kunywa, bali ni haki na amani na furaha katika Roho Mtakatifu."}, {"r": "Isaya 61:10", "t": "Nitafurahi sana katika Bwana, nafsi yangu itashangilia katika Mungu wangu; maana amenivika mavazi ya wokovu, amenifunika vazi la haki, kama bwana arusi ajipambavyo kwa kilemba cha maua, na kama bibi arusi ajipambavyo kwa vyombo vya dhahabu."}, {"r": "Zaburi 126:3", "t": "Bwana alitutendea mambo makuu, Tulikuwa tukifurahi."}, {"r": "Isaya 12:3", "t": "Basi, kwa furaha mtateka maji katika visima vya wokovu."}, {"r": "Wagalatia 5:22", "t": "Lakini tunda la Roho ni upendo, furaha, amani, uvumilivu, utu wema, fadhili, uaminifu,"}, {"r": "Luka 2:10", "t": "Malaika akawaambia, Msiogope; kwa kuwa mimi ninawaletea habari njema ya furaha kuu itakayokuwa kwa watu wote;"}, {"r": "Isaya 35:10", "t": "Na hao waliokombolewa na Bwana watarudi, watafika Sayuni wakiimba; na furaha ya milele itakuwa juu ya vichwa vyao; nao watapata kicheko na furaha, huzuni na kuugua zitakimbia."}, {"r": "Luka 15:10", "t": "Nawaambia, Vivyo hivyo kuna furaha mbele ya malaika wa Mungu kwa ajili ya mwenye dhambi mmoja atubuye."}, {"r": "Nehemia 8:10", "t": "Kisha akawaambia, Enendeni zenu, mle kilichonona, na kunywa kilicho kitamu, tena mpelekeeni sehemu yeye asiyewekewa kitu; maana siku hii ni takatifu kwa Bwana wetu; wala msihuzunike; kwa kuwa furaha ya Bwana ni nguvu zenu."}, {"r": "Warumi 15:13", "t": "Basi Mungu wa tumaini na awajaze ninyi furaha yote na amani katika kuamini, mpate kuzidi sana kuwa na tumaini, katika nguvu za Roho Mtakatifu."}, {"r": "1 Petro 1:8", "t": "Naye mwampenda, ijapokuwa hamkumwona; ambaye ijapokuwa hamwoni sasa, mnamwamini; na kufurahi sana, kwa furaha isiyoneneka, yenye utukufu,"}, {"r": "Mithali 15:13", "t": "Moyo wa furaha huchangamsha uso; Bali kwa huzuni ya moyo roho hupondeka."}, {"r": "Yakobo 1:2", "t": "Ndugu zangu, hesabuni ya kuwa ni furaha tupu, mkiangukia katika majaribu mbalimbali;"}, {"r": "Luka 15:7", "t": "Nawaambia, Vivyo hivyo kutakuwa na furaha mbinguni kwa ajili ya mwenye dhambi mmoja atubuye, kuliko kwa ajili ya wenye haki tisini na kenda ambao hawana haja ya kutubu."}, {"r": "Zaburi 100:1", "t": "Mfanyieni Bwana shangwe, dunia yote;"}, {"r": "Zaburi 34:5", "t": "Wakamwelekea macho wakatiwa nuru, Wala nyuso zao hazitaona haya."}, {"r": "Zaburi 118:24", "t": "Siku hii ndiyo aliyoifanya Bwana, Tutashangilia na kuifurahia."}, {"r": "Warumi 12:8", "t": "mwenye kuonya, katika kuonya kwake; mwenye kukirimu, kwa moyo mweupe; mwenye kusimamia kwa bidii mwenye kurehemu, kwa furaha."}, {"r": "Zaburi 132:9", "t": "Makuhani wako na wavikwe haki, Watauwa wako na washangilie."}, {"r": "Mithali 27:11", "t": "Mwanangu, uwe na hekima na kunifurahisha moyo wangu; Ili nipate kumjibu anilaumuye."}, {"r": "Yeremia 33:9", "t": "Na mji huu utakuwa kwangu jina la furaha, na sifa na utukufu, mbele ya mataifa yote ya dunia, watakaosikia habari ya mema yote niwatendeayo, nao wataogopa na kutetemeka, kwa sababu ya mema yote na amani nitakaoupatia mji huo."}, {"r": "Mithali 23:24", "t": "Baba yake mwenye haki atashangilia; Naye amzaaye mtoto mwenye hekima atamfurahia."}, {"r": "2 Wakorintho 7:13", "t": "Kwa hiyo tulifarijiwa. Tena katika kufarijiwa kwetu tulifurahi sana kupita kiasi kwa sababu ya furaha ya Tito; maana roho yake imeburudishwa na ninyi nyote."}, {"r": "Ayubu 39:13", "t": "Bawa la mbuni hufurahi; Lakini mabawa yake na manyoya yake, je! Yana huruma?"}, {"r": "Zaburi 86:11", "t": "Ee Bwana, unifundishe njia yako; Nitakwenda katika kweli yako; Moyo wangu na ufurahi kulicha jina lako;"}, {"r": "Sefania 2:15", "t": "Huu ndio mji ule wa furaha, Uliokaa pasipo kufikiri, Uliosema moyoni mwake, Mimi niko, Wala hapana mwingine ila mimi. Jinsi ulivyokuwa ukiwa, Mahali pa kulala pa wanyama wa bara! Kila mtu apitaye atazomea, Na kutikisa mkono wake."}, {"r": "Waebrania 12:11", "t": "Kila adhabu wakati wake haionekani kuwa kitu cha furaha, bali cha huzuni; lakini baadaye huwaletea wao waliozoezwa nayo matunda ya haki yenye amani."}, {"r": "Zaburi 30:11", "t": "Uligeuza matanga yangu kuwa machezo; Ulinivua gunia, ukanivika furaha."}, {"r": "Malaki 2:17", "t": "Mmemchokesha Bwana kwa maneno yenu. Lakini ninyi mwasema, Tumemchokesha kwa maneno gani? Kwa kuwa mwasema, Kila atendaye mabaya ni mwema machoni pa Bwana, naye huwafurahia watu hao, au, Mungu mwenye kuhukumu yuko wapi?"}, {"r": "Yohana 3:30", "t": "Basi hii furaha yangu imetimia. Yeye hana budi kuzidi, bali mimi kupungua."}, {"r": "Mathayo 13:44", "t": "Tena ufalme wa mbinguni umefanana na hazina iliyositirika katika shamba; ambayo mtu alipoiona, aliificha; na kwa furaha yake akaenda akauza alivyo navyo vyote, akalinunua shamba lile."}, {"r": "Mathayo 25:23", "t": "Bwana wake akamwambia, Vema, mtumwa mwema na mwaminifu; ulikuwa mwaminifu kwa machache, nitakuweka juu ya mengi; ingia katika furaha ya bwana wako."}, {"r": "Wafilipi 2:28", "t": "Kwa hiyo nimefanya bidii nyingi zaidi kumtuma, ili mtakapomwona tena mpate kufurahi, nami nipunguziwe huzuni yangu."}, {"r": "Mithali 17:5", "t": "Amdhihakiye maskini humsuta Muumba wake; Naye aufurahiaye msiba hatakosa adhabu."}, {"r": "Hosea 10:5", "t": "Wakaao Samaria wataona hofu kwa ajili ya ndama za BethAveni; kwa maana watu wa mji huo wataulilia, na makuhani wake walioufurahia, kwa sababu ya utukufu wake; kwa maana umetoweka."}, {"r": "Yohana 11:15", "t": "Nami nafurahi kwa ajili yenu kwamba sikuwako huko, ili mpate kuamini; lakini na twendeni kwake."}, {"r": "Luka 6:23", "t": "Furahiwani siku ile na kurukaruka, kwa kuwa, tazama, thawabu yenu ni kubwa mbinguni, maana, baba zao waliwatenda manabii vivyo hivyo."}, {"r": "Zaburi 35:9", "t": "Na nafsi yangu itamfurahia Bwana, Na kuushangilia wokovu wake."}, {"r": "2 Wakorintho 8:2", "t": "maana walipokuwa wakijaribiwa kwa dhiki nyingi, wingi wa furaha yao na umaskini wao uliokuwa mwingi uliwaongezea utajiri wa ukarimu wao."}, {"r": "Matendo ya Mitume 7:41", "t": "Wakafanya ndama siku zile, wakaleta dhabihu kwa sanamu ile, wakafurahia kazi za mikono yao."}, {"r": "Luka 24:41", "t": "Basi walipokuwa hawajaamini kwa furaha, huku wakistaajabu, aliwaambia, Mna chakula cho chote hapa?"}, {"r": "Zaburi 45:15", "t": "Watapelekwa kwa furaha na shangwe, Na kuingia katika nyumba ya mfalme."}, {"r": "Zaburi 126:5", "t": "Wapandao kwa machozi Watavuna kwa kelele za furaha."}, {"r": "1 Wathesalonike 2:19", "t": "Maana tumaini letu, au furaha yetu, au taji ya kujionea fahari, ni nini? Je! Si ninyi, mbele za Bwana wetu Yesu, wakati wa kuja kwake?"}, {"r": "Luka 1:14", "t": "Nawe utakuwa na furaha na shangwe, na watu wengi watakufurahia kuzaliwa kwake."}, {"r": "Zaburi 119:16", "t": "Nitajifurahisha sana kwa amri zako, Sitalisahau neno lako."}, {"r": "Zaburi 105:3", "t": "Jisifuni kwa jina lake takatifu, Na ufurahi moyo wao wamtafutao Bwana."}, {"r": "Zaburi 90:14", "t": "Utushibishe asubuhi kwa fadhili zako, Nasi tutashangilia na kufurahi siku zetu zote."}, {"r": "Matendo ya Mitume 15:3", "t": "Basi, wakisafirishwa na kanisa, wakapita kati ya nchi ya Foinike na Samaria, wakitangaza habari za kuongoka kwao Mataifa; wakawafurahisha ndugu sana."}, {"r": "Warumi 15:32", "t": "nipate kufika kwenu kwa furaha, kama apendavyo Mungu, nikapate kupumzika pamoja nanyi."}, {"r": "Zaburi 65:12", "t": "Huyadondokea malisho ya nyikani, Na vilima vyajifunga furaha."}, {"r": "Zaburi 92:4", "t": "Kwa kuwa umenifurahisha, Bwana, Kwa kazi yako; nitashangilia Kwa ajili ya matendo ya mikono yako."}, {"r": "Yeremia 16:9", "t": "Maana Bwana wa majeshi, Mungu wa Israeli, asema hivi, Mimi, mbele ya macho yenu, na katika siku zenu, nitaikomesha sauti ya furaha, na sauti ya kicheko, mahali hapa; sauti ya bwana arusi, na sauti ya bibi arusi."}, {"r": "1 Wakorintho 13:6", "t": "haufurahii udhalimu, bali hufurahi pamoja na kweli;"}, {"r": "Zaburi 53:6", "t": "Laiti wokovu wa Israeli utoke katika Sayuni! MUNGU awarudishapo wafungwa wa watu wake; Yakobo atashangilia, Israeli atafurahi."}, {"r": "Mhubiri 7:14", "t": "Siku ya kufanikiwa ufurahi, Na siku ya mabaya ufikiri. Mungu ameifanya hiyo moja kwenda sambamba na hiyo ya pili, ili mwanadamu asipate kulijua neno lo lote litakalofuata baada yake."}, {"r": "Zaburi 60:6", "t": "Mungu amenena kwa utakatifu wake, Nami nitashangilia. Nitaigawanya Shekemu, Nitalipima bonde la Sukothi."}, {"r": "Mithali 12:25", "t": "Uzito katika moyo wa mtu huuinamisha; Bali neno jema huufurahisha."}, {"r": "Yohana 3:29", "t": "Aliye naye bibi arusi ndiye bwana arusi; lakini rafiki yake bwana arusi, yeye anayesimama na kumsikia, aifurahia sana sauti yake bwana arusi."}, {"r": "Isaya 29:19", "t": "Wanyenyekevu nao wataongeza furaha yao katika Bwana, na maskini katika wanadamu watafurahi katika Mtakatifu wa Israeli."}, {"r": "Zaburi 89:42", "t": "Umeutukuza mkono wa kuume wa watesi wake; Umewafurahisha wote wanaomchukia."}, {"r": "Isaya 52:9", "t": "Pigeni kelele za furaha, imbeni pamoja, Enyi mahali pa Yerusalemu palipokuwa ukiwa; Kwa kuwa Bwana amewafariji watu wake, Ameukomboa Yerusalemu."}, {"r": "Wafilipi 2:18", "t": "Nanyi vivyo hivyo furahini, tena furahini pamoja nami."}, {"r": "Zaburi 45:7", "t": "Umeipenda haki; Umeichukia dhuluma. Kwa hiyo MUNGU, Mungu wako, amekupaka mafuta, Mafuta ya furaha kuliko wenzako."}, {"r": "Ufunuo wa Yohana 12:12", "t": "Kwa hiyo shangilieni, enyi mbingu, nanyi mkaao humo. Ole wa nchi na bahari! Kwa maana yule Ibilisi ameshuka kwenu mwenye ghadhabu nyingi, akijua ya kuwa ana wakati mchache tu."}, {"r": "Matendo ya Mitume 27:25", "t": "Basi, wanaume, changamkeni; kwa sababu namwamini Mungu, ya kwamba yatakuwa vile vile kama nilivyoambiwa."}, {"r": "Zaburi 89:16", "t": "Kwa jina lako hufurahi mchana kutwa, Na kwa haki yako hutukuzwa."}, {"r": "Isaya 9:1", "t": "Lakini yeye aliyekuwa katika dhiki hatakosa changamko. Hapo kwanza aliiingiza nchi ya Zabuloni na nchi ya Naftali katika hali ya kudharauliwa, lakini zamani za mwisho ameifanya kuwa tukufu, karibu na njia ya bahari; ng'ambo ya Yordani, Galilaya ya mataifa."}, {"r": "Ufunuo wa Yohana 19:7", "t": "Na tufurahi, tukashangilie, tukampe utukufu wake; kwa kuwa arusi ya MwanaKondoo imekuja, na mkewe amejiweka tayari."}, {"r": "Mithali 14:10", "t": "Moyo huujua uchungu wa nafsi yake, Wala mgeni haishiriki furaha yake."}, {"r": "Zaburi 119:162", "t": "Naifurahia ahadi yako, Kama apataye mateka mengi."}, {"r": "Mithali 16:13", "t": "Midomo ya haki ni furaha ya wafalme; Nao humpenda yeye asemaye yaliyo sawa."}, {"r": "Amosi 6:13", "t": "ninyi mnaolifurahia jambo lisilo na maana, msemao, Je! Hatukujipatia pembe kwa nguvu zetu wenyewe?"}, {"r": "Zaburi 94:19", "t": "Katika wingi wa mawazo ya moyoni mwangu, Faraja zako zaifurahisha roho yangu."}, {"r": "Ayubu 8:19", "t": "Tazama, furaha ya njia yake ni hii, Na wengine watachipuka kutoka katika nchi."}, {"r": "1 Petro 4:13", "t": "Lakini kama mnavyoyashiriki mateso ya Kristo, furahini; ili na katika ufunuo wa utukufu wake mfurahi kwa shangwe."}, {"r": "Isaya 55:2", "t": "Kwani kutoa fedha kwa ajili ya kitu ambacho si chakula? Na mapato yenu kwa kitu kisichoshibisha? Nisikilizeni kwa bidii, mle kilicho chema, Na kujifurahisha nafsi zenu kwa unono."}, {"r": "Zaburi 98:6", "t": "Kwa panda na sauti ya baragumu. Shangilieni mbele za Mfalme, Bwana."}, {"r": "Isaya 51:11", "t": "Nao waliokombolewa na Bwana watarejea, Watafika Sayuni, wakiimba; Furaha ya milele itakuwa juu ya vichwa vyao; Watapata shangwe na furaha; Huzuni na kuugua zitakimbia."}, {"r": "Isaya 58:2", "t": "Walakini wanitafuta kila siku; hupenda kujua njia zangu; kama vile taifa waliotenda haki, wasioacha sheria ya Mungu wao, hutaka kwangu amri za haki; hufurahi kumkaribia Mungu."}, {"r": "Zaburi 119:77", "t": "Rehema zako zinijie nipate kuishi, Maana sheria yako ni furaha yangu."}, {"r": "Mithali 8:30", "t": "Ndipo nilipokuwa pamoja naye, kama stadi wa kazi; Nikawa furaha yake kila siku; Nikifurahi daima mbele zake;"}, {"r": "Waebrania 11:25", "t": "akaona ni afadhali kupata mateso pamoja na watu wa Mungu kuliko kujifurahisha katika dhambi kwa kitambo;"}, {"r": "Ayubu 38:7", "t": "Hapo nyota za asubuhi zilipoimba pamoja, Na wana wote wa Mungu walipopiga kelele kwa furaha?"}, {"r": "Waebrania 11:13", "t": "Hawa wote wakafa katika imani, wasijazipokea zile ahadi, bali wakaziona tokea mbali na kuzishangilia, na kukiri kwamba walikuwa wageni, na wasafiri juu ya nchi."}, {"r": "Mithali 29:17", "t": "Mrudi mwanao naye atakustarehesha; Naam, atakufurahisha nafsi yako."}, {"r": "Matendo ya Mitume 27:36", "t": "Ndipo wakachangamka wote, wakala chakula wenyewe."}, {"r": "Isaya 65:18", "t": "Lakini furahini, mkashangilie daima, kwa ajili ya hivi niviumbavyo; maana, tazama, naumba Yerusalemu uwe shangwe, na watu wake wawe furaha."}, {"r": "Matendo ya Mitume 21:17", "t": "Tulipofika Yerusalemu wale ndugu wakatukaribisha kwa furaha."}, {"r": "Isaya 66:5", "t": "Lisikilizeni neno la Bwana, ninyi mtetemekao kwa sababu ya neno lake; Ndugu zenu wawachukiao ninyi, waliowatupa kwa ajili ya jina langu, wamesema, Na atukuzwe Bwana, tupate kuiona furaha yenu; lakini watatahayarika."}, {"r": "Mhubiri 11:9", "t": "Wewe kijana, uufurahie ujana wako, na moyo wako ukuchangamshe siku za ujana wako, ukaziendee njia za moyo wako, na katika maono ya macho yako, lakini ujue wewe ya kwamba kwa ajili ya hayo yote Mungu atakuleta hukumuni."}, {"r": "Warumi 16:19", "t": "Maana utii wenu umewafikilia watu wote; basi nafurahi kwa ajili yenu, lakini nataka ninyi kuwa wenye hekima katika mambo mema, na wajinga katika mambo mabaya."}, {"r": "Isaya 65:22", "t": "Hawatajenga, akakaa mtu mwingine ndani yake; hawatapanda, akala mtu mwingine; maana kama siku za mti ndivyo zitakavyokuwa siku za watu wangu, na wateule wangu wataifurahia kazi ya mikono yao muda wa siku nyingi."}, {"r": "Zaburi 81:1", "t": "Mwimbieni Mungu, nguvu zetu, nyimbo za furaha, Mshangilieni Mungu wa Yakobo."}, {"r": "Yohana 20:20", "t": "Naye akiisha kusema hayo, akawaonyesha mikono yake na ubavu wake. Basi wale wanafunzi wakafurahi walipomwona Bwana."}, {"r": "Luka 15:5", "t": "Naye akiisha kumwona, humweka mabegani pake akifurahi."}, {"r": "Zekaria 4:7", "t": "Nani wewe, Ee mlima mkubwa? Mbele ya Zerubabeli utakuwa nchi tambarare; naye atalileta lile jiwe la kuwekwa juu kabisa pamoja na vigelegele vya, Neema, neema, ilikalie."}, {"r": "Wimbo Ulio Bora 1:4", "t": "Nivute nyuma yako, na tukimbie; Mfalme ameniingiza vyumbani mwake. Tutafurahi na kukushangilia; Tutazinena pambaja zako kuliko divai; Ndiyo, ina haki wakupende."}, {"r": "Zaburi 118:15", "t": "Sauti ya furaha na wokovu Imo hemani mwao wenye haki; Mkono wa kuume wa Bwana hutenda makuu."}, {"r": "Zekaria 8:19", "t": "Bwana wa majeshi asema hivi, Saumu ya mwezi wa nne, na saumu ya mwezi wa tano, na saumu ya mwezi wa saba, na saumu ya mwezi wa kumi, zitakuwa furaha na shangwe, na sikukuu za kuchangamkia, kwa nyumba ya Yuda; basi zipendeni kweli na amani."}, {"r": "Isaya 9:17", "t": "Kwa sababu hiyo Bwana hatawafurahia vijana wao, wala hatawahurumia yatima zao wala wajane wao; maana kila mtu ni mnajisi, dhalimu, na kila ulimi hunena upumbavu. Pamoja na hayo yote hasira yake haikugeukia mbali, lakini mkono wake umenyoshwa hata sasa."}, {"r": "Luka 21:28", "t": "Basi mambo hayo yaanzapo kutokea, changamkeni, mkaviinue vichwa vyenu, kwa kuwa ukombozi wenu umekaribia."}, {"r": "Zaburi 65:8", "t": "Kwa hiyo wakaao mbali kabisa huogopa ishara zako; Milango ya asubuhi na jioni waifurahisha."}, {"r": "Yohana 16:21", "t": "Mwanamke azaapo, yuna huzuni kwa kuwa saa yake imefika; lakini akiisha kuzaa mwana, haikumbuki tena ile dhiki, kwa sababu ya furaha ya kuzaliwa mtu ulimwenguni."}, {"r": "Wafilipi 2:29", "t": "Mpokeeni, basi, katika Bwana, kwa furaha yote, mkawahesabu watu kama huyu kuwa watu wa kuheshimiwa."}, {"r": "Mithali 2:14", "t": "Wafurahio kutenda mabaya; Wapendezwao na upotoe wa waovu;"}, {"r": "Ayubu 22:3", "t": "Je! Mwenyezi hupata furaha katika wewe kuwa mwenye haki? Au je, ni faida kwake, kwamba wafanya njia zako kuwa timilifu?"}, {"r": "Matendo ya Mitume 14:17", "t": "Lakini hakujiacha pasipo ushuhuda, kwa kuwa alitenda mema, akiwapeni mvua kutoka mbinguni, na nyakati za mavuno, akiwashibisha mioyo yenu chakula na furaha."}, {"r": "Yoeli 1:12", "t": "Mzabibu umesinyaa, mtini nao umevia; Nao mkomamanga na mtende na mtofaa; Naam, miti yote ya mashamba imekauka; Maana furaha imekauka katika wanadamu."}, {"r": "Mhubiri 8:15", "t": "Kisha nikaisifu furaha, kwa sababu mwanadamu hana neno lo lote lililo jema chini ya jua, kuliko kula, na kunywa, na kucheka; na yakuwa hilo likae naye katika amali yake, siku zote za maisha yake alizompa Mungu chini ya jua."}, {"r": "Isaya 30:29", "t": "Mtakuwa na wimbo kama vile wakati wa usiku, ishikwapo sikukuu takatifu, mtakuwa na furaha ya moyo kama vile mtu aendapo na filimbi katika mlima wa Bwana, aliye Mwamba wa Israeli."}, {"r": "3 Yohana 1:4", "t": "Sina furaha iliyo kuu kuliko hii, kusikia ya kwamba watoto wangu wanakwenda katika kweli."}, {"r": "Yuda 1:24", "t": "Yeye awezaye kuwalinda ninyi msijikwae, na kuwasimamisha mbele ya utukufu wake bila mawaa katika furaha kuu;"}, {"r": "Mithali 14:13", "t": "Hata wakati wa kucheka moyo huwa na huzuni; Na mwisho wa furaha ni uzito wa moyo."}, {"r": "2 Wakorintho 7:7", "t": "Wala si kwa kuja kwake tu, bali kwa zile faraja nazo alizofarijiwa kwenu, akituarifu habari ya shauku yenu, na maombolezo yenu, na bidii yenu kwa ajili yangu, hata nikazidi kufurahi."}, {"r": "Zaburi 13:5", "t": "Nami nimezitumainia fadhili zako; Moyo wangu na uufurahie wokovu wako."}, {"r": "Matendo ya Mitume 11:23", "t": "Naye, alipokwisha kufika na kuiona neema ya Mungu akafurahi, akawasihi wote waambatane na Bwana kwa kusudi la moyo."}, {"r": "Mhubiri 3:12", "t": "Mimi najua ya kwamba hakuna jema kwao kupita kufurahi, na kufanya mema maadamu wanaishi."}, {"r": "Isaya 64:5", "t": "Wewe wamlaki yeye afurahiaye yaliyo haki na kuyatenda, watu wale wakukumbukao katika njia zako; tazama, ulikuwa na hasira, nasi tulitenda dhambi; tumekuwa katika mambo haya muda mwingi; nasi, je! Tutaokolewa?"}, {"r": "2 Wakorintho 11:19", "t": "Ninyi, kwa kuwa mna akili, mnachukuliana na wajinga kwa furaha."}, {"r": "Waamuzi 9:19", "t": "basi ikiwa mmemtendea kwa uaminifu na uelekevu Yerubaali na nyumba yake hivi leo, basi furahini ninyi katika huyo Abimeleki, yeye naye na afurahi kwenu ninyi;"}, {"r": "Luka 8:40", "t": "Basi Yesu aliporudi mkutano ulimkaribisha kwa furaha, maana walikuwa wakimngojea wote."}, {"r": "Matendo ya Mitume 13:52", "t": "Na wanafunzi walijaa furaha na Roho Mtakatifu."}, {"r": "Luka 13:17", "t": "Aliposema haya wakatahayari wote walioshindana naye; mkutano wote wakafurahi kwa sababu ya mambo matukufu yaliyotendwa na yeye."}, {"r": "Matendo ya Mitume 28:15", "t": "Na kutoka huko ndugu, waliposikia habari zetu, wakaja kutulaki mpaka Soko la Apio na Mikahawa Mitatu. Paulo alipowaona alimshukuru Mungu, akachangamka."}, {"r": "Isaya 65:13", "t": "Kwa hiyo Bwana MUNGU asema hivi, Tazama, watumishi wangu watakula, bali ninyi mtaona njaa; tazama, watumishi wangu watakunywa, bali ninyi mtaona kiu; tazama, watumishi wangu watafurahi, bali ninyi mtatahayarika;"}, {"r": "1 Wathesalonike 1:6", "t": "Nanyi mkawa wafuasi wetu na wa Bwana, mkiisha kulipokea neno katika dhiki nyingi, pamoja na furaha ya Roho Mtakatifu."}, {"r": "Zaburi 4:7", "t": "Umenitia furaha moyoni mwangu, Kupita yao wanapozidishiwa nafaka na divai."}, {"r": "Filemoni 1:7", "t": "Maana nalikuwa na furaha nyingi na faraja kwa sababu ya upendo wako, kwa kuwa mioyo ya watakatifu imeburudishwa nawe, ndugu yangu."}, {"r": "Hosea 9:1", "t": "Usifurahi, Israeli, kwa sababu ya furaha, kama hao mataifa; kwa kuwa umezini juu ya Mungu wako, umependa ujira katika kila sakafu ya nafaka."}, {"r": "Mhubiri 10:19", "t": "Karamu hufanywa kwa ajili ya kicheko, Na divai huyafurahisha maisha; Na fedha huleta jawabu la mambo yote."}, {"r": "Mhubiri 9:7", "t": "Wewe enenda zako, ule chakula chako kwa furaha, unywe mvinyo yako kwa moyo wa kuchangamka; kwa kuwa Mungu amekwisha kuzikubali kazi zako."}, {"r": "Maombolezo 5:15", "t": "Furaha ya mioyo yetu imekoma; Machezo yetu yamegeuka maombolezo."}, {"r": "Zaburi 71:23", "t": "Midomo yangu itafurahi sana nikuimbiapo, Na nafsi yangu uliyoikomboa."}, {"r": "Luka 19:6", "t": "Akafanya haraka, akashuka, akamkaribisha kwa furaha."}, {"r": "Mithali 23:25", "t": "Na wafurahi baba yako na mama yako; Na afurahi aliyekuzaa."}, {"r": "Zaburi 86:4", "t": "Uifurahishe nafsi ya mtumishi wako, Maana nafsi yangu nakuinulia Wewe, Bwana."}, {"r": "Wafilipi 4:10", "t": "Nalifurahi sana katika Bwana, kwa kuwa sasa mwisho mmehuisha tena fikira zenu kwa ajili yangu, kama vile mlivyokuwa mkinifikiri hali yangu lakini hamkupata nafasi."}, {"r": "Wimbo Ulio Bora 2:3", "t": "Kama mpera kati ya miti ya msituni, Kadhalika mpendwa wangu kati ya vijana. Naliketi kivulini mwake kwa furaha, Na matunda yake naliyaonja kuwa matamu."}, {"r": "Zaburi 119:70", "t": "Mioyo yao imenenepa kama shahamu, Mimi nimeifurahia sheria yako."}, {"r": "Zaburi 34:2", "t": "Katika Bwana nafsi yangu itajisifu, Wanyenyekevu wasikie wakafurahi."}, {"r": "Luka 10:21", "t": "Saa ile ile alishangilia kwa Roho Mtakatifu, akasema, Nakushukuru, Baba, Bwana wa mbingu na nchi, kwa kuwa mambo haya umewaficha wenye hekima na akili; umewafunulia watoto wachanga; Naam, Baba, kwa kuwa ndivyo ilivyokupendeza."}, {"r": "Marko 4:16", "t": "Kadhalika na hawa ndio wapandwao penye miamba, ambao kwamba wakiisha kulisikia lile neno, mara hulipokea kwa furaha;"}, {"r": "Mithali 29:2", "t": "Wenye haki wakiwa na amri, watu hufurahi; Bali mwovu atawalapo, watu huugua."}, {"r": "Zaburi 97:1", "t": "Bwana ametamalaki, nchi na ishangilie, Visiwa vingi na vifurahi."}, {"r": "Zaburi 137:3", "t": "Maana huko waliotuchukua mateka Walitaka tuwaimbie; Na waliotuonea walitaka furaha; Tuimbieni baadhi ya nyimbo za Sayuni."}, {"r": "Mithali 5:19", "t": "Ni ayala apendaye na paa apendezaye; Maziwa yake yakutoshe sikuzote; Na kwa upendo wake ushangilie daima."}, {"r": "Luka 24:52", "t": "Wakamwabudu; kisha wakarudi Yerusalemu wenye furaha kuu."}, {"r": "2 Wakorintho 6:10", "t": "kama wenye huzuni, bali siku zote tu wenye furaha; kama maskini, bali tukitajirisha wengi; kama wasio na kitu, bali tu wenye vitu vyote."}, {"r": "Isaya 66:11", "t": "mpate kunyonya, na kushibishwa kwa maziwa ya faraja zake, mpate kukama, na kufurahiwa kwa wingi wa utukufu wake."}, {"r": "Zaburi 70:4", "t": "Washangilie, wakufurahie, Wote wakutafutao. Waupendao wokovu wako Waseme daima, Atukuzwe Mungu."}, {"r": "Mika 7:18", "t": "Ni nani aliye Mungu kama wewe, mwenye kusamehe uovu, na kuliachilia kosa la watu wa urithi wake waliosalia? Hashiki hasira yake milele, kwa maana yeye hufurahia rehema."}, {"r": "Zekaria 4:10", "t": "Maana ni nani aliyeidharau siku ya mambo madogo? Kwa kuwa watafurahi, nao wataiona timazi katika mkono wa Zerubabeli; naam, hizi saba ndizo macho ya Bwana; yapiga mbio huko na huko duniani mwote."}, {"r": "Zaburi 48:2", "t": "Kuinuka kwake ni mzuri sana, Ni furaha ya dunia yote. Mlima Sayuni pande za kaskazini, Mji wa Mfalme mkuu."}, {"r": "Ufunuo wa Yohana 11:10", "t": "Nao wakaao juu ya nchi wafurahi juu yao na kushangilia. Nao watapelekeana zawadi wao kwa wao, kwa kuwa manabii hao wawili waliwatesa wao wakaao juu ya nchi."}, {"r": "Zaburi 13:4", "t": "Adui yangu asije akasema, Nimemshinda; Watesi wangu wasifurahi ninapoondoshwa."}, {"r": "Marko 6:20", "t": "Maana Herode alimwogopa Yohana; akimjua kuwa ni mtu wa haki, mtakatifu, akamlinda; na alipokwisha kumsikiliza alifadhaika sana; naye alikuwa akimsikiliza kwa furaha."}, {"r": "Isaya 65:14", "t": "tazama, watumishi wangu wataimba kwa furaha ya moyo, bali ninyi mtalia kwa huzuni ya moyo; mtapiga kelele kwa sababu ya uchungu wa roho zenu."}, {"r": "Waebrania 12:2", "t": "tukimtazama Yesu, mwenye kuanzisha na mwenye kutimiza imani yetu; ambaye kwa ajili ya furaha iliyowekwa mbele yake aliustahimili msalaba na kuidharau aibu, naye ameketi mkono wa kuume wa kiti cha enzi cha Mungu."}, {"r": "Wimbo Ulio Bora 3:11", "t": "Tokeni, enyi binti za Sayuni, Mtazameni Mfalme Sulemani, Amevaa taji alivyovikwa na mamaye, Siku ya maposo yake, Siku ya furaha ya moyo wake."}, {"r": "Isaya 24:7", "t": "Divai mpya inaomboleza, mzabibu umedhoofika, watu wote waliochangamka moyo wanaugua."}, {"r": "Mithali 10:28", "t": "Matumaini yao wenye haki yatakuwa furaha; Bali kutaraji kwao wasio haki kutapotea."}, {"r": "Zaburi 35:15", "t": "Lakini nikijikwaa hufurahi na kukusanyana, Walinikusanyikia watu ovyo nisiowajua, Wananipapura wala hawakomi."}, {"r": "Nehemia 12:43", "t": "Wakatoa dhabihu nyingi siku ile, wakafurahi; kwa kuwa Mungu amewafurahisha furaha kuu; na wanawake pia na watoto wakafurahi; hata ikasikiwa mbali sana furaha hiyo ya Yerusalemu."}, {"r": "Ayubu 39:21", "t": "Huparapara bondeni, na kuzifurahia nguvu zake; Hutoka kwenda kukutana na wenye silaha."}, {"r": "Zaburi 63:7", "t": "Maana Wewe umekuwa msaada wangu, Na uvulini mwa mbawa zako nitashangilia."}, {"r": "Zaburi 149:5", "t": "Watauwa na waushangilie utukufu, Waimbe kwa sauti kuu vitandani mwao."}, {"r": "Isaya 56:7", "t": "Nitawaleta hao nao hata mlima wangu mtakatifu, na kuwafurahisha katika nyumba yangu ya sala; makafara yao na dhabihu zao zitakubaliwa juu ya madhabahu zangu; kwa maana nyumba yangu itaitwa nyumba ya sala kwa mataifa yote."}, {"r": "Isaya 32:13", "t": "Juu ya nchi ya watu wangu itamea michongoma na mibigili; naam, juu ya nyumba za furaha katika mji ulio na shangwe;"}, {"r": "Ayubu 31:25", "t": "Kama nilifurahi kwa kuwa mali yangu yalikuwa mengi, Na kwa sababu mkono wangu umepata vitu vingi;"}, {"r": "Habakuki 1:15", "t": "Yeye huwatoa wote kwa ndoana yake, huwakamata katika wavu wake, na kuwakusanya katika juya lake; ndiyo sababu afurahi na kupendezwa."}, {"r": "Zaburi 104:31", "t": "Utukufu wa Bwana na udumu milele; Bwana na ayafurahie matendo yake."}, {"r": "1 Wakorintho 7:30", "t": "na wale waliao kama hawalii; na wale wafurahio kama hawafurahi; na wale wanunuao, kama hawana kitu."}, {"r": "Isaya 61:7", "t": "Badala ya aibu yenu mtapata maradufu, na badala ya fedheha wataifurahia sehemu yao; basi katika nchi yao watamiliki maradufu; furaha yao itakuwa ya milele."}, {"r": "1 Wafalme 1:40", "t": "Kisha watu wote wakapanda juu nyuma yake, watu wakapiga mazomari, wakafurahi furaha kubwa mno, hata nchi ikapasuka kwa sauti zao."}, {"r": "Zaburi 98:4", "t": "Mshangilieni Bwana, nchi yote, Inueni sauti, imbeni kwa furaha, imbeni zaburi."}, {"r": "Zaburi 59:16", "t": "Nami nitaziimba nguvu zako asubuhi, Nitaziimba fadhili zako kwa furaha. Kwa kuwa ndiwe uliyekuwa ngome yangu, Na makimbilio siku ya shida yangu."}, {"r": "Matendo ya Mitume 16:34", "t": "Akawaleta juu nyumbani kwake, akawaandalia chakula, akafurahi sana, yeye na nyumba yake yote, maana amekwisha kumwamini Mungu."}, {"r": "1 Yohana 1:4", "t": "Na haya twayaandika, ili furaha yetu itimizwe."}, {"r": "Isaya 23:12", "t": "Naye akasema, Usizidi kufurahi, ewe bikira uliyeaibishwa, binti wa Sidoni, haya, ondoka, uende hata Kitimu; huko nako hutapata raha."}, {"r": "Zaburi 46:4", "t": "Kuna mto, vijito vyake vyaufurahisha mji wa Mungu, Patakatifu pa maskani zake Aliye juu."}, {"r": "Mathayo 13:20", "t": "Naye aliyepandwa penye miamba, huyo ndiye alisikiaye lile neno, akalipokea mara kwa furaha;"}, {"r": "Ayubu 27:10", "t": "Je! Atajifurahisha katika Mwenyezi, Na kumlingana Mungu nyakati zote?"}, {"r": "Mithali 15:8", "t": "Sadaka ya mtu mbaya ni chukizo kwa Bwana; Bali maombi ya mtu mnyofu ni furaha yake."}, {"r": "Isaya 65:19", "t": "Nami nitaufurahia Yerusalemu, nitawaonea shangwe watu wangu; sauti ya kulia haitasikiwa ndani yake tena, wala sauti ya kuomboleza."}, {"r": "Zaburi 45:8", "t": "Mavazi yako yote hunukia manemane Na udi na mdalasini. Katika majumba ya pembe Vinubi vimekufurahisha."}, {"r": "Zaburi 37:4", "t": "Nawe utajifurahisha kwa Bwana, Naye atakupa haja za moyo wako."}, {"r": "2 Wathesalonike 2:12", "t": "ili wahukumiwe wote ambao hawakuiamini kweli, bali walikuwa wakijifurahisha katika udhalimu."}, {"r": "2 Mambo ya Nyakati 7:10", "t": "Akawaruhusu watu waende hemani kwao siku ya ishirini na tatu, ya mwezi wa saba, wakifurahi na kuchangamka mioyoni kwa wema wote Bwana aliomfanyia Daudi, na Sulemani, na Israeli watu wake."}, {"r": "1 Wathesalonike 2:8", "t": "Vivyo hivyo nasi tukiwatumaini kwa upendo mwingi, tuliona furaha kuwapa, si Injili ya Mungu tu, bali na roho zetu pia, kwa sababu mmekuwa wapendwa wetu."}, {"r": "Isaya 8:22", "t": "nao wataiangalia nchi, na, tazama, shida na giza; hapana changamko kwa sababu ya dhiki; nao watafukuzwa na kuingia katika giza kubwa."}, {"r": "Yeremia 31:5", "t": "Mara ya pili utapanda mizabibu juu ya milima ya Samaria; wapanzi watapanda, nao watayafurahia matunda yake."}, {"r": "Wafilipi 2:2", "t": "ijalizeni furaha yangu, ili mwe na nia moja, wenye mapenzi mamoja, wenye roho moja, mkinia mamoja."}, {"r": "Mhubiri 12:1", "t": "Mkumbuke Muumba wako siku za ujana wako, Kabla hazijaja siku zilizo mbaya, Wala haijakaribia miaka utakaposema, Mimi sina furaha katika hiyo."}, {"r": "Sefania 3:14", "t": "Imba, Ee binti Sayuni; piga kelele, Ee Israeli; Furahi na kushangilia kwa moyo wako wote, Ee binti Yerusalemu."}, {"r": "Isaya 22:13", "t": "na kumbe! Furaha, na kuchekelea, na kuchinja ng'ombe, na kuchinja kondoo, na kula nyama, na kunywa mvinyo; tule, tunywe, kwa maana kesho tutakufa."}, {"r": "Ayubu 20:5", "t": "Ya kuwa shangwe ya waovu ni kwa muda kidogo, Na furaha ya wapotovu ni ya dakika moja tu?"}, {"r": "Zaburi 98:8", "t": "Mito na ipige makofi, Milima na iimbe pamoja kwa furaha."}, {"r": "Matendo ya Mitume 2:26", "t": "Kwa hiyo moyo wangu ukapendezewa, ulimi wangu ukafurahi; Tena mwili wangu nao utakaa katika matumaini."}, {"r": "Zaburi 119:74", "t": "Wakuchao na wanione na kufurahi, Kwa sababu nimelingojea neno lako."}, {"r": "Ayubu 3:22", "t": "Ambao wafurahi mno, Na kushangilia watakapoliona kaburi?"}, {"r": "Matendo ya Mitume 24:10", "t": "Na liwali alipompungia mkono ili anene, Paulo akajibu, Kwa kuwa ninajua ya kwamba wewe umekuwa mwamuzi wa taifa hili kwa muda wa miaka mingi, najitetea mwenyewe kwa moyo wa furaha."}, {"r": "Matendo ya Mitume 8:8", "t": "Ikawa furaha kubwa katika mji ule."}, {"r": "Zaburi 100:2", "t": "Mtumikieni Bwana kwa furaha; Njoni mbele zake kwa kuimba;"}, {"r": "Yohana 17:13", "t": "Na sasa naja kwako; na maneno haya nayasema ulimwenguni, ili wawe na furaha yangu imetimizwa ndani yao."}, {"r": "Yeremia 31:13", "t": "Ndipo bikira atafurahi katika kucheza, na vijana na wazee pamoja; maana nitageuza masikitiko yao kuwa furaha, nami nitawafariji, na kuwafurahisha waache huzuni zao."}, {"r": "Ayubu 20:20", "t": "Kwa sababu hakujua utulivu ndani yake, Hataponya cho chote katika hicho alichokifurahia."}, {"r": "Zaburi 62:4", "t": "Hufanya shauri kumwangusha tu katika cheo chake; Huufurahia uongo. Kwa kinywa chao hubariki; Kwa moyo wao hulaani."}, {"r": "Yoeli 2:23", "t": "Furahini, basi, enyi wana wa Sayuni, mkamfurahie Bwana, Mungu wenu; kwa kuwa yeye huwapa ninyi mvua ya masika, kwa kipimo cha haki, naye huwanyeshea mvua, mvua ya masika, na mvua ya vuli, kama kwanza."}, {"r": "Isaya 16:10", "t": "Na furaha imeondolewa, na shangwe toka mashamba yaliyozaa sana; hapana kuimba katika mashamba ya mizabibu, wala sauti za furaha; akanyagaye hakanyagi divai katika mashinikizo; nimeikomesha sauti ya furaha yake akanyagaye."}, {"r": "Ayubu 29:13", "t": "Baraka yake yeye aliyekuwa karibu na kupotea ilinijia; Nikaufanya moyo wa mjane kuimba kwa furaha."}, {"r": "Isaya 14:8", "t": "Naam, misunobari inakufurahia, Na mierezi ya Lebanoni, ikisema, Tokea wakati ulipolazwa chini wewe, Hapana mkata miti aliyetujia."}, {"r": "Wakolosai 2:15", "t": "akiisha kuzivua enzi na mamlaka, na kuzifanya kuwa mkogo kwa ujasiri, akizishangilia katika msalaba huo."}, {"r": "2 Wakorintho 1:24", "t": "Si kwamba tunatawala imani yenu; bali tu wasaidizi wa furaha yenu; maana kwa imani yenu mnasimama."}, {"r": "1 Timotheo 6:17", "t": "Walio matajiri wa ulimwengu wa sasa uwaagize wasijivune, wala wasiutumainie utajiri usio yakini, bali wamtumaini Mungu atupaye vitu vyote kwa wingi ili tuvitumie kwa furaha."}, {"r": "Isaya 66:10", "t": "Furahini pamoja na Yerusalemu, shangilieni kwa ajili yake, ninyi nyote mmpendao; furahini pamoja naye kwa furaha, ninyi nyote mliao kwa ajili yake;"}, {"r": "Isaya 25:9", "t": "Katika siku hiyo watasema, Tazama, huyu ndiye Mungu wetu, Ndiye tuliyemngoja atusaidie; Huyu ndiye Bwana tuliyemngoja, Na tushangilie na kuufurahia wokovu wake."}, {"r": "Mithali 27:9", "t": "Marhamu na manukato huufurahisha moyo; Kadhalika utamu wa rafiki ya mtu utokao katika kusudi la moyo wake."}, {"r": "Isaya 13:17", "t": "Tazama, nitawaamsha Wamedi juu yao, ambao hawaoni fedha kuwa kitu, wala hawafurahii dhahabu."}, {"r": "Zaburi 63:5", "t": "Nafsi yangu itakinai kama kushiba mafuta na vinono; Kinywa changu kitakusifu kwa midomo ya furaha."}, {"r": "Ayubu 20:18", "t": "Aliyoyataabikia kazi atayarudisha, asiyameze; Kwa mali aliyoyapata, hatafurahi."}, {"r": "Wafilipi 4:1", "t": "Basi, ndugu zangu, wapendwa wangu, ninaowaonea shauku, furaha yangu, na taji yangu, hivyo simameni imara katika Bwana, wapenzi wangu."}, {"r": "2 Timotheo 1:4", "t": "Nami natamani sana kukuona, nikiyakumbuka machozi yako, ili nijae furaha;"}, {"r": "Waebrania 10:38", "t": "Lakini mwenye haki wangu ataishi kwa imani; Naye akisitasita, roho yangu haina furaha naye."}, {"r": "Isaya 61:3", "t": "kuwaagizia hao waliao katika Sayuni, wapewe taji ya maua badala ya majivu, mafuta ya furaha badala ya maombolezo, vazi la sifa badala ya roho nzito; wapate kuitwa miti ya haki, iliyopandwa na Bwana, ili atukuzwe."}, {"r": "Zaburi 20:5", "t": "Na tuushangilie wokovu wako, Kwa jina la Mungu wetu tuzitweke bendera zetu. Bwana akutimizie matakwa yako yote."}, {"r": "Ufunuo wa Yohana 18:20", "t": "Furahini juu yake, enyi mbingu, nanyi watakatifu na mitume na manabii; kwa maana Mungu amehukumu hukumu yenu juu yake."}, {"r": "Zaburi 43:4", "t": "Hivyo nitakwenda madhabahuni kwa Mungu, kwa Mungu aliye furaha yangu na shangwe yangu; Nitakusifu kwa kinubi, Ee MUNGU, Mungu wangu."}, {"r": "Ayubu 31:29", "t": "Kama nilifurahi kwa kuangamia kwake huyo aliyenichukia, Au kujitukuza alipopatikana na maovu;"}, {"r": "Isaya 23:7", "t": "Je! Huu ndio mji wenu wa furaha, ambao mwanzo wake ulikuwako tangu siku za kale, ambao miguu yake ilimchukua akae mbali sana?"}, {"r": "Zaburi 68:4", "t": "Mwimbieni Mungu, lisifuni jina lake, Mtengenezeeni njia ya barabara, Apitaye majangwani kama mpanda farasi; Jina lake ni YAHU; shangilieni mbele zake."}, {"r": "Zaburi 96:12", "t": "Mashamba na yashangilie, na vyote vilivyomo, Ndipo miti yote ya mwituni iimbe kwa furaha;"}, {"r": "Yakobo 4:9", "t": "Huzunikeni na kuomboleza na kulia. Kucheka kwenu na kugeuzwe kuwa kuomboleza, na furaha yenu kuwa hamu."}, {"r": "Luka 15:32", "t": "Tena, kufanya furaha na shangwe ilipasa, kwa kuwa huyu ndugu yako alikuwa amekufa, naye amefufuka; alikuwa amepotea, naye ameonekana."}, {"r": "Mithali 23:16", "t": "Naam, viuno vyangu vitafurahi, Midomo yako inenapo maneno mema."}, {"r": "2 Wakorintho 7:4", "t": "Ninao ujasiri mwingi kwenu; naona fahari kuu juu yenu. Nimejaa faraja, katika dhiki yetu yote nimejaa furaha ya kupita kiasi."}, {"r": "Esta 9:22", "t": "ambazo ni siku Wayahudi walipojipatia raha mbele ya adui zao, na mwezi uliogeuzwa kwao kuwa furaha badala ya huzuni, na kuwa sikukuu badala ya kilio; wazifanye siku hizo ziwe za karamu na furaha, za kupeana zawadi na za kuwapa maskini vipawa."}, {"r": "Yeremia 7:34", "t": "Ndipo katika miji ya Yuda, na katika njia kuu za Yerusalemu, nitaikomesha sauti ya kicheko na sauti ya furaha, sauti ya bwana arusi na sauti ya bibi arusi; kwa maana nchi hiyo itakuwa ukiwa."}, {"r": "Isaya 1:11", "t": "Huu wingi wa sadaka zenu mnazonitolea una faida gani? Asema Bwana. Nimejaa mafuta ya kafara za kondoo waume, na mafuta ya wanyama walionona; nami siifurahii damu ya ng'ombe wala ya wanakondoo wala ya mbuzi waume."}, {"r": "Isaya 58:13", "t": "Kama ukigeuza mguu wako usihalifu sabato, usifanye anasa yako siku ya utakatifu wangu; ukiita sabato siku ya furaha, na siku takatifu ya Bwana yenye heshima; ukiitukuza, kwa kutokuzifanya njia zako mwenyewe, wala kuyatafuta yakupendezayo, wala kusema maneno yako mwenyewe;"}, {"r": "Yeremia 31:7", "t": "Maana Bwana asema hivi, Mwimbieni Yakobo kwa furaha, mkampigie kelele mkuu wa mataifa, tangazeni, sifuni, mkaseme, Ee Bwana, uwaokoe watu wako, mabaki ya Israeli."}, {"r": "1 Wafalme 8:66", "t": "Hata siku ya nane akaagana na watu, nao wakambarikia mfalme, wakaenda hemani kwao, wakifurahi na kuchangamka moyoni kwa wema wote Bwana aliomfanyia Daudi mtumishi wake, na Israeli watu wake."}, {"r": "Ayubu 21:21", "t": "Kwani ana furaha gani katika mbari yake baada yake, Hesabu ya miezi yake itakapokwisha katwa katikati?"}, {"r": "Yohana 14:28", "t": "Mlisikia ya kwamba mimi naliwaambia, Naenda zangu, tena naja kwenu. Kama mngalinipenda, mngalifurahi kwa sababu naenda kwa Baba, kwa maana Baba ni mkuu kuliko mimi."}, {"r": "Zaburi 108:7", "t": "Mungu amenena kwa utakatifu wake, Nami nitashangilia. Nitaigawanya Shekemu, Nitalipima bonde la Sukothi."}, {"r": "Yeremia 48:33", "t": "Furaha na shangwe zimeondoshwa, katika shamba lizaalo sana, na katika nchi ya Moabu; nami nimeikomesha divai katika mashinikizo; hapana mtu atakayekanyaga zabibu kwa shangwe; shangwe ile itakuwa si shangwe."}, {"r": "Zaburi 97:8", "t": "Sayuni imesikia na kufurahi, Binti za Yuda walishangilia, Kwa sababu ya hukumu zako, Ee Bwana."}, {"r": "Mithali 15:30", "t": "Mng'ao wa macho huufurahisha moyo; Habari njema huinenepesha mifupa."}, {"r": "Zaburi 109:28", "t": "Wao walaani, bali Wewe utabariki, Wameondoka wao wakaaibishwa, Bali mtumishi wako atafurahi."}, {"r": "Isaya 9:3", "t": "Umeliongeza taifa, umezidisha furaha yao; Wanafurahi mbele zako, Kama furaha ya wakati wa mavuno, Kama watu wafurahivyo wagawanyapo nyara."}, {"r": "Zaburi 137:6", "t": "Ulimi wangu na ugandamane Na kaakaa la kinywa changu, nisipokukumbuka. Nisipoikuza Yerusalemu Zaidi ya furaha yangu iliyo kuu."}, {"r": "1 Wathesalonike 3:9", "t": "Maana ni shukrani gani tuwezayo kumlipa Mungu kwa ajili yenu, kwa furaha ile yote tunayoifurahia, kwa sababu yenu mbele za Mungu wetu;"}, {"r": "Yohana 8:56", "t": "Ibrahimu, baba yenu, alishangilia kwa vile atakavyoiona siku yangu; naye akaiona, akafurahi."}, {"r": "Wakolosai 1:11", "t": "mkiwezeshwa kwa uwezo wote, kwa kadiri ya nguvu ya utukufu wake, mpate kuwa na saburi ya kila namna na uvumilivu pamoja na furaha;"}, {"r": "Wafilipi 1:25", "t": "Nami nikitumaini hayo, najua ya kuwa nitakaa na kudumu pamoja nanyi, ili mpate kuendelea na kufurahi katika imani;"}, {"r": "3 Yohana 1:3", "t": "Maana nalifurahi mno walipokuja ndugu na kuishuhudia kweli yako, kama uendavyo katika kweli."}, {"r": "Wakolosai 1:24", "t": "Sasa nayafurahia mateso niliyo nayo kwa ajili yenu; tena nayatimiliza katika mwili wangu yale yaliyopungua ya mateso ya Kristo, kwa ajili ya mwili wake, yaani, kanisa lake;"}, {"r": "Zaburi 119:174", "t": "Ee Bwana, nimeutamani wokovu wako, Na sheria yako ndiyo furaha yangu."}, {"r": "Wakolosai 2:5", "t": "Maana nijapokuwa sipo kwa mwili, lakini nipo pamoja nanyi kwa roho, nikifurahi na kuuona utaratibu wenu na uthabiti wa imani yenu katika Kristo."}, {"r": "Luka 10:20", "t": "Lakini, msifurahi kwa vile pepo wanavyowatii; bali furahini kwa sababu majina yenu yameandikwa mbinguni."}, {"r": "Mithali 23:15", "t": "Mwanangu, kama moyo wako una hekima, Moyo wangu utafurahi, naam, moyo wangu;"}, {"r": "Ayubu 21:12", "t": "Huimba kwa matari na kwa kinubi, Na kuifurahia sauti ya filimbi."}, {"r": "Zaburi 21:1", "t": "Ee Bwana, mfalme atazifurahia nguvu zako, Na wokovu wako ataufanyia shangwe nyingi sana."}, {"r": "Zaburi 63:11", "t": "Bali mfalme atamfurahia Mungu, Kila aapaye kwa Yeye atashangilia, Kwa maana vinywa vya waongo vitafumbwa."}, {"r": "Yeremia 33:11", "t": "itasikilikana tena sauti ya furaha na sauti ya shangwe, sauti ya bwana arusi na sauti ya bibi arusi, sauti yao wasemao Mshukuruni Bwana wa majeshi, maana Bwana ni mwema, rehema zake ni za milele; na sauti zao waletao sadaka za shukrani nyumbani kwa Bwana. Kwa kuwa nitawarudisha wafungwa wa nchi hii kama kwanza, asema Bwana."}, {"r": "Zaburi 119:24", "t": "Shuhuda zako nazo ndizo furaha yangu, Na washauri wangu."}, {"r": "2 Wakorintho 2:2", "t": "Maana mimi nikiwatia huzuni, basi ni nani anifurahishaye mimi ila yeye ahuzunishwaye nami?"}, {"r": "Mithali 15:23", "t": "Mtu hulifurahia jibu la kinywa chake; Na neno linenwalo wakati wa kufaa ni jema kama nini!"}, {"r": "Ayubu 36:11", "t": "Kama wakisikia na kumtumikia, Watapisha siku zao katika kufanikiwa, Na miaka yao katika furaha."}, {"r": "Isaya 51:3", "t": "Maana Bwana ameufariji Sayuni; amepafariji mahali pake palipokuwa ukiwa; amefanya jangwa lake kuwa kama bustani ya Edeni, na nyika yake kama bustani ya Bwana; furaha na kicheko zitaonekana ndani yake, kushukuru, na sauti ya kuimba."}, {"r": "Matendo ya Mitume 2:28", "t": "Umenijuvisha njia za uzima; Utanijaza furaha kwa uso wako."}, {"r": "Ayubu 22:19", "t": "Wenye haki huyaona hayo wakafurahi; Nao wasio na hatia huwacheka;"}, {"r": "Warumi 5:11", "t": "Wala si hivyo tu, ila pia twajifurahisha katika Mungu kwa Bwana wetu Yesu Kristo, ambaye kwa yeye sasa tumeupokea huo upatanisho."}, {"r": "Zaburi 58:10", "t": "Mwenye haki atafurahi akionapo kisasi; Ataiosha miguu yake katika damu ya wasio haki."}, {"r": "Mithali 12:22", "t": "Midomo ya uongo ni chukizo kwa Bwana; Bali watendao uaminifu ndio furaha yake."}, {"r": "2 Mambo ya Nyakati 20:27", "t": "Kisha wakarudi, kila mtu wa Yuda na Yerusalemu, na Yehoshafati mbele yao, ili kuurudia Yerusalemu kwa furaha; kwa kuwa Bwana amewafurahisha juu ya adui zao."}, {"r": "Yohana 5:35", "t": "Yeye alikuwa taa iwakayo na kung'aa, nanyi mlipenda kuishangilia nuru yake kwa muda."}, {"r": "Zaburi 35:27", "t": "Washangilie na kufurahi, Wapendezwao na haki yangu. Naam, waseme daima, Atukuzwe Bwana, Apendezwaye na amani ya mtumishi wake."}, {"r": "Isaya 35:1", "t": "Nyika na mahali palipo ukiwa patafurahi; jangwa litashangilia na kuchanua maua kama waridi."}, {"r": "Zaburi 106:5", "t": "Ili niuone wema wa wateule wako. Nipate kuifurahia furaha ya taifa lako, Na kujisifu pamoja na watu wako."}, {"r": "Isaya 32:14", "t": "maana jumba la mfalme litaachwa; mji uliokuwa na watu wengi utakuwa hauna mtu; kilima na mnara utakuwa makao ya wanyama milele, furaha ya pundamwitu, malisho ya makundi ya kondoo;"}, {"r": "Zaburi 122:1", "t": "Nalifurahi waliponiambia, Na twende nyumbani kwa Bwana."}, {"r": "Zaburi 14:7", "t": "Laiti wokovu wa Israeli utoke katika Sayuni! Bwana awarudishapo wafungwa wa watu wake; Yakobo atashangilia, Israeli atafurahi."}, {"r": "Isaya 24:11", "t": "Pana kilio katika njia kuu kwa sababu ya divai; furaha yote imetiwa giza, na changamko la nchi limetoweka."}, {"r": "Luka 1:58", "t": "Wakasikia jirani zake na jamaa zake ya kwamba Bwana amemwongezea rehema zake, wakafurahi pamoja naye."}, {"r": "Mithali 15:21", "t": "Upumbavu ni furaha kwake aliyepungukiwa na akili; Bali mwenye ufahamu huunyosha mwenendo wake."}, {"r": "Zaburi 132:16", "t": "Na makuhani wake nitawavika wokovu, Na watauwa wake watashangilia."}, {"r": "Isaya 11:3", "t": "na furaha yake itakuwa katika kumcha Bwana; wala hatahukumu kwa kuyafuata ayaonayo kwa macho yake, wala hataonya kwa kuyafuata ayasikiayo kwa masikio yake;"}, {"r": "Matendo ya Mitume 15:31", "t": "Nao walipokwisha kuisoma wakafurahi kwa ajili ya faraja ile."}, {"r": "Wafilipi 1:18", "t": "Yadhuru nini? Lakini kwa njia zote, ikiwa ni kwa hila, au ikiwa ni kwa kweli, Kristo anahubiriwa; na kwa hiyo nafurahi, naam, nami nitafurahi."}, {"r": "Yeremia 25:10", "t": "Tena, nitawaondolea sauti ya kicheko, na sauti ya furaha, sauti ya bwana arusi, na sauti ya bibi arusi, sauti ya mawe ya kusagia, na nuru ya mishumaa."}, {"r": "Mithali 8:31", "t": "Nikiifurahia dunia inayokaliwa na watu; Na furaha yangu ilikuwa pamoja na wanadamu."}, {"r": "1 Wakorintho 12:26", "t": "Na kiungo kimoja kikiumia, viungo vyote huumia nacho, na kiungo kimoja kikitukuzwa, viungo vyote hufurahi pamoja nacho."}, {"r": "1 Wakorintho 16:17", "t": "Nami nafurahi kwa sababu ya kuja kwao Stefana na Fortunato na Akaiko; maana hawa wamenikirimia kwa wingi yale niliyopungukiwa kwenu."}, {"r": "Waebrania 10:34", "t": "Maana mliwaonea huruma wale waliokuwa katika vifungo, tena mkakubali kwa furaha kunyang'anywa mali zenu, mkijua kwamba nafsini mwenu mna mali iliyo njema zaidi, idumuyo."}, {"r": "Zaburi 40:16", "t": "Washangilie, wakufurahie, Wote wakutafutao. Waupendao wokovu wako Waseme daima, Atukuzwe Bwana."}, {"r": "2 Yohana 1:12", "t": "Kwa kuwa ninayo mambo mengi, sitaki kuyaandika kwa karatasi na wino; lakini nataraji kuja kwenu, na kusema nanyi uso kwa uso, ili furaha yetu iwe imetimizwa."}, {"r": "Mithali 29:6", "t": "Kuna mtego katika kosa la mtu mbaya; Bali mwenye haki huimba na kufurahi."}, {"r": "Zaburi 97:11", "t": "Nuru imemzukia mwenye haki, Na furaha wanyofu wa moyo."}, {"r": "Matendo ya Mitume 5:41", "t": "Nao wakatoka katika ile baraza, wakifurahi kwa sababu wamehesabiwa kuwa wamestahili kuaibishwa kwa ajili ya Jina hilo."}, {"r": "Mathayo 5:12", "t": "Furahini, na kushangilia; kwa kuwa thawabu yenu ni kubwa mbinguni; kwa maana ndivyo walivyowaudhi manabii waliokuwa kabla yenu."}, {"r": "Zaburi 42:4", "t": "Nayakumbuka hayo nikiweka wazi nafsi yangu ndani yangu, Jinsi nilivyokuwa nikienda na mkutano, Na kuwaongoza nyumbani kwa Mungu, Kwa sauti ya furaha na kusifu, mkutano wa sikukuu."}, {"r": "2 Wakorintho 7:16", "t": "Nafurahi, kwa sababu katika kila neno nina moyo mkuu kwa ajili yenu."}, {"r": "Zekaria 2:10", "t": "Imba, ufurahi, Ee binti Sayuni; maana, tazama, ninakuja, nami nitakaa kati yako, asema Bwana."}, {"r": "2 Wakorintho 7:9", "t": "Sasa nafurahi, si kwa sababu ya ninyi kuhuzunishwa, bali kwa sababu mlihuzunishwa, hata mkatubu. Maana mlihuzunishwa kwa jinsi ya Mungu, ili msipate hasara kwa tendo letu katika neno lo lote."}, {"r": "Mhubiri 2:2", "t": "Nikasema juu ya kicheko, Ni wazimu; na juu ya furaha, Yafaa nini?"}, {"r": "Zaburi 9:2", "t": "Nitafurahi na kukushangilia Wewe; Nitaliimbia jina lako, Wewe Uliye juu."}, {"r": "Zaburi 105:38", "t": "Misri ilifurahi walipoondoka, Maana kwa ajili yao hofu imewaangukia."}, {"r": "Luka 12:19", "t": "Kisha, nitajiambia, Ee nafsi yangu, una vitu vyema vingi ulivyojiwekea akiba kwa miaka mingi; pumzika basi, ule, unywe, ufurahi."}, {"r": "Zaburi 33:1", "t": "Mpigieni Bwana vigelegele, enyi wenye haki, Kusifu kunawapasa wanyofu wa moyo."}, {"r": "Isaya 43:14", "t": "Bwana, Mkombozi wenu, Mtakatifu wa Israeli, asema hivi; Kwa ajili yenu nimetuma ujumbe Babeli nami nitawashusha wote mfano wa wakimbizi, naam, Wakaldayo, katika merikebu zao walizozifurahia."}, {"r": "Yeremia 51:48", "t": "Ndipo mbingu, na nchi, na vitu vyote vilivyomo, vitaimba kwa furaha juu ya Babeli; kwa maana watu waangamizao watamjilia kutoka kaskazini, asema Bwana."}, {"r": "Ayubu 9:27", "t": "Nikisema, Mimi nitasahau kuugua kwangu, Nitaacha kununa uso nikachangamke moyo;"}, {"r": "Yakobo 5:5", "t": "Mmefanya anasa katika dunia, na kujifurahisha kwa tamaa; mmejilisha mioyo yenu kama siku ya machinjo."}, {"r": "Mika 7:8", "t": "Usifurahi juu yangu, Ee adui yangu; niangukapo, nitasimama tena; nikaapo gizani, Bwana atakuwa nuru kwangu."}, {"r": "Zaburi 119:47", "t": "Nami nitajifurahisha sana kwa maagizo yako, Ambayo nimeyapenda."}, {"r": "Ayubu 33:26", "t": "Yeye humwomba Mungu, naye akamtakabalia; Hata auone uso wake kwa furaha; Naye humrejezea mtu haki yake."}, {"r": "Warumi 12:15", "t": "Furahini pamoja nao wafurahio; lieni pamoja nao waliao."}, {"r": "Isaya 14:29", "t": "Usifurahi, Ee Ufilisti, pia wote, Kwa sababu fimbo ile iliyokupiga imevunjika; Maana katika shina la nyoka atatoka fira, Na uzao wake ni joka la moto arukaye"}, {"r": "1 Mambo ya Nyakati 29:9", "t": "Ndipo hao watu wakafurahi, kwa sababu wametoa kwa hiari yao wenyewe, kwa sababu kwa ukamilifu wa moyo, kwa hiari yao wenyewe, wamemtolea Bwana; mfalme Daudi naye akafurahi kwa furaha kuu."}, {"r": "Zaburi 51:8", "t": "Unifanye kusikia furaha na shangwe, Mifupa uliyoiponda ifurahi."}, {"r": "Zaburi 38:16", "t": "Maana nalisema, Wasije wakanifurahia; Mguu wangu ukiteleza wajitukuza juu yangu."}, {"r": "Zaburi 105:43", "t": "Akawatoa watu wake kwa shangwe, Na wateule wake kwa nyimbo za furaha."}, {"r": "Mika 1:16", "t": "Jifanyie upaa, jikate nywele zako, Kwa ajili ya watoto waliokufurahisha; Panua upaa wako kama tai; Kwa maana wamekwenda mbali nawe utumwani."}, {"r": "Mathayo 25:21", "t": "Bwana wake akamwambia, Vema, mtumwa mwema na mwaminifu; ulikuwa mwaminifu kwa machache, nitakuweka juu ya mengi; ingia katika furaha ya bwana wako."}, {"r": "Zaburi 119:14", "t": "Nimeifurahia njia ya shuhuda zako Kana kwamba ni mali mengi."}, {"r": "Zaburi 68:3", "t": "Bali wenye haki hufurahi, Na kuushangilia uso wa Mungu, Naam, hupiga kelele kwa furaha."}, {"r": "Luka 15:23", "t": "mleteni ndama yule aliyenona mkamchinje; nasi tule na kufurahi;"}, {"r": "Zaburi 113:9", "t": "Huweka nyumbani mwanamke aliye tasa, Awe mama ya watoto mwenye furaha."}, {"r": "2 Wakorintho 12:9", "t": "Naye akaniambia, Neema yangu yakutosha; maana uweza wangu hutimilika katika udhaifu. Basi nitajisifia udhaifu wangu kwa furaha nyingi, ili uweza wa Kristo ukae juu yangu."}, {"r": "Hosea 4:8", "t": "Hujilisha dhambi ya watu wangu, hujifurahisha moyo kwa uovu wao."}, {"r": "Maombolezo 4:21", "t": "Furahi, ushangilie, Ee binti Edomu, Ukaaye katika nchi ya Usi; Hata kwako kikombe kitapita, Utalewa, na kujifanya uchi."}, {"r": "Matendo ya Mitume 8:39", "t": "Kisha, walipopanda kutoka majini, Roho wa Bwana akamnyakua Filipo, yule towashi asimwone tena; basi alikwenda zake akifurahi."}, {"r": "Wafilipi 3:1", "t": "Hatimaye, ndugu zangu, furahini katika Bwana. Kuwaandikieni mambo yale yale hakuniudhi mimi, bali kutawafaa ninyi."}, {"r": "Zaburi 48:11", "t": "Na ufurahi mlima Sayuni. Binti za Yuda na washangilie Kwa sababu ya hukumu zako."}, {"r": "Mathayo 28:8", "t": "Wakaondoka upesi kutoka kaburini, kwa hofu na furaha nyingi, wakaenda mbio kuwapasha wanafunzi wake habari."}, {"r": "Matendo ya Mitume 13:48", "t": "Mataifa waliposikia hayo wakafurahi, wakalitukuza neno la Bwana, nao waliokuwa wamekusudiwa uzima wa milele wakaamini."}, {"r": "Isaya 66:3", "t": "Yeye achinjaye ng'ombe ni kama yeye amwuaye mtu; na yeye atoaye dhabihu ya mwanakondoo ni kama yeye avunjaye shingo ya mbwa; na yeye atoaye matoleo ni kama yeye atoaye damu ya nguruwe; na yeye afukizaye uvumba ni kama yeye abarikiye sanamu; naam, wamezichagua njia zao wenyewe, na nafsi zao zafurahia machukizo yao."}, {"r": "Yoeli 2:21", "t": "Ee nchi, usiogope; furahi na kushangilia; kwa kuwa Bwana ametenda mambo makuu."}, {"r": "Yohana 4:36", "t": "Naye avunaye hupokea mshahara, na kukusanya matunda kwa uzima wa milele, ili yeye apandaye na yeye avunaye wapate kufurahi pamoja."}, {"r": "Zaburi 59:17", "t": "Ee nguvu zangu, nitakuimbia kwa furaha, Maana Mungu ndiye aliye ngome yangu, Mungu wa fadhili zangu."}, {"r": "Isaya 35:2", "t": "Litachanua maua mengi, na kufurahi, naam, kwa shangwe na kuimba; litapewa uzuri wa Lebanoni, utukufu wa Karmeli na Sharoni; watauona utukufu wa Bwana, ukuu wa Mungu wetu."}, {"r": "Waebrania 13:17", "t": "Watiini wenye kuwaongoza, na kuwanyenyekea; maana wao wanakesha kwa ajili ya roho zenu, kama watu watakaotoa hesabu, ili kwamba wafanye hivyo kwa furaha wala si kwa kuugua; maana isingewafaa ninyi."}, {"r": "Hosea 2:11", "t": "Tena nitaikomesha furaha yake yote, na sikukuu zake, na siku zake za mwandamo wa mwezi, na sabato zake, na makusanyiko yake yote yaliyoamriwa."}, {"r": "Zaburi 119:111", "t": "Shuhuda zako nimezifanya urithi wa milele, Maana ndizo changamko la moyo wangu."}, {"r": "Luka 8:13", "t": "Na wale penye mwamba ndio wale ambao wasikiapo hulipokea lile neno kwa furaha; nao hawana mizizi, huamini kitambo kidogo, na wakati wa kujaribiwa hujitenga."}, {"r": "Mithali 12:20", "t": "Hila imo mioyoni mwao wafikirio uovu; Bali wafanyao mashauri ya amani, kwao kuna furaha."}, {"r": "Mithali 21:15", "t": "Ni furaha yao wenye haki kutenda hukumu; Lakini ni uharibifu kwao watendao maovu."}, {"r": "Yeremia 49:25", "t": "Imekuwaje mji wa sifa haukuachwa, mji wa furaha yangu?"}, {"r": "Luka 10:17", "t": "Ndipo wale sabini waliporudi kwa furaha, wakisema, Bwana, hata pepo wanatutii kwa jina lako."}, {"r": "1 Wathesalonike 2:20", "t": "Maana ninyi ndinyi utukufu wetu, na furaha yetu."}, {"r": "Zekaria 10:7", "t": "Na watu wa Efraimu watakuwa kama shujaa, na moyo wao utafurahi kana kwamba ni kwa divai; naam, watoto wao wataona mambo haya, na kufurahi; mioyo yao itamfurahia Bwana."}, {"r": "Zaburi 107:42", "t": "Wanyofu wa moyo wataona na kufurahi, Na uovu wa kila namna utajifumba kinywa."}, {"r": "Isaya 49:13", "t": "Imbeni, enyi mbingu; ufurahi, Ee nchi; Pazeni sauti ya kuimba, enyi milima; Kwa kuwa Bwana amewafariji watu wake, Naye atawahurumia watu wake walioteswa."}, {"r": "Mithali 11:10", "t": "Wenye haki wasitawipo, mji hufurahi; Waovu waangamiapo, watu hupiga kelele."}, {"r": "Warumi 5:2", "t": "ambaye kwa yeye tumepata kwa njia ya imani kuifikia neema hii ambayo mnasimama ndani yake; na kufurahi katika tumaini la utukufu wa Mungu."}, {"r": "Mhubiri 3:22", "t": "Hivyo nikaona ya kwamba hakuna jema kupita mwanadamu kuzifurahia kazi zake; kwa sababu hili ni fungu lake; kwa maana ni nani atakayemrudisha tena ili ayaone yatakayomfuata baadaye."}, {"r": "Luka 23:8", "t": "Na Herode alipomwona Yesu alifurahi sana, kwa sababu alikuwa akitaka sana kumwona tangu siku nyingi, maana amesikia habari zake, akataraji kuona ishara iliyofanywa na yeye."}, {"r": "2 Yohana 1:4", "t": "Nalifurahi mno kwa kuwa nimewaona baadhi ya watoto wako wanaenenda katika kweli, kama vile tulivyopokea amri kwa Baba."}, {"r": "Zaburi 107:30", "t": "Ndipo walipofurahi kwa kuwa yametulia Naye huwaleta mpaka bandari waliyoitamani."}, {"r": "Zaburi 36:8", "t": "Watashibishwa kwa unono wa nyumba yako, Nawe utawanywesha mto wa furaha zako."}, {"r": "Ezra 6:22", "t": "wakaifanya sikukuu ya mikate isiyotiwa chachu kwa furaha, kwa muda wa siku saba; kwa kuwa Bwana amewafurahisha, na kumgeuza moyo mfalme wa Ashuru, awaelekee, ili awatie nguvu mikono yao katika kazi hiyo ya nyumba ya Mungu, Mungu wa Israeli."}, {"r": "Zaburi 85:6", "t": "Je! Hutaki kurudi na kutuhuisha, Watu wako wakufurahie?"}, {"r": "Marko 12:37", "t": "Daudi mwenyewe asema ni Bwana; basi amekuwaje mwanawe? Na mkutano mkubwa walikuwa wakimsikiliza kwa furaha."}, {"r": "Zaburi 16:9", "t": "Kwa hiyo moyo wangu unafurahi, Nao utukufu wangu unashangilia, Naam, mwili wangu nao utakaa kwa kutumaini."}, {"r": "Yeremia 50:11", "t": "Kwa sababu mnafurahi, kwa sababu mnashangilia, enyi mnaouteka urithi wangu, kwa sababu mmewanda kama mtamba akanyagaye nafaka, nanyi mnalia kama farasi wenye nguvu;"}, {"r": "Yeremia 15:17", "t": "Sikuketi katika mkutano wao wanaojifurahisha, wala sikufurahi, naliketi peke yangu kwa sababu ya mkono wako; kwa maana umenijaza ghadhabu."}, {"r": "2 Wakorintho 2:14", "t": "Ila Mungu ashukuriwe, anayetushangiliza daima katika Kristo, na kuidhihirisha harufu ya kumjua yeye kila mahali kwa kazi yetu."}, {"r": "Mathayo 2:10", "t": "Nao walipoiona ile nyota, walifurahi furaha kubwa mno."}, {"r": "Yakobo 5:13", "t": "Mtu wa kwenu amepatikana na mabaya? Na aombe. Ana moyo wa kuchangamka? Na aimbe zaburi."}, {"r": "Wafilipi 2:17", "t": "Naam, hata nikimiminwa juu ya dhabihu na ibada ya imani yenu, nafurahi; tena nafurahi pamoja nanyi nyote."}, {"r": "Isaya 66:14", "t": "Nanyi mtaona, na mioyo yenu itafurahi, na mifupa yenu itasitawi kama majani mabichi; na mkono wa Bwana utajulikana, uwaelekeao watumishi wake, naye atawaonea adui zake ghadhabu."}, {"r": "Yeremia 32:41", "t": "Naam, nitafurahi juu yao niwatendee mema, nami nitawapanda katika nchi hii kweli kweli, kwa moyo wangu wote, na kwa roho yangu yote."}, {"r": "Isaya 66:4", "t": "Mimi nami nitachagua mapigo yao, nitaleta hofu zao juu yao; kwa sababu nilipoita, hawakuitika; na niliponena, hawakusikia; bali walifanya yaliyo maovu machoni pangu, na kuyachagua nisiyoyafurahia."}, {"r": "Luka 15:24", "t": "kwa kuwa huyu mwanangu alikuwa amekufa, naye amefufuka; alikuwa amepotea, naye ameonekana. Wakaanza kushangilia."}, {"r": "Isaya 24:8", "t": "Sauti ya furaha ya matoazi inakoma; kelele yao wafurahio imekwisha; furaha ya kinubi inakoma."}, {"r": "Zaburi 21:6", "t": "Maana umemfanya kuwa baraka za milele, Wamfurahisha kwa furaha ya uso wako."}, {"r": "Zaburi 126:6", "t": "Ingawa mtu anakwenda zake akilia, Azichukuapo mbegu za kupanda. Hakika atarudi kwa kelele za furaha, Aichukuapo miganda yake."}, {"r": "Marko 14:11", "t": "Nao waliposikia walifurahi, wakaahidi kumpa fedha. Akatafuta njia ya kumsaliti wakati wa kufaa."}, {"r": "Zaburi 94:3", "t": "Bwana, hata lini wasio haki, Hata lini wasio haki watashangilia?"}, {"r": "Kumbukumbu la Torati 30:9", "t": "Na Bwana, Mungu wako, atakufanya uwe na wingi wa uheri katika kazi yote ya mkono wako, katika uzao wa tumbo lako, na katika uzao wa ng'ombe wako, na katika uzao wa nchi yako; kwa kuwa Bwana atafurahi tena juu yako kwa wema, kama alivyofurahi juu ya baba zako;"}, {"r": "Yakobo 1:9", "t": "Lakini ndugu asiye na cheo na afurahi kwa kuwa ametukuzwa;"}, {"r": "Maombolezo 1:21", "t": "Wamesikia kwamba napiga kite; Hakuna hata mmoja wa kunifariji; Adui zangu wote wamesikia habari ya mashaka yaliyonipata; Hufurahi kwa kuwa umeyafanya hayo; Utaileta siku ile uliyoitangaza, Nao watakuwa kama mimi."}, {"r": "Mithali 24:25", "t": "Bali kwao wakemeao furaha itakuwako; Na baraka ya kufanikiwa itawajilia."}, {"r": "Kumbukumbu la Torati 28:63", "t": "Tena itakuwa, kama vile alivyokuwa akifurahi Bwana juu yenu kwa kuwatendea mema na kuwafanya kuwa wengi, ndivyo atakavyofurahi Bwana juu yenu kwa kuwapoteza na kuwaangamiza; nanyi mtanyakuliwa katika hiyo nchi mwingiayo kuimiliki."}, {"r": "Matendo ya Mitume 12:14", "t": "Alipoitambua sauti ya Petro, hakukifungua lango, kwa ajili ya furaha, bali alipiga mbio, akaingia ndani akawaambia kwamba Petro anasimama mbele ya lango."}, {"r": "Zaburi 119:92", "t": "Kama sheria yako isingalikuwa furaha yangu, Hapo ningalipotea katika taabu zangu."}, {"r": "Zaburi 90:15", "t": "Utufurahishe kwa kadiri ya siku ulizotutesa, Kama miaka ile tuliyoona mabaya."}, {"r": "Zaburi 30:1", "t": "Ee Bwana, nitakutukuza kwa maana umeniinua, Wala hukuwafurahisha adui zangu juu yangu."}, {"r": "Yeremia 51:39", "t": "Wakiingiwa na ukali, nitawafanyizia karamu yao, nami nitawalevya, wapate kufurahi, na kulala usingizi wa milele, wasiamke tena, asema Bwana."}, {"r": "2 Wakorintho 12:15", "t": "Nami kwa furaha nyingi nitatapanya, tena nitatapanywa kwa ajili ya roho zenu. Je! Kadiri nizidivyo kuwapenda sana, ninapungukiwa kupendwa?"}, {"r": "Yohana 16:20", "t": "Amin, amin, nawaambia, Ninyi mtalia na kuomboleza, bali ulimwengu utafurahi; ninyi mtahuzunishwa, lakini huzuni yenu itageuka kuwa furaha."}, {"r": "Yeremia 30:19", "t": "Tena kwao itasikiwa shukrani, na sauti yao wachangamkao; nami nitawazidisha, wala hawatakuwa wachache; tena nitawatukuza, wala hawatakuwa wanyonge."}, {"r": "1 Mambo ya Nyakati 16:31", "t": "Mbingu na zifurahi, nchi na ishangilie; Na waseme katika mataifa, Bwana ametamalaki;"}, {"r": "Mhubiri 5:20", "t": "Kwa kuwa mtu hatazikumbuka mno siku za maisha yake; kwa sababu Mungu humtakabali katika furaha ya moyo wake."}, {"r": "Zaburi 119:143", "t": "Taabu na dhiki zimenipata, Maagizo yako ni furaha yangu."}, {"r": "Luka 22:5", "t": "Wakafurahi, wakapatana naye kumpa fedha."}, {"r": "Habakuki 3:14", "t": "Ukakichoma kichwa cha mashujaa wake kwa fimbo zao wenyewe; Wakaja kama kisulisuli ili kunitawanya; Kama wakifurahi kuwameza maskini kwa siri."}, {"r": "Luka 15:29", "t": "Akamjibu baba yake, akasema, Tazama, mimi nimekutumikia miaka mingapi hii, wala sijakosa amri yako wakati wo wote, lakini hujanipa mimi mwanambuzi, nifanye furaha na rafiki zangu;"}, {"r": "1 Petro 1:6", "t": "Mnafurahi sana wakati huo, ijapokuwa sasa kwa kitambo kidogo, ikiwa ni lazima, mmehuzunishwa kwa majaribu ya namna mbalimbali;"}, {"r": "Yeremia 41:13", "t": "Basi, ikawa, watu wote waliokuwa pamoja na Ishmaeli, walipomwona Yohana, mwana wa Karea, na hao maakida wote wa majeshi waliokuwa pamoja naye, ndipo wakafurahi."}, {"r": "Zaburi 89:12", "t": "Kaskazini na kusini ndiwe uliyeziumba, Tabori na Hermoni hulifurahia jina lako."}, {"r": "Malaki 1:10", "t": "Laiti angekuwapo kwenu mtu mmoja wa kuifunga milango; msije mkawasha moto bure madhabahuni pangu! Sina furaha kwenu, asema Bwana wa majeshi, wala sitakubali dhabihu yo yote mikononi mwenu."}, {"r": "Zaburi 40:8", "t": "Kuyafanya mapenzi yako, Ee Mungu wangu, ndiyo furaha yangu; Naam, sheria yako imo moyoni mwangu."}, {"r": "Zaburi 69:32", "t": "Walioonewa watakapoona watafurahi; Enyi mmtafutao Mungu, mioyo yenu ihuishwe."}, {"r": "Yoeli 1:16", "t": "Je! Chakula hakikukatiliwa mbali mbele ya macho yetu? Naam, furaha na kicheko mbali na nyumba ya Mungu wetu?"}, {"r": "Zaburi 25:2", "t": "Ee Mungu wangu, Nimekutumaini Wewe, nisiaibike, Adui zangu wasifurahi kwa kunishinda."}, {"r": "Zaburi 126:2", "t": "Ndipo kinywa chetu kilipojaa kicheko, Na ulimi wetu kelele za furaha. Ndipo waliposema katika mataifa, Bwana amewatendea mambo makuu."}, {"r": "2 Wakorintho 13:9", "t": "Maana twafurahi, iwapo sisi tu dhaifu, nanyi mmekuwa hodari. Tena twaomba hili nalo, kutimilika kwenu."}, {"r": "Yeremia 6:10", "t": "Niseme na nani na kushuhudia, wapate kusikia? Tazama, sikio lao halikutahiriwa, wala hawawezi kusikiliza; tazama, neno la Bwana limekuwa matukano kwao; hawalifurahii."}, {"r": "Yeremia 15:16", "t": "Maneno yako yalionekana, nami nikayala; na maneno yako yalikuwa ni furaha kwangu, na shangwe ya moyo wangu; maana nimeitwa kwa jina lako, Ee Bwana, Mungu wa majeshi."}, {"r": "Zaburi 67:4", "t": "Mataifa na washangilie, Naam, waimbe kwa furaha, Maana kwa haki utawahukumu watu, Na kuwaongoza mataifa walioko duniani."}, {"r": "Mhubiri 2:10", "t": "Wala sikuyanyima macho yangu cho chote yalichokitamani; wala sikuuzuia moyo wangu katika furaha yo yote; maana moyo wangu ulifurahi kwa sababu ya kazi yangu yote, na hii ilikuwa sehemu yangu katika kazi yangu yote."}, {"r": "Yeremia 31:4", "t": "Mara ya pili nitakujenga, nawe utajengwa, Ee bikira wa Israeli mara ya pili utapambwa kwa matari yako, nawe utatokea katika michezo yao wanaofurahi."}, {"r": "Zekaria 9:9", "t": "Furahi sana, Ee binti Sayuni; Piga kelele, Ee binti Yerusalemu; Tazama, mfalme wako anakuja kwako; Ni mwenye haki, naye ana wokovu; Ni mnyenyekevu, amepanda punda, Naam, mwanapunda, mtoto wa punda."}, {"r": "Mithali 24:17", "t": "Usifurahi, adui yako aangukapo; Wala moyo wako usishangilie ajikwaapo;"}, {"r": "2 Wakorintho 2:3", "t": "Nami naliwaandikia neno lilo hilo, ili nijapo nisitiwe huzuni na wale ambao ilinipasa kuwafurahia; nikiwatumaini ninyi nyote kwamba furaha yangu ni yenu nyote pia."}, {"r": "Mhubiri 5:19", "t": "Tena, kwa habari za kila mwanadamu, ambaye Mungu amempa mali na ukwasi, akamwezesha kula katika hizo, na kuipokea sehemu yake, na kuifurahia amali yake; hiyo ndiyo karama ya Mungu."}], "amani": [{"r": "Zaburi 37:11", "t": "Bali wenye upole watairithi nchi, Watajifurahisha kwa wingi wa amani."}, {"r": "Wafilipi 4:9", "t": "Mambo mliyojifunza kwangu na kuyapokea, na kuyasikia na kuyaona kwangu, yatendeni hayo; na Mungu wa amani atakuwa pamoja nanyi."}, {"r": "Wakolosai 3:15", "t": "Na amani ya Kristo iamue mioyoni mwenu; ndiyo mliyoitiwa katika mwili mmoja; tena iweni watu wa shukrani."}, {"r": "Warumi 14:19", "t": "Basi kama ni hivyo, na mfuate mambo ya amani na mambo yafaayo kwa kujengana."}, {"r": "Yohana 14:27", "t": "Amani nawaachieni; amani yangu nawapa; niwapavyo mimi sivyo kama ulimwengu utoavyo. Msifadhaike mioyoni mwenu, wala msiwe na woga."}, {"r": "Hesabu 6:26", "t": "Bwana akuinulie uso wake, na kukupa amani."}, {"r": "Mathayo 11:28", "t": "Njoni kwangu, ninyi nyote msumbukao na wenye kulemewa na mizigo, nami nitawapumzisha."}, {"r": "Waebrania 12:14", "t": "Tafuteni kwa bidii kuwa na amani na watu wote, na huo utakatifu, ambao hapana mtu atakayemwona Bwana asipokuwa nao;"}, {"r": "Yohana 16:33", "t": "Hayo nimewaambieni mpate kuwa na amani ndani yangu. Ulimwenguni mnayo dhiki; lakini jipeni moyo; mimi nimeushinda ulimwengu."}, {"r": "Isaya 9:6", "t": "Maana kwa ajili yetu mtoto amezaliwa, Tumepewa mtoto mwanamume; Na uweza wa kifalme utakuwa begani mwake; Naye ataitwa jina lake, Mshauri wa ajabu, Mungu mwenye nguvu, Baba wa milele, Mfalme wa amani."}, {"r": "Wafilipi 4:6", "t": "Msijisumbue kwa neno lo lote; bali katika kila neno kwa kusali na kuomba, pamoja na kushukuru, haja zenu na zijulikane na Mungu."}, {"r": "Warumi 12:18", "t": "Kama yamkini, kwa upande wenu, mkae katika amani na watu wote."}, {"r": "Warumi 8:6", "t": "Kwa kuwa nia ya mwili ni mauti; bali nia ya roho ni uzima na amani."}, {"r": "Waefeso 4:3", "t": "na kujitahidi kuuhifadhi umoja wa Roho katika kifungo cha amani."}, {"r": "Mithali 16:7", "t": "Njia za mtu zikimpendeza Bwana, Hata adui zake huwapatanisha naye."}, {"r": "Waefeso 2:14", "t": "Kwa maana yeye ndiye amani yetu, aliyetufanya sisi sote tuliokuwa wawili kuwa mmoja; akakibomoa kiambaza cha kati kilichotutenga."}, {"r": "Warumi 15:13", "t": "Basi Mungu wa tumaini na awajaze ninyi furaha yote na amani katika kuamini, mpate kuzidi sana kuwa na tumaini, katika nguvu za Roho Mtakatifu."}, {"r": "Zaburi 119:165", "t": "Wana amani nyingi waipendao sheria yako, Wala hawana la kuwakwaza."}, {"r": "Isaya 26:3", "t": "Utamlinda yeye ambaye moyo wake umekutegemea Katika amani kamilifu, kwa kuwa anakutumaini."}, {"r": "Zaburi 85:8", "t": "Na nisikie atakavyosema Mungu Bwana, Maana atawaambia watu wake amani, Naam, na watauwa wake pia, Bali wasiurudie upumbavu tena."}, {"r": "Isaya 32:17", "t": "Na kazi ya haki itakuwa amani; na mazao ya haki yatakuwa ni utulivu na matumaini daima."}, {"r": "2 Wathesalonike 3:16", "t": "Sasa, Bwana wa amani mwenyewe na awape amani daima kwa njia zote. Bwana awe pamoja nanyi nyote."}, {"r": "Isaya 48:18", "t": "Laiti ungalisikiliza amri zangu! Ndipo amani yako ingalikuwa kama mto wa maji, na haki yako kama mawimbi ya bahari;"}, {"r": "Zaburi 29:11", "t": "Bwana atawapa watu wake nguvu; Bwana atawabariki watu wake kwa amani."}, {"r": "Zaburi 34:14", "t": "Uache mabaya ukatende mema, Utafute amani ukaifuatie."}, {"r": "Mithali 14:30", "t": "Moyo ulio mzima ni uhai wa mwili; Bali husuda ni ubovu wa mifupa."}, {"r": "Warumi 5:1", "t": "Basi tukiisha kuhesabiwa haki itokayo katika imani, na mwe na amani kwa Mungu, kwa njia ya Bwana wetu Yesu Kristo,"}, {"r": "Isaya 53:5", "t": "Bali alijeruhiwa kwa makosa yetu, Alichubuliwa kwa maovu yetu; Adhabu ya amani yetu ilikuwa juu yake, Na kwa kupigwa kwake sisi tumepona."}, {"r": "Luka 2:14", "t": "Atukuzwe Mungu juu mbinguni, Na duniani iwe amani kwa watu aliowaridhia."}, {"r": "Mathayo 5:9", "t": "Heri wapatanishi; Maana hao wataitwa wana wa Mungu."}, {"r": "Wafilipi 4:7", "t": "Na amani ya Mungu, ipitayo akili zote, itawahifadhi mioyo yenu na nia zenu katika Kristo Yesu."}, {"r": "Zaburi 4:8", "t": "Katika amani nitajilaza na kupata usingizi mara, Maana Wewe, Bwana, peke yako, Ndiwe unijaliaye kukaa salama."}, {"r": "1 Petro 3:11", "t": "Na aache mabaya, atende mema; Atafute amani, aifuate sana."}, {"r": "Zaburi 37:37", "t": "Umwangalie sana mtu mkamilifu, Umtazame mtu mnyofu, Maana mwisho wake mtu huyo ni amani."}, {"r": "Zaburi 4:4", "t": "Mwe na hofu wala msitende dhambi, Tafakarini vitandani mwenu na kutulia."}, {"r": "1 Timotheo 2:2", "t": "kwa ajili ya wafalme na wote wenye mamlaka, tuishi maisha ya utulivu na amani, katika utauwa wote na ustahivu."}, {"r": "Isaya 39:8", "t": "Ndipo Hezekia akamwambia Isaya, Neno la Bwana ulilolinena ni jema. Tena akamwambia, Maana itakuwapo amani na kweli katika siku zangu mimi."}, {"r": "Ufunuo wa Yohana 1:4", "t": "Yohana, kwa yale makanisa saba yaliyoko Asia; Neema na iwe kwenu na amani, zitokazo kwake yeye aliyeko na aliyekuwako na atakayekuja; na zitokazo kwa roho saba walioko mbele ya kiti chake cha enzi;"}, {"r": "1 Petro 5:14", "t": "Salimianeni kwa busu la upendo. Amani na iwe kwenu nyote, mlio katika Kristo. Amina."}, {"r": "Yakobo 3:18", "t": "Na tunda la haki hupandwa katika amani na wale wafanyao amani."}, {"r": "2 Yohana 1:3", "t": "Neema, na rehema, na amani, zitokazo kwa Mungu Baba na kwa Yesu Kristo Mwana wa Baba, zitakuwa pamoja nasi katika kweli na upendo."}, {"r": "Ayubu 24:23", "t": "Huwapa kuwa na salama, nao wapumzika kwayo; Na macho yake ya juu ya njia zao."}, {"r": "Amosi 5:22", "t": "Naam, ijapokuwa mnanitolea sadaka zenu za kuteketezwa na sadaka zenu za unga, sitazikubali; wala sitaziangalia sadaka zenu za amani, na za wanyama walionona."}, {"r": "Yeremia 29:11", "t": "Maana nayajua mawazo ninayowawazia ninyi, asema Bwana, ni mawazo ya amani wala si ya mabaya, kuwapa ninyi tumaini siku zenu za mwisho."}, {"r": "Kutoka 23:12", "t": "Siku sita utafanya kazi yako, na siku ya saba utapumzika; ili kwamba ng'ombe wako na punda wako wapate kupumzika, kisha mwana wa mjakazi wako na mgeni wapate kuburudika."}, {"r": "Zaburi 147:14", "t": "Ndiye afanyaye amani mipakani mwako, Akushibishaye kwa unono wa ngano."}, {"r": "Ezekieli 46:12", "t": "Naye mkuu atakapotengeneza sadaka atoayo kwa hiari yake mwenyewe, sadaka ya kuteketezwa, au sadaka za amani, ziwe sadaka amtoleazo Bwana kwa hiari yake mwenyewe, mtu mmoja atamfungulia lango lile lielekealo upande wa mashariki, naye ataitengeneza sadaka yake ya kuteketezwa, na sadaka zake za amani, kama afanyavyo siku ya sabato; kisha atatoka; na baada ya kutoka kwake mtu mmoja atalifunga lango."}, {"r": "Isaya 54:13", "t": "Na watoto wako wote watafundishwa na Bwana; na amani ya watoto wako itakuwa nyingi."}, {"r": "Zaburi 23:2", "t": "Katika malisho ya majani mabichi hunilaza, Kando ya maji ya utulivu huniongoza."}, {"r": "Yeremia 29:7", "t": "Kautakieni amani mji ule, ambao nimewafanya mchukuliwe mateka, mkauombee kwa Bwana; kwa maana katika amani yake mji huo ninyi mtapata amani."}, {"r": "Marko 4:39", "t": "Akaamka, akaukemea upepo, akaiambia bahari, Nyamaza, utulie. Upepo ukakoma, kukawa shwari kuu."}, {"r": "2 Petro 1:2", "t": "Neema na iwe kwenu na amani iongezwe katika kumjua Mungu na Yesu Bwana wetu."}, {"r": "Isaya 18:4", "t": "Maana Bwana ameniambia hivi, Mimi nitatulia, na kuangalia katika makazi yangu, kama wakati wa mwangaza mweupe wa jua kali, mfano wa wingu la umande katika hari ya mavuno."}, {"r": "Wafilipi 1:2", "t": "Neema na iwe kwenu na amani zitokazo kwa Mungu Baba yetu na kwa Bwana Yesu Kristo."}, {"r": "Ayubu 3:17", "t": "Huko waovu huacha kusumbua; Huko nako hao waliochoka wapumzika"}, {"r": "Luka 14:32", "t": "Na kama akiona hawezi, hutuma ujumbe kutaka sharti za amani, mtu yule akali mbali."}, {"r": "Ayubu 22:21", "t": "Mjue sana Mungu, ili uwe na amani; Ndivyo mema yatakavyokujia."}, {"r": "Yeremia 46:27", "t": "Lakini usiogope wewe, Ee Yakobo, mtumishi wangu; wala usifadhaike, Ee Israeli; kwa maana, tazama, nitakuokoa toka mbali, na wazao wako toka nchi ya uhamisho wao; na Yakobo atarudi, naye atatulia na kustarehe, wala hapana mtu atakayemtia hofu."}, {"r": "Waebrania 7:2", "t": "ambaye Ibrahimu alimgawia sehemu ya kumi ya vitu vyote; (tafsiri ya jina lake kwanza ni mfalme wa haki, tena, mfalme wa Salemu, maana yake, mfalme wa amani;"}, {"r": "1 Timotheo 1:2", "t": "kwa Timotheo, mwanangu hasa katika imani. Neema na iwe kwako, na rehema, na amani, zitokazo kwa Mungu Baba na kwa Kristo Yesu Bwana wetu."}, {"r": "2 Wakorintho 13:11", "t": "Hatimaye, ndugu, kwaherini; mtimilike, mfarijike, nieni mamoja, mkae katika amani; na Mungu wa upendo na amani atakuwa pamoja nanyi."}, {"r": "Yeremia 25:37", "t": "Na mazizi yenye amani yamenyamazishwa, kwa sababu ya hasira kali ya Bwana."}, {"r": "Zekaria 8:12", "t": "Kwa maana itakuwako mbegu ya amani; mzabibu utatoa matunda yake, nayo ardhi itatoa mazao yake, na hizo mbingu zitatoa umande wake; nami nitawarithisha mabaki ya watu hawa vitu hivi vyote."}, {"r": "Zekaria 8:19", "t": "Bwana wa majeshi asema hivi, Saumu ya mwezi wa nne, na saumu ya mwezi wa tano, na saumu ya mwezi wa saba, na saumu ya mwezi wa kumi, zitakuwa furaha na shangwe, na sikukuu za kuchangamkia, kwa nyumba ya Yuda; basi zipendeni kweli na amani."}, {"r": "Mithali 24:15", "t": "Ewe mtu mbaya, usiyavizie makao yake mwenye haki; Wala usipaharibu mahali pake pa kupumzika;"}, {"r": "Warumi 1:7", "t": "kwa wote walioko Rumi, wapendwao na Mungu, walioitwa kuwa watakatifu. Neema na iwe kwenu na amani itokayo kwa Mungu Baba yetu, na kwa Bwana Yesu Kristo."}, {"r": "Yeremia 47:7", "t": "Utawezaje kutulia, Ikiwa Bwana amekupa agizo? Juu ya Ashkeloni na juu ya pwani, Ndipo alipoyaamuru hayo."}, {"r": "Luka 1:79", "t": "Kuwaangaza wakaao katika giza na uvuli wa mauti, Na kuiongoza miguu yetu kwenye njia ya amani."}, {"r": "Waefeso 6:23", "t": "Amani na iwe kwa ndugu, na pendo, pamoja na imani, zitokazo kwa Mungu Baba na kwa Bwana Yesu Kristo."}, {"r": "Isaya 55:12", "t": "Maana mtatoka kwa furaha, Mtaongozwa kwa amani; Mbele yenu milima na vilima vitatoa nyimbo; Na miti yote ya kondeni itapiga makofi."}, {"r": "1 Timotheo 2:12", "t": "Simpi mwanamke ruhusa ya kufundisha, wala kumtawala mwanamume, bali awe katika utulivu."}, {"r": "Isaya 52:7", "t": "Jinsi ilivyo mizuri juu ya milima Miguu yake aletaye habari njema, Yeye aitangazaye amani, Aletaye habari njema ya mambo mema, Yeye autangazaye wokovu, Auambiaye Sayuni, Mungu wako anamiliki!"}, {"r": "Isaya 57:21", "t": "Hapana amani kwa wabaya; asema Mungu wangu."}, {"r": "Ayubu 20:20", "t": "Kwa sababu hakujua utulivu ndani yake, Hataponya cho chote katika hicho alichokifurahia."}, {"r": "Yakobo 2:16", "t": "na mtu wa kwenu akawaambia, Enendeni zenu kwa amani, mkaote moto na kushiba, lakini asiwape mahitaji ya mwili, yafaa nini?"}, {"r": "Wagalatia 1:3", "t": "Neema na iwe kwenu, na amani, zitokazo kwa Mungu Baba, na kwa Bwana wetu Yesu Kristo;"}, {"r": "2 Wathesalonike 1:2", "t": "Neema na iwe kwenu na amani zitokazo kwa Mungu Baba, na kwa Bwana Yesu Kristo."}, {"r": "Yeremia 33:9", "t": "Na mji huu utakuwa kwangu jina la furaha, na sifa na utukufu, mbele ya mataifa yote ya dunia, watakaosikia habari ya mema yote niwatendeayo, nao wataogopa na kutetemeka, kwa sababu ya mema yote na amani nitakaoupatia mji huo."}, {"r": "Isaya 33:7", "t": "Angalia, mashujaa wao wanalia nje, wajumbe wa amani wanalia kwa uchungu."}, {"r": "Mathayo 10:13", "t": "Na nyumba ile ikistahili, amani yenu na iifikilie; la, kwamba haistahili, amani yenu na iwarudie ninyi."}, {"r": "1 Petro 3:4", "t": "bali kuwe utu wa moyoni usioonekana, katika mapambo yasiyoharibika; yaani, roho ya upole na utulivu, iliyo ya thamani kuu mbele za Mungu."}, {"r": "Yeremia 9:8", "t": "Ulimi wao ni mshale ufishao; husema maneno ya hadaa; mtu mmoja husema maneno ya amani na mwenzake kwa kinywa chake, lakini moyoni mwake humwotea."}, {"r": "Isaya 30:15", "t": "Kwa maana Bwana MUNGU, Mtakatifu wa Israeli, asema hivi, Kwa kurudi na kustarehe mtaokolewa; nguvu zenu zitakuwa katika kutulia na kutumaini; lakini hamkukubali."}, {"r": "Luka 12:19", "t": "Kisha, nitajiambia, Ee nafsi yangu, una vitu vyema vingi ulivyojiwekea akiba kwa miaka mingi; pumzika basi, ule, unywe, ufurahi."}, {"r": "Zaburi 125:5", "t": "Bali wao wanaozigeukia njia zao zilizopotoka, Bwana atawaondoa pamoja na watenda maovu. Amani ikae na Israeli."}, {"r": "Isaya 66:1", "t": "Bwana asema hivi, Mbingu ni kiti changu cha enzi, na dunia ni mahali pa kuweka miguu yangu; mtanijengea nyumba ya namna gani? Na mahali pangu pa kupumzikia ni mahali gani?"}, {"r": "Zekaria 1:11", "t": "Nao wakamjibu yule malaika wa Bwana aliyesimama kati ya mihadasi, wakasema, Tumekwenda huko na huko duniani, na tazama, dunia yote inatulia, nayo imestarehe."}, {"r": "1 Wakorintho 1:3", "t": "Neema na iwe kwenu na amani, zitokazo kwa Mungu Baba yetu, na kwa Bwana Yesu Kristo."}, {"r": "Zaburi 122:7", "t": "Amani na ikae ndani ya kuta zako, Na kufanikiwa ndani ya majumba yako."}, {"r": "Luka 8:24", "t": "Wakamwendea, wakamwamsha, wakisema, Bwana mkubwa, Bwana mkubwa, tunaangamia. Akaamka, akaukemea upepo na msukosuko wa maji, vikakoma; kukawa shwari."}, {"r": "1 Wakorintho 7:15", "t": "Lakini yule asiyeamini akiondoka, na aondoke. Hapo huyo ndugu mume au ndugu mke hafungiki. Lakini Mungu ametuita katika amani."}, {"r": "Yeremia 50:6", "t": "Watu wangu wamekuwa kondoo waliopotea, wachungaji wao wamewapoteza; wamewapotosha milimani; wamekwenda toka mlima hata kilima, wamesahau mahali pao pa kupumzika."}, {"r": "1 Mambo ya Nyakati 12:18", "t": "Ndipo roho ikamjilia Abishai, mkuu wa wale thelathini, naye akasema, Sisi tu watu wako, Ee Daudi; Na wa upande wako, Ee mwana wa Yese; Amani, naam, amani iwe kwako, Na amani iwe kwao wakusaidiao; Maana akusaidiye ndiye Mungu wako. Ndipo Daudi akawakaribisha, akawaweka wawe maakida wa kile kikosi."}, {"r": "Mithali 17:27", "t": "Azuiaye maneno yake ni mwenye maarifa; Na mwenye roho ya utulivu ana busara."}, {"r": "Isaya 48:22", "t": "Hapana amani kwa wabaya, asema Bwana."}, {"r": "Zaburi 72:3", "t": "Milima itawazalia watu amani, Na vilima navyo kwa haki."}, {"r": "Mhubiri 4:6", "t": "Heri konzi moja pamoja na utulivu, Kuliko konzi mbili pamoja na taabu;"}, {"r": "Wakolosai 1:2", "t": "kwa ndugu watakatifu, waaminifu katika Kristo, walioko Kolosai. Neema na iwe kwenu, na amani, zitokazo kwa Mungu Baba yetu."}, {"r": "Yeremia 30:10", "t": "Kwa sababu hiyo usiogope, Ee Yakobo, mtumishi wangu, asema Bwana; wala usifadhaike, Ee Israeli; kwa maana, tazama, nitakuokoa toka mbali, na wazao wako toka nchi ya uhamisho wao; na Yakobo atarudi, naye atatulia na kustarehe, wala hapana mtu atakayemtia hofu."}, {"r": "Ayubu 34:29", "t": "Akitoa utulivu yeye, ni nani awezaye kuhukumia makosa? Akificha uso wake, ni nani awezaye kumtazama? Kama hufanyiwa taifa, au mtu mmoja, ni sawasawa;"}, {"r": "Luka 7:50", "t": "Akamwambia yule mwanamke, Imani yako imekuokoa, enenda zako kwa amani."}, {"r": "Luka 19:38", "t": "wakasema, Ndiye mbarikiwa Mfalme ajaye kwa jina la Bwana; amani mbinguni, na utukufu huko juu."}, {"r": "Luka 10:6", "t": "na akiwamo mwana wa amani, amani yenu itamkalia; la, hayumo, amani yenu itarudi kwenu."}, {"r": "Ayubu 3:13", "t": "Maana hapo ningelala na kutulia; Ningelala usingizi; na kupata kupumzika;"}, {"r": "Isaya 11:10", "t": "Na itakuwa katika siku hiyo, shina la Yese lisimamalo kuwa ishara kwa kabila za watu, yeye ndiye ambaye mataifa watamtafuta; na mahali pake pa kupumzikia patakuwa na utukufu."}, {"r": "Kutoka 23:11", "t": "lakini mwaka wa saba utaiacha nchi ipumzike na kutulia; hao maskini miongoni mwa watu wako wapate kula; na hicho watakachosaza wao, wapate kula wanyama wa kondeni. Utafanya vivyo katika shamba lako la mizabibu, na katika shamba lako la mizeituni."}, {"r": "1 Timotheo 2:11", "t": "Mwanamke na ajifunze katika utulivu, akitii kwa kila namna."}, {"r": "Ayubu 11:18", "t": "Nawe utakuwa salama, kwa sababu kuna matumaini; Naam, utatafutatafuta kando yako, na kupumzika katika salama."}, {"r": "Mambo ya Walawi 26:35", "t": "Wakati wote itakapokuwa na ukiwa, itapumzika; ni hayo mapumziko ambayo haikuwa nayo katika Sabato zenu, hapo mlipokaa katika nchi hiyo."}, {"r": "Yeremia 8:11", "t": "Kwa maana wameiponya jeraha ya binti ya watu wangu kwa juujuu tu, wakisema, Amani, Amani, wala hapana amani."}, {"r": "Zaburi 128:6", "t": "Naam, ukawaone wana wa wanao. Amani ikae na Israeli."}, {"r": "Waefeso 2:17", "t": "Akaja akahubiri amani kwenu ninyi mliokuwa mbali, na amani kwao wale waliokuwa karibu."}, {"r": "Isaya 25:10", "t": "Kwa maana mkono wa Bwana utatulia katika mlima huu, na Moabu atakanyagwa chini huko aliko, kama vile majani makavu yakanyagwavyo katika maji ya jaa."}, {"r": "Zaburi 107:29", "t": "Huituliza dhoruba, ikawa shwari, Mawimbi yake yakanyamaza."}, {"r": "Isaya 38:17", "t": "Tazama; nalikuwa na uchungu mwingi kwa ajili ya amani yangu; Lakini kwa kunipenda umeniokoa na shimo la uharibifu; Kwa maana umezitupa dhambi zangu zote nyuma yako."}, {"r": "Yeremia 16:5", "t": "Maana Bwana asema hivi, Usiingie ndani ya nyumba yenye matanga, wala usiende kuwaombolezea, wala kuwalilia; maana nimewaondolea watu hawa amani yangu, asema Bwana, hata fadhili zangu na rehema zangu."}, {"r": "1 Wafalme 8:64", "t": "Siku ile ile mfalme akaitakasa behewa ya katikati iliyokuwa mbele ya nyumba ya Bwana; kwa kuwa hapo ndipo alipotoa sadaka ya kuteketezwa, na sadaka ya unga, na mafuta ya sadaka za amani; kwa sababu ile madhabahu ya shaba iliyokuwa mbele za Bwana ilikuwa ndogo, haikutosha kuzipokea sadaka za kuteketezwa, na sadaka za unga, na mafuta ya sadaka za amani."}, {"r": "Isaya 14:7", "t": "Dunia yote inastarehe na kutulia; Hata huanzilisha kuimba."}, {"r": "Yeremia 14:19", "t": "Je! Umemkataa Yuda kabisa? Roho yako imeichukia Sayuni? Mbona umetupiga, tusiwe na dawa ya kutuponya? Tulitazamia amani, lakini hayakuja mema yo yote, tulitazamia wakati wa kupona, na tazama, kufadhaika tu!"}, {"r": "Zaburi 107:30", "t": "Ndipo walipofurahi kwa kuwa yametulia Naye huwaleta mpaka bandari waliyoitamani."}, {"r": "Isaya 27:5", "t": "Au azishike nguvu zangu, Afanye amani nami; Naam, afanye amani nami."}, {"r": "Matendo ya Mitume 12:20", "t": "Naye Herode alikuwa amewakasirikia sana watu wa Tiro na Sidoni; wakamwendea kwa nia moja, na wakiisha kufanya urafiki na Blasto, mwenye kukitunza chumba cha mfalme cha kulalia, wakataka amani; kwa maana nchi yao ilipata riziki kwa nchi ya mfalme."}, {"r": "Mithali 7:14", "t": "Kwangu ziko sadaka za amani; Leo hivi nimeziondoa nadhiri zangu;"}, {"r": "Maombolezo 3:17", "t": "Umeniweka nafsi yangu mbali na amani; Nikasahau kufanikiwa."}, {"r": "Isaya 57:20", "t": "Bali wabaya wanafanana na bahari iliyochafuka; maana haiwezi kutulia, na maji yake hutoa tope na takataka."}, {"r": "Zaburi 51:10", "t": "Ee Mungu, uniumbie moyo safi, Uifanye upya roho iliyotulia ndani yangu"}, {"r": "Wimbo Ulio Bora 8:10", "t": "Mimi nalikuwa ukuta, Na maziwa yangu kama minara; Ndipo nikawa machoni pake Kama mtu aliyeipata amani."}, {"r": "Ufunuo wa Yohana 4:8", "t": "Na hawa wenye uhai wanne, kila mmoja alikuwa na mabawa sita; na pande zote na ndani wamejaa macho, wala hawapumziki mchana wala usiku, wakisema, Mtakatifu, Mtakatifu, Mtakatifu, Bwana Mungu Mwenyezi, aliyekuwako na aliyeko na atakayekuja."}, {"r": "Warumi 16:20", "t": "Naye Mungu wa amani atamseta Shetani chini ya miguu yenu upesi. Neema ya Bwana wetu Yesu Kristo na iwe pamoja nanyi. [Amina.]"}, {"r": "2 Timotheo 1:2", "t": "kwa Timotheo, mwanangu mpendwa. Neema na iwe kwako, na rehema, na amani, zitokazo kwa Mungu Baba na kwa Kristo Yesu Bwana wetu."}, {"r": "2 Petro 3:14", "t": "Kwa hiyo, wapenzi, kwa kuwa mnatazamia mambo hayo, fanyeni bidii ili mwonekane katika amani kuwa hamna mawaa wala aibu mbele yake."}, {"r": "Ayubu 25:2", "t": "Enzi na hofu zi pamoja naye; Hufanya amani katika mahali pake palipoinuka."}, {"r": "Isaya 57:19", "t": "Mimi nayaumba matunda ya midomo; Amani, amani, kwake yeye aliye mbali, na kwake yeye aliye karibu; asema Bwana; nami nitamponya."}, {"r": "Yeremia 28:9", "t": "Nabii atabiriye habari za amani, neno la nabii yule litakapotokea, ndipo nabii yule atakapojulikana, kuwa Bwana amemtuma kweli kweli."}, {"r": "2 Wakorintho 1:2", "t": "Neema na iwe kwenu na amani, zitokazo kwa Mungu Baba yetu na kwa Bwana Yesu Kristo."}, {"r": "Luka 2:29", "t": "Sasa, Bwana, wamruhusu mtumishi wako, Kwa amani, kama ulivyosema;"}, {"r": "1 Wathesalonike 4:11", "t": "Tena mjitahidi kutulia, na kutenda shughuli zenu, na kufanya kazi kwa mikono yenu wenyewe, kama tulivyowaagiza;"}, {"r": "2 Wathesalonike 3:12", "t": "Basi twawaagiza hao, na kuwaonya katika Bwana Yesu Kristo, watende kazi kwa utulivu na kula chakula chao wenyewe."}, {"r": "Zaburi 72:7", "t": "Siku zake yeye, mtu mwenye haki atasitawi, Na wingi wa amani hata mwezi utakapokoma."}, {"r": "Wagalatia 6:16", "t": "Na wote watakaoenenda kwa kanuni hiyo, amani na iwe kwao na rehema, naam, kwa Israeli wa Mungu."}, {"r": "2 Wafalme 9:19", "t": "Ndipo akapeleka mpanda farasi wa pili, naye akawafikilia, akasema, Mfalme asema hivi, Je! Ni amani? Yehu akasema, Wewe una nini na amani? Geuka unifuate."}, {"r": "Isaya 60:17", "t": "Badala ya shaba nitaleta dhahabu, Na badala; ya chuma nitaleta fedha, Na badala ya mti, shaba, Na badala ya mawe, chuma; Tena nitawafanya wasimamizi wako wawe amani, Na hao wakutozao fedha kuwa haki."}, {"r": "Ayubu 32:20", "t": "Nitanena, ili nipate kutulia; Nitafunua midomo yangu na kujibu."}, {"r": "1 Wathesalonike 5:23", "t": "Mungu wa amani mwenyewe awatakase kabisa; nanyi nafsi zenu na roho zenu na miili yenu mhifadhiwe mwe kamili, bila lawama, wakati wa kuja kwake Bwana wetu Yesu Kristo."}, {"r": "Yeremia 33:6", "t": "Tazama, nitauletea afya na kupona, nami nitawaponya; nami nitawafunulia wingi wa amani na kweli."}, {"r": "Nahumu 1:15", "t": "Tazama, juu ya milima iko miguu yake aletaye habari njema, atangazaye amani. Zishike sikukuu zako, Ee Yuda, uziondoe nadhiri zako; kwa maana yule asiyefaa kitu hatapita kati yako tena kamwe; amekwisha kukatiliwa mbali."}, {"r": "Yeremia 43:12", "t": "Nami nitawasha moto katika nyumba za miungu ya Misri, na kuziteketeza, na kuwachukua mateka; naye atajipamba kwa nchi ya Misri, kama vile mchungaji avaavyo nguo zake; naye atatoka huko na amani."}, {"r": "1 Wathesalonike 1:1", "t": "Paulo, na Silwano, na Timotheo, kwa kanisa la Wathesalonike, lililo katika Mungu Baba, na katika Bwana Yesu Kristo. Neema na iwe kwenu na amani."}, {"r": "Yeremia 8:15", "t": "Tulitazamia amani, lakini hayakuja mema yo yote; tulitazamia wakati wa kupona, na tazama, kufadhaika tu!"}, {"r": "Mithali 1:33", "t": "Bali kila anisikilizaye atakaa salama, Naye atatulia bila kuogopa mabaya."}, {"r": "Marko 9:50", "t": "Chumvi ni njema; lakini chumvi ikiwa si chumvi tena, mtaitia nini ikolee? Mwe na chumvi ndani yenu, mkakae kwa amani ninyi kwa ninyi."}, {"r": "Mithali 3:17", "t": "Njia zake ni njia za kupendeza sana, Na mapito yake yote ni amani."}, {"r": "Isaya 7:19", "t": "Nao watakuja na kutulia katika mabonde yaliyo ukiwa, na katika pango za majabali, na juu ya michongoma yote, na juu ya malisho yote."}, {"r": "Wakolosai 1:20", "t": "na kwa yeye kuvipatanisha vitu vyote na nafsi yake akiisha kufanya amani kwa damu ya msalaba wake; kwa yeye, ikiwa ni vitu vilivyo juu ya nchi, au vilivyo mbinguni."}, {"r": "Mika 5:5", "t": "Na mtu huyu atakuwa amani yetu; wakati Mwashuri atakapoingia katika nchi yetu, na kuyakanyaga majumba yetu, hapo mtaondokesha wachungaji saba juu yake, na wakuu wanane."}, {"r": "Zekaria 6:13", "t": "Naam, yeye atalijenga hekalu la Bwana; naye atauchukua huo utukufu; ataketi akimiliki katika kiti chake cha enzi; na kutakuwa na kuhani katika kiti chake cha enzi; na shauri la amani litakuwa kati ya hao wawili."}, {"r": "Zaburi 73:3", "t": "Maana naliwaonea wivu wenye kujivuna, Nilipoiona hali ya amani ya wasio haki."}, {"r": "Isaya 62:1", "t": "Kwa ajili ya Sayuni sitanyamaza, na kwa ajili ya Yerusalemu sitatulia, hata haki yake itakapotokea kama mwangaza, na wokovu wake kama taa iwakayo."}, {"r": "Ayubu 37:17", "t": "Jinsi nguo zako zilivyo na moto, Hapo nchi ituliapo kwa sababu ya upepo wa kusini?"}, {"r": "1 Mambo ya Nyakati 4:40", "t": "Wakaona malisho ya unono, mazuri, na nchi yenyewe ilikuwa na nafasi, tena imetulia, na kuwa na amani; kwani waliokaa huko zamani walikuwa watu wa Hamu."}, {"r": "Ayubu 14:6", "t": "Acha kumwangalia yeye, apate kupumzika, Hata atakapoitimiza siku yake, kama aliyeajiriwa."}, {"r": "Zaburi 122:6", "t": "Utakieni Yerusalemu amani; Na wafanikiwe wakupendao;"}, {"r": "Warumi 2:10", "t": "bali utukufu na heshima na amani kwa kila mtu atendaye mema, Myahudi kwanza na Myunani pia;"}, {"r": "Yeremia 12:5", "t": "Ikiwa umepiga mbio pamoja na hao waendao kwa miguu, nao wamekuchosha, basi wawezaje kushindana na farasi? Na ujapokuwa katika nchi ya amani u salama, lakini utafanyaje hapo katika kiburi cha Yordani?"}, {"r": "1 Wathesalonike 5:3", "t": "Wakati wasemapo, Kuna amani na salama, ndipo uharibifu uwajiapo kwa ghafula, kama vile utungu umjiavyo mwenye mimba, wala hakika hawataokolewa."}, {"r": "Ayubu 5:23", "t": "Kwani utakuwa na mapatano na mawe ya bara; Nao wanyama wa bara watakuwa na amani kwako."}, {"r": "Yeremia 34:5", "t": "utakufa katika amani; na kwa mafukizo ya baba zako, wafalme wa zamani waliokutangulia, ndivyo watakavyokufukizia; nao watakulilia, Aa, Bwana! Kwa maana mimi nimelinena neno hili, asema Bwana."}, {"r": "Isaya 26:12", "t": "Bwana, utatuamuria amani; maana ni wewe pia uliyetutendea kazi zetu zote."}, {"r": "Warumi 15:33", "t": "Mungu wa amani na awe pamoja nanyi nyote. Amina."}, {"r": "Marko 5:34", "t": "Akamwambia, Binti, imani yako imekuponya, enenda zako kwa amani, uwe mzima, usiwe na msiba wako tena."}, {"r": "2 Timotheo 2:22", "t": "Lakini zikimbie tamaa za ujanani; ukafuate haki, na imani, na upendo, na amani, pamoja na wale wamwitao Bwana kwa moyo safi."}, {"r": "Tito 1:4", "t": "kwa Tito, mwanangu hasa katika imani tuishirikiyo. Neema na iwe kwako na amani zitokazo kwa Mungu Baba na kwa Kristo Yesu Mwokozi wetu."}, {"r": "Isaya 9:7", "t": "Maongeo ya enzi yake na amani Hayatakuwa na mwisho kamwe, Katika kiti cha enzi cha Daudi na ufalme wake; Kuuthibitisha na kuutegemeza Kwa hukumu na kwa haki, Tangu sasa na hata milele. Wivu wa Bwana wa majeshi ndio utakaotenda hayo."}, {"r": "Yakobo 3:17", "t": "Lakini hekima itokayo juu, kwanza ni safi, tena ni ya amani, ya upole, tayari kusikiliza maneno ya watu, imejaa rehema na matunda mema, haina fitina, haina unafiki."}, {"r": "Zekaria 8:16", "t": "Haya ndiyo mtakayoyatenda; kila mtu na aseme kweli na jirani yake; hukumuni kweli na hukumu ya amani malangoni mwenu;"}, {"r": "Matendo ya Mitume 16:36", "t": "Yule mlinzi wa gereza akamwarifu Paulo maneno haya akisema, Makadhi wametuma watu ili mfunguliwe; basi, sasa tokeni nje, enendeni zenu kwa amani."}, {"r": "Isaya 32:18", "t": "Na watu wangu watakaa katika kao la amani; na katika maskani zilizo salama, na katika mahali pa kupumzikia penye utulivu."}, {"r": "Zaburi 34:3", "t": "Mtukuzeni Bwana pamoja nami, Na tuliadhimishe jina lake pamoja."}, {"r": "Luka 12:51", "t": "Je! Mwadhani ya kwamba nimekuja kuleta amani duniani? Nawaambia, La, sivyo, bali mafarakano."}, {"r": "Yakobo 3:8", "t": "Bali ulimi hakuna awezaye kuufuga; ni uovu usiotulia, umejaa sumu iletayo mauti."}, {"r": "Zaburi 35:20", "t": "Maana hawasemi maneno ya amani, Na juu ya watulivu wa nchi huwaza hila."}, {"r": "Mathayo 12:43", "t": "Pepo mchafu, amtokapo mtu, hupitia mahali pasipo maji, akitafuta mahali pa kupumzika, asipate."}, {"r": "1 Wathesalonike 5:13", "t": "mkawastahi sana katika upendo, kwa ajili ya kazi zao. Iweni na amani ninyi kwa ninyi."}, {"r": "Isaya 42:19", "t": "Ni nani aliye kipofu, ila mtumishi wangu? Au aliye kiziwi, kama mjumbe wangu nimtumaye? Ni nani aliye kipofu, kama yeye aliye na amani? Naam, kipofu kama mtumishi wa Bwana?"}, {"r": "Waefeso 2:15", "t": "Naye akiisha kuuondoa ule uadui kwa mwili wake; ndiyo sheria ya amri zilizo katika maagizo; ili afanye hao wawili kuwa mtu mpya mmoja ndani ya nafsi yake; akafanya amani."}, {"r": "Zaburi 85:10", "t": "Fadhili na kweli zimekutana, Haki na amani zimehusiana."}, {"r": "Mambo ya Walawi 7:29", "t": "Nena na wana wa Israeli uwaambie, Yeye asongezaye dhabihu yake ya sadaka za amani kwa Bwana, atamletea Bwana matoleo yake, kutoka katika ile dhabihu ya sadaka zake za amani;"}, {"r": "Zekaria 8:10", "t": "Maana kabla ya siku zile hapakuwa na ijara kwa mwanadamu, wala hapakuwa na ijara kwa mnyama; wala hapakuwa na amani kwake yeye aliyetoka, wala kwake yeye aliyeingia, kwa sababu ya adui; nami nalimwacha kila mtu kugombana na jirani yake."}, {"r": "Luka 8:48", "t": "Akamwambia Binti, imani yako imekuponya; enenda zako na amani."}, {"r": "Mithali 12:20", "t": "Hila imo mioyoni mwao wafikirio uovu; Bali wafanyao mashauri ya amani, kwao kuna furaha."}, {"r": "Zaburi 28:3", "t": "Usinikokote pamoja na wasio haki, Wala pamoja na watenda maovu. Wawaambiao jirani zao maneno ya amani, Lakini mioyoni mwao mna madhara."}, {"r": "Yeremia 48:11", "t": "Moabu amestarehe tangu ujana wake, naye ametulia juu ya sira zake, wala hakumiminwa kutoka chombo kimoja kutiwa chombo kingine, wala hakwenda kufungwa; kwa hiyo ladha yake anakaa nayo, wala harufu yake haikubadilika."}, {"r": "Waebrania 12:11", "t": "Kila adhabu wakati wake haionekani kuwa kitu cha furaha, bali cha huzuni; lakini baadaye huwaletea wao waliozoezwa nayo matunda ya haki yenye amani."}, {"r": "Ezekieli 13:16", "t": "yaani, manabii wa Israeli, watabirio habari za Yerusalemu, na kuona maono ya amani katika habari zake; wala hapana amani, asema Bwana MUNGU."}, {"r": "Warumi 14:17", "t": "Maana ufalme wa Mungu si kula wala kunywa, bali ni haki na amani na furaha katika Roho Mtakatifu."}, {"r": "Zaburi 38:3", "t": "Hamna uzima katika mwili wangu Kwa sababu ya ghadhabu yako. Wala hamna amani mifupani mwangu Kwa sababu ya hatia zangu."}, {"r": "Mithali 3:2", "t": "Maana zitakuongezea wingi wa siku. Na miaka ya uzima, na amani."}, {"r": "1 Samueli 25:6", "t": "na hivi ndivyo mtakavyomwambia huyu aishiye salama, Amani na iwe kwako, na amani nyumbani mwako, na amani kwao wote ulio nao."}, {"r": "Yeremia 49:23", "t": "Habari za Dameski. Hamathi umetahayarika, na Arpadi pia; Maana wamesikia habari mbaya; Wameyeyuka kabisa; Huzuni iko baharini, haiwezi kutulia."}, {"r": "Matendo ya Mitume 15:33", "t": "Na wakiisha kukaa huko muda, wakaruhusiwa na ndugu waende kwa amani kwa hao waliowatuma. ["}, {"r": "Mathayo 8:26", "t": "Akawaambia, Mbona mmekuwa waoga, enyi wa imani haba? Mara akaondoka, akazikemea pepo na bahari; kukawa shwari kuu."}, {"r": "Mithali 17:1", "t": "Afadhali mego kavu pamoja na utulivu, Kuliko nyumba yenye karamu nyingi pamoja na magomvi."}, {"r": "Waefeso 6:15", "t": "na kufungiwa miguu utayari tupatao kwa Injili ya amani;"}, {"r": "Matendo ya Mitume 19:36", "t": "Basi kwa kuwa mambo haya hayawezi kukanushwa, imewapasa kutulia; msifanye neno la haraka haraka."}, {"r": "Kutoka 34:21", "t": "Utafanya kazi siku sita, lakini katika siku ya saba utapumzika; wakati wa kulima mashamba, na wakati wa kuvuna pia, utapumzika."}, {"r": "Isaya 66:12", "t": "Maana Bwana asema hivi, Tazama, nitamwelekezea amani kama mto, na utukufu wa mataifa kama kijito kifurikacho, nanyi mtapata kunyonya; mtabebwa; na juu ya magoti mtabembelezwa."}, {"r": "Maombolezo 2:18", "t": "Mioyo yao ilimlilia Bwana; Ee ukuta wa binti Sayuni! Machozi na yachuruzike kama mto Mchana na usiku; Usijipatie kupumzika; Mboni ya jicho lako isikome."}, {"r": "Yeremia 6:14", "t": "Wameiponya jeraha ya watu wangu kwa juu juu tu, wakisema, Amani, Amani, wala hapana amani."}, {"r": "Warumi 3:17", "t": "Wala njia ya amani hawakuijua."}, {"r": "Maombolezo 3:26", "t": "Ni vema mtu autarajie wokovu wa Bwana Na kumngojea kwa utulivu."}, {"r": "1 Yohana 3:23", "t": "Na hii ndiyo amri yake, kwamba tuliamini jina la Mwana wake Yesu Kristo, na kupendana sisi kwa sisi, kama alivyotupa amri."}, {"r": "Isaya 54:10", "t": "Maana milima itaondoka, na vilima vitaondolewa; bali wema wangu hautaondoka kwako, wala agano langu la amani halitaondolewa; asema Bwana akurehemuye."}, {"r": "Ayubu 30:17", "t": "Wakati wa usiku mifupa yangu huchomeka ndani yangu, Na maumivu yanayonitafuna hayapumziki."}, {"r": "Malaki 2:5", "t": "Agano langu naye lilikuwa agano la uhai na amani; nami nikampa ili aogope, naye akaniogopa, akalicha jina langu."}, {"r": "Waefeso 1:2", "t": "Neema na iwe kwenu na amani zitokazo kwa Mungu Baba yetu na kwa Bwana Yesu Kristo."}, {"r": "Zaburi 35:27", "t": "Washangilie na kufurahi, Wapendezwao na haki yangu. Naam, waseme daima, Atukuzwe Bwana, Apendezwaye na amani ya mtumishi wake."}, {"r": "Zaburi 120:6", "t": "Nafsi yangu imekaa siku nyingi, Pamoja naye aichukiaye amani."}, {"r": "Isaya 57:2", "t": "Yeye huingia katika amani; wao hustarehe katika vitanda vyao, kila mtu aendaye katika unyofu wake."}, {"r": "1 Petro 1:2", "t": "kama vile Mungu Baba alivyotangulia kuwajua katika kutakaswa na Roho, hata mkapata kutii na kununyiziwa damu ya Yesu Kristo. Neema na amani na ziongezwe kwenu."}, {"r": "Warumi 15:32", "t": "nipate kufika kwenu kwa furaha, kama apendavyo Mungu, nikapate kupumzika pamoja nanyi."}, {"r": "Malaki 2:6", "t": "Sheria ya kweli ilikuwa kinywani mwake, wala udhalimu haukuonekana midomoni mwake; alikwenda pamoja nami katika amani na unyofu, na kuwageuza wengi hata wakaacha uovu."}, {"r": "Filemoni 1:3", "t": "Neema na iwe kwenu, na amani, zitokazo kwa Mungu, Baba yetu, na kwa Bwana Yesu Kristo."}, {"r": "Yeremia 23:17", "t": "Daima huwaambia wao wanaonidharau, Bwana amesema, Mtakuwa na amani; nao humwambia kila mtu aendaye kwa ukaidi wa moyo wake, Hamtapatwa na ubaya wo wote."}, {"r": "2 Wafalme 9:18", "t": "Basi mpanda farasi mmoja akatoka awalaki, akasema, Mfalme asema hivi, Je! Ni amani? Yehu akasema, Wewe una nini na amani? Geuka unifuate. Yule mlinzi akatoa habari, akasema, Yule mjumbe amewafikilia, lakini harudi tena."}, {"r": "Isaya 59:8", "t": "Njia ya amani hawaijui; wala hapana hukumu ya haki katika miendo yao; wamejifanyizia njia zilizopotoka; kila apitaye katika njia hizo hajui amani."}, {"r": "Ayubu 16:18", "t": "Ee nchi, usiifunike damu yangu, Na kilio changu kisipate mahali pa kupumzika."}, {"r": "Marko 6:31", "t": "Akawaambia, Njoni ninyi peke yenu kwa faragha, mahali pasipokuwa na watu, mkapumzike kidogo. Kwa sababu walikuwako watu wengi, wakija, wakienda, hata haikuwapo nafasi ya kula."}, {"r": "Yuda 1:2", "t": "Mwongezewe rehema na amani na upendano."}, {"r": "1 Wakorintho 14:33", "t": "Kwa maana Mungu si Mungu wa machafuko, bali wa amani; vile vile kama ilivyo katika makanisa yote ya watakatifu."}, {"r": "Ayubu 3:26", "t": "Mimi sioni raha, wala situlii, wala kupumzika; Lakini huja taabu."}, {"r": "3 Yohana 1:15", "t": "Amani kwako. Rafiki zetu wakusalimu. Wasalimu hao rafiki zetu, kila mtu kwa jina lake."}, {"r": "Luka 19:42", "t": "akisema, Laiti ungalijua, hata wewe katika siku hii, yapasayo amani! Lakini sasa yamefichwa machoni pako."}, {"r": "Nahumu 3:18", "t": "Wachungaji wako wanalala usingizi, Ee mfalme wa Ashuru; watu wako wenye heshima wamepumzika; watu wako wametawanyika juu ya milima, wala hapana mtu wa kuwakusanya."}, {"r": "Ufunuo wa Yohana 14:13", "t": "Nikasikia sauti kutoka mbinguni ikisema, Andika, Heri wafu wafao katika Bwana tangu sasa. Naam, asema Roho, wapate kupumzika baada ya taabu zao; kwa kuwa matendo yao yafuatana nao."}, {"r": "Yeremia 30:5", "t": "Maana Bwana asema hivi, Tumesikia sauti ya tetemeko, na ya hofu, wala si ya amani."}, {"r": "1 Wakorintho 16:11", "t": "basi mtu ye yote asimdharau, lakini msafirisheni kwa amani, ili aje kwangu; maana ninamtazamia pamoja na ndugu zetu."}], "uvumilivu": [{"r": "Waebrania 6:12", "t": "ili msiwe wavivu, bali mkawe wafuasi wa hao wazirithio ahadi kwa imani na uvumilivu."}, {"r": "Maombolezo 3:25", "t": "Bwana ni mwema kwa hao wamngojeao, Kwa hiyo nafsi imtafutayo."}, {"r": "Mithali 14:29", "t": "Asiye mwepesi wa hasira ana fahamu nyingi; Bali mwenye roho ya hamaki hutukuza upumbavu."}, {"r": "Yakobo 1:3", "t": "mkifahamu ya kuwa kujaribiwa kwa imani yenu huleta saburi."}, {"r": "Warumi 15:4", "t": "Kwa kuwa yote yaliyotangulia kuandikwa yaliandikwa ili kutufundisha sisi; ili kwa saburi na faraja ya maandiko tupate kuwa na tumaini."}, {"r": "Warumi 8:25", "t": "Bali tukikitarajia kitu tusichokiona, twakingojea kwa saburi."}, {"r": "Isaya 40:31", "t": "bali wao wamngojeao Bwana watapata nguvu mpya; watapanda juu kwa mbawa kama tai; watapiga mbio, wala hawatachoka; watakwenda kwa miguu, wala hawatazimia."}, {"r": "Zaburi 40:1", "t": "Nalimngoja Bwana kwa saburi, Akaniinamia akakisikia kilio changu."}, {"r": "Mhubiri 7:8", "t": "Heri mwisho wa neno kuliko mwanzo wake, Na mvumilivu rohoni kuliko mwenye roho ya kiburi."}, {"r": "Warumi 15:5", "t": "Na Mungu mwenye saburi na faraja awajalie kunia mamoja ninyi kwa ninyi, kwa mfano wa Kristo Yesu;"}, {"r": "Mithali 19:11", "t": "Busara ya mtu huiahirisha hasira yake; Nayo ni fahari yake kusamehe makosa."}, {"r": "Wagalatia 5:22", "t": "Lakini tunda la Roho ni upendo, furaha, amani, uvumilivu, utu wema, fadhili, uaminifu,"}, {"r": "Waefeso 4:2", "t": "kwa unyenyekevu wote na upole, kwa uvumilivu, mkichukuliana katika upendo;"}, {"r": "Warumi 5:3", "t": "Wala si hivyo tu, ila na mfurahi katika dhiki pia; mkijua ya kuwa dhiki, kazi yake ni kuleta saburi;"}, {"r": "Yakobo 1:4", "t": "Saburi na iwe na kazi kamilifu, mpate kuwa wakamilifu na watimilifu bila kupungukiwa na neno."}, {"r": "Waebrania 10:36", "t": "Maana mnahitaji saburi, ili kwamba mkiisha kuyafanya mapenzi ya Mungu mpate ile ahadi."}, {"r": "2 Petro 3:9", "t": "Bwana hakawii kuitimiza ahadi yake, kama wengine wanavyokudhani kukawia, bali huvumilia kwenu, maana hapendi mtu ye yote apotee, bali wote wafikilie toba."}, {"r": "Wagalatia 6:9", "t": "Tena tusichoke katika kutenda mema; maana tutavuna kwa wakati wake, tusipozimia roho."}, {"r": "Yakobo 5:8", "t": "Nanyi vumilieni, mthibitishe mioyo yenu, kwa maana kuja kwake Bwana kunakaribia."}, {"r": "Yakobo 5:11", "t": "Angalieni, twawaita heri wao waliosubiri. Mmesikia habari ya subira yake Ayubu, mmeuona mwisho wa Bwana ya kwamba Bwana ni mwingi wa rehema, mwenye huruma."}, {"r": "Zaburi 37:7", "t": "Ukae kimya mbele za Bwana, Nawe umngojee kwa saburi; Usimkasirikie yeye afanikiwaye katika njia yake, Wala mtu afanyaye hila."}, {"r": "1 Wathesalonike 5:14", "t": "Ndugu, twawasihi, waonyeni wale wasiokaa kwa utaratibu; watieni moyo walio dhaifu; watieni nguvu wanyonge; vumilieni na watu wote."}, {"r": "Luka 21:19", "t": "Nanyi kwa subira yenu mtaziponya nafsi zenu."}, {"r": "Luka 8:15", "t": "Na zile penye udongo mzuri, ndio wale ambao kwa unyofu na wema wa mioyo yao hulisikia neno, na kulishika; kisha huzaa matunda kwa kuvumilia."}, {"r": "Zaburi 27:14", "t": "Umngoje Bwana, uwe hodari, Upige moyo konde, naam, umngoje Bwana."}, {"r": "Mithali 16:32", "t": "Asiye mwepesi wa hasira ni mwema kuliko shujaa; Na mtu aitawalaye roho yake kuliko mtu atekaye mji."}, {"r": "Waebrania 12:1", "t": "Basi na sisi pia, kwa kuwa tunazungukwa na wingu kubwa la mashahidi namna hii, na tuweke kando kila mzigo mzito, na dhambi ile ituzingayo kwa upesi; na tupige mbio kwa saburi katika yale mashindano yaliyowekwa mbele yetu,"}, {"r": "Maombolezo 3:26", "t": "Ni vema mtu autarajie wokovu wa Bwana Na kumngojea kwa utulivu."}, {"r": "Warumi 12:12", "t": "kwa tumaini, mkifurahi; katika dhiki, mkisubiri; katika kusali, mkidumu;"}, {"r": "1 Wakorintho 13:4", "t": "Upendo huvumilia, hufadhili; upendo hauhusudu; upendo hautakabari; haujivuni;"}, {"r": "Warumi 5:4", "t": "na kazi ya saburi ni uthabiti wa moyo; na kazi ya uthabiti wa moyo ni tumaini;"}, {"r": "Yakobo 1:12", "t": "Heri mtu astahimiliye majaribu; kwa sababu akiisha kukubaliwa ataipokea taji ya uzima, Bwana aliyowaahidia wampendao."}, {"r": "Wakolosai 1:11", "t": "mkiwezeshwa kwa uwezo wote, kwa kadiri ya nguvu ya utukufu wake, mpate kuwa na saburi ya kila namna na uvumilivu pamoja na furaha;"}, {"r": "Wakolosai 3:12", "t": "Basi, kwa kuwa mmekuwa wateule wa Mungu, watakatifu wapendwao, jivikeni moyo wa rehema, utu wema, unyenyekevu, upole, uvumilivu,"}, {"r": "Yakobo 5:7", "t": "Kwa hiyo ndugu, vumilieni, hata kuja kwake Bwana. Tazama, mkulima hungoja mazao ya nchi yaliyo ya thamani, huvumilia kwa ajili yake hata yatakapopata mvua ya kwanza na ya mwisho."}, {"r": "1 Wakorintho 9:12", "t": "Ikiwa wengine wanashiriki uwezo huu juu yenu, sisi si zaidi? Lakini hatukuutumia uwezo huo; bali twayavumilia mambo yote tusije tukaizuia Habari Njema ya Kristo."}, {"r": "1 Wakorintho 13:7", "t": "huvumilia yote; huamini yote; hutumaini yote; hustahimili yote."}, {"r": "2 Wakorintho 1:6", "t": "Lakini ikiwa sisi tu katika dhiki, ni kwa ajili ya faraja yenu na wokovu wenu; au ikiwa twafarijiwa, ni kwa ajili ya faraja yenu; ambayo hutenda kazi yake kwa kustahimili mateso yale yale tuteswayo na sisi."}, {"r": "2 Wathesalonike 1:4", "t": "Hata na sisi wenyewe twaona fahari juu yenu katika makanisa ya Mungu kwa ajili ya saburi yenu, na imani mliyo nayo katika adha zenu zote na dhiki mnazostahimili."}, {"r": "2 Wakorintho 6:6", "t": "katika kuwa safi, katika elimu, katika uvumilivu, katika utu wema, katika Roho Mtakatifu, katika upendo usio unafiki;"}, {"r": "2 Timotheo 1:8", "t": "Basi usiuonee haya ushuhuda wa Bwana wetu, wala usinionee haya mimi mfungwa wake, bali uvumilie mabaya pamoja nami kwa ajili ya Injili, kwa kadiri ya nguvu ya Mungu;"}, {"r": "1 Petro 3:20", "t": "watu wasiotii hapo zamani, uvumilivu wa Mungu ulipokuwa ukingoja, siku za Nuhu, safina ilipokuwa ikitengenezwa; ambamo ndani yake wachache, yaani, watu wanane, waliokoka kwa maji."}, {"r": "Ufunuo wa Yohana 14:12", "t": "Hapa ndipo penye subira ya watakatifu, hao wazishikao amri za Mungu, na imani ya Yesu."}, {"r": "Mathayo 20:12", "t": "wakisema, Hao wa mwisho wametenda kazi saa moja tu, nawe umewasawazisha na sisi tuliostahimili taabu na hari za mchana kutwa."}, {"r": "Matendo ya Mitume 26:3", "t": "Hasa kwa sababu wewe unajua sana desturi na maswali yote waliyo nayo Wayahudi; kwa sababu hiyo nakuomba unisikilize kwa uvumilivu."}, {"r": "2 Wakorintho 6:4", "t": "bali katika kila neno tujipatie sifa njema, kama watumishi wa Mungu; katika saburi nyingi, katika dhiki, katika misiba, katika shida;"}, {"r": "Malaki 3:2", "t": "Lakini ni nani atakayestahimili siku ya kuja kwake? Au ni nani atakayesimama atakapoonekana yeye? Kwa maana yeye ni mfano wa moto wa mtu asafishaye fedha, ni mfano wa sabuni ya mtu afuaye nguo;"}, {"r": "Waebrania 6:15", "t": "Na hivyo kwa kuvumilia akaipata ile ahadi."}, {"r": "Ufunuo wa Yohana 2:19", "t": "Nayajua matendo yako na upendo na imani na huduma na subira yako; tena kwamba matendo yako ya mwisho yamezidi yale ya kwanza."}, {"r": "Tito 2:2", "t": "ya kwamba wazee wawe wenye kiasi, wastahivu, wenye busara, wazima katika imani na katika upendo na katika saburi."}, {"r": "1 Timotheo 6:11", "t": "Bali wewe, mtu wa Mungu, uyakimbie mambo hayo; ukafuate haki, utauwa, imani, upendo, saburi, upole."}, {"r": "Waebrania 12:3", "t": "Maana mtafakarini sana yeye aliyeyastahimili mapingamizi makuu namna hii ya watendao dhambi juu ya nafsi zao, msije mkachoka, mkizimia mioyoni mwenu."}, {"r": "Amosi 7:10", "t": "Ndipo Amazia, kuhani wa Betheli, akapeleka habari kwa Yeroboamu, mfalme wa Israeli, akisema, Amosi amefanya fitina juu yako kati ya nyumba ya Israeli; nchi haiwezi kustahimili maneno yake yote."}, {"r": "1 Wakorintho 10:13", "t": "Jaribu halikuwapata ninyi, isipokuwa lililo kawaida ya wanadamu; ila Mungu ni mwaminifu; ambaye hatawaacha mjaribiwe kupita mwezavyo; lakini pamoja na lile jaribu atafanya na mlango wa kutokea, ili mweze kustahimili."}, {"r": "Waebrania 12:7", "t": "Ni kwa ajili ya kurudiwa mwastahimili; Mungu awatendea kama wana; maana ni mwana yupi asiyerudiwa na babaye?"}, {"r": "Ufunuo wa Yohana 2:2", "t": "Nayajua matendo yako, na taabu yako, na subira yako, na ya kuwa huwezi kuchukuliana na watu wabaya, tena umewajaribu wale wajiitao mitume, nao sio, ukawaona kuwa waongo;"}, {"r": "Mathayo 10:15", "t": "Amin, nawaambia, itakuwa rahisi nchi ya Sodoma na Gomora kustahimili adhabu ya siku ya hukumu, kuliko mji ule."}, {"r": "Mithali 30:21", "t": "Kwa ajili ya mambo matatu nchi hutetemeka, Naam, kwa ajili ya manne haiwezi kuvumilia."}, {"r": "Zaburi 55:12", "t": "Kwa maana aliyetukana si adui; Kama ndivyo, ningevumilia. Aliyejitukuza juu yangu siye anichukiaye; Kama ndivyo, ningejificha asinione."}, {"r": "2 Wathesalonike 3:5", "t": "Bwana awaongoze mioyo yenu mkapate pendo la Mungu, na saburi ya Kristo."}, {"r": "Ufunuo wa Yohana 3:10", "t": "Kwa kuwa umelishika neno la subira yangu, mimi nami nitakulinda, utoke katika saa ya kuharibiwa iliyo tayari kuujilia ulimwengu wote, kuwajaribu wakaao juu ya nchi."}, {"r": "1 Petro 2:19", "t": "Maana huu ndio wema hasa, mtu akivumilia huzuni kwa kumkumbuka Mungu, pale ateswapo isivyo haki."}, {"r": "Mathayo 10:22", "t": "Nanyi mtakuwa mkichukiwa na watu wote kwa ajili ya jina langu; lakini mwenye kuvumilia hata mwisho, ndiye atakayeokoka."}, {"r": "Waebrania 12:20", "t": "maana hawakuweza kustahimili neno lile lililoamriwa, Hata mnyama akiugusa huo mlima atapigwa kwa mawe."}, {"r": "Matendo ya Mitume 13:18", "t": "Na kwa muda wa miaka kama arobaini akawavumilia katika jangwa."}, {"r": "Mithali 18:14", "t": "Roho ya mtu itastahimili udhaifu wake; Bali roho iliyovunjika nani awezaye kuistahimili?"}, {"r": "1 Timotheo 1:16", "t": "Lakini kwa ajili hii nalipata rehema, ili katika mimi wa kwanza, Yesu Kristo audhihirishe uvumilivu wake wote; niwe kielelezo kwa wale watakaomwamini baadaye, wapate uzima wa milele."}, {"r": "1 Wathesalonike 3:1", "t": "Basi kwa hiyo, tulipokuwa hatuwezi kuvumilia zaidi, tuliona vema kuachwa Athene peke yetu."}, {"r": "Waebrania 10:32", "t": "Lakini zikumbukeni siku za kwanza, ambazo, mlipokwisha kutiwa nuru, mlistahimili mashindano makubwa ya maumivu;"}, {"r": "Luka 10:12", "t": "Nawaambia ya kwamba siku ile itakuwa rahisi zaidi Sodoma kuistahimili adhabu yake kuliko mji huo."}, {"r": "Warumi 2:4", "t": "Au waudharau wingi wa wema wake na ustahimili wake na uvumilivu wake, usijue ya kuwa wema wa Mungu wakuvuta upate kutubu?"}, {"r": "2 Petro 3:15", "t": "Nanyi uhesabuni uvumilivu wa Bwana wetu kuwa ni wokovu, kama vile na ndugu yetu mpenzi Paulo alivyowaandikia kwa hekima aliyopewa;"}, {"r": "Yeremia 10:19", "t": "Ole wangu, kwa sababu ya jeraha yangu! Pigo langu laumia; lakini nalisema, Kweli, ni huzuni yangu mimi, nami sina budi kuivumilia."}, {"r": "Zaburi 89:50", "t": "Ee Bwana, ukumbuke, Wanavyosimangwa watumishi wako; Jinsi ninavyostahimili kifuani mwangu Masimango ya watu wengi."}, {"r": "2 Timotheo 3:11", "t": "na upendo, na saburi; tena na adha zangu na mateso, mambo yaliyonipata katika Antiokia, katika Ikonio, na katika Listra, kila namna ya adha niliyoistahimili, naye Bwana aliniokoa katika hayo yote."}, {"r": "Yohana 16:12", "t": "Hata bado nikali ninayo mengi ya kuwaambia, lakini hamwezi kuyastahimili hivi sasa."}, {"r": "Waebrania 12:2", "t": "tukimtazama Yesu, mwenye kuanzisha na mwenye kutimiza imani yetu; ambaye kwa ajili ya furaha iliyowekwa mbele yake aliustahimili msalaba na kuidharau aibu, naye ameketi mkono wa kuume wa kiti cha enzi cha Mungu."}, {"r": "2 Timotheo 2:12", "t": "Kama tukistahimili, tutamiliki pamoja naye; Kama tukimkana yeye, yeye naye atatukana sisi;"}, {"r": "Ufunuo wa Yohana 1:9", "t": "Mimi Yohana, ndugu yenu na mwenye kushiriki pamoja nanyi katika mateso na ufalme na subira ya Yesu Kristo, nalikuwa katika kisiwa kiitwacho Patmo, kwa ajili ya Neno la Mungu, na ushuhuda wa Yesu."}, {"r": "Zaburi 101:5", "t": "Amsingiziaye jirani yake kwa siri, Huyo nitamharibu. Mwenye macho ya kiburi na moyo wa majivuno, Huyo sitavumilia naye."}, {"r": "1 Wathesalonike 1:3", "t": "Wala hatuachi kuikumbuka kazi yenu ya imani, na taabu yenu ya upendo, na saburi yenu ya tumaini lililo katika Bwana wetu Yesu Kristo, mbele za Mungu Baba yetu."}, {"r": "Mathayo 24:13", "t": "Lakini mwenye kuvumilia hata mwisho, ndiye atakayeokoka."}, {"r": "Mithali 25:15", "t": "Kwa uvumilivu mwingi mkuu husadikishwa; Na ulimi laini huvunja mfupa."}, {"r": "Waebrania 11:27", "t": "Kwa imani akatoka Misri, asiogope ghadhabu ya mfalme; maana alistahimili kama amwonaye yeye asiyeonekana."}, {"r": "Yeremia 20:9", "t": "Nami nikisema, Sitamtaja, wala sitasema tena kwa jina lake; basi, ndipo moyoni mwangu kumekuwamo kama moto uwakao, uliofungwa ndani ya mifupa yangu, nami nimechoka kwa kustahimili, wala siwezi kujizuia."}, {"r": "Yeremia 10:10", "t": "Bali Bwana ndiye Mungu wa kweli; Ndiye Mungu aliye hai, Mfalme wa milele; Mbele za ghadhabu yake nchi yatetemeka, Wala mataifa hawawezi kustahimili hasira yake."}, {"r": "Yakobo 5:10", "t": "Ndugu, watwaeni manabii walionena kwa jina la Bwana, wawe mfano wa kustahimili mabaya, na wa uvumilivu."}, {"r": "1 Petro 2:20", "t": "Kwa maana ni sifa gani kustahimili, mtendapo dhambi na kupigwa makofi? Lakini kustahimili, mtendapo mema na kupata mateso, huu ndio wema hasa mbele za Mungu."}, {"r": "2 Wakorintho 11:4", "t": "Maana yeye ajaye akihubiri Yesu mwingine ambaye sisi hatukumhubiri, au mkipokea roho nyingine msiyoipokea, au injili nyingine msiyoikubali, mnatenda vema kuvumiliana naye!"}, {"r": "Luka 10:14", "t": "Lakini, siku ya hukumu itakuwa rahisi Tiro na Sidoni kustahimili adhabu zake kuliko ninyi."}, {"r": "2 Timotheo 2:10", "t": "Kwa ajili ya hilo nastahimili mambo yote, kwa ajili ya wateule, ili wao nao waupate wokovu ule ulio katika Kristo Yesu, pamoja na utukufu wa milele."}, {"r": "Mathayo 11:22", "t": "Walakini nawaambieni, itakuwa rahisi Tiro na Sidoni kustahimili adhabu zao siku ya hukumu kuliko ninyi."}, {"r": "1 Wathesalonike 3:5", "t": "Kwa hiyo mimi nami nilipokuwa siwezi kuvumilia tena, nalituma mtu ili niijue imani yenu, asije yule mjaribu akawajaribu, na taabu yetu ikawa haina faida."}, {"r": "Marko 13:13", "t": "Nanyi mtakuwa mkichukiwa na watu wote kwa ajili ya jina langu; lakini mwenye kusaburi hata mwisho, ndiye atakayeokoka."}, {"r": "Zaburi 69:7", "t": "Maana kwa ajili yako nimestahimili laumu, Fedheha imenifunika uso wangu."}, {"r": "Mathayo 18:26", "t": "Basi yule mtumwa akaanguka, akamsujudia akisema, Bwana, nivumilie, nami nitakulipa yote pia."}, {"r": "Warumi 2:7", "t": "wale ambao kwa saburi katika kutenda mema wanatafuta utukufu na heshima na kutokuharibika, watapewa uzima wa milele;"}, {"r": "2 Timotheo 4:5", "t": "Bali wewe, uwe na kiasi katika mambo yote, vumilia mabaya, fanya kazi ya mhubiri wa Injili, timiliza huduma yako."}, {"r": "Ufunuo wa Yohana 2:3", "t": "tena ulikuwa na subira na kuvumilia kwa ajili ya jina langu, wala hukuchoka."}, {"r": "Mika 7:9", "t": "Nitaivumilia ghadhabu ya Bwana, kwa kuwa nimemwasi; hata atakaponitetea teto langu, na kunifanyia hukumu; atanileta nje kwenye nuru, nami nitaiona haki yake."}, {"r": "Yeremia 44:22", "t": "Hata Bwana asiweze kuvumilia tena, kwa sababu ya uovu wa matendo yenu, na kwa sababu ya machukizo mliyoyafanya; kwa sababu hiyo nchi yenu imekuwa ukiwa, na ajabu, na laana, isikaliwe na mtu kama ilivyo leo."}, {"r": "2 Wakorintho 12:12", "t": "Kweli ishara za mtume zilitendwa katikati yenu katika saburi yote, kwa ishara na maajabu na miujiza."}, {"r": "Warumi 9:22", "t": "Ni nini basi, ikiwa Mungu kwa kutaka kuonyesha ghadhabu yake, na kuudhihirisha uweza wake, kwa uvumilivu mwingi, alichukuliana na vile vyombo vya ghadhabu vilivyofanywa tayari kwa uharibifu;"}, {"r": "2 Timotheo 4:2", "t": "lihubiri neno, uwe tayari, wakati ukufaao na wakati usiokufaa, karipia, kemea, na kuonya kwa uvumilivu wote na mafundisho."}, {"r": "Yeremia 15:15", "t": "Ee Bwana, unajua wewe; unikumbuke, unijilie, ukanilipie kisasi juu yao wanaoniudhi; usiniondoe kwa uvumilivu wako; ujue ya kuwa ni kwa ajili yako nilivyopatikana na mashutumu."}, {"r": "Ayubu 34:31", "t": "Kwani kuna mtu aliyemwambia Mungu, Mimi nimevumilia kurudiwa, ingawa sikukosa;"}, {"r": "Mathayo 11:24", "t": "Walakini nawaambieni, itakuwa rahisi nchi ya Sodoma kustahimili adhabu yake siku ya hukumu kuliko wewe."}, {"r": "1 Wakorintho 4:12", "t": "kisha twataabika tukifanya kazi kwa mikono yetu wenyewe. Tukitukanwa twabariki, tukiudhiwa twastahimili;"}, {"r": "Yoeli 2:11", "t": "naye Bwana anatoa sauti yake mbele ya jeshi lake; maana matuo yake ni makubwa sana; kwa maana yeye ni hodari atekelezaye neno lake; kwa kuwa siku ya Bwana ni kuu, yenye kitisho sana; naye ni nani awezaye kuistahimili?"}], "utuwema": [{"r": "Zaburi 107:1", "t": "Mshukuruni Bwana kwa kuwa ni mwema, Kwa maana fadhili zake ni za milele."}, {"r": "Mithali 11:17", "t": "Mwenye rehema huitendea mema nafsi yake; Aliye mkali hujisumbua mwili wake."}, {"r": "Wakolosai 3:12", "t": "Basi, kwa kuwa mmekuwa wateule wa Mungu, watakatifu wapendwao, jivikeni moyo wa rehema, utu wema, unyenyekevu, upole, uvumilivu,"}, {"r": "Mathayo 5:16", "t": "Vivyo hivyo nuru yenu na iangaze mbele ya watu, wapate kuyaona matendo yenu mema, wamtukuze Baba yenu aliye mbinguni."}, {"r": "Waefeso 2:7", "t": "ili katika zamani zinazokuja audhihirishe wingi wa neema yake upitao kiasi kwa wema wake kwetu sisi katika Kristo Yesu."}, {"r": "Zaburi 86:5", "t": "Kwa maana Wewe, Bwana, U mwema, Umekuwa tayari kusamehe, Na mwingi wa fadhili, Kwa watu wote wakuitao."}, {"r": "Wagalatia 6:10", "t": "Kwa hiyo kadiri tupatavyo nafasi na tuwatendee watu wote mema; na hasa jamaa ya waaminio."}, {"r": "Mithali 31:26", "t": "Hufumbua kinywa chake kwa hekima, Na sheria ya wema i katika ulimi wake."}, {"r": "Wagalatia 6:9", "t": "Tena tusichoke katika kutenda mema; maana tutavuna kwa wakati wake, tusipozimia roho."}, {"r": "Tito 3:4", "t": "Lakini wema wake Mwokozi wetu Mungu, na upendo wake kwa wanadamu, ulipofunuliwa, alituokoa;"}, {"r": "Wagalatia 5:22", "t": "Lakini tunda la Roho ni upendo, furaha, amani, uvumilivu, utu wema, fadhili, uaminifu,"}, {"r": "1 Wathesalonike 5:15", "t": "Angalieni mtu awaye yote asimlipe mwenziwe mabaya kwa mabaya; bali siku zote lifuateni lililo jema, ninyi kwa ninyi na kwa watu wote."}, {"r": "Zaburi 100:5", "t": "Kwa kuwa Bwana ndiye mwema; Rehema zake ni za milele; Na uaminifu wake vizazi na vizazi."}, {"r": "Zaburi 27:13", "t": "Naamini ya kuwa nitauona wema wa Bwana Katika nchi ya walio hai."}, {"r": "Warumi 12:21", "t": "Usishindwe na ubaya, bali uushinde ubaya kwa wema."}, {"r": "Luka 6:35", "t": "Bali wapendeni adui zenu, tendeni mema, na kukopesha msitumaini kupata malipo, na thawabu yenu itakuwa nyingi; nanyi mtakuwa wana wa Aliye juu, kwa kuwa yeye ni mwema kwa wasiomshukuru, na waovu."}, {"r": "Zaburi 145:9", "t": "Bwana ni mwema kwa watu wote, Na rehema zake zi juu ya kazi zake zote."}, {"r": "Mithali 19:17", "t": "Amhurumiaye maskini humkopesha Bwana; Naye atamlipa kwa tendo lake jema."}, {"r": "Luka 6:36", "t": "Basi, iweni na huruma, kama Baba yenu alivyo na huruma."}, {"r": "Waebrania 13:16", "t": "Lakini msisahau kutenda mema na kushirikiana; maana sadaka kama hizi ndizo zimpendezazo Mungu."}, {"r": "Mathayo 25:40", "t": "Na Mfalme atajibu, akiwaambia, Amin, nawaambia, kadiri mlivyomtendea mmojawapo wa hao ndugu zangu walio wadogo, mlinitendea mimi."}, {"r": "Mithali 14:21", "t": "Amdharauye mwenzake afanya dhambi; Bali amhurumiaye maskini ana heri."}, {"r": "Warumi 2:4", "t": "Au waudharau wingi wa wema wake na ustahimili wake na uvumilivu wake, usijue ya kuwa wema wa Mungu wakuvuta upate kutubu?"}, {"r": "Mithali 3:27", "t": "Usiwanyime watu mema yaliyo haki yao, Ikiwa katika uwezo wa mkono wako kuyatenda."}, {"r": "Mika 6:8", "t": "Ee mwanadamu, yeye amekuonyesha yaliyo mema; na Bwana anataka nini kwako, ila kutenda haki, na kupenda rehema, na kwenda kwa unyenyekevu na Mungu wako!"}, {"r": "Waefeso 4:32", "t": "tena iweni wafadhili ninyi kwa ninyi, wenye huruma, mkasameheane kama na Mungu katika Kristo alivyowasamehe ninyi."}, {"r": "Zaburi 118:1", "t": "Haleluya. Mshukuruni Bwana kwa kuwa ni mwema, Kwa maana fadhili zake ni za milele."}, {"r": "Matendo ya Mitume 20:35", "t": "Katika mambo yote nimewaonyesha ya kuwa kwa kushika kazi hivi imewapasa kuwasaidia wanyonge, na kuyakumbuka maneno ya Bwana Yesu, jinsi alivyosema mwenyewe, Ni heri kutoa kuliko kupokea."}, {"r": "Zaburi 34:8", "t": "Onjeni mwone ya kuwa Bwana yu mwema; Heri mtu yule anayemtumaini."}, {"r": "Zaburi 23:6", "t": "Hakika wema na fadhili zitanifuata Siku zote za maisha yangu; Nami nitakaa nyumbani mwa Bwana milele."}, {"r": "Zaburi 119:64", "t": "Bwana, dunia imejaa fadhili zako, Unifundishe amri zako."}, {"r": "Zaburi 77:8", "t": "Rehema zake zimekoma hata milele? Ahadi yake imekwisha hata vizazi vyote?"}, {"r": "Luka 8:15", "t": "Na zile penye udongo mzuri, ndio wale ambao kwa unyofu na wema wa mioyo yao hulisikia neno, na kulishika; kisha huzaa matunda kwa kuvumilia."}, {"r": "Zaburi 136:24", "t": "Akatuokoa na watesi wetu; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 136:11", "t": "Akawatoa Waisraeli katikati yao; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 65:4", "t": "Heri mtu yule umchaguaye, Na kumkaribisha akae nyuani mwako. Na tushibe wema wa nyumba yako, Patakatifu pa hekalu lako."}, {"r": "Wagalatia 6:16", "t": "Na wote watakaoenenda kwa kanuni hiyo, amani na iwe kwao na rehema, naam, kwa Israeli wa Mungu."}, {"r": "1 Petro 1:3", "t": "Ahimidiwe Mungu, Baba wa Bwana wetu Yesu Kristo, ambaye kwa rehema zake nyingi alituzaa mara ya pili ili tupate tumaini lenye uzima kwa kufufuka kwake Yesu Kristo katika wafu;"}, {"r": "Maombolezo 3:22", "t": "Ni huruma za Bwana kwamba hatuangamii, Kwa kuwa rehema zake hazikomi."}, {"r": "Mithali 16:6", "t": "Kwa rehema na kweli uovu husafishwa; Kwa kumcha Bwana watu hujiepusha na maovu."}, {"r": "Zaburi 136:14", "t": "Akawavusha Israeli katikati yake; Kwa maana fadhili zake ni za milele."}, {"r": "1 Petro 2:9", "t": "Bali ninyi ni mzao mteule, ukuhani wa kifalme, taifa takatifu, watu wa milki ya Mungu, mpate kuzitangaza fadhili zake yeye aliyewaita mtoke gizani mkaingie katika nuru yake ya ajabu;"}, {"r": "Zaburi 136:5", "t": "Yeye aliyefanya mbingu kwa fahamu zake; Kwa maana fadhili zake ni za milele."}, {"r": "Hosea 10:1", "t": "Israeli ni mzabibu, utoao matunda yake; kwa kadiri ya wingi wa matunda yake, kwa kadiri iyo hiyo ameongeza madhabahu zake; kwa kadiri ya wema wa nchi yake, kwa kadiri iyo hiyo wamefanya nguzo nzuri."}, {"r": "Mathayo 23:23", "t": "Ole wenu waandishi na Mafarisayo, wanafiki! Kwa kuwa mnalipa zaka za mnanaa na bizari na jira, lakini mmeacha mambo makuu ya sheria, yaani, adili, na rehema, na imani; hayo imewapasa kuyafanya, wala yale mengine msiyaache."}, {"r": "Hosea 2:23", "t": "Nami nitampanda katika nchi kwa ajili yangu mwenyewe; nami nitamrehemu yeye asiyepewa rehema; nami nitawaambia wale wasiokuwa watu wangu, Ninyi ndinyi watu wangu; nao watasema, Wewe ndiwe Mungu wangu."}, {"r": "Zaburi 116:7", "t": "Ee nafsi yangu, urudi rahani mwako, Kwa kuwa Bwana amekutendea ukarimu."}, {"r": "Zaburi 18:25", "t": "Kwa mtu mwenye fadhili utakuwa mwenye fadhili; Kwa mkamilifu utajionyesha kuwa mkamilifu;"}, {"r": "Zaburi 89:28", "t": "Hata milele nitamwekea fadhili zangu, Na agano langu litafanyika amini kwake."}, {"r": "Zaburi 62:12", "t": "Na fadhili ziko kwako, Ee Bwana; Maana ndiwe umlipaye kila mtu Sawasawa na haki yake."}, {"r": "Isaya 54:7", "t": "Kwa kitambo kidogo nimekuacha; lakini kwa rehema nyingi nitakukusanya."}, {"r": "Zaburi 119:77", "t": "Rehema zako zinijie nipate kuishi, Maana sheria yako ni furaha yangu."}, {"r": "Waefeso 5:9", "t": "kwa kuwa tunda la nuru ni katika wema wote na haki na kweli;"}, {"r": "Zaburi 61:7", "t": "Atakaa mbele za Mungu milele, Ziagize fadhili na kweli zimhifadhi."}, {"r": "Tito 3:2", "t": "wasimtukane mtu ye yote, wasiwe wagomvi, wawe wema, wakionyesha upole wote kwa watu wote."}, {"r": "Zaburi 116:12", "t": "Nimrudishie Bwana nini Kwa ukarimu wake wote alionitendea?"}, {"r": "Luka 7:13", "t": "Bwana alipomwona alimwonea huruma, akamwambia, Usilie."}, {"r": "Mathayo 13:48", "t": "hata lilipojaa, walilivuta pwani; wakaketi, wakakusanya walio wema vyomboni, bali walio wabaya wakawatupa."}, {"r": "Zaburi 88:11", "t": "Fadhili zako zitasimuliwa kaburini? Au uaminifu wako katika uharibifu?"}, {"r": "Zekaria 7:9", "t": "Bwana wa majeshi amesema hivi, ya kwamba, Fanyeni hukumu za kweli, kila mtu na amwonee ndugu yake rehema na huruma;"}, {"r": "Zaburi 25:7", "t": "Usiyakumbuke makosa ya ujana wangu, Wala maasi yangu. Unikumbuke kwa kadiri ya fadhili zako, Ee Bwana kwa ajili ya wema wako."}, {"r": "Zaburi 36:10", "t": "Uwadumishie wakujuao fadhili zako, Na wanyofu wa moyo uaminifu wako."}, {"r": "Zaburi 92:2", "t": "Kuzitangaza rehema zako asubuhi, Na uaminifu wako wakati wa usiku."}, {"r": "3 Yohana 1:11", "t": "Mpenzi, usiuige ubaya, bali uige wema. Yeye atendaye mema ni wa Mungu, bali yeye atendaye mabaya hakumwona Mungu."}, {"r": "Zaburi 51:1", "t": "Ee Mungu, unirehemu, Sawasawa na fadhili zako. Kiasi cha wingi wa rehema zako, Uyafute makosa yangu."}, {"r": "Luka 6:32", "t": "Maana mkiwapenda wale wawapendao ninyi, mwaonyesha fadhili gani? Kwa kuwa hata wenye dhambi huwapenda wale wawapendao."}, {"r": "Zaburi 59:10", "t": "Mungu wa fadhili zangu atanitangulia, Mungu atanijalia kuwatazama adui zangu."}, {"r": "Zaburi 85:7", "t": "Ee Bwana, utuonyeshe rehema zako, Utupe wokovu wako."}, {"r": "Zaburi 33:5", "t": "Huzipenda haki na hukumu, Nchi imejaa fadhili za Bwana."}, {"r": "Warumi 14:16", "t": "Basi, huo wema wenu usitajwe kwa ubaya."}, {"r": "Zaburi 118:29", "t": "Mshukuruni Bwana kwa kuwa ni mwema, Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 32:10", "t": "Naye mtu mwovu ana mapigo mengi, Bali amtumainiye Bwana fadhili zitamzunguka."}, {"r": "Luka 6:33", "t": "Nanyi mkiwatendea mema wale wawatendeao mema, mwaonyesha fadhili gani? Hata wenye dhambi hufanya vivyo hivyo."}, {"r": "Zekaria 6:14", "t": "Na hizo taji zitakuwa za Heldai, na Tobia, na Yedaya; na kwa fadhili za mwana wa Sefania; ziwe ukumbusho katika hekalu la Bwana."}, {"r": "Zaburi 77:9", "t": "Mungu amesahau fadhili zake? Amezuia kwa hasira rehema zake?"}, {"r": "Yeremia 3:12", "t": "Enenda, ukatangaze maneno haya kuelekea upande wa kaskazini, ukaseme, Rudi, Ee Israeli mwenye kuasi, asema Bwana; sitakutazama kwa hasira; maana mimi ni mwenye rehema, asema Bwana, sitashika hasira hata milele."}, {"r": "Warumi 1:31", "t": "wasio na ufahamu, wenye kuvunja maagano, wasiopenda jamaa zao, wasio na rehema;"}, {"r": "Matendo ya Mitume 7:46", "t": "aliyepata fadhili mbele za Mungu, naye aliomba ampatie Mungu wa Yakobo maskani."}, {"r": "Zaburi 136:26", "t": "Mshukuruni Mungu wa mbingu; Kwa maana fadhili zake ni za milele."}, {"r": "1 Yohana 3:17", "t": "Lakini mtu akiwa na riziki ya dunia, kisha akamwona ndugu yake ni mhitaji, akamzuilia huruma zake, je! Upendo wa Mungu wakaaje ndani yake huyo?"}, {"r": "Zaburi 31:19", "t": "Jinsi zilivyo nyingi fadhili zako Ulizowawekea wakuchao; Ulizowatendea wakukimbiliao Mbele ya wanadamu!"}, {"r": "Ayubu 37:13", "t": "Kama ni kwa kuonya, au kama ni kwa nchi yake, Au kama ni kwa rehema, ndiye aletaye."}, {"r": "Mithali 15:9", "t": "Njia ya mtu mbaya ni chukizo kwa Bwana; Bali humpenda mtu afuatiaye wema."}, {"r": "Yakobo 1:5", "t": "Lakini mtu wa kwenu akipungukiwa na hekima, na aombe dua kwa Mungu, awapaye wote, kwa ukarimu, wala hakemei; naye atapewa."}, {"r": "1 Wakorintho 7:25", "t": "Kwa habari za wanawali sina amri ya Bwana, lakini natoa shauri langu, mimi niliyejaliwa kwa rehema za Bwana kuwa mwaminifu."}, {"r": "Waebrania 10:28", "t": "Mtu aliyeidharau sheria ya Musa hufa pasipo huruma, kwa neno la mashahidi wawili au watatu."}, {"r": "Zaburi 17:7", "t": "Dhihirisha fadhili zako za ajabu Wewe uwaokoaye wanaokukimbilia; Kwa mkono wako wa kuume Uwaokoe nao wanaowaondokea."}, {"r": "2 Samueli 22:26", "t": "Kwa mtu mwenye fadhili utakuwa mwenye fadhili Kwa mkamilifu utajionyesha kuwa mkamilifu;"}, {"r": "Zaburi 136:8", "t": "Jua litawale mchana; Kwa maana fadhili zake ni za milele."}, {"r": "Isaya 40:6", "t": "Sikiliza, ni sauti ya mtu asemaye, Lia! Nikasema, Nilie nini? Wote wenye mwili ni majani, Na wema wake wote ni kama ua la kondeni;"}, {"r": "Zaburi 147:11", "t": "Bwana huwaridhia wao wamchao, Na kuzitarajia fadhili zake."}, {"r": "1 Timotheo 1:2", "t": "kwa Timotheo, mwanangu hasa katika imani. Neema na iwe kwako, na rehema, na amani, zitokazo kwa Mungu Baba na kwa Kristo Yesu Bwana wetu."}, {"r": "Zaburi 68:10", "t": "Kabila yako ilifanya kao lake huko; Ee Mungu, kwa wema wako uliwaruzuku walioonewa."}, {"r": "Hosea 14:3", "t": "Ashuru hatatuokoa; hatutapanda farasi; wala hatutaiambia tena kazi ya mikono yetu, Ninyi ndinyi miungu yetu; maana kwako wewe wasio na baba hupata rehema."}, {"r": "Zaburi 119:159", "t": "Uangalie niyapendavyo mausia yako, Ee Bwana, unihuishe sawasawa na fadhili zako."}, {"r": "Matendo ya Mitume 7:10", "t": "akamtoa katika dhiki zake zote, akampa fadhili na hekima mbele ya Farao, mfalme wa Misri; naye akamfanya awe mtawala juu ya Misri na nyumba yake yote."}, {"r": "Ayubu 33:24", "t": "Ndipo amwoneapo rehema, na kusema, Mwokoe asishuke shimoni; Mimi nimeuona ukombozi."}, {"r": "Hosea 10:12", "t": "Jipandieni katika haki, vuneni kwa fadhili; uchimbueni udongo wa mashamba yenu, kwa maana wakati umewadia wa kumtafuta Bwana, hata atakapokuja na kuwanyeshea haki."}, {"r": "Yeremia 31:3", "t": "Bwana alinitokea zamani, akisema, Naam nimekupenda kwa upendo wa milele, ndiyo maana nimekuvuta kwa fadhili zangu."}, {"r": "Ayubu 36:31", "t": "Kwani huwahukumu kabila za watu kwa njia hizi; Hutoa chakula kwa ukarimu."}, {"r": "1 Timotheo 1:13", "t": "ingawa hapo kwanza nalikuwa mtukanaji, mwenye kuudhi watu, mwenye jeuri, lakini nalipata rehema kwa kuwa nalitenda hivyo kwa ujinga, na kwa kutokuwa na imani."}, {"r": "1 Petro 2:3", "t": "ikiwa mmeonja ya kwamba Bwana ni mwenye fadhili."}, {"r": "Zaburi 138:2", "t": "Nitasujudu nikilikabili hekalu lako takatifu, Nitalishukuru jina lako, Kwa ajili ya fadhili zako na uaminifu wako, Kwa maana umeikuza ahadi yako, Kuliko jina lako lote."}, {"r": "Warumi 15:14", "t": "Ndugu zangu, nimehakikishwa mimi mwenyewe kwa habari zenu ya kuwa ninyi nanyi mmejaa wema, mmejazwa elimu yote, tena mwaweza kuonyana."}, {"r": "Zaburi 117:2", "t": "Maana fadhili zake kwetu sisi ni kuu, Na uaminifu wa Bwana ni wa milele."}, {"r": "Zaburi 102:14", "t": "Maana watumishi wako wameyaridhia mawe yake, Na kuyaonea huruma mavumbi yake."}, {"r": "Yeremia 16:5", "t": "Maana Bwana asema hivi, Usiingie ndani ya nyumba yenye matanga, wala usiende kuwaombolezea, wala kuwalilia; maana nimewaondolea watu hawa amani yangu, asema Bwana, hata fadhili zangu na rehema zangu."}, {"r": "Zaburi 40:10", "t": "Sikusitiri haki yako moyoni mwangu; Nimetangaza uaminifu wako na wokovu wako. Sikuficha fadhili zako wala kweli yako Katika kusanyiko kubwa."}, {"r": "Yuda 1:21", "t": "jilindeni katika upendo wa Mungu, huku mkingojea rehema ya Bwana wetu Yesu Kristo, hata mpate uzima wa milele."}, {"r": "Yeremia 50:42", "t": "Wanashika upinde na mkuki; Ni wakatili, hawana huruma; Sauti yao inanguruma kama bahari, Nao wamepanda farasi; Kila mmoja amejipanga kama aendaye vitani, Juu yako, Ee binti Babeli."}, {"r": "Zaburi 90:14", "t": "Utushibishe asubuhi kwa fadhili zako, Nasi tutashangilia na kufurahi siku zetu zote."}, {"r": "Zaburi 109:21", "t": "Na Wewe, MUNGU, Bwana, unitendee kwa ajili ya jina lako, Kwa kuwa fadhili zako ni njema uniokoe."}, {"r": "Zaburi 36:5", "t": "Ee Bwana, fadhili zako zafika hata mbinguni, Uaminifu wako hata mawinguni."}, {"r": "Yeremia 16:13", "t": "basi, kwa sababu hiyo, nitawatoeni katika nchi hii, na kuwaingiza katika nchi ambayo hamkuijua, wala ninyi wala baba zenu; na huko mtawatumikia miungu mingine mchana na usiku; kwa maana mimi sitawapa fadhili zangu hata kidogo."}, {"r": "Luka 1:58", "t": "Wakasikia jirani zake na jamaa zake ya kwamba Bwana amemwongezea rehema zake, wakafurahi pamoja naye."}, {"r": "Zaburi 13:5", "t": "Nami nimezitumainia fadhili zako; Moyo wangu na uufurahie wokovu wako."}, {"r": "Zaburi 41:10", "t": "Lakini Wewe, Bwana, unifadhili, Uniinue nipate kuwalipa."}, {"r": "Zaburi 136:9", "t": "Mwezi na nyota zitawale usiku; Kwa maana fadhili zake ni za milele."}, {"r": "Kutoka 37:9", "t": "Na hayo makerubi yakayanyosha mabawa yao juu, na kukifunika hicho kiti cha rehema kwa mabawa yao, na nyuso zao zilikuwa zaelekeana hili na hili; nyuso za hayo makerubi zilikuwa zikielekea kiti cha rehema."}, {"r": "Zaburi 42:8", "t": "Mchana Bwana ataagiza fadhili zake, na usiku wimbo wake utakuwa nami, Naam, maombi kwa Mungu aliye uhai wangu."}, {"r": "Matendo ya Mitume 6:3", "t": "Basi ndugu, chagueni watu saba miongoni mwenu, walioshuhudiwa kuwa wema, wenye kujawa na Roho, na hekima, ili tuwaweke juu ya jambo hili;"}, {"r": "Mithali 14:22", "t": "Je! Hawakosi wawazao mabaya? Bali fadhili na kweli zina wao wawazao mema."}, {"r": "Zaburi 112:5", "t": "Heri atendaye fadhili na kukopesha; Atengenezaye mambo yake kwa haki."}, {"r": "Hosea 3:5", "t": "baada ya hayo wana wa Israeli watarejea, na kumtafuta Bwana, Mungu wao, na Daudi, mfalme wao; nao watamwendea Bwana na wema wake kwa kicho siku za mwisho."}, {"r": "Zaburi 106:7", "t": "Baba zetu katika Misri Hawakufikiri matendo yako ya ajabu; Hawakukumbuka wingi wa fadhili zako; Wakaasi penye bahari, bahari ya Shamu."}, {"r": "Zaburi 41:4", "t": "Nami nalisema, Bwana, unifadhili, Uniponye roho yangu maana nimekutenda dhambi."}, {"r": "Isaya 26:10", "t": "Mtu mbaya ajapofadhiliwa, Hata hivyo hatajifunza haki; Katika nchi ya unyofu atatenda udhalimu, Wala hatauona utukufu wa Bwana."}, {"r": "Zaburi 86:3", "t": "Wewe, Bwana, unifadhili, Maana nakulilia Wewe mchana kutwa."}, {"r": "Isaya 55:3", "t": "Tegeni masikio yenu, na kunijia; Sikieni, na nafsi zenu zitaishi; Nami nitafanya nanyi agano la milele, Naam, rehema za Daudi zilizo imara."}, {"r": "Zaburi 136:25", "t": "Kila chenye mwili akipa chakula chake; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 25:10", "t": "Njia zote za Bwana ni fadhili na kweli, Kwao walishikao agano lake na shuhuda zake."}, {"r": "Yeremia 26:19", "t": "Je! Hezekia, mfalme wa Yuda, na watu wote wa Yuda, walimwua Mikaya? Je! Hakumcha Bwana, na kumwomba Bwana awafadhili; naye Bwana akaghairi, asiyatende mabaya yale aliyoyatamka juu yao? Na sisi tungetenda mabaya makuu juu ya roho zetu."}, {"r": "Mathayo 19:17", "t": "Akamwambia Kwani kuniuliza habari ya wema? Aliye mwema ni mmoja. Lakini ukitaka kuingia katika uzima, zishike amri."}, {"r": "Zaburi 26:11", "t": "Ila mimi nitakwenda kwa ukamilifu wangu; Unikomboe, unifanyie fadhili."}, {"r": "Matendo ya Mitume 24:27", "t": "Na miaka miwili ilipotimia, Feliki akampokea Porkio Festo atawale badala yake. Na Feliki, akitaka kuwafanyia Wayahudi fadhili, akamwacha Paulo amefungwa."}, {"r": "Zaburi 52:8", "t": "Bali mimi ni kama mzeituni Umeao katika nyumba ya Mungu. Nazitumainia fadhili za Mungu milele na milele."}, {"r": "Zaburi 48:9", "t": "Tumezitafakari fadhili zako, Ee Mungu, Katikati ya hekalu lako."}, {"r": "Zaburi 67:1", "t": "Mungu na atufadhili na kutubariki, Na kutuangazia uso wake."}, {"r": "Zaburi 107:31", "t": "Na wamshukuru Bwana kwa fadhili zake, Na maajabu yake kwa wanadamu."}, {"r": "Warumi 11:22", "t": "Tazama, basi, wema na ukali wa Mungu; kwa wale walioanguka, ukali, bali kwako wewe wema wa Mungu, ukikaa katika wema huo; kama sivyo, wewe nawe utakatiliwa mbali."}, {"r": "2 Wakorintho 6:6", "t": "katika kuwa safi, katika elimu, katika uvumilivu, katika utu wema, katika Roho Mtakatifu, katika upendo usio unafiki;"}, {"r": "Zaburi 89:24", "t": "Uaminifu wangu na fadhili zangu atakuwa nazo, Na kwa jina langu pembe yake itatukuka."}, {"r": "Zaburi 66:20", "t": "Na ahimidiwe Mungu asiyeyakataa maombi yangu, Wala kuniondolea fadhili zake."}, {"r": "Zaburi 138:8", "t": "Bwana atanitimilizia mambo yangu; Ee Bwana, fadhili zako ni za milele; Usiziache kazi za mikono yako."}, {"r": "1 Petro 4:10", "t": "kila mmoja kwa kadiri alivyoipokea karama, itumieni kwa kuhudumiana; kama mawakili wema wa neema mbalimbali za Mungu."}, {"r": "Zaburi 136:6", "t": "Yeye aliyeitandaza nchi juu ya maji; Kwa maana fadhili zake ni za milele."}, {"r": "2 Wathesalonike 1:11", "t": "Kwa hiyo twawaombea ninyi sikuzote, ili Mungu wetu awahesabu kuwa mmekustahili kuitwa kwenu, akatimiza kila haja ya wema na kila kazi ya imani kwa nguvu;"}, {"r": "Zaburi 136:15", "t": "Akamwangusha Farao na jeshi lake katika Bahari ya Shamu; Kwa maana fadhili zake ni za milele."}, {"r": "Luka 22:25", "t": "Akawaambia, Wafalme wa Mataifa huwatawala, na wenye mamlaka juu yao huitwa Wenye fadhili;"}, {"r": "Mithali 28:13", "t": "Afichaye dhambi zake hatafanikiwa; Bali yeye aziungamaye na kuziacha atapata rehema."}, {"r": "Zaburi 59:16", "t": "Nami nitaziimba nguvu zako asubuhi, Nitaziimba fadhili zako kwa furaha. Kwa kuwa ndiwe uliyekuwa ngome yangu, Na makimbilio siku ya shida yangu."}, {"r": "Tito 3:5", "t": "si kwa sababu ya matendo ya haki tuliyoyatenda sisi; bali kwa rehema yake, kwa kuoshwa kwa kuzaliwa kwa pili na kufanywa upya na Roho Mtakatifu;"}, {"r": "Mathayo 12:7", "t": "Lakini kama mngalijua maana yake maneno haya, Nataka rehema, wala si sadaka, msingaliwalaumu wasio na hatia."}, {"r": "Isaya 30:18", "t": "Kwa ajili ya hayo Bwana atangoja, ili awaonee huruma, na kwa ajili ya hayo atatukuzwa, ili awarehemu; kwa maana Bwana ni Mungu wa hukumu; heri wote wamngojao."}, {"r": "1 Petro 2:10", "t": "ninyi mliokuwa kwanza si taifa, bali sasa ni taifa la Mungu; mliokuwa hamkupata rehema, bali sasa mmepata rehema."}, {"r": "Zaburi 136:22", "t": "Urithi wa Israeli mtumishi wake; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 136:23", "t": "Aliyetukumbuka katika unyonge wetu; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 69:13", "t": "Nami maombi yangu nakuomba Wewe, Bwana, Wakati ukupendezao; Ee Mungu, Kwa wingi wa fadhili zako unijibu, Katika kweli ya wokovu wako."}, {"r": "Zaburi 136:20", "t": "Na Ogu, mfalme wa Bashani; Kwa maana fadhili zake ni za milele."}, {"r": "Waefeso 2:4", "t": "Lakini Mungu, kwa kuwa ni mwingi wa rehema, kwa mapenzi yake makuu aliyotupenda;"}, {"r": "Yeremia 31:12", "t": "Nao watakuja, na kuimba katika mlima Sayuni, wataukimbilia wema wa Bwana, nafaka, na divai, na mafuta, na wachanga wa kondoo na wa ng'ombe; na roho zao zitakuwa kama bustani iliyotiwa maji; wala hawatahuzunika tena kabisa."}, {"r": "1 Petro 2:19", "t": "Maana huu ndio wema hasa, mtu akivumilia huzuni kwa kumkumbuka Mungu, pale ateswapo isivyo haki."}, {"r": "Zaburi 103:17", "t": "Bali fadhili za Bwana zina wamchao Tangu milele hata milele, Na haki yake ina wana wa wana;"}, {"r": "2 Timotheo 1:18", "t": "Bwana na ampe kuona rehema machoni pa Bwana siku ile. Na jinsi alivyonihudumia kwa mengi huko Efeso, wewe unajua sana."}, {"r": "Isaya 63:15", "t": "Tazama toka mbinguni, ukaone toka makao ya utukufu wako na fahari yako; uko wapi wivu wako, na uweza wako? Shauku ya moyo wako, na huruma zako zimezuiliwa kwangu."}, {"r": "Zaburi 111:4", "t": "Amefanya ukumbusho wa matendo yake ya ajabu; Bwana ni mwenye fadhili na rehema."}, {"r": "Zaburi 136:7", "t": "Yeye aliyefanya mianga mikubwa; Kwa maana fadhili zake ni za milele."}, {"r": "Zekaria 9:17", "t": "Maana wema wake, jinsi ulivyo mwingi! Na uzuri wake, jinsi ulivyo mwingi! Nafaka itawasitawisha vijana wanaume, Na divai mpya vijana wanawake."}, {"r": "Mathayo 5:7", "t": "Heri wenye rehema; Maana hao watapata rehema."}, {"r": "Malaki 1:9", "t": "Na sasa, nawasihi, ombeni fadhili za Mungu, ili atupe neema; ikiwa jambo hili limetoka katika mikono yenu; je! Atawakubali nafsi zenu? Asema Bwana wa majeshi."}, {"r": "Filemoni 1:14", "t": "Lakini sikutaka kutenda neno lo lote isipokuwa kwa shauri lako, ili kwamba wema wako usiwe kama kwa lazima, bali kwa hiari."}, {"r": "Zaburi 119:156", "t": "Ee Bwana, rehema zako ni nyingi, Unihuishe sawasawa na hukumu zako."}, {"r": "2 Wakorintho 4:1", "t": "Kwa sababu hiyo, kwa kuwa tuna huduma hii, kwa jinsi tulivyopata rehema, hatulegei;"}, {"r": "Mithali 21:21", "t": "Aandamaye haki na fadhili, Ataona uhai na haki na heshima."}, {"r": "Zaburi 78:38", "t": "Lakini Yeye, kwa kuwa anayo rehema, Husamehe uovu wala haangamizi. Mara nyingi huipishia mbali ghadhabu yake, Wala haiwashi hasira yake yote."}, {"r": "Isaya 54:8", "t": "Kwa ghadhabu ifurikayo nalikuficha uso wangu dakika moja; lakini kwa fadhili za milele nitakurehemu, asema Bwana, Mkombozi wako."}, {"r": "Zaburi 89:1", "t": "Fadhili za Bwana nitaziimba milele; Kwa kinywa changu nitavijulisha vizazi vyote uaminifu wako."}, {"r": "Maombolezo 3:32", "t": "Maana ajapomhuzunisha atamrehemu, Kwa kadiri ya wingi wa huruma zake."}, {"r": "Waebrania 10:34", "t": "Maana mliwaonea huruma wale waliokuwa katika vifungo, tena mkakubali kwa furaha kunyang'anywa mali zenu, mkijua kwamba nafsini mwenu mna mali iliyo njema zaidi, idumuyo."}, {"r": "2 Wakorintho 1:3", "t": "Na ahimidiwe Mungu, Baba wa Bwana wetu Yesu Kristo, Baba wa rehema, Mungu wa faraja yote;"}, {"r": "Zekaria 1:16", "t": "Kwa sababu hiyo Bwana asema hivi, Ninaurudia Yerusalemu kwa rehema nyingi; nyumba yangu itajengwa ndani yake, asema Bwana wa majeshi, na kamba itanyoshwa juu ya Yerusalemu."}, {"r": "2 Wakorintho 9:13", "t": "kwa kuwa mkijaribiwa kwa utumishi huo, wanamtukuza Mungu kwa ajili ya utii wenu katika kuikiri Injili ya Kristo, na kwa ajili ya ukarimu wenu mliowashirikisha wao na watu wote."}, {"r": "2 Petro 1:11", "t": "Maana hivi mtaruzukiwa kwa ukarimu kuingia katika ufalme wa milele wa Bwana wetu, Mwokozi wetu Yesu Kristo."}, {"r": "Isaya 63:7", "t": "Nitautaja wema wa Bwana, sifa za Bwana kwa yote aliyotukirimia Bwana; na wingi wa wema wake kwa nyumba ya Israeli, aliowakirimia kwa rehema zake, na kwa wingi wa wema wake."}, {"r": "Zaburi 6:4", "t": "Bwana urudi, uniopoe nafsi yangu, Uniokoe kwa ajili ya fadhili zako."}, {"r": "Mithali 14:19", "t": "Wabaya huinama mbele ya wema, Na wasio haki malangoni mwao wenye haki."}, {"r": "Zaburi 136:2", "t": "Mshukuruni Mungu wa miungu; Kwa maana fadhili zake ni za milele."}, {"r": "2 Samueli 10:2", "t": "Naye Daudi akasema, Nitamtendea wema Hanuni, mwana wa Nahasi, kama babaye alivyonitendea wema mimi. Basi Daudi akatuma kwa mkono wa watumishi wake, ili kumtuliza kwa habari za babaye. Wakaja watumishi wa Daudi katika nchi ya wana wa Amoni."}, {"r": "2 Samueli 2:6", "t": "Bwana naye sasa awatendee ninyi fadhili na kweli; mimi nami nitawalipeni fadhili hiyo, kwa sababu mmetenda jambo hilo."}, {"r": "Mithali 16:15", "t": "Kuna uhai katika nuru ya uso wa mfalme, Na fadhili zake ni kama wingu la masika."}, {"r": "Waebrania 13:2", "t": "Msisahau kuwafadhili wageni; maana kwa njia hii wengine wamewakaribisha malaika pasipo kujua."}, {"r": "1 Wafalme 3:6", "t": "Sulemani akasema, Umemfanyia mtumwa wako Daudi baba yangu fadhili kuu, kadiri alivyoenenda mbele zako katika kweli, na katika haki, na katika unyofu wa moyo pamoja nawe; nawe umemwekea na fadhili hii kubwa, maana umempa mwana wa kuketi kitini pake kama ilivyo leo."}, {"r": "Zaburi 136:12", "t": "Kwa mkono hodari na mkono ulionyoshwa; Kwa maana fadhili zake ni za milele."}, {"r": "Yeremia 33:11", "t": "itasikilikana tena sauti ya furaha na sauti ya shangwe, sauti ya bwana arusi na sauti ya bibi arusi, sauti yao wasemao Mshukuruni Bwana wa majeshi, maana Bwana ni mwema, rehema zake ni za milele; na sauti zao waletao sadaka za shukrani nyumbani kwa Bwana. Kwa kuwa nitawarudisha wafungwa wa nchi hii kama kwanza, asema Bwana."}, {"r": "Mambo ya Walawi 16:2", "t": "Bwana akamwambia Musa, Sema na Haruni ndugu yako, kwamba asiingie wakati wo wote katika mahali patakatifu ndani ya pazia, mbele ya kiti cha rehema, kilicho juu ya sanduku, asije akafa; maana, mimi nitaonekana katika lile wingu juu ya kiti cha rehema."}, {"r": "Hosea 4:1", "t": "Lisikieni neno la Bwana, enyi wana wa Israeli; kwa maana Bwana ana mateto nao wakaao katika nchi, kwa sababu hapana kweli, wala fadhili, wala kumjua Mungu katika nchi."}, {"r": "Zaburi 86:16", "t": "Unielekee na kunifadhili mimi; Mpe mtumishi wako nguvu zako, Umwokoe mwana wa mjakazi wako."}, {"r": "Zaburi 33:22", "t": "Ee Bwana, fadhili zako zikae nasi, Kama vile tulivyokungoja Wewe."}, {"r": "Mathayo 22:10", "t": "Watumwa wale wakatoka wakaenda njia kuu, wakakusanya wote waliowaona, waovu kwa wema; arusi ikajaa wageni."}, {"r": "1 Mambo ya Nyakati 19:2", "t": "Naye Daudi akasema, Nitamtendea wema Hanuni, mwana wa Nahashi, kwa kuwa babaye alinitendea mimi wema. Basi Daudi akapeleka wajumbe ili kumtuliza kwa habari za babaye. Wakaja watumishi wa Daudi katika nchi ya wana wa Amoni kwa Hanuni, ili wamtulize."}, {"r": "Zaburi 33:18", "t": "Tazama, jicho la Bwana li kwao wamchao, Wazingojeao fadhili zake."}, {"r": "Zaburi 106:45", "t": "Akawakumbukia agano lake; Akawahurumia kwa wingi wa fadhili zake;"}, {"r": "Zaburi 109:12", "t": "Asiwe na mtu wa kumfanyia fadhili, Wala mtu wa kuwahurumia yatima wake."}, {"r": "Mathayo 5:45", "t": "ili mpate kuwa wana wa Baba yenu aliye mbinguni; maana yeye huwaangazia jua lake waovu na wema, huwanyeshea mvua wenye haki na wasio haki."}, {"r": "Mithali 20:28", "t": "Fadhili na uaminifu humhifadhi mfalme, Na kiti chake cha enzi huthibitishwa kwa fadhili."}, {"r": "Zaburi 136:3", "t": "Mshukuruni Bwana wa mabwana; Kwa maana fadhili zake ni za milele."}, {"r": "Mithali 3:3", "t": "Rehema na kweli zisifarakane nawe; Zifunge shingoni mwako; Ziandike juu ya kibao cha moyo wako."}, {"r": "Yakobo 3:17", "t": "Lakini hekima itokayo juu, kwanza ni safi, tena ni ya amani, ya upole, tayari kusikiliza maneno ya watu, imejaa rehema na matunda mema, haina fitina, haina unafiki."}, {"r": "Mithali 21:10", "t": "Nafsi ya mtu mbaya hutamani uovu; Jirani yake hapati fadhili machoni pake."}, {"r": "Waebrania 2:17", "t": "Hivyo ilimpasa kufananishwa na ndugu zake katika mambo yote, apate kuwa kuhani mkuu mwenye rehema, mwaminifu katika mambo ya Mungu, ili afanye suluhu kwa dhambi za watu wake."}, {"r": "Luka 10:37", "t": "Akasema, Ni huyo aliyemwonea huruma. Yesu akamwambia, Enenda zako, nawe ukafanye vivyo hivyo."}, {"r": "Zaburi 86:15", "t": "Lakini Wewe, Bwana, U Mungu wa rehema na neema, Mvumilivu, mwingi wa fadhili na kweli."}, {"r": "Zaburi 85:10", "t": "Fadhili na kweli zimekutana, Haki na amani zimehusiana."}, {"r": "Warumi 9:23", "t": "tena, ili audhihirishe wingi wa utukufu wake katika vile vyombo vya rehema, alivyovitengeneza tangu zamani vipate utukufu;"}, {"r": "Mathayo 6:1", "t": "Angalieni msifanye wema wenu machoni pa watu, kusudi mtazamwe na wao; kwa maana mkifanya kama hayo, hampati thawabu kwa Baba yenu aliye mbinguni."}, {"r": "2 Timotheo 1:2", "t": "kwa Timotheo, mwanangu mpendwa. Neema na iwe kwako, na rehema, na amani, zitokazo kwa Mungu Baba na kwa Kristo Yesu Bwana wetu."}, {"r": "Zaburi 18:50", "t": "Ampa mfalme wake wokovu mkuu, Amfanyia fadhili masihi"}, {"r": "Hosea 12:6", "t": "Basi, mrudie Mungu wako; shika fadhili na hukumu; ukamngojee Mungu wako daima."}, {"r": "Zaburi 101:1", "t": "Rehema na hukumu nitaziimba, Ee Bwana, nitakuimbia zaburi."}, {"r": "Isaya 63:9", "t": "Katika mateso yao yote yeye aliteswa, na malaika wa uso wake akawaokoa; kwa mapenzi yake, na huruma zake, aliwakomboa mwenyewe; akawainua, akawachukua siku zote za kale."}, {"r": "Hosea 6:4", "t": "Ee Efraimu, nikutendee nini? Ee Yuda, nikutendee nini? Kwa maana fadhili zenu ni kama wingu la asubuhi na kama umande utowekao mapema."}, {"r": "Warumi 15:9", "t": "tena ili Mataifa wamtukuze Mungu kwa ajili ya rehema zake; kama ilivyoandikwa, Kwa hiyo nitakushukuru kati ya Mataifa, Nami nitaliimbia jina lako."}, {"r": "Mithali 19:6", "t": "Watu wengi watamsihi mkuu ili awafadhili; Na kila mtu ni rafiki yake atoaye tunu."}, {"r": "Zekaria 8:22", "t": "Naam, watu wa kabila nyingi na mataifa hodari watakuja Yerusalemu kumtafuta Bwana wa majeshi, na kuomba fadhili za Bwana."}, {"r": "Yeremia 31:14", "t": "Nami nitaishibisha roho ya makuhani kwa unono, na watu wangu watashiba kwa wema wangu, asema Bwana"}, {"r": "Waebrania 4:16", "t": "Basi na tukikaribie kiti cha neema kwa ujasiri, ili tupewe rehema, na kupata neema ya kutusaidia wakati wa mahitaji."}, {"r": "Mika 7:18", "t": "Ni nani aliye Mungu kama wewe, mwenye kusamehe uovu, na kuliachilia kosa la watu wa urithi wake waliosalia? Hashiki hasira yake milele, kwa maana yeye hufurahia rehema."}, {"r": "Zaburi 25:16", "t": "Uniangalie na kunifadhili, Maana mimi ni mkiwa na mteswa."}, {"r": "Zaburi 4:1", "t": "Ee Mungu wa haki yangu, uniitikie niitapo; Umenifanyizia nafasi wakati wa shida; Unifadhili na kuisikia sala yangu."}, {"r": "Zaburi 136:16", "t": "Yeye aliyewaongoza watu wake jangwani; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 108:4", "t": "Maana fadhili zako ni kubwa hata mbinguni, Na uaminifu wako hata mawinguni."}, {"r": "Zaburi 40:11", "t": "Nawe, Bwana, usinizuilie rehema zako, Fadhili zako na kweli yako na zinihifadhi daima."}, {"r": "Zaburi 119:124", "t": "Kama zilivyo rehema zako umtendee mtumishi wako, Na amri zako unifundishe."}, {"r": "Zaburi 26:3", "t": "Maana fadhili zako zi mbele ya macho yangu, Nami nimekwenda katika kweli yako."}, {"r": "Warumi 11:30", "t": "Kwa maana kama ninyi zamani mlivyomwasi Mungu, lakini sasa mmepata rehema kwa kuasi kwao;"}, {"r": "1 Petro 2:20", "t": "Kwa maana ni sifa gani kustahimili, mtendapo dhambi na kupigwa makofi? Lakini kustahimili, mtendapo mema na kupata mateso, huu ndio wema hasa mbele za Mungu."}, {"r": "Kutoka 25:20", "t": "Na hayo makerubi yatainua mabawa yao juu, na kukifunika hicho kiti cha rehema kwa mabawa yao, na nyuso zao zitaelekeana hili na hili; nyuso za hayo makerubi zitaelekea kiti cha rehema."}, {"r": "Zaburi 86:17", "t": "Unifanyie ishara ya wema, Wanichukiao waione na kuaibishwa. Kwa kuwa Wewe, Bwana, Umenisaidia na kunifariji."}, {"r": "Zaburi 52:1", "t": "Kwa nini kujisifia uovu, Ewe jabari? Wema wa Mungu upo sikuzote."}, {"r": "Zaburi 109:26", "t": "Ee Bwana, Mungu wangu, unisaidie, Uniokoe sawasawa na fadhili zako."}, {"r": "Zaburi 107:43", "t": "Aliye na hekima na ayaangalie hayo; Na wazitafakari fadhili za Bwana."}, {"r": "Zaburi 136:18", "t": "Akawaua wafalme mashuhuri; Kwa maana fadhili zake ni za milele."}, {"r": "Warumi 15:2", "t": "Kila mtu miongoni mwetu na ampendeze jirani yake, apate wema, akajengwe."}, {"r": "Zaburi 143:8", "t": "Unifanye kusikia fadhili zako asubuhi, Kwa maana nimekutumaini Wewe. Unijulishe njia nitakayoiendea, Kwa maana nakuinulia nafsi yangu."}, {"r": "Zaburi 136:13", "t": "Yeye aliyeigawa Bahari ya Shamu; Kwa maana fadhili zake ni za milele."}, {"r": "Wafilipi 4:8", "t": "Hatimaye, ndugu zangu, mambo yo yote yaliyo ya kweli, yo yote yaliyo ya staha, yo yote yaliyo ya haki, yo yote yaliyo safi, yo yote yenye kupendeza, yo yote yenye sifa njema; ukiwapo wema wo wote, ikiwapo sifa nzuri yo yote, yatafakarini hayo."}, {"r": "Zaburi 112:4", "t": "Nuru huwazukia wenye adili gizani; Ana fadhili na huruma na haki."}, {"r": "Hosea 6:6", "t": "Maana nataka fadhili wala si sadaka; na kumjua Mungu kuliko sadaka za kuteketezwa."}, {"r": "Hosea 11:8", "t": "Niwezeje kukuacha, Efraimu? Niwezeje kukuponya, Israeli? Niwezeje kukufanya kama Adma? Niwezeje kukuweka kama Seboimu ? Moyo wangu umegeuka ndani yangu, huruma zangu zimewaka pamoja."}, {"r": "Zaburi 115:1", "t": "Ee Bwana, kutukuza usitutukuze sisi, Bali ulitukuze jina lako, Kwa ajili ya fadhili zako, Kwa ajili ya uaminifu wako."}, {"r": "Zaburi 107:15", "t": "Na wamshukuru Bwana kwa fadhili zake, Na maajabu yake kwa wanadamu."}, {"r": "Zaburi 118:4", "t": "Wamchao Bwana na waseme sasa, Ya kwamba fadhili zake ni za milele."}, {"r": "Tito 2:5", "t": "na kuwa wenye kiasi, kuwa safi, kufanya kazi nyumbani mwao, kuwa wema, kuwatii waume zao wenyewe; ili neno la Mungu lisitukanwe."}, {"r": "Zaburi 125:4", "t": "Ee Bwana, uwatendee mema walio wema, Nao walio wanyofu wa moyo."}, {"r": "Zaburi 119:41", "t": "Ee Bwana, fadhili zako zinifikie na mimi, Naam, wokovu wako sawasawa na ahadi yako."}, {"r": "Luka 1:72", "t": "Ili kuwatendea rehema baba zetu, Na kulikumbuka agano lake takatifu;"}, {"r": "Zaburi 65:11", "t": "Umeuvika mwaka taji ya wema wako; Mapito yako yadondoza unono."}, {"r": "Warumi 12:13", "t": "kwa mahitaji ya watakatifu, mkifuata ukarimu; katika kukaribisha wageni mkijitahidi."}, {"r": "Zaburi 36:7", "t": "Ee Mungu, jinsi zilivyo na thamani fadhili zako! Wanadamu huukimbilia uvuli wa mbawa zako."}, {"r": "Zaburi 136:1", "t": "Mshukuruni Bwana kwa kuwa ni mwema; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 119:88", "t": "Unihuishe kwa fadhili zako, Nami nitazishika shuhuda za kinywa chako."}, {"r": "Isaya 47:6", "t": "Nalikuwa nimekasirika na watu wangu, naliutia unajisi urithi wangu, nikawatia mkononi mwako; wewe hukuwatendea rehema; uliwatia wazee nira yako, nayo nzito sana."}, {"r": "Amosi 5:15", "t": "Yachukieni mabaya; yapendeni mema; mkaithibitishe haki langoni; yamkini kwamba Bwana, Mungu wa majeshi, atawafanyia fadhili mabaki ya Yusufu."}, {"r": "Mithali 11:27", "t": "Atafutaye mema kwa bidii hutafuta fadhili; Atafutaye madhara, hayo yatamjia."}, {"r": "Yuda 1:2", "t": "Mwongezewe rehema na amani na upendano."}, {"r": "Maombolezo 3:43", "t": "Umetufunika kwa hasira na kutufuatia; Umeua, wala hukuona huruma."}, {"r": "Habakuki 3:2", "t": "Ee Bwana, nimesikia habari zako, nami naogopa; Ee Bwana, fufua kazi yako katikati ya miaka; Katikati ya miaka tangaza habari yake; Katika ghadhabu kumbuka rehema."}, {"r": "Zaburi 55:1", "t": "Ee Mungu, uisikilize sala yangu, Wala usijifiche nikuombapo rehema."}, {"r": "Maombolezo 2:17", "t": "Bwana ameyatenda aliyoyakusudia; amelitimiza neno lake, Aliloliamuru siku za kale; Ameangusha hata chini, Wala hakuona huruma; Naye amemfurahisha adui juu yako, Ameitukuza pembe ya watesi wako."}, {"r": "Zaburi 118:3", "t": "Mlango wa Haruni na waseme sasa, Ya kwamba fadhili zake ni za milele."}, {"r": "Maombolezo 4:10", "t": "Mikono ya wanawake wenye huruma Imewatokosa watoto wao wenyewe; Walikuwa ndio chakula chao Katika uharibifu wa binti ya watu wangu."}, {"r": "2 Petro 1:3", "t": "Kwa kuwa uweza wake wa Uungu umetukirimia vitu vyote vipasavyo uzima na utauwa, kwa kumjua yeye aliyetuita kwa utukufu wake na wema wake mwenyewe."}, {"r": "Zaburi 13:6", "t": "Naam, nimwimbie Bwana, Kwa kuwa amenitendea kwa ukarimu."}, {"r": "Zaburi 107:21", "t": "Na wamshukuru Bwana kwa fadhili zake, Na maajabu yake kwa wanadamu."}, {"r": "Isaya 16:5", "t": "Na kiti cha enzi kitafanywa imara kwa rehema; na mmoja ataketi juu yake katika kweli, katika hema ya Daudi; akifanya hukumu, akitaka sana yaliyo haki, mwepesi wa kutenda haki."}, {"r": "Luka 1:50", "t": "Na rehema zake hudumu vizazi hata vizazi Kwa hao wanaomcha."}, {"r": "Zaburi 116:5", "t": "Bwana ni mwenye neema na haki, Naam, Mungu wetu ni mwenye rehema."}, {"r": "Zaburi 107:8", "t": "Na wamshukuru Bwana, kwa fadhili zake, Na maajabu yake kwa wanadamu."}, {"r": "Ayubu 39:13", "t": "Bawa la mbuni hufurahi; Lakini mabawa yake na manyoya yake, je! Yana huruma?"}, {"r": "Zaburi 118:2", "t": "Israeli na aseme sasa, Ya kwamba fadhili zake ni za milele."}, {"r": "Yoeli 2:13", "t": "rarueni mioyo yenu, wala si mavazi yenu, mkamrudie Bwana, Mungu wenu; kwa maana yeye ndiye mwenye neema, amejaa huruma; si mwepesi wa hasira, ni mwingi wa rehema, naye hughairi mabaya."}, {"r": "Zaburi 25:6", "t": "Ee Bwana, kumbuka rehema zako na fadhili zako, Maana zimekuwako tokea zamani."}, {"r": "Mithali 2:20", "t": "Ili upate kwenda katika njia ya watu wema, Na kuyashika mapito ya wenye haki."}, {"r": "Zaburi 31:9", "t": "Ee Bwana, unifadhili, maana ni katika dhiki, Jicho langu limenyauka kwa masumbufu, Naam, mwili wangu na nafsi yangu."}, {"r": "Isaya 5:20", "t": "Ole wao wasemao kwamba uovu ni wema, na kwamba wema ni uovu; watiao giza badala ya nuru, na nuru badala ya giza; watiao uchungu badala ya utamu, na utamu badala ya uchungu!"}, {"r": "Luka 1:54", "t": "Amemsaidia Israeli, mtumishi wake; Ili kukumbuka rehema zake;"}, {"r": "2 Wakorintho 9:11", "t": "mkitajirishwa katika vitu vyote mpate kuwa na ukarimu wote, umpatiao Mungu shukrani kwa kazi yetu."}, {"r": "2 Yohana 1:3", "t": "Neema, na rehema, na amani, zitokazo kwa Mungu Baba na kwa Yesu Kristo Mwana wa Baba, zitakuwa pamoja nasi katika kweli na upendo."}, {"r": "Zaburi 63:3", "t": "Maana fadhili zako ni njema kuliko uhai; Midomo yangu itakusifu."}, {"r": "Zaburi 94:18", "t": "Niliposema, Mguu wangu unateleza; Ee Bwana, fadhili zako zilinitegemeza."}, {"r": "Yakobo 5:11", "t": "Angalieni, twawaita heri wao waliosubiri. Mmesikia habari ya subira yake Ayubu, mmeuona mwisho wa Bwana ya kwamba Bwana ni mwingi wa rehema, mwenye huruma."}, {"r": "Nehemia 9:17", "t": "ila wakakataa kutii, wala hawakuyakumbuka maajabu yako, uliyoyafanya kati yao; lakini wakafanya shingo zao kuwa ngumu, na katika kuasi kwao wakaweka jemadari, ili wairudie hali ya utumwa; lakini wewe u Mungu, uliye tayari kusamehe, mwenye neema, mwenye huruma nyingi, si mwepesi wa hasira, u mwingi wa rehema, basi hukuwaacha."}, {"r": "Matendo ya Mitume 24:4", "t": "Lakini nisikuudhi zaidi, nakusihi utusikilize maneno machache kwa fadhili zako."}, {"r": "2 Wakorintho 9:6", "t": "Lakini nasema neno hili, Apandaye haba atavuna haba; apandaye kwa ukarimu atavuna kwa ukarimu."}, {"r": "Zaburi 21:7", "t": "Kwa kuwa mfalme humtumaini Bwana, Na kwa fadhili zake Aliye juu hataondoshwa."}, {"r": "Tito 1:8", "t": "bali awe mkaribishaji, mpenda wema, mwenye kiasi, mwenye haki, mtakatifu, mwenye kudhibiti nafsi yake;"}, {"r": "Zaburi 106:1", "t": "Haleluya. Mshukuruni Bwana kwa kuwa ni mwema, Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 103:8", "t": "Bwana amejaa huruma na neema, Haoni hasira upesi, ni mwingi wa fadhili."}, {"r": "Kutoka 34:6", "t": "Bwana akapita mbele yake, akatangaza, Bwana, Bwana, Mungu mwingi wa huruma, mwenye fadhili, si mwepesi wa hasira, mwingi wa rehema na kweli;"}, {"r": "Zaburi 5:7", "t": "Bali mimi, kwa wingi wa fadhili zako, Nitaingia nyumbani mwako; Na kusujudu kwa kicho, Nikilielekea hekalu lako takatifu."}, {"r": "Yakobo 2:13", "t": "Maana hukumu haina huruma kwake yeye asiyeona huruma. Huruma hujitukuza juu ya hukumu."}, {"r": "2 Wakorintho 8:2", "t": "maana walipokuwa wakijaribiwa kwa dhiki nyingi, wingi wa furaha yao na umaskini wao uliokuwa mwingi uliwaongezea utajiri wa ukarimu wao."}, {"r": "Zaburi 141:5", "t": "Mwenye haki na anipige, itakuwa fadhili; Anikemee, itakuwa kama mafuta kichwani; Kichwa changu kisikatae, Maana siachi kusali kati ya mabaya yao."}, {"r": "Matendo ya Mitume 25:3", "t": "na kumwomba fadhili juu yake, kwamba atoe amri aletwe Yerusalemu, wapate kumwotea na kumwua njiani."}, {"r": "Zaburi 145:7", "t": "Watalihubiri kumbukumbu la wema wako mkuu. Wataiimba haki yako."}, {"r": "Isaya 30:19", "t": "Kwa maana watu watakaa katika Sayuni huko Yerusalemu; wewe hutalia tena; hakika yake atakuonea rehema nyingi kwa sauti ya kilio chako; asikiapo ndipo atakapokujibu."}, {"r": "Zaburi 89:49", "t": "Bwana, zi wapi fadhili zako za kwanza, Ulizomwapia Daudi kwa uaminifu wako?"}, {"r": "2 Timotheo 1:16", "t": "Bwana awape rehema wale walio wa mlango wake Onesiforo; maana mara nyingi aliniburudisha, wala hakuuonea haya mnyororo wangu;"}, {"r": "Zaburi 103:2", "t": "Ee nafsi yangu, umhimidi Bwana, Wala usizisahau fadhili zake zote."}, {"r": "Zaburi 103:11", "t": "Maana mbingu zilivyoinuka juu ya nchi, Kadiri ile ile rehema zake ni kuu kwa wamchao."}, {"r": "Mathayo 9:13", "t": "Lakini nendeni, mkajifunze maana yake maneno haya, Nataka rehema, wala si sadaka; kwa maana sikuja kuwaita wenye haki, bali wenye dhambi."}, {"r": "Zaburi 57:10", "t": "Maana fadhili zako ni kubwa hata mbinguni, Na uaminifu wako hata mawinguni."}, {"r": "Zaburi 136:21", "t": "Akaitoa nchi yao iwe urithi; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 98:3", "t": "Amezikumbuka rehema zake, Na uaminifu wake kwa nyumba ya Israeli. Miisho yote ya dunia imeuona Wokovu wa Mungu wetu."}, {"r": "1 Timotheo 1:16", "t": "Lakini kwa ajili hii nalipata rehema, ili katika mimi wa kwanza, Yesu Kristo audhihirishe uvumilivu wake wote; niwe kielelezo kwa wale watakaomwamini baadaye, wapate uzima wa milele."}, {"r": "Zaburi 37:21", "t": "Asiye haki hukopa wala halipi, Bali mwenye haki hufadhili, hukirimu."}, {"r": "Warumi 12:1", "t": "Basi, ndugu zangu, nawasihi, kwa huruma zake Mungu, itoeni miili yenu iwe dhabihu iliyo hai, takatifu, ya kumpendeza Mungu, ndiyo ibada yenu yenye maana."}, {"r": "Zaburi 145:17", "t": "Bwana ni mwenye haki katika njia zake zote, Na mwenye fadhili juu ya kazi zake zote."}, {"r": "Zekaria 8:21", "t": "wenyeji wa mji huu watauendea mji huu, wakisema, Haya! Twendeni zetu kwa haraka tuombe fadhili za Bwana, na kumtafuta Bwana wa majeshi; Mimi nami nitakwenda."}, {"r": "Waebrania 9:5", "t": "na juu yake makerubi ya utukufu, yakikitia kivuli kiti cha rehema; basi hatuna nafasi sasa ya kueleza habari za vitu hivi kimoja kimoja."}, {"r": "Zaburi 136:17", "t": "Yeye aliyewapiga wafalme wakuu; Kwa maana fadhili zake ni za milele."}, {"r": "Maombolezo 2:2", "t": "Bwana ameyameza makao yote ya Yakobo, Wala hakuona huruma; Ameziangusha ngome za binti Yuda Katika ghadhabu yake; Amezibomoa hata nchi Ameunajisi ufalme na wakuu wake."}, {"r": "Mithali 12:10", "t": "Mwenye haki huufikiri uhai wa mnyama wake; Bali huruma za mtu mwovu ni ukatili."}, {"r": "Mithali 22:9", "t": "Mwenye jicho la ukarimu atabarikiwa; Maana huwapa maskini chakula chake."}, {"r": "Zaburi 77:7", "t": "Je! Bwana atatupa milele na milele? Hatatenda fadhili tena kabisa?"}, {"r": "Zaburi 106:5", "t": "Ili niuone wema wa wateule wako. Nipate kuifurahia furaha ya taifa lako, Na kujisifu pamoja na watu wako."}, {"r": "Yeremia 42:12", "t": "Nami nitawapa rehema, kwamba awarehemu ninyi, na kuwarudisha mkae katika nchi yenu wenyewe."}, {"r": "Zaburi 31:16", "t": "Umwangaze mtumishi wako Kwa nuru ya uso wako; Uniokoe kwa ajili ya fadhili zako."}, {"r": "Zaburi 44:26", "t": "Uondoke, uwe msaada wetu, Utukomboe kwa ajili ya fadhili zako."}, {"r": "Zaburi 136:19", "t": "Sihoni, mfalme wa Waamori; Kwa maana fadhili zake ni za milele."}, {"r": "Mika 7:20", "t": "Wewe utamtimilizia Yakobo kweli yako, na Ibrahimu rehema zako, ulizowaapia baba zetu tangu siku za kale."}, {"r": "Zaburi 37:26", "t": "Mchana kutwa hufadhili na kukopesha, Na mzao wake hubarikiwa."}, {"r": "Zaburi 89:33", "t": "Lakini fadhili zangu sitamwondolea yeye, Wala sitafanya uaminifu wangu kuwa uongo."}, {"r": "Ayubu 20:10", "t": "Watoto wake watataka fadhili kwa maskini, Na mikono yake itarudisha mali yake."}, {"r": "Hosea 2:19", "t": "Nami nitakuposa uwe wangu kwa milele; naam, nitakuposa kwa haki, na kwa hukumu, na kwa ufadhili, na kwa rehema."}, {"r": "Luka 15:20", "t": "Akaondoka, akaenda kwa babaye. Alipokuwa angali mbali, baba yake alimwona, akamwonea huruma, akaenda mbio akamwangukia shingoni, akambusu sana."}, {"r": "Mambo ya Walawi 16:14", "t": "Kisha atatwaa baadhi ya damu ya yule ng'ombe, na kuinyunyiza kwa kidole chake juu ya kiti cha rehema upande wa mashariki; na mbele ya kiti cha rehema atainyunyiza ile damu kwa kidole chake mara saba."}, {"r": "Luka 6:34", "t": "Na mkiwakopesha watu huku mkitumaini kupata kitu kwao, mwaonyesha fadhili gani? Hata wenye dhambi huwakopesha wenye dhambi, ili warudishiwe vile vile."}, {"r": "Yona 4:2", "t": "Akamwomba Bwana, akasema, Nakuomba, Ee Bwana; sivyo hivyo nilivyosema, hapo nilipokuwa katika nchi yangu? Hii ndiyo sababu nalifanya haraka kukimbilia Tarshishi; kwa maana nalijua ya kuwa wewe u Mungu mwenye neema, umejaa huruma, si mwepesi wa hasira, u mwingi wa rehema, nawe waghairi mabaya."}, {"r": "Nehemia 9:31", "t": "Ila kwa rehema zako nyingi hukuwakomesha kabisa, wala kuwaacha; kwa maana wewe u Mungu mwenye neema, mwenye rehema."}, {"r": "Zaburi 16:2", "t": "Nimemwambia Bwana, Ndiwe Bwana wangu; Sina wema ila utokao kwako."}, {"r": "1 Petro 2:18", "t": "Enyi watumishi, watiini bwana zenu kwa hofu nyingi, sio wao walio wema na wenye upole tu, bali nao walio wakali."}, {"r": "Zaburi 119:149", "t": "Uisikie sauti yangu sawasawa na fadhili zako, Ee Bwana, unihuishe sawasawa na hukumu yako."}, {"r": "1 Wakorintho 13:4", "t": "Upendo huvumilia, hufadhili; upendo hauhusudu; upendo hautakabari; haujivuni;"}, {"r": "Zaburi 119:76", "t": "Nakuomba, fadhili zako ziwe faraja kwangu, Sawasawa na ahadi yako kwa mtumishi wako."}, {"r": "Zaburi 136:10", "t": "Yeye aliyewapiga Wamisri kwa kuwaua wazaliwa wa kwanza wao; Kwa maana fadhili zake ni za milele."}, {"r": "Matendo ya Mitume 28:2", "t": "Wenyeji wakatufanyia fadhili zisizokuwa za kawaida. Kwa maana waliwasha moto, wakatukaribisha sote, kwa sababu ya mvua iliyonyesha na kwa sababu ya baridi."}, {"r": "Zaburi 69:16", "t": "Ee Bwana, unijibu, maana fadhili zako ni njema, Kwa kadiri ya rehema zako unielekee."}, {"r": "Zaburi 59:17", "t": "Ee nguvu zangu, nitakuimbia kwa furaha, Maana Mungu ndiye aliye ngome yangu, Mungu wa fadhili zangu."}, {"r": "Zekaria 10:6", "t": "Nami nitaitia nguvu nyumba ya Yuda, nami nitaiokoa nyumba ya Yusufu, nami nitawarudisha, kwa maana nawaonea rehema; nao watakuwa kana kwamba sikuwatupa; kwa maana mimi ni Bwana, Mungu wao, nami nitawasikia."}, {"r": "Zaburi 136:4", "t": "Yeye peke yake afanya maajabu makuu; Kwa maana fadhili zake ni za milele."}, {"r": "Zaburi 119:17", "t": "Umtendee mtumishi wako ukarimu, Nipate kuishi, nami nitalitii neno lako."}, {"r": "Zaburi 6:2", "t": "Bwana, unifadhili, maana ninanyauka; Bwana, uniponye, mifupa yangu imefadhaika."}, {"r": "Warumi 11:31", "t": "kadhalika na hao wameasi sasa, ili kwa kupata rehema kwenu wao nao wapate rehema."}, {"r": "Zaburi 130:7", "t": "Ee Israeli, umtarajie Bwana; Maana kwa Bwana kuna fadhili, Na kwake kuna ukombozi mwingi."}, {"r": "Zaburi 143:12", "t": "Kwa fadhili zako utawakatilia mbali adui zangu; Na kuwaangamiza wote wanitesao nafsi, Kwa maana mimi ni mtumishi wako."}, {"r": "Isaya 54:10", "t": "Maana milima itaondoka, na vilima vitaondolewa; bali wema wangu hautaondoka kwako, wala agano langu la amani halitaondolewa; asema Bwana akurehemuye."}], "uaminifu": [{"r": "Zaburi 101:6", "t": "Macho yangu yatawaelekea waaminifu katika nchi, Hao wakae nami. Yeye aendaye katika njia kamilifu, Ndiye atakayenitumikia."}, {"r": "Mathayo 25:23", "t": "Bwana wake akamwambia, Vema, mtumwa mwema na mwaminifu; ulikuwa mwaminifu kwa machache, nitakuweka juu ya mengi; ingia katika furaha ya bwana wako."}, {"r": "Mithali 20:6", "t": "Wanadamu hutangaza kila mtu hisani yake mwenyewe; Bali mtu aliye mwaminifu, ni nani awezaye kumpata?"}, {"r": "Mithali 11:3", "t": "Ukamilifu wao wenye haki utawaongoza Bali ukaidi wao wenye fitina utawaangamiza."}, {"r": "1 Wakorintho 15:58", "t": "Basi, ndugu zangu wapendwa, mwimarike, msitikisike, mkazidi sana kutenda kazi ya Bwana sikuzote, kwa kuwa mwajua ya kwamba taabu yenu siyo bure katika Bwana."}, {"r": "Mithali 12:22", "t": "Midomo ya uongo ni chukizo kwa Bwana; Bali watendao uaminifu ndio furaha yake."}, {"r": "Waebrania 10:23", "t": "Na mlishike sana ungamo la tumaini letu, lisigeuke; maana yeye aliyeahidi ni mwaminifu;"}, {"r": "Zaburi 100:5", "t": "Kwa kuwa Bwana ndiye mwema; Rehema zake ni za milele; Na uaminifu wake vizazi na vizazi."}, {"r": "Waebrania 11:11", "t": "Kwa imani hata Sara mwenyewe alipokea uwezo wa kuwa na mimba; alipokuwa amepita wakati wake; kwa kuwa alimhesabu yeye aliyeahidi kuwa mwaminifu."}, {"r": "1 Wathesalonike 5:24", "t": "Yeye ni mwaminifu ambaye awaita, naye atafanya."}, {"r": "Kumbukumbu la Torati 7:9", "t": "Basi jueni ya kuwa Bwana, Mungu wenu, ndiye Mungu; Mungu mwaminifu, ashikaye agano lake na rehema zake kwao wampendao, na kushika amri zake, hata vizazi elfu;"}, {"r": "Zaburi 119:90", "t": "Uaminifu wako upo kizazi baada ya kizazi, Umeiweka nchi, nayo inakaa."}, {"r": "Luka 16:10", "t": "Aliye mwaminifu katika lililo dogo sana, huwa mwaminifu katika lililo kubwa pia; na aliye dhalimu katika lililo dogo, huwa dhalimu katika lililo kubwa pia."}, {"r": "2 Timotheo 2:13", "t": "Kama sisi hatuamini, yeye hudumu wa kuaminiwa. Kwa maana hawezi kujikana mwenyewe."}, {"r": "Ufunuo wa Yohana 2:10", "t": "Usiogope mambo yatakayokupata; tazama, huyo Ibilisi atawatupa baadhi yenu gerezani ili mjaribiwe, nanyi mtakuwa na dhiki siku kumi. Uwe mwaminifu hata kufa, nami nitakupa taji ya uzima."}, {"r": "Zaburi 31:23", "t": "Mpendeni Bwana, Ninyi nyote mlio watauwa wake. Bwana huwahifadhi waaminifu, Humlipa atendaye kiburi malipo tele."}, {"r": "Mathayo 25:21", "t": "Bwana wake akamwambia, Vema, mtumwa mwema na mwaminifu; ulikuwa mwaminifu kwa machache, nitakuweka juu ya mengi; ingia katika furaha ya bwana wako."}, {"r": "Mithali 28:20", "t": "Mtu mwaminifu atakuwa na baraka tele; Lakini afanyaye haraka kuwa tajiri hakosi ataadhibiwa."}, {"r": "Mithali 3:3", "t": "Rehema na kweli zisifarakane nawe; Zifunge shingoni mwako; Ziandike juu ya kibao cha moyo wako."}, {"r": "1 Wakorintho 4:2", "t": "Hapo tena inayohitajiwa katika mawakili, ndiyo mtu aonekane kuwa mwaminifu."}, {"r": "Luka 16:12", "t": "Na kama hamkuwa waaminifu katika mali ya mtu mwingine, ni nani atakayewapa iliyo yenu wenyewe?"}, {"r": "Zaburi 36:5", "t": "Ee Bwana, fadhili zako zafika hata mbinguni, Uaminifu wako hata mawinguni."}, {"r": "Maombolezo 3:23", "t": "Ni mpya kila siku asubuhi; Uaminifu wako ni mkuu."}, {"r": "Maombolezo 3:22", "t": "Ni huruma za Bwana kwamba hatuangamii, Kwa kuwa rehema zake hazikomi."}, {"r": "Zaburi 89:1", "t": "Fadhili za Bwana nitaziimba milele; Kwa kinywa changu nitavijulisha vizazi vyote uaminifu wako."}, {"r": "Zaburi 33:4", "t": "Kwa kuwa neno la Bwana lina adili, Na kazi yake yote huitenda kwa uaminifu."}, {"r": "1 Yohana 1:9", "t": "Tukiziungama dhambi zetu, Yeye ni mwaminifu na wa haki hata atuondolee dhambi zetu, na kutusafisha na udhalimu wote."}, {"r": "Yeremia 42:5", "t": "Wakamwambia Yeremia, Bwana na awe shahidi wa kweli na uaminifu kati yetu; ikiwa hatufanyi sawasawa na neno lile, ambalo Bwana, Mungu wako, atakutuma utuletee."}, {"r": "Zaburi 89:2", "t": "Maana nimesema, Fadhili zitajengwa milele; Katika mbingu utauthibitisha uaminifu wako."}, {"r": "Mika 3:9", "t": "Sikieni haya, tafadhali, enyi vichwa vya nyumba ya Yakobo, mnaoitawala nyumba ya Israeli, mnaochukia hukumu, na kuipotosha adili."}, {"r": "Zaburi 54:5", "t": "Atawarudishia adui zangu ubaya wao; Uwaangamize kwa uaminifu wako."}, {"r": "Zaburi 112:2", "t": "Wazao wake watakuwa hodari duniani; Kizazi cha wenye adili kitabarikiwa."}, {"r": "Zaburi 115:1", "t": "Ee Bwana, kutukuza usitutukuze sisi, Bali ulitukuze jina lako, Kwa ajili ya fadhili zako, Kwa ajili ya uaminifu wako."}, {"r": "2 Timotheo 2:2", "t": "Na mambo yale uliyoyasikia kwangu mbele ya mashahidi wengi, hayo uwakabidhi watu waaminifu watakaofaa kuwafundisha na wengine."}, {"r": "Zaburi 64:10", "t": "Mwenye haki atamfurahia Bwana na kumkimbilia, Na wote wenye moyo wa adili watajisifu."}, {"r": "Mithali 20:28", "t": "Fadhili na uaminifu humhifadhi mfalme, Na kiti chake cha enzi huthibitishwa kwa fadhili."}, {"r": "Zaburi 58:1", "t": "Ni kweli, enyi wakuu, mnanena haki? Enyi wanadamu, mnahukumu kwa adili?"}, {"r": "Luka 11:42", "t": "Lakini, ole wenu, Mafarisayo, kwa kuwa mwatoa zaka za mnanaa na mchicha na kila mboga, na huku mwaacha mambo ya adili, na upendo wa Mungu; iliwapasa kuyafanya hayo ya kwanza, bila kuyaacha hayo ya pili."}, {"r": "Zaburi 92:15", "t": "Watangaze ya kuwa Bwana ni mwenye adili, Mwamba wangu, ndani yake hamna udhalimu."}, {"r": "Yeremia 9:3", "t": "Huupinda ulimi wao, kana kwamba ni upinde, ili kusema uongo; nao wamepata nguvu katika nchi, lakini si katika uaminifu; maana huendelea toka ubaya hata ubaya, wala hawanijui mimi, asema Bwana."}, {"r": "Zaburi 78:37", "t": "Kwa maana mioyo yao haikuwa thabiti kwake, Wala hawakuwa waaminifu katika agano lake."}, {"r": "Tito 2:10", "t": "wasiwe waibaji; bali wauonyeshe uaminifu mwema wote, ili wayapambe mafundisho ya Mwokozi wetu Mungu katika mambo yote."}, {"r": "Zaburi 112:4", "t": "Nuru huwazukia wenye adili gizani; Ana fadhili na huruma na haki."}, {"r": "Zaburi 96:13", "t": "Mbele za Bwana, kwa maana anakuja, Kwa maana anakuja aihukumu nchi. Atauhukumu ulimwengu kwa haki, Na mataifa kwa uaminifu wake."}, {"r": "Hosea 2:20", "t": "Nami nitakuposa kwa uaminifu; nawe utamjua Bwana."}, {"r": "Zaburi 119:138", "t": "Umeziagiza shuhuda zako kwa haki, Na kwa uaminifu mwingi."}, {"r": "Yeremia 23:28", "t": "Nabii aliye na ndoto, na aseme ndoto yake; na yeye aliye na neno langu, na aseme neno langu kwa uaminifu. Makapi ni kitu gani kuliko ngano? Asema Bwana."}, {"r": "Isaya 11:4", "t": "bali kwa haki atawahukumu maskini, naye atawaonya wanyenyekevu wa dunia kwa adili; naye ataipiga dunia kwa fimbo ya kinywa chake, na kwa pumzi ya midomo yake atawaua wabaya."}, {"r": "Isaya 11:5", "t": "Na haki itakuwa mshipi wa viuno vyake, na uaminifu mshipi wa kujifungia."}, {"r": "Isaya 33:15", "t": "Ni yeye aendaye kwa haki, anenaye maneno ya adili; ni yeye anayedharau faida ipatikanayo kwa dhuluma; akung'utaye mikono yake asipokee rushwa; azibaye masikio yake asisikie habari za damu; afumbaye macho yake asitazame uovu."}, {"r": "Zaburi 89:33", "t": "Lakini fadhili zangu sitamwondolea yeye, Wala sitafanya uaminifu wangu kuwa uongo."}, {"r": "Mika 7:2", "t": "Mtu amchaye Mungu ametoweka, asionekane katika nchi, wala hapana mtu mwenye adili katika wanadamu; wote huotea ili kumwaga damu; kila mtu humwinda ndugu yake kwa wavu."}, {"r": "Isaya 45:19", "t": "Sikusema kwa siri, katika mahali pa nchi ya giza; sikuwaambia wazao wa Yakobo; Nitafuteni bure; Mimi, Bwana, nasema haki; nanena mambo ya adili."}, {"r": "Luka 16:11", "t": "Basi, kama ninyi hamkuwa waaminifu katika mali ya udhalimu, ni nani atakayewapa amana mali ya kweli?"}, {"r": "Mithali 2:9", "t": "Ndipo utakapofahamu haki na hukumu, Na adili, na kila njia njema."}, {"r": "Zaburi 92:2", "t": "Kuzitangaza rehema zako asubuhi, Na uaminifu wako wakati wa usiku."}, {"r": "Zaburi 57:10", "t": "Maana fadhili zako ni kubwa hata mbinguni, Na uaminifu wako hata mawinguni."}, {"r": "Zaburi 117:2", "t": "Maana fadhili zake kwetu sisi ni kuu, Na uaminifu wa Bwana ni wa milele."}, {"r": "Zaburi 99:4", "t": "Nguvu za mfalme nazo zapenda hukumu; Wewe ndiwe uliyeithibitisha adili; Ulifanya hukumu na haki katika Yakobo."}, {"r": "Zaburi 96:10", "t": "Semeni katika mataifa, Bwana ametamalaki; Naam, ulimwengu umethibitika usitikisike, Atawahukumu watu kwa adili."}, {"r": "Zaburi 119:75", "t": "Najua ya kuwa hukumu zako ni za haki, Ee Bwana, na kwa uaminifu umenitesa."}, {"r": "Mithali 29:14", "t": "Mfalme awahukumuye maskini kwa uaminifu; Kiti chake cha enzi kitathibitika milele."}, {"r": "Zaburi 19:8", "t": "Maagizo ya Bwana ni ya adili, Huufurahisha moyo. Amri ya Bwana ni safi, Huyatia macho nuru."}, {"r": "Zaburi 111:8", "t": "Yamethibitika milele na milele, Yamefanywa katika kweli na adili."}, {"r": "Zaburi 98:9", "t": "Mbele za Bwana; Kwa maana anakuja aihukumu nchi. Atauhukumu ulimwengu kwa haki, Na mataifa kwa adili."}, {"r": "Mithali 8:6", "t": "Sikieni, maana nitasema yaliyo mazuri, Na kufumbua midomo yangu kutakuwa maadili."}, {"r": "Wakolosai 4:1", "t": "Ninyi akina bwana, wapeni watumwa wenu yaliyo haki na ya adili, mkijua ya kuwa ninyi nanyi mna Bwana mbinguni."}, {"r": "Zaburi 89:24", "t": "Uaminifu wangu na fadhili zangu atakuwa nazo, Na kwa jina langu pembe yake itatukuka."}, {"r": "Zaburi 145:18", "t": "Bwana yu karibu na wote wamwitao, Wote wamwitao kwa uaminifu."}, {"r": "Mithali 11:13", "t": "Mwenye kitango akisingizia hufunua siri; Bali mwenye roho ya uaminifu husitiri mambo."}, {"r": "Zaburi 37:3", "t": "Umtumaini Bwana ukatende mema, Ukae katika nchi, upendezwe na uaminifu."}, {"r": "Zaburi 119:137", "t": "Ee Bwana, Wewe ndiwe mwenye haki, Na hukumu zako ni za adili."}, {"r": "Zaburi 140:13", "t": "Hakika wenye haki watalishukuru jina lako, Wenye adili watakaa mahali ulipo Wewe."}, {"r": "Zaburi 91:4", "t": "Kwa manyoya yake atakufunika, Chini ya mbawa zake utapata kimbilio; Uaminifu wake ni ngao na kigao."}, {"r": "Zaburi 36:10", "t": "Uwadumishie wakujuao fadhili zako, Na wanyofu wa moyo uaminifu wako."}, {"r": "Zaburi 119:128", "t": "Maana nayaona mausia yako yote kuwa ya adili, Kila njia ya uongo naichukia."}, {"r": "Mithali 21:18", "t": "Mtu asiye haki ni fidia ya wenye haki; Naye afanyaye hila ni badala ya watu wa adili."}, {"r": "Zaburi 9:8", "t": "Naye atauhukumu ulimwengu kwa haki; Atawaamua watu kwa adili."}, {"r": "Zaburi 138:2", "t": "Nitasujudu nikilikabili hekalu lako takatifu, Nitalishukuru jina lako, Kwa ajili ya fadhili zako na uaminifu wako, Kwa maana umeikuza ahadi yako, Kuliko jina lako lote."}, {"r": "Zaburi 108:4", "t": "Maana fadhili zako ni kubwa hata mbinguni, Na uaminifu wako hata mawinguni."}, {"r": "Mathayo 23:23", "t": "Ole wenu waandishi na Mafarisayo, wanafiki! Kwa kuwa mnalipa zaka za mnanaa na bizari na jira, lakini mmeacha mambo makuu ya sheria, yaani, adili, na rehema, na imani; hayo imewapasa kuyafanya, wala yale mengine msiyaache."}, {"r": "Mithali 1:3", "t": "kufundishwa matendo ya busara, katika haki na hukumu na adili."}, {"r": "Mithali 20:11", "t": "Hata mtoto hujijulisha kwa matendo yake; Kwamba kazi yake ni safi, kwamba ni adili."}, {"r": "Zaburi 89:49", "t": "Bwana, zi wapi fadhili zako za kwanza, Ulizomwapia Daudi kwa uaminifu wako?"}, {"r": "1 Timotheo 3:11", "t": "Vivyo hivyo wake zao na wawe wastahivu; si wasingiziaji; watu wa kiasi, waaminifu katika mambo yote."}, {"r": "2 Mambo ya Nyakati 31:20", "t": "Na hivyo ndivyo alivyofanya Hezekia katika Yuda yote; akatenda yaliyo mema, na ya adili, na uaminifu, mbele za Bwana, Mungu wake."}, {"r": "Isaya 25:1", "t": "Ee Bwana, wewe u Mungu wangu; Nitakutukuza na kulihimidi jina lako; Kwa kuwa umetenda mambo ya ajabu, Mashauri ya kale, kwa uaminifu na kweli."}, {"r": "Zaburi 45:6", "t": "Kiti chako cha enzi, Mungu, ni cha milele na milele, Fimbo ya ufalme wako ni fimbo ya adili."}, {"r": "Yeremia 5:1", "t": "Pigeni mbio huku na huku katika njia za Yerusalemu, mkaone sasa, na kujua, na kutafuta katika viwanja vyake, kwamba mwaweza kumpata mtu mmoja, kwamba yuko mtu mmoja awaye yote atendaye kwa haki, atafutaye uaminifu; nami nitausamehe mji huo."}, {"r": "Zaburi 17:2", "t": "Hukumu yangu na itoke kwako, Macho yako na yatazame mambo ya adili."}, {"r": "Mithali 12:5", "t": "Mawazo ya mwenye haki ni adili; Bali mashauri ya mtu mwovu ni hadaa."}, {"r": "Yeremia 7:28", "t": "Nawe utawaambia, Taifa hili ndilo lisilosikiliza sauti ya Bwana, Mungu wao, wala kupokea mafundisho; uaminifu umepotea, umekatiliwa mbali na vinywa vyao."}, {"r": "Zaburi 25:8", "t": "Bwana yu mwema, mwenye adili, Kwa hiyo atawafundisha wenye dhambi njia."}, {"r": "Yeremia 5:3", "t": "Ee Bwana, macho yako je! Hayaangalii uaminifu? Umewapiga, lakini hawakuhuzunika; umewakomesha, lakini wamekataa kurudiwa wamefanya nyuso zao kuwa ngumu kuliko mwamba wamekataa kurudi."}, {"r": "Zaburi 12:1", "t": "Bwana, uokoe, maana mcha Mungu amekoma, Maana waaminifu wametoweka katika wanadamu."}, {"r": "Zaburi 119:30", "t": "Nimeichagua njia ya uaminifu, Na kuziweka hukumu zako mbele yangu."}, {"r": "Zaburi 40:10", "t": "Sikusitiri haki yako moyoni mwangu; Nimetangaza uaminifu wako na wokovu wako. Sikuficha fadhili zako wala kweli yako Katika kusanyiko kubwa."}, {"r": "Zaburi 5:9", "t": "Maana vinywani mwao hamna uaminifu; Mtima wao ni shimo tupu, koo lao ni kaburi wazi, Ulimi wao hujipendekeza."}, {"r": "Isaya 8:2", "t": "nami nitajipatia mashahidi waaminifu ili kuandika habari, yaani, Uria, kuhani, na Zekaria, mwana wa Yeberekia."}, {"r": "Zaburi 89:8", "t": "Bwana, Mungu wa majeshi, Ni nani aliye hodari kama Wewe, Ee YAHU? Na uaminifu wako unakuzunguka."}, {"r": "Wakolosai 1:2", "t": "kwa ndugu watakatifu, waaminifu katika Kristo, walioko Kolosai. Neema na iwe kwenu, na amani, zitokazo kwa Mungu Baba yetu."}, {"r": "Zaburi 88:11", "t": "Fadhili zako zitasimuliwa kaburini? Au uaminifu wako katika uharibifu?"}, {"r": "Warumi 3:3", "t": "Ni nini, basi, ikiwa baadhi yao hawakuamini? Je! Kutokuamini kwao kutaubatili uaminifu wa Mungu?"}, {"r": "Kumbukumbu la Torati 32:4", "t": "Yeye Mwamba, kazi yake ni kamilifu; Maana, njia zake zote ni haki. Mungu wa uaminifu, asiye na uovu, Yeye ndiye mwenye haki na adili."}, {"r": "Amosi 5:10", "t": "Wao humchukia yeye akemeaye langoni, nao humzira anenaye maneno ya adili."}, {"r": "Mika 7:4", "t": "Mtu aliye mwema miongoni mwao ni kama mbigili; mtu aliye mwenye adili miongoni mwao ni mbaya kuliko boma la michongoma; hiyo siku ya walinzi wako, yaani, siku ya kujiliwa kwako, imefika; sasa kutatokea kufadhaika kwao."}, {"r": "Zaburi 98:3", "t": "Amezikumbuka rehema zake, Na uaminifu wake kwa nyumba ya Israeli. Miisho yote ya dunia imeuona Wokovu wa Mungu wetu."}, {"r": "Zaburi 143:1", "t": "Ee Bwana, uisikie sala yangu, uzisikilize dua zangu, Kwa uaminifu wako unijibu kwa haki yako."}], "upole": [{"r": "Hesabu 12:3", "t": "Basi huyo mtu, huyo Musa, alikuwa mpole sana zaidi ya wanadamu wote waliokuwa juu ya uso wa nchi."}, {"r": "Mathayo 21:5", "t": "Mwambieni binti Sayuni Tazama, mfalme wako anakuja kwako, Mpole, naye amepanda punda, Na mwanapunda, mtoto wa punda."}, {"r": "Wafilipi 4:5", "t": "Upole wenu na ujulikane na watu wote. Bwana yu karibu."}, {"r": "Wakolosai 3:12", "t": "Basi, kwa kuwa mmekuwa wateule wa Mungu, watakatifu wapendwao, jivikeni moyo wa rehema, utu wema, unyenyekevu, upole, uvumilivu,"}, {"r": "Waefeso 4:2", "t": "kwa unyenyekevu wote na upole, kwa uvumilivu, mkichukuliana katika upendo;"}, {"r": "Mathayo 5:5", "t": "Heri wenye upole; Maana hao watairithi nchi."}, {"r": "Wagalatia 6:1", "t": "Ndugu zangu, mtu akighafilika katika kosa lo lote, ninyi mlio wa Roho mrejezeni upya mtu kama huyo kwa roho ya upole, ukijiangalia nafsi yako usije ukajaribiwa wewe mwenyewe."}, {"r": "1 Timotheo 6:11", "t": "Bali wewe, mtu wa Mungu, uyakimbie mambo hayo; ukafuate haki, utauwa, imani, upendo, saburi, upole."}, {"r": "Mathayo 11:29", "t": "Jitieni nira yangu, mjifunze kwangu; kwa kuwa mimi ni mpole na mnyenyekevu wa moyo; nanyi mtapata raha nafsini mwenu;"}, {"r": "Yakobo 1:21", "t": "Kwa hiyo wekeeni mbali uchafu wote na ubaya uzidio, na kupokea kwa upole neno lile lililopandwa ndani, liwezalo kuziokoa roho zenu."}, {"r": "Mithali 25:15", "t": "Kwa uvumilivu mwingi mkuu husadikishwa; Na ulimi laini huvunja mfupa."}, {"r": "Zaburi 25:9", "t": "Wenye upole atawaongoza katika hukumu, Wenye upole atawafundisha njia yake."}, {"r": "1 Petro 3:15", "t": "Mwe tayari siku zote kumjibu kila mtu awaulizaye habari za tumaini lililo ndani yenu; lakini kwa upole na kwa hofu."}, {"r": "2 Timotheo 2:25", "t": "akiwaonya kwa upole wao washindanao naye, ili kama ikiwezekana, Mungu awape kutubu na kuijua kweli;"}, {"r": "Wagalatia 5:23", "t": "upole, kiasi; juu ya mambo kama hayo hakuna sheria."}, {"r": "Sefania 2:3", "t": "Mtafuteni Bwana, enyi nyote mlio wanyenyekevu wa dunia, ninyi mliozitenda hukumu zake; itafuteni haki, utafuteni unyenyekevu; huenda mtafichwa katika siku ya hasira ya Bwana."}, {"r": "Mithali 15:1", "t": "Jawabu la upole hugeuza hasira; Bali neno liumizalo huchochea ghadhabu."}, {"r": "Tito 3:2", "t": "wasimtukane mtu ye yote, wasiwe wagomvi, wawe wema, wakionyesha upole wote kwa watu wote."}, {"r": "Yakobo 3:17", "t": "Lakini hekima itokayo juu, kwanza ni safi, tena ni ya amani, ya upole, tayari kusikiliza maneno ya watu, imejaa rehema na matunda mema, haina fitina, haina unafiki."}, {"r": "Zaburi 37:11", "t": "Bali wenye upole watairithi nchi, Watajifurahisha kwa wingi wa amani."}, {"r": "Zaburi 149:4", "t": "Kwa kuwa Bwana awaridhia watu wake, Huwapamba wenye upole kwa wokovu."}, {"r": "1 Petro 3:4", "t": "bali kuwe utu wa moyoni usioonekana, katika mapambo yasiyoharibika; yaani, roho ya upole na utulivu, iliyo ya thamani kuu mbele za Mungu."}, {"r": "2 Wakorintho 10:1", "t": "Basi, mimi Paulo mwenyewe nawasihi kwa upole na utaratibu wa Kristo; mimi niliye mnyenyekevu nikiwapo pamoja nanyi, bali nisipokuwapo ni mwenye ujasiri kwenu;"}, {"r": "Zaburi 81:15", "t": "Wamchukiao Bwana wangenyenyekea mbele zake, Bali wakati wao ungedumu milele."}, {"r": "Wakolosai 2:23", "t": "Mambo hayo yanaonekana kana kwamba yana hekima, katika namna ya ibada mliyojitungia wenyewe, na katika kunyenyekea, na katika kuutawala mwili kwa ukali; lakini hayafai kitu kwa kuzizuia tamaa za mwili."}, {"r": "Mika 6:8", "t": "Ee mwanadamu, yeye amekuonyesha yaliyo mema; na Bwana anataka nini kwako, ila kutenda haki, na kupenda rehema, na kwenda kwa unyenyekevu na Mungu wako!"}, {"r": "Yakobo 3:13", "t": "N'nani aliye na hekima na ufahamu kwenu? Na aonyeshe kazi zake kwa mwenendo wake mzuri, katika upole wa hekima."}, {"r": "Zaburi 113:6", "t": "Anyenyekeaye kutazama, Mbinguni na duniani?"}, {"r": "Ayubu 15:11", "t": "Je! Utulizi wa Mungu ni mdogo sana kwako, Na hilo neno la upole si kitu kwako?"}, {"r": "1 Petro 5:5", "t": "Vivyo hivyo ninyi vijana, watiini wazee. Naam, ninyi nyote jifungeni unyenyekevu, mpate kuhudumiana; kwa sababu Mungu huwapinga wenye kiburi, lakini huwapa wanyenyekevu neema."}, {"r": "Isaya 40:11", "t": "Atalilisha kundi lake kama mchungaji, Atawakusanya wanakondoo mikononi mwake; Na kuwachukua kifuani mwake, Nao wanyonyeshao atawaongoza polepole."}, {"r": "Mithali 29:23", "t": "Kiburi cha mtu kitamshusha; Bali mwenye roho ya unyenyekevu ataheshimiwa."}, {"r": "Zaburi 76:9", "t": "Mungu aliposimama ili kuhukumu Na kuwaokoa wapole wa dunia wote pia."}, {"r": "Zaburi 22:26", "t": "Wapole watakula na kushiba, Wamtafutao Bwana watamsifu; Mioyo yenu na iishi milele."}, {"r": "Mithali 11:2", "t": "Kijapo kiburi ndipo ijapo aibu; Bali hekima hukaa na wanyenyekevu."}, {"r": "Zaburi 66:3", "t": "Mwambieni Mungu, Matendo yako yatisha kama nini! Kwa ajili ya wingi wa nguvu zako, Adui zako watakuja kunyenyekea mbele zako."}, {"r": "Waebrania 13:17", "t": "Watiini wenye kuwaongoza, na kuwanyenyekea; maana wao wanakesha kwa ajili ya roho zenu, kama watu watakaotoa hesabu, ili kwamba wafanye hivyo kwa furaha wala si kwa kuugua; maana isingewafaa ninyi."}, {"r": "Isaya 61:1", "t": "Roho ya Bwana MUNGU i juu yangu; kwa sababu Bwana amenitia mafuta niwahubiri wanyenyekevu habari njema; amenituma ili kuwaganga waliovunjika moyo, kuwatangazia mateka uhuru wao, na hao waliofungwa habari za kufunguliwa kwao."}, {"r": "Yeremia 11:19", "t": "Lakini mimi nalikuwa kama mwanakondoo mpole, achukuliwaye kwenda kuchinjwa; wala sikujua ya kuwa wamefanya mashauri kinyume changu, wakisema, Na tuuharibu mti pamoja na matunda yake, na tumkatilie mbali atoke katika nchi ya walio hai, ili jina lake lisikumbukwe tena."}, {"r": "1 Petro 3:8", "t": "Neno la mwisho ni hili; mwe na nia moja, wenye kuhurumiana, wenye kupendana kama ndugu, wasikitikivu, wanyenyekevu;"}, {"r": "Waebrania 12:28", "t": "Basi kwa kuwa tunapokea ufalme usioweza kutetemeshwa, na mwe na neema, ambayo kwa hiyo tumtolee Mungu ibada ya kumpendeza, pamoja na unyenyekevu na kicho;"}, {"r": "Isaya 38:15", "t": "Niseme nini? Yeye amenena nami, na yeye mwenyewe ametenda hayo; Nitakwenda polepole miaka yangu yote, kwa sababu ya uchungu wa nafsi yangu."}, {"r": "Zaburi 45:4", "t": "Katika fahari yako usitawi uendelee Kwa ajili ya kweli na upole na haki Na mkono wako wa kuume Utakufundisha mambo ya kutisha."}, {"r": "Zaburi 108:6", "t": "Ili wapenzi wako waopolewe, Uokoe kwa mkono wako wa kuume, uniitikie."}, {"r": "2 Wakorintho 11:7", "t": "Je! Nalifanya dhambi kwa kunyenyekea ili ninyi mtukuzwe, kwa sababu naliwahubiri Injili ya Mungu bila ujira?"}, {"r": "Wakolosai 2:18", "t": "Mtu asiwanyang'anye thawabu yenu, kwa kunyenyekea kwa mapenzi yake mwenyewe tu, na kuabudu malaika, akijitia katika maono yake na kujivuna bure, kwa akili zake za kimwili;"}, {"r": "Mathayo 10:16", "t": "Angalieni, mimi nawatuma kama kondoo kati ya mbwamwitu; basi iweni na busara kama nyoka, na kuwa watu wapole kama hua."}, {"r": "Waefeso 5:21", "t": "hali mnanyenyekeana katika kicho cha Kristo."}, {"r": "2 Petro 2:5", "t": "wala hakuuachilia ulimwengu wa kale, bali alimhifadhi Nuhu, mjumbe wa haki, na watu wengine saba, hapo alipoleta Gharika juu ya ulimwengu wa wasiomcha Mungu;"}, {"r": "1 Timotheo 3:3", "t": "si mtu wa kuzoelea ulevi, si mpiga watu; bali awe mpole; si mtu wa kujadiliana, wala asiwe mwenye kupenda fedha;"}, {"r": "Yakobo 4:6", "t": "Lakini hutujalia sisi neema iliyozidi; kwa hiyo husema, Mungu huwapinga wajikuzao, bali huwapa neema wanyenyekevu."}, {"r": "Amosi 2:7", "t": "nao hutwetea mavumbi yaliyo juu ya vichwa vya maskini, na kuipotosha njia ya mwenye upole; na mtu na baba yake humwendea mwanamke mmoja, hata kulitia unajisi jina langu takatifu;"}, {"r": "Zaburi 60:5", "t": "Ili wapenzi wako waopolewe, Uokoe kwa mkono wako wa kuume, utuitikie."}, {"r": "Matendo ya Mitume 27:7", "t": "Tukasafiri polepole kwa muda wa siku nyingi, tukafika mpaka Nido kwa shida; na kwa sababu upepo ulikuwa ukituzuia tukapita chini ya Krete, tukaikabili Salmone."}, {"r": "Tito 3:1", "t": "Uwakumbushe watu kunyenyekea kwa wenye uwezo na mamlaka, na kutii, na kuwa tayari kwa kila kazi njema;"}, {"r": "Isaya 57:15", "t": "Maana yeye aliye juu, aliyetukuka, akaaye milele; ambaye jina lake ni Mtakatifu; asema hivi; Nakaa mimi mahali palipoinuka, palipo patakatifu; tena pamoja na yeye aliye na roho iliyotubu na kunyenyekea, ili kuzifufua roho za wanyenyekevu, na kuifufua mioyo yao waliotubu."}, {"r": "Mithali 16:19", "t": "Afadhali kuwa na roho ya unyenyekevu pamoja na maskini, Kuliko kugawanya nyara pamoja na wenye kiburi."}, {"r": "Isaya 11:4", "t": "bali kwa haki atawahukumu maskini, naye atawaonya wanyenyekevu wa dunia kwa adili; naye ataipiga dunia kwa fimbo ya kinywa chake, na kwa pumzi ya midomo yake atawaua wabaya."}, {"r": "Wafilipi 2:3", "t": "Msitende neno lo lote kwa kushindana wala kwa majivuno; bali kwa unyenyekevu, kila mtu na amhesabu mwenziwe kuwa bora kuliko nafsi yake."}, {"r": "Ayubu 41:3", "t": "Je! Atakusihi sana? Au, atakuambia maneno ya upole?"}, {"r": "Zaburi 18:35", "t": "Nawe umenipa ngao ya wokovu wako, Mkono wako wa kuume umenitegemeza, Na unyenyekevu wako umenikuza."}, {"r": "Isaya 29:19", "t": "Wanyenyekevu nao wataongeza furaha yao katika Bwana, na maskini katika wanadamu watafurahi katika Mtakatifu wa Israeli."}, {"r": "Mithali 18:12", "t": "Kabla ya uharibifu moyo wa mwanadamu hujivuna; Na kabla ya heshima hutangulia unyenyekevu."}, {"r": "Mithali 15:33", "t": "Kumcha Bwana ni maonyo ya hekima; Na kabla ya heshima hutangulia unyenyekevu."}, {"r": "Mithali 22:4", "t": "Thawabu ya unyenyekevu ambao ni kumcha Bwana Ni utajiri, na heshima, nayo ni uzima."}, {"r": "Isaya 53:7", "t": "Alionewa, lakini alinyenyekea, Wala hakufunua kinywa chake; Kama mwanakondoo apelekwaye machinjoni, Na kama vile kondoo anyamazavyo Mbele yao wakatao manyoya yake; Naam, hakufunua kinywa chake."}, {"r": "1 Wathesalonike 2:7", "t": "bali tulikuwa wapole katikati yenu, kama vile mlezi awatunzavyo watoto wake mwenyewe."}, {"r": "Luka 4:16", "t": "Akaenda Nazareti, hapo alipolelewa; na siku ya sabato akaingia katika sinagogi kama ilivyokuwa desturi yake, akasimama ili asome."}, {"r": "1 Wakorintho 4:21", "t": "Mnataka vipi? Nije kwenu na fimbo, au nije katika upendo na roho ya upole?"}, {"r": "Yeremia 18:22", "t": "Kilio na kisikiwe kitokacho katika nyumba zao, hapo utakapoleta kikosi juu yao kwa ghafula; kwa maana wamenichimbia shimo waninase, nao wameifichia miguu yangu mitego."}, {"r": "Zaburi 147:6", "t": "Bwana huwategemeza wenye upole, Huwaangusha chini wenye jeuri."}, {"r": "Zaburi 18:44", "t": "Kwa kusikia tu habari zangu, Mara wakanitii. Wageni walinijia wakinyenyekea."}, {"r": "2 Petro 1:17", "t": "Maana alipata kwa Mungu Baba heshima na utukufu, hapo alipoletewa sauti iliyotoka katika utukufu mkuu, Huyu ni Mwanangu, mpendwa wangu, ninayependezwa naye."}, {"r": "Yeremia 44:10", "t": "Hawajanyenyekea hata leo, wala hawakuogopa, wala hawakuenenda katika sheria yangu, wala katika amri zangu, nilizoweka mbele yenu, na mbele ya baba zenu."}, {"r": "Matendo ya Mitume 20:19", "t": "nikimtumikia Bwana kwa unyenyekevu wote, na kwa machozi, na majaribu yaliyonipata kwa hila za Wayahudi;"}, {"r": "Hosea 9:12", "t": "Wajapolea watoto wao, mimi nitawanyang'anya watoto wao, asisalie hata mtu mmoja; naam, ole wao! Nitakapoondoka na kuwaacha."}, {"r": "Waebrania 5:2", "t": "awezaye kuwachukulia kwa upole wao wasiojua na wenye kupotea, kwa kuwa yeye mwenyewe yu katika hali ya udhaifu;"}, {"r": "1 Petro 2:18", "t": "Enyi watumishi, watiini bwana zenu kwa hofu nyingi, sio wao walio wema na wenye upole tu, bali nao walio wakali."}, {"r": "Mithali 3:34", "t": "Hakika yake huwadharau wenye dharau, Bali huwapa wanyenyekevu neema."}], "kiasi": [{"r": "Mithali 21:23", "t": "Mtu azuiaye kinywa chake na ulimi wake, Atajilinda nafsi yake na taabu."}, {"r": "Tito 1:8", "t": "bali awe mkaribishaji, mpenda wema, mwenye kiasi, mwenye haki, mtakatifu, mwenye kudhibiti nafsi yake;"}, {"r": "Zaburi 141:3", "t": "Ee Bwana, uweke mlinzi kinywani pangu, Mngojezi mlangoni pa midomo yangu."}, {"r": "Tito 2:2", "t": "ya kwamba wazee wawe wenye kiasi, wastahivu, wenye busara, wazima katika imani na katika upendo na katika saburi."}, {"r": "Mithali 13:3", "t": "Yeye alindaye kinywa chake huilinda nafsi yake; Bali afunuaye midomo yake atapata uharibifu."}, {"r": "1 Petro 4:7", "t": "Lakini mwisho wa mambo yote umekaribia; basi, iweni na akili, mkeshe katika sala."}, {"r": "Yakobo 1:19", "t": "Hayo mnajua, ndugu zangu wapenzi. Basi kila mtu na awe mwepesi wa kusikia, bali si mwepesi wa kusema; wala kukasirika;"}, {"r": "Mithali 25:16", "t": "Je! Umeona asali? Kula kadiri ya kukutosha; Usije ukashiba na kuitapika."}, {"r": "Warumi 13:14", "t": "Bali mvaeni Bwana Yesu Kristo, wala msiuangalie mwili, hata kuwasha tamaa zake."}, {"r": "Mithali 25:28", "t": "Asiyetawala roho yake Ni mfano wa mji uliobomolewa, usio na kuta."}, {"r": "1 Wathesalonike 5:6", "t": "Basi tusilale usingizi kama wengine, bali tukeshe, na kuwa na kiasi."}, {"r": "2 Timotheo 1:7", "t": "Maana Mungu hakutupa roho ya woga, bali ya nguvu na ya upendo na ya moyo wa kiasi."}, {"r": "Wafilipi 4:5", "t": "Upole wenu na ujulikane na watu wote. Bwana yu karibu."}, {"r": "Warumi 12:3", "t": "Kwa maana kwa neema niliyopewa namwambia kila mtu aliyeko kwenu asinie makuu kupita ilivyompasa kunia; bali awe na nia ya kiasi, kama Mungu alivyomgawia kila mtu kiasi cha imani."}, {"r": "Mithali 29:11", "t": "Mpumbavu hudhihirisha hasira yake yote; Bali mwenye hekima huizuia na kuituliza."}, {"r": "Yakobo 3:2", "t": "Maana twajikwaa sisi sote pia katika mambo mengi. Mtu asiyejikwaa katika kunena, huyo ni mtu mkamilifu, awezaye kuuzuia na mwili wake wote kama kwa lijamu."}, {"r": "Wakolosai 4:6", "t": "Maneno yenu yawe na neema siku zote, yakikolea munyu, mpate kujua jinsi iwapasavyo kumjibu kila mtu."}, {"r": "1 Wakorintho 9:27", "t": "bali nautesa mwili wangu na kuutumikisha; isiwe, nikiisha kuwahubiri wengine, mwenyewe niwe mtu wa kukataliwa."}, {"r": "1 Wakorintho 10:13", "t": "Jaribu halikuwapata ninyi, isipokuwa lililo kawaida ya wanadamu; ila Mungu ni mwaminifu; ambaye hatawaacha mjaribiwe kupita mwezavyo; lakini pamoja na lile jaribu atafanya na mlango wa kutokea, ili mweze kustahimili."}, {"r": "1 Wakorintho 6:12", "t": "Vitu vyote ni halali kwangu, lakini si vyote vifaavyo; vitu vyote ni halali kwangu, lakini mimi sitatiwa chini ya uwezo wa kitu cho chote."}, {"r": "Waefeso 5:18", "t": "Tena msilewe kwa mvinyo, ambamo mna ufisadi; bali mjazwe Roho;"}, {"r": "Tito 2:12", "t": "nayo yatufundisha kukataa ubaya na tamaa za kidunia; tupate kuishi kwa kiasi, na haki, na utauwa, katika ulimwengu huu wa sasa;"}, {"r": "Wagalatia 5:23", "t": "upole, kiasi; juu ya mambo kama hayo hakuna sheria."}, {"r": "Tito 2:11", "t": "Maana neema ya Mungu iwaokoayo wanadamu wote imefunuliwa;"}, {"r": "1 Petro 1:13", "t": "Kwa hiyo vifungeni viuno vya nia zenu, na kuwa na kiasi; mkiitumainia kwa utimilifu ile neema mtakayoletewa katika ufunuo wake Yesu Kristo."}, {"r": "Mithali 16:32", "t": "Asiye mwepesi wa hasira ni mwema kuliko shujaa; Na mtu aitawalaye roho yake kuliko mtu atekaye mji."}, {"r": "2 Petro 1:6", "t": "na katika maarifa yenu kiasi, na katika kiasi chenu saburi, na katika saburi yenu utauwa,"}, {"r": "1 Wathesalonike 5:8", "t": "Lakini sisi tulio wa mchana, tuwe na kiasi, hali tukijivika kifuani imani na upendo, na chapeo yetu iwe tumaini la wokovu."}, {"r": "1 Petro 5:8", "t": "Mwe na kiasi na kukesha; kwa kuwa mshitaki wenu Ibilisi, kama simba angurumaye, huzungukazunguka, akitafuta mtu ammeze."}, {"r": "1 Wakorintho 9:25", "t": "Na kila ashindanaye katika michezo hujizuia katika yote; basi hao hufanya hivyo kusudi wapokee taji iharibikayo; bali sisi tupokee taji isiyoharibika."}, {"r": "Mithali 17:27", "t": "Azuiaye maneno yake ni mwenye maarifa; Na mwenye roho ya utulivu ana busara."}, {"r": "Ayubu 33:19", "t": "Yeye hutiwa adabu kwa maumivu kitandani mwake, Na kwa mashindano yaendeleayo daima mifupani mwake;"}, {"r": "Mhubiri 1:17", "t": "Nikatia moyo wangu ili kuijua hekima, na kujua wazimu na upumbavu; nikatambua ya kwamba hayo yote nayo ni kujilisha upepo."}, {"r": "Mithali 23:15", "t": "Mwanangu, kama moyo wako una hekima, Moyo wangu utafurahi, naam, moyo wangu;"}, {"r": "Mithali 15:12", "t": "Mwenye mzaha hapendi kukaripiwa; Wala yeye hawaendei wenye hekima."}, {"r": "Yeremia 51:57", "t": "Nami nitawalevya wakuu wake, na watu wake wenye hekima, maliwali wake, na maakida wake, na mashujaa wake; nao watalala usingizi wa milele, wasiamke, asema Mfalme, Bwana wa majeshi, ambaye jina lake ni Bwana."}, {"r": "Yakobo 3:17", "t": "Lakini hekima itokayo juu, kwanza ni safi, tena ni ya amani, ya upole, tayari kusikiliza maneno ya watu, imejaa rehema na matunda mema, haina fitina, haina unafiki."}, {"r": "Mhubiri 1:13", "t": "Nikatia moyo wangu ili kuyatafuta yote yanayotendeka chini ya mbingu, na kuyavumbua kwa hekima; ni taabu kubwa ambayo Mungu amewapa wanadamu, ili kutaabika ndani yake."}, {"r": "Ayubu 12:12", "t": "Wazee ndio walio na hekima, Na katika kuishi siku nyingi iko fahamu."}, {"r": "Matendo ya Mitume 7:22", "t": "Musa akafundishwa hekima yote ya Wamisri, akawa hodari wa maneno na matendo."}, {"r": "Ayubu 34:2", "t": "Sikilizeni maneno yangu, enyi wenye hekima; Tegeni masikio kwangu, ninyi mlio na maarifa."}, {"r": "Mhubiri 10:10", "t": "Iwapo chuma hakipati, wala mtu hakinoi; Ndipo hana budi kutumia nguvu zaidi. Walakini yafaa kutumia hekima, na kufanikiwa."}, {"r": "Waefeso 1:8", "t": "Naye alituzidishia hiyo katika hekima yote na ujuzi;"}, {"r": "Marko 7:37", "t": "wakashangaa mno kupita kiasi, wakinena, Ametenda mambo yote vema; viziwi awafanya wasikie, na bubu waseme."}, {"r": "Yeremia 17:10", "t": "Mimi, Bwana, nauchunguza moyo, navijaribu viuno, hata kumpa kila mtu kiasi cha njia zake, kiasi cha matunda ya matendo yake."}, {"r": "Ayubu 26:3", "t": "Jinsi ulivyomshauri huyo asiye na hekima! Na kutangaza ujuzi wa kweli kwa wingi!"}, {"r": "Wakolosai 2:3", "t": "ambaye ndani yake yeye hazina zote za hekima na maarifa zimesitirika."}, {"r": "Mithali 31:26", "t": "Hufumbua kinywa chake kwa hekima, Na sheria ya wema i katika ulimi wake."}, {"r": "2 Wakorintho 2:7", "t": "hata kinyume cha hayo, ni afadhali mmsamehe na kumfariji, mtu kama huyo asije akamezwa katika huzuni yake ipitayo kiasi."}, {"r": "Mithali 15:33", "t": "Kumcha Bwana ni maonyo ya hekima; Na kabla ya heshima hutangulia unyenyekevu."}, {"r": "Mithali 22:3", "t": "Mwenye busara huyaona mabaya na kujificha; Bali wajinga huendelea mbele wakaumia."}, {"r": "Isaya 11:2", "t": "Na roho ya Bwana atakaa juu yake, roho ya hekima na ufahamu, roho ya shauri na uweza, roho ya maarifa na ya kumcha Bwana;"}, {"r": "Mithali 9:12", "t": "Kama una hekima, una hekima kwa nafsi yako; Na kama una dharau, utaichukua peke yako."}, {"r": "1 Wakorintho 12:8", "t": "Maana mtu mmoja kwa Roho apewa neno la hekima; na mwingine neno la maarifa, apendavyo Roho yeye yule;"}, {"r": "2 Wakorintho 1:12", "t": "Kwa maana kujisifu kwetu ni huku, ushuhuda wa dhamiri yetu, ya kwamba kwa utakatifu na weupe wa moyo utokao kwa Mungu; si kwa hekima ya mwili, bali kwa neema ya Mungu; tulienenda katika dunia, na hasa kwenu ninyi."}, {"r": "Mithali 1:3", "t": "kufundishwa matendo ya busara, katika haki na hukumu na adili."}, {"r": "Mithali 1:5", "t": "mwenye hekima asikie na kuongezewa elimu, na mwenye ufahamu ayafikie mashauri yenye njia."}, {"r": "Warumi 11:33", "t": "Jinsi zilivyo kuu utajiri na hekima na maarifa ya Mungu! Hukumu zake hazichunguziki, wala njia zake hazitafutikani!"}, {"r": "Wakolosai 1:28", "t": "ambaye sisi tunamhubiri habari zake tukimwonya kila mtu, na kumfundisha kila mtu katika hekima yote, tupate kumleta kila mtu mtimilifu katika Kristo."}, {"r": "Zaburi 19:7", "t": "Sheria ya Bwana ni kamilifu, Huiburudisha nafsi. Ushuhuda wa Bwana ni amini, Humtia mjinga hekima."}, {"r": "Mithali 20:1", "t": "Mvinyo hudhihaki, kileo huleta ugomvi; Na akosaye kwa vitu hivyo hana hekima."}, {"r": "Mithali 14:18", "t": "Wajinga hurithi upumbavu; Bali wenye busara huvikwa taji ya maarifa."}, {"r": "Hosea 14:9", "t": "Ni nani aliye na hekima, naye atayafahamu mambo haya? Ni nani aliye na busara, naye atayajua? Kwa maana njia za Bwana zimenyoka, nao wenye haki watakwenda katika njia hizo; bali waasio wataanguka ndani yake."}, {"r": "Ayubu 32:7", "t": "Nilisema, Yafaa siku ziseme, Na wingi wa miaka ufundishe hekima."}, {"r": "Mhubiri 2:12", "t": "Nikageuka ili kuipambanua hekima, na wazimu na upumbavu. Kwa maana mtu amfuataye mfalme afanye nini? Lilo hilo tu lililokwisha kufanywa."}, {"r": "Ayubu 17:10", "t": "Lakini rudini; ninyi nyote, njoni sasa; Wala sitampata mtu mwenye hekima kati yenu."}, {"r": "Mithali 8:11", "t": "Maana hekima ni bora kuliko marijani; Wala vyote vinavyotamanika havilingani nayo."}, {"r": "Mithali 21:22", "t": "Mwenye hekima huupandia mji wao wenye nguvu; Na kuziangusha nguvu za tumaini lao."}, {"r": "Mithali 3:7", "t": "Usiwe mwenye hekima machoni pako; Mche Bwana, ukajiepushe na uovu."}, {"r": "Mithali 2:7", "t": "Huwawekea wanyofu akiba ya hekima kamili; Yeye ni ngao kwao waendao kwa ukamilifu;"}, {"r": "Mhubiri 7:7", "t": "Kweli jeuri humpumbaza mwenye hekima, Na rushwa huuharibu ufahamu."}, {"r": "2 Wakorintho 7:13", "t": "Kwa hiyo tulifarijiwa. Tena katika kufarijiwa kwetu tulifurahi sana kupita kiasi kwa sababu ya furaha ya Tito; maana roho yake imeburudishwa na ninyi nyote."}, {"r": "Mhubiri 9:15", "t": "Basi, kulionekana humo mtu maskini mwenye hekima, naye kwa hekima yake akauokoa mji ule lakini hata hivyo hapakuwa na mtu ye yote aliyemkumbuka yule mtu maskini."}, {"r": "Luka 16:8", "t": "Yule bwana akamsifu wakili dhalimu kwa vile alivyotenda kwa busara; kwa kuwa wana wa ulimwengu huu katika kizazi chao wenyewe huwa na busara kuliko wana wa nuru."}, {"r": "Ayubu 28:12", "t": "Bali hekima itapatikana wapi? Na mahali pa ufahamu ni wapi?"}, {"r": "Kumbukumbu la Torati 4:6", "t": "Zishikeni basi, mkazitende, maana hii ndiyo hekima yenu na akili zenu, machoni pa mataifa watakaozisikia amri hizi zote, nao watasema, Hakika taifa hili kubwa ni watu wenye hekima na akili."}, {"r": "Mathayo 26:38", "t": "Ndipo akawaambia, Roho yangu ina huzuni nyingi kiasi cha kufa; kaeni hapa, mkeshe pamoja nami."}, {"r": "Danieli 2:21", "t": "Yeye hubadili majira na nyakati; huuzulu wafalme na kuwamilikisha wafalme; huwapa hekima wenye hekima; huwapa wenye ufahamu maarifa;"}, {"r": "Mithali 9:9", "t": "Mwelimishe mwenye hekima, naye atazidi kuwa na hekima; Mfundishe mwenye haki, naye atazidi kuwa na elimu;"}, {"r": "1 Wakorintho 1:26", "t": "Maana, ndugu zangu, angalieni mwito wenu, ya kwamba si wengi wenye hekima ya mwilini, si wengi wenye nguvu, si wengi wenye cheo walioitwa;"}, {"r": "Ayubu 15:18", "t": "(Ambayo watu wenye hekima wameyatangaza Tokea baba zao, wala hawakuyaficha;"}, {"r": "Kutoka 28:3", "t": "Nawe utawaambia watu wote wenye moyo wa hekima, niliowajaza na roho ya hekima wamfanyie Haruni mavazi ili kumtakasa anitumikie katika kazi ya ukuhani."}, {"r": "Mathayo 25:9", "t": "Lakini wale wenye busara wakawajibu, wakisema, Sivyo; hayatatutosha sisi na ninyi; afadhali shikeni njia mwende kwa wauzao, mkajinunulie."}, {"r": "1 Wakorintho 2:13", "t": "Nayo twayanena, si kwa maneno yanayofundishwa kwa hekima ya kibinadamu, bali yanayofundishwa na Roho, tukiyafasiri mambo ya rohoni kwa maneno ya rohoni."}, {"r": "Hesabu 11:31", "t": "Kisha upepo ukavuma kutoka kwa Bwana, nao ukaleta kware kutoka pande za baharini, nao ukawaacha wakaanguka karibu na kambi, kama kiasi cha mwendo wa siku moja upande huu, na kama kiasi cha mwendo wa siku moja upande huu, kuizunguka, nao wakafikilia kiasi cha dhiraa mbili juu ya uso wa nchi."}, {"r": "Matendo ya Mitume 7:10", "t": "akamtoa katika dhiki zake zote, akampa fadhili na hekima mbele ya Farao, mfalme wa Misri; naye akamfanya awe mtawala juu ya Misri na nyumba yake yote."}, {"r": "Mhubiri 7:10", "t": "Usiseme, Kwani siku za kale kupita siku hizi? Maana si kwa hekima uulizavyo neno hilo."}, {"r": "Warumi 1:22", "t": "Wakijinena kuwa wenye hekima walipumbazika;"}, {"r": "Mithali 25:17", "t": "Mguu wako usiingie katika nyumba ya jirani yako ila kwa kiasi; Asije akakukinai na kukuchukia."}, {"r": "Warumi 1:14", "t": "Nawiwa na Wayunani na wasio Wayunani, nawiwa na wenye hekima na wasio na hekima."}, {"r": "Isaya 19:12", "t": "Wako wapi, basi, watu wako wenye hekima? Na wakuambie sasa; na wajue mambo aliyokusudia Bwana wa majeshi juu ya Misri."}, {"r": "Luka 17:6", "t": "Bwana akasema, Kama mngekuwa na imani kiasi cha chembe ya haradali, mngeuambia mkuyu huu, Ng'oka, ukapandwe baharini, nao ungewatii."}, {"r": "Mhubiri 8:5", "t": "Aishikaye amri hatajua neno baya; Na moyo wa mwenye hekima hujua wakati na hukumu."}, {"r": "Isaya 10:13", "t": "Kwa maana amesema, Kwa nguvu za mkono wangu nimetenda jambo hili, na kwa hekima yangu; maana mimi nina busara; nami nimeiondoa mipaka ya watu, nikaziteka akiba zao, nikawaangusha waketio juu ya viti vya enzi kama afanyavyo shujaa."}, {"r": "Ayubu 38:36", "t": "Je! Ni nani aliyetia hekima moyoni? Au ni nani aliyetia ufahamu rohoni?"}, {"r": "Mithali 30:3", "t": "Wala sikujifunza hekima; Wala sina maarifa ya kumjua Mtakatifu."}, {"r": "1 Wakorintho 1:25", "t": "Kwa sababu upumbavu wa Mungu una hekima zaidi ya wanadamu, na udhaifu wa Mungu una nguvu zaidi ya wanadamu."}, {"r": "Mathayo 13:54", "t": "Na alipofika nchi yake, akawafundisha katika sinagogi lao, hata wakashangaa, wakasema, Huyu amepata wapi hekima hii na miujiza hii?"}, {"r": "Mhubiri 7:23", "t": "Mambo hayo yote mimi nimeyahakikisha katika hekima. Nilisema, Mimi nitakuwa na hekima, lakini imefarakana nami."}, {"r": "Yeremia 9:12", "t": "Ni nani aliye na hekima, apate kuelewa na haya? Tena ni nani ambaye kinywa cha Bwana kimesema naye, apate kuyatangaza? Nayo ni nini maana yake nchi hii kuharibika, na kuteketea kama nyika, asipite mtu?"}, {"r": "Ufunuo wa Yohana 17:9", "t": "Hapo ndipo penye akili zenye hekima. Vile vichwa saba ni milima saba anayokalia mwanamke huyo."}, {"r": "1 Timotheo 2:9", "t": "Vivyo hivyo wanawake na wajipambe kwa mavazi ya kujisitiri, pamoja na adabu nzuri, na moyo wa kiasi; si kwa kusuka nywele, wala kwa dhahabu na lulu, wala kwa nguo za thamani;"}, {"r": "Ayubu 32:13", "t": "Jitunzeni msiseme, Sisi tumepata hekima; Mungu yumkini akamshinda, si mtu;"}, {"r": "1 Wathesalonike 4:12", "t": "ili mwenende kwa adabu mbele yao walio nje, wala msiwe na haja ya kitu cho chote."}, {"r": "Danieli 2:14", "t": "Ndipo Danieli kwa busara na hadhari akamjibu Arioko, akida wa walinzi wa mfalme, aliyekuwa ametoka ili kuwaua wenye hekima wa Babeli;"}, {"r": "Yeremia 6:11", "t": "Lakini nimejaa ghadhabu ya Bwana; nimechoka kwa kujizuia; imwageni juu ya watoto walio njiani, na juu ya kusanyiko la vijana pia; maana hata mume atatwaliwa pamoja na mkewe, mzee pamoja na yeye aliyetimiza siku zake."}, {"r": "1 Timotheo 2:15", "t": "Walakini ataokolewa kwa uzazi wake, kama wakidumu katika imani na upendo na utakaso, pamoja na moyo wa kiasi."}, {"r": "Mithali 4:11", "t": "Nimekufundisha katika njia ya hekima; Nimekuongoza katika mapito ya unyofu."}, {"r": "2 Wakorintho 11:23", "t": "Wao ni wahudumu wa Kristo? (Nanena kiwazimu), mimi ni zaidi; katika taabu kuzidi sana; katika vifungo kuzidi sana; katika mapigo kupita kiasi; katika mauti mara nyingi."}, {"r": "Yeremia 18:18", "t": "Hapo ndipo waliposema, Njoni na tufanye mashauri juu ya Yeremia; maana sheria haitampotea kuhani, wala shauri halitampotea mwenye hekima, wala neno halitampotea nabii. Njoni, na tumpige kwa ndimi zetu, wala tusiyaangalie maneno yake yo yote."}, {"r": "1 Wakorintho 3:10", "t": "Kwa kadiri ya neema ya Mungu niliyopewa, mimi, kama mkuu wa wajenzi mwenye hekima, naliuweka msingi, na mtu mwingine anajenga juu yake. Lakini kila mtu na aangalie jinsi anavyojenga juu yake."}, {"r": "Mithali 2:2", "t": "Hata ukatega sikio lako kusikia hekima, Ukauelekeza moyo wako upate kufahamu;"}, {"r": "Danieli 2:24", "t": "Basi Danieli akaenda kwa Arioko, aliyewekwa na mfalme kuwaangamiza wenye hekima wa Babeli; alikwenda akamwambia hivi, Usiwaangamize wenye hekima wa Babeli; niingize mimi mbele ya mfalme, nami nitamwonyesha mfalme ile tafsiri."}, {"r": "Ayubu 5:13", "t": "Yeye huwanasa wenye hekima katika hila yao wenyewe; Na mashauri ya washupavu yaharibika kwa haraka."}, {"r": "Mithali 8:33", "t": "Sikieni mafundisho, mpate hekima, Wala msiikatae."}, {"r": "Waefeso 5:15", "t": "Basi angalieni sana jinsi mnavyoenenda; si kama watu wasio na hekima bali kama watu wenye hekima;"}, {"r": "Mithali 11:2", "t": "Kijapo kiburi ndipo ijapo aibu; Bali hekima hukaa na wanyenyekevu."}, {"r": "Luka 10:21", "t": "Saa ile ile alishangilia kwa Roho Mtakatifu, akasema, Nakushukuru, Baba, Bwana wa mbingu na nchi, kwa kuwa mambo haya umewaficha wenye hekima na akili; umewafunulia watoto wachanga; Naam, Baba, kwa kuwa ndivyo ilivyokupendeza."}, {"r": "Mithali 21:11", "t": "Mwenye mzaha aadhibiwapo, mjinga hupata hekima; Na mwenye hekima afundishwapo, hupokea maarifa."}, {"r": "Mithali 19:25", "t": "Mpige mwenye mzaha, na mjinga atapata busara; Mwonye mwenye ufahamu, naye atatambua maarifa."}, {"r": "Zaburi 111:10", "t": "Kumcha Bwana ndio mwanzo wa hekima, Wote wafanyao hayo wana akili njema, Sifa zake zakaa milele."}, {"r": "Isaya 33:6", "t": "Nyakati zako zitakuwa nyakati za kukaa imara; za wokovu tele na hekima na maarifa; kumcha Bwana ni hazina yake ya akiba."}, {"r": "Zaburi 90:12", "t": "Basi, utujulishe kuzihesabu siku zetu, Tujipatie moyo wa hekima."}, {"r": "Mithali 27:11", "t": "Mwanangu, uwe na hekima na kunifurahisha moyo wangu; Ili nipate kumjibu anilaumuye."}, {"r": "Mithali 29:18", "t": "Pasipo maono, watu huacha kujizuia; Bali ana heri mtu yule aishikaye sheria."}, {"r": "Kutoka 36:1", "t": "Basi Bezaleli na Oholiabu watatenda kazi, na kila mtu mwenye moyo wa hekima, ambaye Bwana amemtia akili na hekima ili ajue kufanya kazi hiyo yote kwa huo utumishi wa mahali patakatifu, kama hayo yote Bwana aliyoyaagiza."}, {"r": "Mithali 1:2", "t": "Kujua hekima na adabu; kutambua maneno ya ufahamu;"}, {"r": "Mithali 13:1", "t": "Mwana mwenye hekima husikiliza mausia ya babaye; Bali mwenye dharau hasikilizi maonyo."}, {"r": "1 Wakorintho 2:7", "t": "bali twanena hekima ya Mungu katika siri, ile hekima iliyofichwa, ambayo Mungu aliiazimu tangu milele, kwa utukufu wetu;"}, {"r": "Wakolosai 1:9", "t": "Kwa sababu hiyo sisi nasi, tangu siku ile tuliposikia, hatuachi kufanya maombi na dua kwa ajili yenu, ili mjazwe maarifa ya mapenzi yake katika hekima yote na ufahamu wa rohoni;"}, {"r": "2 Wakorintho 7:4", "t": "Ninao ujasiri mwingi kwenu; naona fahari kuu juu yenu. Nimejaa faraja, katika dhiki yetu yote nimejaa furaha ya kupita kiasi."}, {"r": "Waefeso 3:10", "t": "ili sasa, kwa njia ya kanisa, hekima ya Mungu iliyo ya namna nyingi ijulikane na falme na mamlaka katika ulimwengu wa roho;"}, {"r": "Zaburi 49:3", "t": "Kinywa changu kitanena hekima, Na fikira za moyo wangu zitakuwa za busara."}, {"r": "Mithali 21:30", "t": "Hapana hekima, wala ufahamu, Wala shauri, juu ya Bwana."}, {"r": "Mhubiri 1:16", "t": "Nikatafakari nikisema, Nimejipatia hekima nyingi kupita wote walionitangulia katika Yerusalemu; naam, moyo wangu umeona kwa wingi hekima na maarifa."}, {"r": "Zaburi 119:98", "t": "Maagizo yako hunitia hekima kuliko adui zangu, Kwa maana ninayo sikuzote."}, {"r": "Mithali 8:1", "t": "Je! Hekima halii? Ufahamu hatoi sauti yake?"}, {"r": "Yeremia 51:15", "t": "Ameiumba dunia kwa uweza wake, Ameuthibitisha ulimwengu kwa hekima yake, Na kwa ufahamu wake amezitandika mbingu."}, {"r": "Mhubiri 7:25", "t": "Nikageuka, na moyo wangu ulikazwa katika kujua na kupeleleza, na kuitafuta hekima, na maana ya mambo yaliyoko; ili nifahamu ya kuwa uovu ni upumbavu, na upumbavu ni wazimu."}, {"r": "Mithali 24:14", "t": "Basi utaijua hekima kuwa tamu kwa nafsi yako; Ikiwa umekwisha kuiona; Ndipo itakapofuata thawabu; Wala tumaini lako halitabatilika."}, {"r": "Ayubu 15:8", "t": "Je! Umesikia mashauri ya siri ya Mungu? Nawe je! Wazuia hekima iwe yako tu?"}, {"r": "1 Wafalme 4:30", "t": "Hekima ya Sulemani ikapita hekima ya wana wote wa mashariki, na hekima zote za Misri."}, {"r": "Mithali 26:16", "t": "Mtu mvivu ni mwenye hekima machoni pake, Kuliko watu saba wawezao kutoa sababu."}, {"r": "Isaya 38:5", "t": "Enenda ukamwambie Hezekia, Bwana, Mungu wa Daudi, baba yako, asema hivi, Mimi nimeyasikia maombi yako, nimeyaona machozi yako; tazama, nitaziongeza siku zako, kiasi cha miaka kumi na mitano."}, {"r": "Ayubu 34:35", "t": "Huyo Ayubu amesema pasipo maarifa, Na maneno yake hayana hekima."}, {"r": "1 Wakorintho 1:24", "t": "bali kwao waitwao, Wayahudi kwa Wayunani, ni Kristo, nguvu ya Mungu, na hekima ya Mungu."}, {"r": "Isaya 28:29", "t": "Hayo nayo yatoka kwa Bwana wa majeshi, mwenye shauri la ajabu, apitaye wote kwa hekima yake."}, {"r": "1 Wakorintho 7:9", "t": "Lakini ikiwa hawawezi kujizuia, na waoe; maana ni afadhali kuoa kuliko kuwaka tamaa."}, {"r": "Yuda 1:11", "t": "Ole wao! Kwa sababu walikwenda katika njia ya Kaini, na kulifuata kosa la Balaamu pasipo kujizuia, kwa ajili ya ujira, nao wameangamia katika maasi ya Kora."}, {"r": "2 Wakorintho 7:15", "t": "Na mapenzi yake kwenu yamekuwa mengi kupita kiasi, akumbukapo kutii kwenu ninyi nyote, jinsi mlivyomkaribisha kwa hofu na kutetemeka."}, {"r": "Wakolosai 2:23", "t": "Mambo hayo yanaonekana kana kwamba yana hekima, katika namna ya ibada mliyojitungia wenyewe, na katika kunyenyekea, na katika kuutawala mwili kwa ukali; lakini hayafai kitu kwa kuzizuia tamaa za mwili."}, {"r": "Mithali 18:15", "t": "Moyo wa mwenye busara hupata maarifa; Na sikio la mwenye hekima hutafuta maarifa."}, {"r": "Isaya 52:13", "t": "Tazama, mtumishi wangu atatenda kwa busara, atatukuzwa, na kuinuliwa juu, naye atakuwa juu sana."}, {"r": "Mithali 4:7", "t": "Bora hekima, basi jipatie hekima; Naam, kwa mapato yako yote jipatie ufahamu."}, {"r": "Mithali 11:16", "t": "Mwanamke wa adabu huheshimiwa daima; Na watu wakali hushika mali siku zote."}, {"r": "Mhubiri 7:19", "t": "Hekima ni nguvu zake mwenye hekima, Zaidi ya wakuu kumi waliomo mjini."}, {"r": "Mithali 20:26", "t": "Mfalme mwenye hekima huwapepeta wasio haki; Naye hulipitisha gurudumo la kupuria juu yao."}, {"r": "Isaya 27:8", "t": "Umemwadhibu kwa kiasi, ulipomfukuza; ukampepeta kwa upepo mkali katika siku ya upepo wa mashariki."}, {"r": "Mithali 8:12", "t": "Mimi, hekima, nimefanya werevu kuwa kao langu; Natafuta maarifa na busara."}, {"r": "Ufunuo wa Yohana 5:12", "t": "wakisema kwa sauti kuu, Astahili MwanaKondoo aliyechinjwa, kuupokea uweza na utajiri na hekima na nguvu na heshima na utukufu na baraka."}, {"r": "Waefeso 1:17", "t": "Mungu wa Bwana wetu Yesu Kristo, Baba wa utukufu, awape ninyi roho ya hekima na ya ufunuo katika kumjua yeye;"}, {"r": "Mhubiri 9:13", "t": "Pia nimeona hekima chini ya jua, nayo ni kama hivi, tena kwangu mimi ilionekana kuwa ni neno kubwa."}, {"r": "Mithali 9:1", "t": "Hekima umeijenga nyumba yake, Amezichonga nguzo zake saba;"}, {"r": "1 Wakorintho 1:27", "t": "bali Mungu aliyachagua mambo mapumbavu ya dunia awaaibishe wenye hekima; tena Mungu alivichagua vitu dhaifu vya dunia ili aviaibishe vyenye nguvu;"}, {"r": "Mithali 14:24", "t": "Taji ya wenye hekima ni mali zao; Bali upumbavu wa wajinga ni upumbavu tu."}, {"r": "Yeremia 9:23", "t": "Bwana asema hivi, Mwenye hekima asijisifu kwa sababu ya hekima yake, wala mwenye nguvu asijisifu kwa sababu ya nguvu zake, wala tajiri asijisifu kwa sababu ya utajiri wake;"}, {"r": "Mithali 28:7", "t": "Yeye aishikaye sheria ni mwana mwenye hekima; Bali aliye rafiki wa walafi humwaibisha babaye."}, {"r": "Marko 12:34", "t": "Naye Yesu, alipoona kwamba amejibu kwa busara, alimwambia, Wewe hu mbali na ufalme wa Mungu. Wala hakuthubutu mtu kumsaili neno tena tokea hapo."}, {"r": "1 Wakorintho 2:6", "t": "Walakini iko hekima tusemayo kati ya wakamilifu; ila si hekima ya dunia hii, wala ya hao wanaoitawala dunia hii, wanaobatilika;"}, {"r": "Marko 14:34", "t": "Akawaambia, Roho yangu ina huzuni nyingi kiasi cha kufa; kaeni hapa mkeshe."}, {"r": "2 Mambo ya Nyakati 2:12", "t": "Hiramu akasema tena, Na ahimidiwe Bwana, Mungu wa Israeli, aliyezifanya mbingu na nchi, ambaye amempa mfalme Daudi mwana wa hekima, mwenye busara na akili, ili amjengee Bwana nyumba, na nyumba kwa ufalme wake."}, {"r": "1 Wakorintho 1:17", "t": "Maana Kristo hakunituma ili nibatize, bali niihubiri Habari Njema; wala si kwa hekima ya maneno, msalaba wa Kristo usije ukabatilika."}, {"r": "Isaya 29:14", "t": "kwa sababu hiyo mimi nitafanya tena kazi ya ajabu kati ya watu hawa, kazi ya ajabu na mwujiza; na akili za watu wao wenye akili zitapotea, na ufahamu wa wenye busara wao utafichwa."}, {"r": "Mhubiri 8:16", "t": "Mimi nilipotia moyo wangu katika kuijua hekima, na kuuona utumishi uliofanyika juu ya nchi, (maana kuna asiyepata usingizi kwa macho yake mchana wala usiku);"}, {"r": "Zaburi 78:72", "t": "Akawalisha kwa ukamilifu wa moyo wake, Na kuwaongoza kwa busara ya mikono yake."}, {"r": "Mhubiri 8:17", "t": "basi, niliiona kazi yote ya Mungu, ya kuwa haitafutikani na mwanadamu kazi inayofanyika chini ya jua; kwa sababu mwanadamu na akijisumbua kadiri awezavyo kuitafuta, hata hivyo hataiona; naam, zaidi ya hayo, mwenye hekima ajapodhania ya kuwa ataijua, lakini yeye hataweza kuiona."}, {"r": "Zaburi 37:30", "t": "Kinywa chake mwenye haki hunena hekima, Na ulimi wake husema hukumu."}, {"r": "Mithali 24:5", "t": "Mtu mwenye hekima ana nguvu; Naam, mtu wa maarifa huongeza uwezo;"}, {"r": "Yeremia 10:12", "t": "Ameiumba dunia kwa uweza wake, Ameuthibitisha ulimwengu kwa hekima yake, Na kwa ufahamu wake amezitandika mbingu."}, {"r": "2 Wakorintho 12:7", "t": "Na makusudi nisipate kujivuna kupita kiasi, kwa wingi wa mafunuo hayo nalipewa mwiba katika mwili, mjumbe wa Shetani ili anipige, nisije nikajivuna kupita kiasi."}, {"r": "Mithali 19:11", "t": "Busara ya mtu huiahirisha hasira yake; Nayo ni fahari yake kusamehe makosa."}, {"r": "Mithali 10:13", "t": "Hekima hupatikana midomoni mwa mwenye ufahamu; Bali fimbo hufaa kwa mgongo wake asiye na ufahamu."}, {"r": "Mithali 9:10", "t": "Kumcha Bwana ni mwanzo wa hekima; Na kumjua Mtakatifu ni ufahamu."}, {"r": "Mathayo 12:42", "t": "Malkia wa kusini atasimama siku ya hukumu pamoja na watu wa kizazi hiki, naye atawahukumu kuwa wamekosa; kwa sababu yeye alikuja kutoka pande za mwisho za dunia ili asikie hekima ya Sulemani, na hapa yupo aliye mkuu kuliko Sulemani."}, {"r": "Mithali 16:16", "t": "Si afadhali kupata hekima kuliko dhahabu? Naam, yafaa kuchagua ufahamu kuliko fedha."}, {"r": "Ayubu 13:5", "t": "Laiti mngenyamaza kabisa! Hilo lingekuwa hekima kwenu."}, {"r": "Waefeso 2:7", "t": "ili katika zamani zinazokuja audhihirishe wingi wa neema yake upitao kiasi kwa wema wake kwetu sisi katika Kristo Yesu."}, {"r": "Mithali 27:12", "t": "Mwenye busara huyaona mabaya na kujificha; Bali wajinga huendelea mbele wakaumia."}, {"r": "1 Wakorintho 1:30", "t": "Bali kwa yeye ninyi mmepata kuwa katika Kristo Yesu, aliyefanywa kwetu hekima itokayo kwa Mungu, na haki, na utakatifu, na ukombozi;"}, {"r": "Ufunuo wa Yohana 7:12", "t": "wakisema, Amina; Baraka na utukufu na hekima na shukrani na heshima na uweza na nguvu zina Mungu wetu hata milele na milele. Amina."}, {"r": "Zaburi 51:1", "t": "Ee Mungu, unirehemu, Sawasawa na fadhili zako. Kiasi cha wingi wa rehema zako, Uyafute makosa yangu."}, {"r": "1 Timotheo 3:2", "t": "Basi imempasa askofu awe mtu asiyelaumika, mume wa mke mmoja, mwenye kiasi na busara, mtu wa utaratibu, mkaribishaji, ajuaye kufundisha;"}, {"r": "Luka 11:31", "t": "Malkia wa Kusini ataondoka siku ya hukumu pamoja na watu wa kizazi hiki, naye atawahukumu kuwa na hatia; kwa sababu yeye alikuja kutoka ncha za dunia aisikie hekima ya Sulemani; na hapa pana mkubwa kuliko Sulemani."}, {"r": "Marko 12:42", "t": "Akaja mwanamke mmoja, mjane, maskini, akatia senti mbili, kiasi cha nusu pesa."}, {"r": "Mithali 2:10", "t": "Maana hekima itaingia moyoni mwako, Na maarifa yatakupendeza nafsi yako;"}, {"r": "Ayubu 11:6", "t": "Tena akuonyeshe hizo siri za hekima, Ya kuwa hufanikiwa katika kuyatimiza makusudi yake! Ujue basi ya kuwa Mungu akuachilia katika uovu wako."}, {"r": "Mhubiri 12:11", "t": "Maneno yao wenye hekima huwa mfano wa michokoo; na kama misumari iliyogongomewa sana; ndivyo yalivyo maneno yao walio wakuu wa makusanyiko, ambayo yatoka kwa mchungaji mmoja."}, {"r": "1 Petro 4:4", "t": "mambo ambayo wao huona kuwa ni ajabu ya ninyi kutokwenda mbio pamoja nao katika ufisadi ule ule usio na kiasi, wakiwatukana."}, {"r": "Ayubu 13:12", "t": "Matamko yenu ya hekima ni mithali ya majivu, Ngome zenu ni ngome za udongo."}, {"r": "Mhubiri 2:9", "t": "Basi nikawa mkuu, nikaongezeka kupita wote walionitangulia katika Yerusalemu; pia hekima yangu nikakaa nayo."}, {"r": "Mhubiri 2:13", "t": "Ndipo nilipoona ya kuwa kweli hekima hupita upumbavu, kwa kadiri nuru ipitavyo giza;"}, {"r": "1 Wafalme 4:34", "t": "Wakaja wa mataifa yote ili waisikie hekima ya Sulemani, toka wafalme wote wa ulimwengu, waliokuwa wamepata habari za hekima yake."}, {"r": "Mithali 11:30", "t": "Mazao ya mwenye haki ni mti wa uzima; Na mwenye hekima huvuta roho za watu."}, {"r": "Mithali 2:11", "t": "Busara itakulinda; Ufahamu utakuhifadhi."}, {"r": "Luka 21:15", "t": "kwa sababu mimi nitawapa kinywa na hekima ambayo watesi wenu wote hawataweza kushindana nayo wala kuipinga."}, {"r": "Isaya 5:21", "t": "Ole wao walio wenye hekima katika macho yao wenyewe, na wenye busara katika fikira zao wenyewe!"}, {"r": "Mithali 14:6", "t": "Mwenye dharau hutafuta hekima, asiipate; Bali maarifa huwa mepesi kwa mwenye ufahamu."}, {"r": "2 Petro 3:15", "t": "Nanyi uhesabuni uvumilivu wa Bwana wetu kuwa ni wokovu, kama vile na ndugu yetu mpenzi Paulo alivyowaandikia kwa hekima aliyopewa;"}, {"r": "Ayubu 9:4", "t": "Yeye ni mwenye hekima moyoni, na mwenye uwezo katika nguvu; Ni nani aliyejifanya kuwa mgumu juu yake, naye akafanikiwa?"}, {"r": "Kutoka 31:6", "t": "Tena, tazama, nimemchagua, awe pamoja naye, huyo Oholiabu, mwana wa Ahisamaki, wa kabila ya Dani; nami nimetia hekima katika mioyo ya wote wenye moyo wa hekima, ili wapate kufanya vyote nilivyokuagiza;"}, {"r": "Ayubu 34:34", "t": "Watu walio na akili wataniambia, Naam, kila mtu mwenye hekima anisikiaye;"}, {"r": "Mithali 19:14", "t": "Nyumba na mali ni urithi apatao mtu kwa babaye; Bali mke mwenye busara, mtu hupewa na Bwana."}, {"r": "Mhubiri 9:11", "t": "Nikarudi, na kuona chini ya jua, ya kwamba si wenye mbio washindao katika michezo, wala si walio hodari washindao vitani, wala si wenye hekima wapatao chakula, wala si watu wa ufahamu wapatao mali, wala wenye ustadi wapatao upendeleo; lakini wakati na bahati huwapata wote."}, {"r": "Yeremia 5:28", "t": "Wamewanda sana, wang'aa; naam, wamepita kiasi kwa matendo maovu; hawatetei madai ya yatima, ili wapate kufanikiwa; wala hawaamui haki ya mhitaji."}, {"r": "1 Wakorintho 2:5", "t": "ili imani yenu isiwe katika hekima ya wanadamu, bali katika nguvu za Mungu."}, {"r": "Matendo ya Mitume 24:25", "t": "Na Paulo alipokuwa akitoa hoja zake katika habari ya haki, na kuwa na kiasi, na hukumu itakayokuja, Feliki akafanya hofu akajibu, Sasa enenda zako, nami nikipata nafasi nitakuita."}, {"r": "Mithali 10:31", "t": "Kinywa cha mwenye haki hutoa hekima; Bali ulimi wa ukaidi utakatiliwa mbali."}, {"r": "Wakolosai 4:5", "t": "Enendeni kwa hekima mbele yao walio nje, mkiukomboa wakati."}, {"r": "Mithali 15:31", "t": "Sikio lisikilizalo lawama yenye uhai Litakaa kati yao wenye hekima."}, {"r": "Ayubu 38:37", "t": "Ni nani awezaye kuyahesabu mawingu kwa hekima? Au ni nani awezaye kuzimimina chupa za mbinguni?"}, {"r": "Mathayo 23:25", "t": "Ole wenu waandishi na Mafarisayo, wanafiki! Kwa kuwa mnasafisha nje ya kikombe na chano, na ndani yake vimejaa unyang'anyi na kutokuwa na kiasi."}, {"r": "Mhubiri 2:3", "t": "Moyoni mwangu nikapeleleza jinsi ya kuuburudisha mwili kwa mvinyo, na (moyo wangu ukali ukiniongoza kwa hekima) jinsi ya kushikana na upumbavu, hata niyaone yaliyo mema ya kuwafaa wanadamu, ili wayafanye hayo chini ya mbingu siku zote za maisha yao."}, {"r": "Mithali 2:3", "t": "Naam, ukiita busara, Na kupaza sauti yako upate ufahamu;"}, {"r": "Wafilipi 3:8", "t": "Naam, zaidi ya hayo, nayahesabu mambo yote kuwa hasara kwa ajili ya uzuri usio na kiasi wa kumjua Kristo Yesu, Bwana wangu; ambaye kwa ajili yake nimepata hasara ya mambo yote nikiyahesabu kuwa kama mavi ili nipate Kristo;"}, {"r": "Mithali 3:21", "t": "Mwanangu, yasiondoke haya machoni pako, Shika hekima kamili na busara."}, {"r": "Mithali 23:24", "t": "Baba yake mwenye haki atashangilia; Naye amzaaye mtoto mwenye hekima atamfurahia."}, {"r": "Mithali 3:19", "t": "Kwa hekima Bwana aliiweka misingi ya nchi; Kwa akili zake akazifanya mbingu imara;"}, {"r": "1 Wakorintho 2:1", "t": "Basi, ndugu zangu, mimi nilipokuja kwenu, sikuja niwahubiri siri ya Mungu kwa ufasaha wa maneno, wala kwa hekima."}, {"r": "1 Wakorintho 13:2", "t": "Tena nijapokuwa na unabii, na kujua siri zote na maarifa yote, nijapokuwa na imani timilifu kiasi cha kuweza kuhamisha milima, kama sina upendo, si kitu mimi."}, {"r": "Mhubiri 7:16", "t": "Usiwe na haki kupita kiasi; Wala usijiongezee hekima mno; Kwani kujiangamiza mwenyewe?"}, {"r": "Mithali 16:14", "t": "Hasira ya mfalme ni kama wajumbe wa mauti; Lakini mtu mwenye hekima ataituliza."}, {"r": "Ayubu 12:2", "t": "Hapana shaka ninyi ndinyi watu halisi, Nanyi mtakapokufa, ndipo na hekima itakoma."}, {"r": "Warumi 16:19", "t": "Maana utii wenu umewafikilia watu wote; basi nafurahi kwa ajili yenu, lakini nataka ninyi kuwa wenye hekima katika mambo mema, na wajinga katika mambo mabaya."}, {"r": "Ayubu 4:2", "t": "Mtu akijaribu kuzungumza nawe, je! Utaona ni vibaya? Lakini ni nani awezaye kujizuia asinene?"}, {"r": "Mhubiri 12:9", "t": "Walakini, kwa sababu huyo Mhubiri alikuwa na hekima, aliendelea kuwafundisha watu maarifa, naam, akatafakari, akatafutatafuta, akatunga mithali nyingi."}, {"r": "Mithali 23:23", "t": "Inunue kweli, wala usiiuze; Naam, hekima, na mafundisho, na ufahamu."}, {"r": "Mathayo 11:25", "t": "Wakati ule Yesu akajibu, akasema, Nakushukuru, Baba, Bwana wa mbingu na nchi, kwa kuwa mambo haya uliwaficha wenye hekima na akili, ukawafunulia watoto wachanga."}, {"r": "1 Wakorintho 1:22", "t": "Kwa sababu Wayahudi wanataka ishara, na Wayunani wanatafuta hekima;"}, {"r": "Luka 12:42", "t": "Bwana akasema, Ni nani, basi, aliye wakili mwaminifu, mwenye busara, ambaye bwana wake atamweka juu ya utumishi wake wote, awape watu posho kwa wakati wake?"}, {"r": "Ayubu 15:2", "t": "Je! Yapasa mtu mwenye hekima kujibu kwa ujuzi wa uvuvio, Na kujaza tumbo lake na upepo wa mashariki?"}, {"r": "Mithali 29:15", "t": "Fimbo na maonyo hutia hekima; Bali mwana aliyeachiliwa humwaibisha mamaye."}, {"r": "Yeremia 23:5", "t": "Tazama siku zinakuja, asema Bwana, nitakapomchipushia Daudi Chipukizi la haki; naye atamiliki mfalme, atatenda kwa hekima, naye atafanya hukumu na haki katika nchi."}, {"r": "Yeremia 49:7", "t": "Habari za Edomu. Bwana wa majeshi asema hivi, Je! Hapana tena hekima katika Temani? Mashauri yamewapotea wenye busara? Je! Imetoweka hekima yao?"}, {"r": "Ayubu 22:2", "t": "Je! Yumkini mtu awaye yote kumfaa Mungu? Hakika yeye aliye na hekima hujifaa mwenyewe."}, {"r": "1 Wakorintho 3:19", "t": "Maana hekima ya dunia hii ni upuzi mbele za Mungu. Kwa maana imeandikwa, Yeye ndiye awanasaye wenye hekima katika hila yao."}, {"r": "Mithali 23:19", "t": "Sikia, mwanangu, uwe na hekima, Na kuuongoza moyo wako katika njia njema."}, {"r": "Ufunuo wa Yohana 13:18", "t": "Hapa ndipo penye hekima. Yeye aliye na akili, na aihesabu hesabu ya mnyama huyo; maana ni hesabu ya kibinadamu. Na hesabu yake ni mia sita, sitini na sita."}, {"r": "Mithali 3:13", "t": "Heri mtu yule aonaye hekima, Na mtu yule apataye ufahamu."}, {"r": "Ayubu 28:18", "t": "Havitatajwa fedhaluka wala bilauri; Naam, kima cha hekima chapita marijani."}, {"r": "Tito 2:6", "t": "Vivyo hivyo na vijana waume uwaonye kuwa na kiasi;"}, {"r": "Wafilipi 1:9", "t": "Na hii ndiyo dua yangu, kwamba pendo lenu lizidi kuwa jingi sana, katika hekima na ufahamu wote;"}, {"r": "Zaburi 107:43", "t": "Aliye na hekima na ayaangalie hayo; Na wazitafakari fadhili za Bwana."}, {"r": "Mithali 1:20", "t": "Hekima hupaza sauti yake katika njia kuu, Hutoa sauti yake katika viwanja;"}, {"r": "Mithali 18:4", "t": "Maneno ya kinywa cha mtu ni kama maji ya vilindi; Kijito kibubujikacho; chemchemi ya hekima."}, {"r": "Mathayo 23:34", "t": "Kwa sababu hiyo, angalieni, mimi natuma kwenu manabii na wenye hekima na waandishi; na wengine wao ninyi mtawaua na kuwasulibisha, na wengine wao mtawapiga katika masinagogi yenu, na kuwafukuza mji kwa mji;"}, {"r": "Ezra 7:22", "t": "hata kiasi cha talanta mia za fedha, na vipimo mia vya ngano, na bathi mia za divai, na bathi mia za mafuta, na chumvi bila kuuliza kiasi chake."}, {"r": "Ayubu 33:33", "t": "Kama sivyo, unisikilize mimi; Nyamaza, nami nitakufunza hekima."}, {"r": "Mithali 13:10", "t": "Kiburi huleta mashindano tu; Bali hekima hukaa nao wanaoshauriana."}, {"r": "Mithali 19:8", "t": "Apataye hekima hujipenda nafsi yake; Ashikaye ufahamu atapata mema."}, {"r": "Yeremia 10:7", "t": "Ni nani asiyekucha wewe, Ee mfalme wa mataifa? Maana hii ni sifa yako wewe; kwa kuwa miongoni mwa wenye hekima wote wa mataifa, na katika hali yao ya enzi yote pia, hapana hata mmoja kama wewe."}, {"r": "Mithali 28:11", "t": "Mtu tajiri ana hekima machoni pake mwenyewe; Bali maskini mwenye ufahamu humchunguza sana."}, {"r": "Mithali 6:6", "t": "Ewe mvivu, mwendee chungu, Zitafakari njia zake ukapate hekima."}, {"r": "1 Wakorintho 1:20", "t": "Yu wapi mwenye hekima? Yu wapi mwandishi? Yu wapi mlete hoja wa zamani hizi? Je! Mungu hakuifanya hekima ya dunia kuwa ni upumbavu?"}, {"r": "Kutoka 29:40", "t": "tena, pamoja na mwanakondoo mmoja utatoa vibaba vitatu vya unga mzuri uliochanganyika na mafuta yenye kupondwa, kiasi cha kibaba na robo kibaba; na divai kiasi cha kibaba na robo kibaba, iwe sadaka ya kinywaji."}, {"r": "Mithali 5:2", "t": "Upate kuilinda busara, Na midomo yako iyahifadhi maarifa."}, {"r": "Mhubiri 7:12", "t": "Kwa maana hekima ni ulinzi, kama vile fedha ilivyo ulinzi; na ubora wa maarifa ni ya kwamba hekima humhifadhi yeye aliye nayo."}, {"r": "Mathayo 17:20", "t": "Yesu akawaambia, Kwa sababu ya upungufu wa imani yenu. Kwa maana, amin, nawaambia, Mkiwa na imani kiasi cha punje ya haradali mtauambia mlima huu, Ondoka hapa uende kule; nao utaondoka; wala halitakuwako neno lisilowezekana kwenu."}, {"r": "Ayubu 28:20", "t": "Basi hekima yatoka wapi? Na mahali pa ufahamu ni wapi?"}, {"r": "Mithali 14:15", "t": "Mjinga huamini kila neno; Bali mwenye busara huangalia sana aendavyo."}, {"r": "Mhubiri 9:16", "t": "Ndipo niliposema, Bora hekima kuliko nguvu; walakini hekima ya maskini hudharauliwa, wala maneno yake hayasikilizwi."}, {"r": "Zaburi 104:24", "t": "Ee Bwana, jinsi yalivyo mengi matendo yako! Kwa hekima umevifanya vyote pia. Dunia imejaa mali zako."}, {"r": "1 Wakorintho 13:5", "t": "haukosi kuwa na adabu; hautafuti mambo yake; hauoni uchungu; hauhesabu mabaya;"}, {"r": "Matendo ya Mitume 7:5", "t": "Wala hakumpa urithi humu hata kiasi cha kuweka mguu; akaahidi kwamba atampa, iwe milki yake, na ya uzao wake baadaye alipokuwa hana mtoto."}, {"r": "Isaya 47:9", "t": "lakini mambo haya mawili yatakupata katika dakika moja siku moja, kufiwa na watoto, na ujane; yatakupata kiasi kitimilifu, uchawi wako ujapokuwa mwingi, na uganga wako mwingi mno."}, {"r": "Mithali 17:2", "t": "Mtumwa atendaye kwa busara atamtawala mwana atendaye mambo ya aibu; Tena atapata sehemu ya urithi kati ya ndugu."}, {"r": "Mhubiri 10:1", "t": "Mainzi mafu huvundisha marhamu ya mwuza marashi; Kadhalika upumbavu haba ni mzito kuliko hekima na heshima."}, {"r": "Mithali 16:21", "t": "Aliye na hekima moyoni ataitwa mwenye busara; Utamu wa maneno huongeza elimu."}, {"r": "Mithali 1:6", "t": "Kufahamu mithali na kitendawili, na maneno ya wenye hekima na mafumbo yao."}, {"r": "Mithali 19:20", "t": "Sikiliza mashauri, ukapokee mafundisho, Upate kuwa na hekima siku zako za mwisho."}, {"r": "Yeremia 8:9", "t": "Wenye hekima wametahayari, wamefadhaika na kushikwa; tazama, wamelikataa neno la Bwana, wana akili gani ndani yao?"}, {"r": "Luka 2:40", "t": "Yule mtoto akakua, akaongezeka nguvu, amejaa hekima, na neema ya Mungu ilikuwa juu yake."}, {"r": "Mithali 9:8", "t": "Usimkaripie mwenye dharau, asije akakuchukia; Mkaripie mwenye hekima, naye atakupenda."}, {"r": "Ayubu 12:13", "t": "Hekima na amri zina yeye [Mungu]; Yeye anayo mashauri na fahamu."}, {"r": "Mhubiri 7:11", "t": "Hekima ni njema, mfano wa urithi; Naam, nayo ni bora kwao walionao jua."}, {"r": "Mithali 4:5", "t": "Jipatie hekima, jipatie ufahamu; usiusahau; Wala usiyakatae maneno ya kinywa changu."}, {"r": "Isaya 44:25", "t": "Nizitanguaye ishara za waongo, na kuwatia waganga wazimu; niwarudishaye nyuma wenye hekima, na kuyageuza maarifa yao kuwa ujinga;"}, {"r": "Matendo ya Mitume 6:10", "t": "lakini hawakuweza kushindana na hiyo hekima na huyo Roho aliyesema naye."}, {"r": "Mithali 14:35", "t": "Upendeleo wa mfalme humwelekea mtumwa atendaye kwa busara; Bali ghadhabu yake itakuwa juu yake aletaye aibu."}, {"r": "Habakuki 1:6", "t": "Kwa maana, angalieni, nawaondokesha Wakaldayo, taifa lile kali, lenye haraka kupita kiasi; wapitao katikati ya dunia, ili wayamiliki makao yasiyo yao."}, {"r": "Wakolosai 3:16", "t": "Neno la Kristo na likae kwa wingi ndani yenu katika hekima yote, mkifundishana na kuonyana kwa zaburi, na nyimbo, na tenzi za rohoni; huku mkimwimbia Mungu kwa neema mioyoni mwenu."}, {"r": "Mathayo 25:4", "t": "bali wale wenye busara walitwaa mafuta katika vyombo vyao pamoja na taa zao."}, {"r": "1 Wakorintho 6:5", "t": "Nasema hayo nipate kuwatahayarisha. Je! Ndivyo, kwamba kwenu hakuna hata mtu mmoja mwenye hekima, awezaye kukata maneno ya ndugu zake?"}, {"r": "Ayubu 37:24", "t": "Kwa hiyo watu humwogopa; Yeye hawaangalii walio na hekima mioyoni."}, {"r": "Yakobo 4:5", "t": "Au mwadhani ya kwamba maandiko yasema bure? Huyo Roho akaaye ndani yetu hututamani kiasi cha kuona wivu?"}, {"r": "1 Timotheo 3:11", "t": "Vivyo hivyo wake zao na wawe wastahivu; si wasingiziaji; watu wa kiasi, waaminifu katika mambo yote."}, {"r": "Yeremia 20:9", "t": "Nami nikisema, Sitamtaja, wala sitasema tena kwa jina lake; basi, ndipo moyoni mwangu kumekuwamo kama moto uwakao, uliofungwa ndani ya mifupa yangu, nami nimechoka kwa kustahimili, wala siwezi kujizuia."}, {"r": "Isaya 47:10", "t": "Maana umeutumainia ubaya wako; umesema, Hapana anionaye; hekima yako, na maarifa yako yamekupotosha, nawe umesema moyoni mwako, Mimi ndiye, wala hapana mwingine zaidi yangu mimi."}, {"r": "Mithali 29:8", "t": "Watu wenye dharau huwasha mji moto; Bali wenye hekima hugeuzia mbali ghadhabu."}, {"r": "Mithali 22:17", "t": "Tega sikio lako uyasikie maneno ya wenye hekima, na kuuelekeza moyo wako kwa maarifa yangu;"}, {"r": "Luka 2:52", "t": "Naye Yesu akazidi kuendelea katika hekima na kimo, akimpendeza Mungu na wanadamu."}, {"r": "Ayubu 35:11", "t": "Atufundishaye zaidi ya hayawani wa nchi, Na kutufanya wenye hekima kuliko ndege za angani?"}, {"r": "Waefeso 6:4", "t": "Nanyi, akina baba, msiwachokoze watoto wenu; bali waleeni katika adabu na maonyo ya Bwana."}, {"r": "Ayubu 28:28", "t": "Kisha akamwambia mwanadamu, Tazama, kumcha Bwana ndiyo hekima, Na kujitenga na uovu ndio ufahamu."}, {"r": "Zaburi 39:4", "t": "Bwana, unijulishe mwisho wangu, Na kiasi cha siku zangu ni kiasi gani; Nijue jinsi nilivyo dhaifu."}, {"r": "Isaya 56:12", "t": "Husema, Njoni, nitaleta divai, Na tunywe sana kileo; Na kesho itakuwa kama leo, Sikukuu kupita kiasi."}, {"r": "Mithali 7:4", "t": "Mwambie hekima, Wewe ndiwe umbu langu; Mwite ufahamu jamaa yako mwanamke."}, {"r": "Warumi 16:27", "t": "Ndiye Mungu mwenye hekima peke yake. Utukufu una yeye kwa Yesu Kristo, milele na milele. Amina."}, {"r": "Mithali 2:6", "t": "Kwa kuwa Bwana huwapa watu hekima; Kinywani mwake hutoka maarifa na ufahamu;"}, {"r": "Mithali 21:16", "t": "Mtu aikosaye njia ya busara Atakaa katika mkutano wao waliokufa."}, {"r": "Mithali 5:1", "t": "Mwanangu, sikiliza hekima yangu; Tega sikio lako, mzisikie akili zangu;"}, {"r": "Tito 2:5", "t": "na kuwa wenye kiasi, kuwa safi, kufanya kazi nyumbani mwao, kuwa wema, kuwatii waume zao wenyewe; ili neno la Mungu lisitukanwe."}, {"r": "2 Timotheo 4:5", "t": "Bali wewe, uwe na kiasi katika mambo yote, vumilia mabaya, fanya kazi ya mhubiri wa Injili, timiliza huduma yako."}, {"r": "Mathayo 10:16", "t": "Angalieni, mimi nawatuma kama kondoo kati ya mbwamwitu; basi iweni na busara kama nyoka, na kuwa watu wapole kama hua."}, {"r": "Mathayo 11:19", "t": "Mwana wa Adamu alikuja, akila na kunywa, wakasema, Mlafi huyu, na mlevi, rafiki yao watoza ushuru na wenye dhambi! Na hekima imejulikana kuwa ina haki kwa kazi zake."}, {"r": "Yakobo 3:13", "t": "N'nani aliye na hekima na ufahamu kwenu? Na aonyeshe kazi zake kwa mwenendo wake mzuri, katika upole wa hekima."}, {"r": "Mithali 10:5", "t": "Akusanyaye wakati wa hari ni mwana mwenye hekima; Bali asinziaye wakati wa mavuno ni mwana mwenye kuaibisha."}, {"r": "Mithali 25:12", "t": "Kipuli cha dhahabu, na pambo la dhahabu safi; Ndivyo alivyo mwonyaji mwenye hekima kwa sikio lisikialo."}, {"r": "Mhubiri 9:1", "t": "Na kwa ajili ya hayo yote, nikatia moyo wangu katika kuyatafutatafuta haya; ya kuwa wenye haki, na wenye hekima, pamoja na matendo yao yote, wamo mkononi mwa Mungu; kwamba ni pendo au kwamba ni chuki, mwanadamu hajui; mambo yote yawapita."}, {"r": "Mithali 28:26", "t": "Mwenye kujitumainia moyo wake ni mjinga; Bali yeye aendaye kwa busara ataokolewa."}, {"r": "Yakobo 1:5", "t": "Lakini mtu wa kwenu akipungukiwa na hekima, na aombe dua kwa Mungu, awapaye wote, kwa ukarimu, wala hakemei; naye atapewa."}, {"r": "1 Wakorintho 1:19", "t": "Kwa kuwa imeandikwa, Nitaiharibu hekima yao wenye hekima, Na akili zao wenye akili nitazikataa."}, {"r": "1 Wakorintho 7:5", "t": "Msinyimane isipokuwa mmepatana kwa muda, ili mpate faragha kwa kusali; mkajiane tena, Shetani asije akawajaribu kwa kutokuwa na kiasi kwenu."}, {"r": "Yeremia 6:28", "t": "Ni waasi kupita kiasi wote pia, waendao huko na huko wakisingizia, ni shaba na chuma hao, hutenda dhuluma wote pia."}, {"r": "Marko 6:2", "t": "Na ilipokuwa sabato, alianza kufundisha katika sinagogi; wengi waliposikia wakashangaa, wakisema, Huyu ameyapata wapi haya? Na, Ni hekima gani hii aliyopewa huyu? Na, Ni nini miujiza hii mikubwa inayotendeka kwa mikono yake?"}, {"r": "Yakobo 3:15", "t": "Hekima hiyo siyo ile ishukayo kutoka juu, bali ni ya dunia, ya tabia ya kibinadamu, na Shetani."}, {"r": "Matendo ya Mitume 6:3", "t": "Basi ndugu, chagueni watu saba miongoni mwenu, walioshuhudiwa kuwa wema, wenye kujawa na Roho, na hekima, ili tuwaweke juu ya jambo hili;"}, {"r": "2 Petro 2:13", "t": "Wakipatikana na madhara, ambayo ni ujira wa udhalimu wao, wakidhania kuwa ulevi wakati wa mchana ni anasa; wamekuwa ni mawaa na aibu wakifuata anasa zisizo kiasi katika karamu zao za upendo, wafanyapo karamu pamoja nanyi;"}, {"r": "Luka 7:35", "t": "Na hekima imejulikana kuwa ina haki kwa watoto wake wote."}, {"r": "Amosi 5:13", "t": "Kwa ajili ya hayo mwenye busara atanyamaza kimya wakati kama huo; kwa kuwa ni wakati mbaya."}, {"r": "Mhubiri 8:1", "t": "Ni nani aliye kama mwenye hekima; Naye ni nani ajuaye kufasiri neno? Hekima ya mtu humng'ariza uso wake, Na ugumu wa uso wake hubadilika."}, {"r": "Wagalatia 1:13", "t": "Maana mmesikia habari za mwenendo wangu zamani katika dini ya Kiyahudi, kwamba naliliudhi kanisa la Mungu kupita kiasi, nikaliharibu."}, {"r": "1 Wakorintho 1:21", "t": "Kwa maana katika hekima ya Mungu, dunia isipopata kumjua Mungu kwa hekima yake, Mungu alipenda kuwaokoa waaminio kwa upuzi wa lile neno linalohubiriwa."}, {"r": "Zaburi 105:22", "t": "Awafunge masheki wake kama apendavyo, Na kuwafundisha wazee wake hekima."}, {"r": "Mithali 29:3", "t": "Apendaye hekima humfurahisha babaye; Bali ashikamanaye na makahaba hutapanya mali."}, {"r": "Mithali 16:23", "t": "Moyo wake mwenye hekima hufundisha kinywa chake; Huzidisha elimu ya midomo yake."}], "imani": [{"r": "1 Yohana 5:4", "t": "Kwa maana kila kitu kilichozaliwa na Mungu huushinda ulimwengu; na huku ndiko kushinda kuushindako ulimwengu, hiyo imani yetu."}, {"r": "Habakuki 2:4", "t": "Tazama, roho yake hujivuna, haina unyofu ndani yake; lakini mwenye haki ataishi kwa imani yake."}, {"r": "Yohana 20:29", "t": "Yesu akamwambia, Wewe, kwa kuwa umeniona, umesadiki; wa heri wale wasioona, wakasadiki."}, {"r": "Yakobo 2:17", "t": "Vivyo hivyo na imani, isipokuwa ina matendo, imekufa nafsini mwake."}, {"r": "1 Timotheo 6:12", "t": "Piga vita vile vizuri vya imani; shika uzima ule wa milele ulioitiwa, ukaungama maungamo mazuri mbele ya mashahidi wengi."}, {"r": "Mithali 3:5", "t": "Mtumaini Bwana kwa moyo wako wote, Wala usizitegemee akili zako mwenyewe;"}, {"r": "Warumi 4:21", "t": "huku akijua hakika ya kuwa Mungu aweza kufanya yale aliyoahidi."}, {"r": "Mithali 3:6", "t": "Katika njia zako zote mkiri yeye, Naye atayanyosha mapito yako."}, {"r": "Warumi 4:20", "t": "Lakini akiiona ahadi ya Mungu hakusita kwa kutokuamini, bali alitiwa nguvu kwa imani, akimtukuza Mungu;"}, {"r": "Warumi 10:9", "t": "Kwa sababu, ukimkiri Yesu kwa kinywa chako ya kuwa ni Bwana, na kuamini moyoni mwako ya kuwa Mungu alimfufua katika wafu, utaokoka."}, {"r": "Marko 11:24", "t": "Kwa sababu hiyo nawaambia, Yo yote myaombayo mkisali, aminini ya kwamba mnayapokea, nayo yatakuwa yenu."}, {"r": "Mathayo 9:29", "t": "Ndipo alipowagusa macho, akasema, Kwa kadiri ya imani yenu mpate."}, {"r": "Waefeso 2:8", "t": "Kwa maana mmeokolewa kwa neema, kwa njia ya imani; ambayo hiyo haikutokana na nafsi zenu, ni kipawa cha Mungu;"}, {"r": "Wafilipi 4:13", "t": "Nayaweza mambo yote katika yeye anitiaye nguvu."}, {"r": "Marko 11:22", "t": "Yesu akajibu, akamwambia, Mwaminini Mungu."}, {"r": "Wagalatia 3:26", "t": "Kwa kuwa ninyi nyote mmekuwa wana wa Mungu kwa njia ya imani katika Kristo Yesu."}, {"r": "Luka 1:45", "t": "Naye heri aliyesadiki; kwa maana yatatimizwa aliyoambiwa na Bwana."}, {"r": "Luka 17:6", "t": "Bwana akasema, Kama mngekuwa na imani kiasi cha chembe ya haradali, mngeuambia mkuyu huu, Ng'oka, ukapandwe baharini, nao ungewatii."}, {"r": "Mathayo 21:22", "t": "Na yo yote mtakayoyaomba katika sala mkiamini, mtapokea."}, {"r": "2 Timotheo 4:7", "t": "Nimevipiga vita vilivyo vizuri, mwendo nimeumaliza, Imani nimeilinda;"}, {"r": "Marko 5:36", "t": "Lakini Yesu, alipolisikia lile neno likinenwa, akamwambia mkuu wa sinagogi, Usiogope, amini tu."}, {"r": "Waefeso 6:16", "t": "zaidi ya yote mkiitwaa ngao ya imani, ambayo kwa hiyo mtaweza kuizima mishale yote yenye moto ya yule mwovu."}, {"r": "Wagalatia 2:20", "t": "Nimesulibiwa pamoja na Kristo; lakini ni hai; wala si mimi tena, bali Kristo yu hai ndani yangu; na uhai nilio nao sasa katika mwili, ninao katika imani ya Mwana wa Mungu, ambaye alinipenda, akajitoa nafsi yake kwa ajili yangu."}, {"r": "Mathayo 17:20", "t": "Yesu akawaambia, Kwa sababu ya upungufu wa imani yenu. Kwa maana, amin, nawaambia, Mkiwa na imani kiasi cha punje ya haradali mtauambia mlima huu, Ondoka hapa uende kule; nao utaondoka; wala halitakuwako neno lisilowezekana kwenu."}, {"r": "2 Wakorintho 5:7", "t": "(Maana twaenenda kwa imani, si kwa kuona.)"}, {"r": "Yakobo 1:6", "t": "Ila na aombe kwa imani, pasipo shaka yo yote; maana mwenye shaka ni kama wimbi la bahari lililochukuliwa na upepo, na kupeperushwa huku na huku."}, {"r": "Luka 17:5", "t": "Mitume wakamwambia Bwana, Tuongezee imani."}, {"r": "Warumi 10:17", "t": "Basi imani, chanzo chake ni kusikia; na kusikia huja kwa neno la Kristo."}, {"r": "Waebrania 11:6", "t": "Lakini pasipo imani haiwezekani kumpendeza; kwa maana mtu amwendeaye Mungu lazima aamini kwamba yeye yuko, na kwamba huwapa thawabu wale wamtafutao."}, {"r": "2 Wakorintho 4:18", "t": "tusiviangalie vinavyoonekana, bali visivyoonekana. Kwa maana vinavyoonekana ni vya muda tu; bali visivyoonekana ni vya milele."}, {"r": "1 Petro 1:7", "t": "ili kwamba kujaribiwa kwa imani yenu, ambayo ina thamani kuu kuliko dhahabu ipoteayo, ijapokuwa hiyo hujaribiwa kwa moto, kuonekane kuwa kwenye sifa na utukufu na heshima, katika kufunuliwa kwake Yesu Kristo."}, {"r": "Waebrania 11:3", "t": "Kwa imani twafahamu ya kuwa ulimwengu uliumbwa kwa neno la Mungu, hata vitu vinavyoonekana havikufanywa kwa vitu vilivyo dhahiri."}, {"r": "Yakobo 2:26", "t": "Maana kama vile mwili pasipo roho umekufa, vivyo hivyo na imani pasipo matendo imekufa."}, {"r": "Yohana 11:40", "t": "Yesu akamwambia, Mimi sikukuambia ya kwamba ukiamini utauona utukufu wa Mungu?"}, {"r": "Marko 9:23", "t": "Yesu akamwambia, Ukiweza! Yote yawezekana kwake aaminiye."}, {"r": "Warumi 5:1", "t": "Basi tukiisha kuhesabiwa haki itokayo katika imani, na mwe na amani kwa Mungu, kwa njia ya Bwana wetu Yesu Kristo,"}, {"r": "Warumi 1:17", "t": "Kwa maana haki ya Mungu inadhihirishwa ndani yake, toka imani hata imani; kama ilivyoandikwa, Mwenye haki ataishi kwa imani."}, {"r": "Yohana 11:25", "t": "Yesu akamwambia, Mimi ndimi huo ufufuo, na uzima. Yeye aniaminiye mimi, ajapokufa, atakuwa anaishi;"}, {"r": "Waebrania 11:1", "t": "Basi imani ni kuwa na hakika ya mambo yatarajiwayo, ni bayana ya mambo yasiyoonekana."}, {"r": "2 Timotheo 2:13", "t": "Kama sisi hatuamini, yeye hudumu wa kuaminiwa. Kwa maana hawezi kujikana mwenyewe."}, {"r": "Matendo ya Mitume 3:16", "t": "Na kwa imani katika jina lake, jina lake limemtia nguvu mtu huyu mnayemwona na kumjua; na imani ile iliyo kwake yeye imempatia huyu uzima huu mkamilifu mbele yenu ninyi nyote."}, {"r": "Yohana 7:38", "t": "Aniaminiye mimi, kama vile maandiko yalivyonena, mito ya maji yaliyo hai itatoka ndani yake."}, {"r": "Waebrania 11:11", "t": "Kwa imani hata Sara mwenyewe alipokea uwezo wa kuwa na mimba; alipokuwa amepita wakati wake; kwa kuwa alimhesabu yeye aliyeahidi kuwa mwaminifu."}, {"r": "Matendo ya Mitume 13:48", "t": "Mataifa waliposikia hayo wakafurahi, wakalitukuza neno la Bwana, nao waliokuwa wamekusudiwa uzima wa milele wakaamini."}, {"r": "Waefeso 1:19", "t": "na ubora wa ukuu wa uweza wake ndani yetu tuaminio jinsi ulivyo; kwa kadiri ya utendaji wa nguvu za uweza wake;"}, {"r": "Luka 22:32", "t": "lakini nimekuombea wewe ili imani yako isitindike; nawe utakapoongoka waimarishe ndugu zako."}, {"r": "Matendo ya Mitume 18:27", "t": "Na alipotaka kuvuka bahari aende mpaka Akaya, ndugu wakamhimiza, wakawaandikia wale wanafunzi wamkaribishe, naye alipofika akawasaidia sana wale waliokwisha kuamini kwa neema ya Mungu."}, {"r": "Wagalatia 3:24", "t": "Hivyo torati imekuwa kiongozi kutuleta kwa Kristo, ili tuhesabiwe haki kwa imani."}, {"r": "Zaburi 116:10", "t": "Naliamini, kwa maana nitasema, Mimi naliteswa sana."}, {"r": "Filemoni 1:6", "t": "ili kwamba ushirika wa imani yako ufanye kazi yake, katika ujuzi wa kila kitu chema kilicho kwetu, katika Kristo."}, {"r": "Wagalatia 3:8", "t": "Na andiko, kwa vile lilivyoona tangu zamani kwamba Mungu atawahesabia haki Mataifa kwa imani, lilimhubiri Ibrahimu habari njema zamani, kusema, Katika wewe Mataifa yote watabarikiwa."}, {"r": "Tito 1:13", "t": "Ushuhuda huo ni kweli. Kwa sababu hiyo uwakemee kwa ukali, ili wapate kuwa wazima katika imani;"}, {"r": "Ufunuo wa Yohana 2:19", "t": "Nayajua matendo yako na upendo na imani na huduma na subira yako; tena kwamba matendo yako ya mwisho yamezidi yale ya kwanza."}, {"r": "Yohana 6:47", "t": "Amin, amin, nawaambia, Yeye aaminiye yuna uzima wa milele."}, {"r": "Marko 1:15", "t": "akisema, Wakati umetimia, na ufalme wa Mungu umekaribia; tubuni, na kuiamini Injili."}, {"r": "Warumi 10:4", "t": "Kwa maana Kristo ni mwisho wa sheria, ili kila aaminiye ahesabiwe haki."}, {"r": "Warumi 6:8", "t": "Lakini tukiwa tulikufa pamoja na Kristo, twaamini ya kuwa tutaishi pamoja naye;"}, {"r": "Zaburi 19:7", "t": "Sheria ya Bwana ni kamilifu, Huiburudisha nafsi. Ushuhuda wa Bwana ni amini, Humtia mjinga hekima."}, {"r": "1 Timotheo 4:6", "t": "Uwakumbushe ndugu mambo hayo, nawe utakuwa mtumishi mwema wa Kristo Yesu, na mzoevu wa maneno ya imani, na mafundisho mazuri yale uliyoyafuata."}, {"r": "Wakolosai 2:12", "t": "Mkazikwa pamoja naye katika ubatizo; na katika huo mkafufuliwa pamoja naye, kwa kuziamini nguvu za Mungu aliyemfufua katika wafu."}, {"r": "1 Timotheo 1:19", "t": "uwe mwenye imani na dhamiri njema, ambayo wengine wameisukumia mbali, wakaangamia kwa habari ya Imani."}, {"r": "Marko 9:42", "t": "Na ye yote atakayemkosesha mmojawapo wa wadogo hawa waniaminio, afadhali afungiwe jiwe la kusagia shingoni mwake, na kutupwa baharini."}, {"r": "Matendo ya Mitume 16:1", "t": "Basi akafika Derbe na Listra, na hapo palikuwa na mwanafunzi mmoja jina lake Timotheo, mwana wa mwanamke Myahudi aliyeamini; lakini babaye alikuwa Myunani."}, {"r": "Waebrania 12:2", "t": "tukimtazama Yesu, mwenye kuanzisha na mwenye kutimiza imani yetu; ambaye kwa ajili ya furaha iliyowekwa mbele yake aliustahimili msalaba na kuidharau aibu, naye ameketi mkono wa kuume wa kiti cha enzi cha Mungu."}, {"r": "Waebrania 11:39", "t": "Na watu hao wote wakiisha kushuhudiwa kwa sababu ya imani yao, hawakuipokea ahadi;"}, {"r": "Luka 8:13", "t": "Na wale penye mwamba ndio wale ambao wasikiapo hulipokea lile neno kwa furaha; nao hawana mizizi, huamini kitambo kidogo, na wakati wa kujaribiwa hujitenga."}, {"r": "Luka 17:19", "t": "Akamwambia, Inuka, enenda zako, imani yako imekuokoa."}, {"r": "Wagalatia 3:2", "t": "Nataka kujifunza neno hili moja kwenu. Je! Mlipokea Roho kwa matendo ya sheria, au kwa kusikia kunakotokana na imani?"}, {"r": "Ufunuo wa Yohana 14:12", "t": "Hapa ndipo penye subira ya watakatifu, hao wazishikao amri za Mungu, na imani ya Yesu."}, {"r": "Marko 5:34", "t": "Akamwambia, Binti, imani yako imekuponya, enenda zako kwa amani, uwe mzima, usiwe na msiba wako tena."}, {"r": "1 Timotheo 3:9", "t": "wakiishika siri ya imani katika dhamiri safi."}, {"r": "Tito 3:15", "t": "Watu wote walio pamoja nami wakusalimu. Tusalimie wale watupendao katika imani. Neema na iwe pamoja nanyi nyote."}, {"r": "1 Wathesalonike 1:8", "t": "Maana kutoka kwenu neno la Mungu limevuma, si katika Makedonia na Akaya tu, ila na kila mahali imani yenu mliyo nayo kwa Mungu imeenea; hata hatuna haja sisi kunena lo lote."}, {"r": "Waebrania 11:23", "t": "Kwa imani Musa, alipozaliwa, akafichwa miezi mitatu na wazazi wake, kwa sababu waliona kwamba ni mtoto mzuri; wala hawakuiogopa amri ya mfalme."}, {"r": "Warumi 11:20", "t": "Vema. Yalikatwa kwa kutokuamini kwao, na wewe wasimama kwa imani yako. Usijivune, bali uogope."}, {"r": "Warumi 13:11", "t": "Naam, tukiujua wakati, kwamba saa ya kuamka katika usingizi imekwisha kuwadia; kwa maana sasa wokovu wetu u karibu nasi kuliko tulipoanza kuamini"}, {"r": "2 Wathesalonike 1:4", "t": "Hata na sisi wenyewe twaona fahari juu yenu katika makanisa ya Mungu kwa ajili ya saburi yenu, na imani mliyo nayo katika adha zenu zote na dhiki mnazostahimili."}, {"r": "1 Wakorintho 12:9", "t": "mwingine imani katika Roho yeye yule; na mwingine karama za kuponya katika Roho yule mmoja;"}, {"r": "Matendo ya Mitume 14:1", "t": "Ikawa huko Ikonio wakaingia pamoja katika sinagogi la Wayahudi; na kwa vile walivyonena, kundi kubwa la Wayahudi na la Wayunani wakaamini."}, {"r": "Marko 15:32", "t": "Kristo, mfalme wa Israeli, na ashuke sasa msalabani tupate kuona na kuamini. Hata wale waliosulibiwa pamoja naye wakamfyolea."}, {"r": "Yohana 1:7", "t": "Huyo alikuja kwa ushuhuda, ili aishuhudie ile nuru, wote wapate kuamini kwa yeye."}, {"r": "2 Wakorintho 10:15", "t": "wala hatujisifu zaidi ya kadiri yetu, yaani, katika taabu za watu wengine; bali tukiwa na tumaini ya kwamba, imani yenu ikuapo, tutakuzwa kwenu kwa kadiri ya kipimo chetu, na kupata ziada;"}, {"r": "Wafilipi 2:17", "t": "Naam, hata nikimiminwa juu ya dhabihu na ibada ya imani yenu, nafurahi; tena nafurahi pamoja nanyi nyote."}, {"r": "Matendo ya Mitume 24:24", "t": "Baada ya siku kadha wa kadha, Feliki akafika pamoja na Drusila mkewe aliyekuwa Myahudi, akatuma kumwita Paulo akamsikiliza habari za imani iliyo kwa Kristo Yesu."}, {"r": "Yakobo 2:18", "t": "Lakini mtu atasema, Wewe unayo imani, nami ninayo matendo. Nionyeshe imani yako pasipo matendo, nami nitakuonyesha imani yangu kwa njia ya matendo yangu."}, {"r": "Mathayo 6:30", "t": "Basi, ikiwa Mungu huyavika hivi majani ya kondeni, yaliyopo leo, na kesho hutupwa kalibuni, je! Hatazidi sana kuwavika ninyi, enyi wa imani haba?"}, {"r": "Yohana 2:22", "t": "Basi alipofufuka katika wafu, wanafunzi wake wakakumbuka ya kuwa alisema hivi, wakaliamini lile andiko na lile neno alilolinena Yesu."}, {"r": "Luka 7:9", "t": "Yesu aliposikia hayo alimstaajabia, akaugeukia mkutano uliokuwa ukimfuata, akasema, Nawaambia, hata katika Israeli sijaona imani kubwa namna hii."}, {"r": "Waebrania 3:12", "t": "Angalieni, ndugu zangu, usiwe katika mmoja wenu moyo mbovu wa kutokuamini, kwa kujitenga na Mungu aliye hai."}, {"r": "1 Timotheo 6:11", "t": "Bali wewe, mtu wa Mungu, uyakimbie mambo hayo; ukafuate haki, utauwa, imani, upendo, saburi, upole."}, {"r": "Waebrania 11:13", "t": "Hawa wote wakafa katika imani, wasijazipokea zile ahadi, bali wakaziona tokea mbali na kuzishangilia, na kukiri kwamba walikuwa wageni, na wasafiri juu ya nchi."}, {"r": "Mithali 27:6", "t": "Jeraha utiwazo na rafiki ni amini; Bali kubusu kwa adui ni kwingi sana."}, {"r": "1 Timotheo 2:15", "t": "Walakini ataokolewa kwa uzazi wake, kama wakidumu katika imani na upendo na utakaso, pamoja na moyo wa kiasi."}, {"r": "Mathayo 23:23", "t": "Ole wenu waandishi na Mafarisayo, wanafiki! Kwa kuwa mnalipa zaka za mnanaa na bizari na jira, lakini mmeacha mambo makuu ya sheria, yaani, adili, na rehema, na imani; hayo imewapasa kuyafanya, wala yale mengine msiyaache."}, {"r": "Warumi 3:30", "t": "kama kwa kweli Mungu ni mmoja, atakayewahesabia haki wale waliotahiriwa katika imani, nao wale wasiotahiriwa atawahesabia haki kwa njia ya imani iyo hiyo."}, {"r": "Mathayo 8:13", "t": "Naye Yesu akamwambia yule akida, Nenda zako; na iwe kwako kama ulivyoamini. Mtumishi wake akapona saa ile ile."}, {"r": "Wagalatia 3:9", "t": "Basi hao walio wa imani hubarikiwa pamoja na Ibrahimu aliyekuwa mwenye imani."}, {"r": "Wakolosai 1:4", "t": "tangu tuliposikia habari za imani yenu katika Kristo Yesu, na upendo mlio nao kwa watakatifu wote;"}, {"r": "Wagalatia 5:5", "t": "Maana sisi kwa Roho tunalitazamia tumaini la haki kwa njia ya imani."}, {"r": "Mathayo 15:28", "t": "Ndipo Yesu akajibu, akamwambia, Mama, imani yako ni kubwa; na iwe kwako kama utakavyo. Akapona binti yake tangu saa ile."}, {"r": "Yakobo 2:22", "t": "Waona kwamba imani ilitenda kazi pamoja na matendo yake, na ya kwamba imani ile ilikamilishwa kwa njia ya matendo yale."}, {"r": "1 Wathesalonike 3:2", "t": "Tukamtuma Timotheo ndugu yetu, mtumishi wa Mungu katika Injili ya Kristo, ili kuwafanya ninyi imara na kuwafariji kwa habari ya imani yenu;"}, {"r": "1 Timotheo 5:8", "t": "Lakini mtu ye yote asiyewatunza walio wake, yaani, wale wa nyumbani mwake hasa, ameikana Imani, tena ni mbaya kuliko mtu asiyeamini."}, {"r": "Ayubu 9:16", "t": "Kama ningemwita, naye akaniitikia; Hata hivyo singeamini kuwa amesikiza sauti yangu."}, {"r": "Waebrania 11:21", "t": "Kwa imani Yakobo, alipokuwa katika kufa, akambariki kila mmoja wa wana wa Yusufu, akaabudu akiegemea kichwa cha fimbo yake."}, {"r": "Yakobo 1:3", "t": "mkifahamu ya kuwa kujaribiwa kwa imani yenu huleta saburi."}, {"r": "Mathayo 9:2", "t": "Na tazama, wakamletea mtu mwenye kupooza, amelala kitandani; naye Yesu, alipoiona imani yao, alimwambia yule mwenye kupooza, Jipe moyo mkuu, mwanangu, umesamehewa dhambi zako."}, {"r": "Wakolosai 2:5", "t": "Maana nijapokuwa sipo kwa mwili, lakini nipo pamoja nanyi kwa roho, nikifurahi na kuuona utaratibu wenu na uthabiti wa imani yenu katika Kristo."}, {"r": "Waebrania 11:22", "t": "Kwa imani Yusufu, alipokuwa amekaribia mwisho wake, alitaja habari za kutoka kwao wana wa Israeli, akaagiza kwa habari ya mifupa yake."}, {"r": "Waebrania 11:8", "t": "Kwa imani Ibrahimu alipoitwa aliitika, atoke aende mahali pale atakapopapata kuwa urithi; akatoka asijue aendako."}, {"r": "2 Wathesalonike 3:2", "t": "tukaokolewe na watu wasio haki, wabaya; maana si wote walio na imani."}, {"r": "Luka 18:8", "t": "Nawaambia, atawapatia haki upesi; walakini, atakapokuja Mwana wa Adamu, je! Ataiona imani duniani?"}, {"r": "Yohana 4:41", "t": "Watu wengi zaidi wakaamini kwa sababu ya neno lake."}, {"r": "1 Petro 1:21", "t": "ambao kwa yeye mmekuwa wenye kumwamini Mungu, aliyemfufua katika wafu akampa utukufu; hata imani yenu na tumaini lenu liwe kwa Mungu."}, {"r": "Filemoni 1:21", "t": "Kwa kuwa nakuamini kutii kwako ndiyo maana nimekuandikia, nikijua ya kuwa utafanya zaidi ya hayo nisemayo."}, {"r": "1 Wakorintho 15:2", "t": "na kwa hiyo mnaokolewa; ikiwa mnayashika sana maneno niliyowahubiri isipokuwa mliamini bure."}, {"r": "Waebrania 10:38", "t": "Lakini mwenye haki wangu ataishi kwa imani; Naye akisitasita, roho yangu haina furaha naye."}, {"r": "Matendo ya Mitume 4:32", "t": "Na jamii ya watu walioamini walikuwa na moyo mmoja na roho moja; wala hapana mmoja aliyesema ya kuwa kitu cho chote alicho nacho ni mali yake mwenyewe; bali walikuwa na vitu vyote shirika."}, {"r": "Zaburi 106:12", "t": "Ndipo walipoyaamini maneno yake, Waliziimba sifa zake."}, {"r": "Yohana 4:42", "t": "Wakamwambia yule mwanamke, Sasa tunaamini, wala si kwa sababu ya maneno yako tu; maana sisi tumesikia wenyewe, tena twajua ya kuwa hakika huyu ndiye Mwokozi wa ulimwengu."}, {"r": "Matendo ya Mitume 19:9", "t": "Lakini wengine walikaidi, wakakataa kuamini, wakiitukana ile Njia mbele ya mkutano; basi, akaondoka akawaacha, akawatenga wanafunzi, akahojiana na watu kila siku katika darasa ya mtu mmoja, jina lake Tirano."}, {"r": "Marko 16:17", "t": "Na ishara hizi zitafuatana na hao waaminio; kwa jina langu watatoa pepo; watasema kwa lugha mpya;"}, {"r": "Matendo ya Mitume 15:5", "t": "Lakini baadhi ya madhehebu ya Mafarisayo walioamini wakasimama wakisema, Ni lazima kuwatahiri na kuwaagiza kuishika torati ya Musa."}, {"r": "Yohana 5:47", "t": "Lakini msipoyaamini maandiko yake, mtayaamini wapi maneno yangu?"}, {"r": "Waebrania 10:22", "t": "na tukaribie wenye moyo wa kweli, kwa utimilifu wa imani, hali tumenyunyiziwa mioyo tuache dhamiri mbaya, tumeoshwa miili kwa maji safi."}, {"r": "Warumi 14:22", "t": "Ile imani uliyo nayo uwe nayo nafsini mwako mbele za Mungu. Heri mtu yule asiyejihukumu nafsi yake katika neno lile analolikubali."}, {"r": "2 Wathesalonike 1:3", "t": "Ndugu, imetupasa kumshukuru Mungu sikuzote kwa ajili yenu, kama ilivyo wajibu, kwa kuwa imani yenu inazidi sana, na upendo wa kila mtu kwenu kwa mwenzake umekuwa mwingi."}, {"r": "2 Wakorintho 8:7", "t": "Lakini kama mlivyo na wingi wa mambo yote; imani, na usemi, na elimu, na bidii yote, na upendo wenu kwetu sisi; basi vivyo hivyo mpate wingi wa neema hii pia."}, {"r": "Warumi 12:3", "t": "Kwa maana kwa neema niliyopewa namwambia kila mtu aliyeko kwenu asinie makuu kupita ilivyompasa kunia; bali awe na nia ya kiasi, kama Mungu alivyomgawia kila mtu kiasi cha imani."}, {"r": "Wafilipi 1:27", "t": "Lakini mwenendo wenu na uwe kama inavyoipasa Injili ya Kristo, ili, nikija na kuwaona ninyi, au nisipokuwapo, niyasikie mambo yenu, kama mnasimama imara katika roho moja, kwa moyo mmoja mkiishindania imani ya Injili;"}, {"r": "Ufunuo wa Yohana 2:13", "t": "Napajua ukaapo, ndipo penye kiti cha enzi cha Shetani; nawe walishika sana jina langu, wala hukuikana imani yangu, hata katika siku za Antipa shahidi wangu, mwaminifu wangu, aliyeuawa kati yenu, hapo akaapo Shetani."}, {"r": "1 Wakorintho 13:2", "t": "Tena nijapokuwa na unabii, na kujua siri zote na maarifa yote, nijapokuwa na imani timilifu kiasi cha kuweza kuhamisha milima, kama sina upendo, si kitu mimi."}, {"r": "Marko 9:24", "t": "Mara babaye yule kijana akapaza sauti, akasema, Naamini, nisaidie kutokuamini kwangu."}, {"r": "Waebrania 11:9", "t": "Kwa imani alikaa ugenini katika ile nchi ya ahadi, kama katika nchi isiyo yake, akikaa katika hema pamoja na Isaka na Yakobo, warithi pamoja naye wa ahadi ile ile."}, {"r": "Zaburi 89:28", "t": "Hata milele nitamwekea fadhili zangu, Na agano langu litafanyika amini kwake."}, {"r": "Matendo ya Mitume 24:14", "t": "Ila neno hili naungama kwako ya kwamba kwa Njia ile ambayo waiita uzushi, ndivyo ninavyomwabudu Mungu wa baba zetu, nikiyaamini yote yanayopatana na torati na yaliyoandikwa katika vyuo vya manabii."}, {"r": "Wafilipi 1:25", "t": "Nami nikitumaini hayo, najua ya kuwa nitakaa na kudumu pamoja nanyi, ili mpate kuendelea na kufurahi katika imani;"}, {"r": "Waefeso 4:13", "t": "hata na sisi sote tutakapoufikia umoja wa imani na kumfahamu sana Mwana wa Mungu, hata kuwa mtu mkamilifu, hata kufika kwenye cheo cha kimo cha utimilifu wa Kristo;"}, {"r": "Tito 1:9", "t": "akilishika lile neno la imani vile vile kama alivyofundishwa, apate kuweza kuwaonya watu kwa mafundisho yenye uzima, na kuwashinda wenye kupinga."}, {"r": "Zaburi 119:86", "t": "Maagizo yako yote ni amini, Wananifuatia bure, unisaidie."}, {"r": "2 Petro 1:1", "t": "Simoni Petro, mtumwa na mtume wa Yesu Kristo, kwa wale waliopata imani moja na sisi, yenye thamani, katika hali ya Mungu wetu, na Mwokozi Yesu Kristo."}, {"r": "Yohana 14:1", "t": "Msifadhaike mioyoni mwenu; mnamwamini Mungu, niaminini na mimi."}, {"r": "Warumi 10:10", "t": "Kwa maana kwa moyo mtu huamini hata kupata haki, na kwa kinywa hukiri hata kupata wokovu."}, {"r": "Wagalatia 3:14", "t": "ili kwamba baraka ya Ibrahimu iwafikilie Mataifa katika Yesu Kristo, tupate kupokea ahadi ya Roho kwa njia ya imani."}, {"r": "1 Timotheo 1:13", "t": "ingawa hapo kwanza nalikuwa mtukanaji, mwenye kuudhi watu, mwenye jeuri, lakini nalipata rehema kwa kuwa nalitenda hivyo kwa ujinga, na kwa kutokuwa na imani."}, {"r": "Yohana 12:36", "t": "Maadamu mnayo nuru, iaminini nuru hiyo, ili mpate kuwa wana wa nuru. Hayo aliyasema Yesu, akaenda zake, akajificha wasimwone."}, {"r": "Matendo ya Mitume 15:9", "t": "wala hakufanya tofauti kati yetu sisi na wao, akiwasafisha mioyo yao kwa imani."}, {"r": "1 Timotheo 1:4", "t": "wala wasiangalie hadithi na nasaba zisizo na ukomo, ziletazo maswali wala si madaraka ya Mungu yaliyo katika imani; basi ufanye hivyo."}, {"r": "Yohana 1:50", "t": "Yesu akajibu, akamwambia, Kwa sababu nilikuambia, Nilikuona chini ya mtini, waamini? Utaona mambo makubwa kuliko haya."}, {"r": "Warumi 3:31", "t": "Basi, je! Twaibatilisha sheria kwa imani hiyo? Hasha! Kinyume cha hayo twaithibitisha sheria."}, {"r": "1 Timotheo 4:10", "t": "kwa maana twajitaabisha na kujitahidi kwa kusudi hili, kwa sababu tunamtumaini Mungu aliye hai, aliye Mwokozi wa watu wote, hasa wa waaminio."}, {"r": "1 Timotheo 4:3", "t": "wakiwazuia watu wasioe, na kuwaamuru wajiepushe na vyakula, ambavyo Mungu aliviumba vipokewe kwa shukrani na walio na imani wenye kuijua hiyo kweli."}, {"r": "Mathayo 18:6", "t": "bali atakayemkosesha mmojawapo wa wadogo hawa waniaminio, yamfaa afungiwe shingoni jiwe kubwa la kusagia, na kutoswa katika kilindi cha bahari."}, {"r": "Warumi 4:12", "t": "tena awe baba ya kutahiriwa, kwa wale ambao si waliotahiriwa tu, bali pia wanazifuata nyayo za imani yake baba yetu Ibrahimu aliyokuwa nayo kabla hajatahiriwa."}, {"r": "Warumi 11:23", "t": "Na hao pia, wasipokaa katika kutokuamini kwao, watapandikizwa; kwa kuwa Mungu aweza kuwapandikiza tena."}, {"r": "1 Wakorintho 7:14", "t": "Kwa maana yule mume asiyeamini hutakaswa katika mkewe; na yule mke asiyeamini hutakaswa katika mumewe; kama isingekuwa hivyo, watoto wenu wangekuwa si safi; bali sasa ni watakatifu."}, {"r": "Warumi 4:18", "t": "Naye aliamini kwa kutarajia yasiyoweza kutarajiwa, ili apate kuwa baba wa mataifa mengi, kama ilivyonenwa, Ndivyo utakavyokuwa uzao wako."}, {"r": "Zaburi 119:66", "t": "Unifundishe akili na maarifa, Maana nimeyaamini maagizo yako."}, {"r": "Matendo ya Mitume 10:45", "t": "Na wale waliotahiriwa, walioamini, wakashangaa, watu wote waliokuja pamoja na Petro, kwa sababu Mataifa nao wamemwagiwa kipawa cha Roho Mtakatifu."}, {"r": "2 Timotheo 3:8", "t": "Na kama vile Yane na Yambre walivyopingana na Musa, vivyo hivyo na hawa wanapingana na ile kweli; ni watu walioharibika akili zao, wamekataliwa kwa mambo ya imani."}, {"r": "Yuda 1:3", "t": "Wapenzi, nilipokuwa nikifanya bidii sana kuwaandikia habari ya wokovu ambao ni wetu sisi sote, naliona imenilazimu kuwaandikia, ili niwaonye kwamba mwishindanie imani waliyokabidhiwa watakatifu mara moja tu."}, {"r": "Matendo ya Mitume 21:20", "t": "Nao waliposikia wakamtukuza Mungu, wakamwambia, Ndugu yetu, unaona jinsi Wayahudi walioamini walivyo elfu nyingi, nao wote wana wivu sana kwa ajili ya torati."}, {"r": "1 Timotheo 1:15", "t": "Ni neno la kuaminiwa, tena lastahili kukubalika kabisa, ya kwamba Kristo Yesu alikuja ulimwenguni awaokoe wenye dhambi; ambao wa kwanza wao ni mimi."}, {"r": "Warumi 3:4", "t": "Hasha! Mungu aonekane kuwa amini na kila mtu mwongo; kama ilivyoandikwa, Ili ujulike kuwa una haki katika maneno yako, Ukashinde uingiapo katika hukumu."}, {"r": "Waebrania 10:39", "t": "Lakini sisi hatumo miongoni mwao wasitao na kupotea, bali tumo miongoni mwa hao walio na imani ya kutuokoa roho zetu."}, {"r": "1 Wathesalonike 5:8", "t": "Lakini sisi tulio wa mchana, tuwe na kiasi, hali tukijivika kifuani imani na upendo, na chapeo yetu iwe tumaini la wokovu."}, {"r": "Matendo ya Mitume 4:4", "t": "Lakini wengi katika hao waliosikia lile neno waliamini; na hesabu ya watu waume ikawa kama elfu tano."}, {"r": "Warumi 10:16", "t": "Lakini si wote walioitii ile habari njema. Kwa maana Isaya asema, Bwana, ni nani aliyeziamini habari zetu?"}, {"r": "Marko 4:40", "t": "Akawaambia, Mbona mmekuwa waoga? Hamna imani bado?"}, {"r": "Waebrania 11:28", "t": "Kwa imani akaifanya Pasaka, na kule kunyunyiza damu, ili yule mwenye kuwaangamiza wazaliwa wa kwanza asiwaguse wao."}, {"r": "Luka 8:50", "t": "Lakini Yesu aliposikia hayo, alimjibu, Usiwe na hofu, amini tu, naye ataponywa."}, {"r": "Yohana 11:15", "t": "Nami nafurahi kwa ajili yenu kwamba sikuwako huko, ili mpate kuamini; lakini na twendeni kwake."}, {"r": "1 Timotheo 4:12", "t": "Mtu awaye yote asiudharau ujana wako, bali uwe kielelezo kwao waaminio, katika usemi na mwenendo, na katika upendo na imani na usafi."}, {"r": "Matendo ya Mitume 13:12", "t": "Ndipo yule liwali, alipoyaona yaliyotendeka, akaamini, akiyastaajabia mafundisho ya Bwana."}, {"r": "Yohana 14:29", "t": "Na sasa nimewaambia kabla halijatokea, kusudi litakapotokea mpate kuamini."}, {"r": "2 Wakorintho 4:13", "t": "Lakini kwa kuwa tuna roho ile ile ya imani; kama ilivyoandikwa, Naliamini, na kwa sababu hiyo nalinena; sisi nasi twaamini, na kwa sababu hiyo twanena;"}, {"r": "Matendo ya Mitume 11:24", "t": "Maana alikuwa mtu mwema amejaa Roho Mtakatifu na imani; watu wengi wakaongezeka upande wa Bwana."}, {"r": "1 Yohana 5:5", "t": "Mwenye kuushinda ulimwengu ni nani, isipokuwa ni yeye aaminiye ya kwamba Yesu ni Mwana wa Mungu?"}, {"r": "Yohana 12:46", "t": "Mimi nimekuja ili niwe nuru ya ulimwengu, ili kila mtu aniaminiye mimi asikae gizani."}, {"r": "Mathayo 16:8", "t": "Naye Yesu akafahamu, akawaambia, Mbona mnabishana ninyi kwa ninyi, enyi wa imani chache, kwa sababu hamna mikate?"}, {"r": "1 Yohana 5:1", "t": "Kila mtu aaminiye kwamba Yesu ni Kristo amezaliwa na Mungu. Na kila mtu ampendaye mwenye kuzaa, ampenda hata yeye aliyezaliwa na yeye."}, {"r": "1 Petro 3:1", "t": "Kadhalika ninyi wake, watiini waume zenu; kusudi, ikiwa wako wasioliamini Neno, wavutwe kwa mwenendo wa wake zao, pasipo lile Neno;"}, {"r": "Warumi 4:19", "t": "Yeye asiyekuwa dhaifu wa imani, alifikiri hali ya mwili wake uliokuwa umekwisha kufa, (akiwa amekwisha kupata umri wa kama miaka mia), na hali ya kufa ya tumbo lake Sara."}, {"r": "Yakobo 2:24", "t": "Mwaona kwamba mwanadamu huhesabiwa kuwa ana haki kwa matendo yake; si kwa imani peke yake."}, {"r": "1 Wathesalonike 3:10", "t": "usiku na mchana tunapoomba kwa juhudi tupate kuwaona nyuso zenu, na kuyatengeneza mapungufu ya imani yenu?"}, {"r": "Matendo ya Mitume 14:27", "t": "Hata walipofika wakalikutanisha kanisa, wakawaeleza mambo yote aliyoyafanya Mungu pamoja nao, na ya kwamba amewafungulia Mataifa mlango wa imani."}, {"r": "1 Petro 1:9", "t": "katika kuupokea mwisho wa imani yenu, yaani, wokovu wa roho zenu."}, {"r": "Matendo ya Mitume 11:21", "t": "Mkono wa Bwana ukawa pamoja nao, watu wengi wakaamini, wakamwelekea Bwana."}, {"r": "Wakolosai 1:23", "t": "mkidumu tu katika ile imani, hali mmewekwa juu ya msingi, mkawa imara; msipogeuzwa na kuliacha tumaini la Injili mliyosikia habari zake, iliyohubiriwa katika viumbe vyote vilivyo chini ya mbingu; ambayo mimi Paulo nalikuwa mhudumu wake."}, {"r": "Yakobo 2:19", "t": "Wewe waamini ya kuwa Mungu ni mmoja; watenda vema. Mashetani nao waamini na kutetemeka."}, {"r": "Warumi 4:11", "t": "Naye aliipokea dalili hii ya kutahiriwa, muhuri ya ile haki ya imani aliyokuwa nayo kabla hajatahiriwa; apate kuwa baba yao wote waaminio, ijapokuwa hawakutahiriwa, ili na wao pia wahesabiwe haki;"}, {"r": "Warumi 3:3", "t": "Ni nini, basi, ikiwa baadhi yao hawakuamini? Je! Kutokuamini kwao kutaubatili uaminifu wa Mungu?"}, {"r": "2 Timotheo 1:5", "t": "nikiikumbuka imani uliyo nayo isiyo na unafiki, ambayo ilikaa kwanza katika bibi yako Loisi, na katika mama yako Eunike, nami nasadiki wewe nawe unayo."}, {"r": "Waebrania 11:4", "t": "Kwa imani Habili alimtolea Mungu dhabihu iliyo bora kuliko Kaini; kwa hiyo alishuhudiwa kuwa ana haki; Mungu akazishuhudia sadaka zake, na kwa hiyo, ijapokuwa amekufa, angali akinena."}, {"r": "Mithali 14:15", "t": "Mjinga huamini kila neno; Bali mwenye busara huangalia sana aendavyo."}, {"r": "1 Timotheo 1:5", "t": "Walakini mwisho wa agizo hilo ni upendo utokao katika moyo safi na dhamiri njema, na imani isiyo na unafiki."}, {"r": "Warumi 4:16", "t": "Kwa hiyo ilitoka katika imani, iwe kwa njia ya neema, ili kwamba ile ahadi iwe imara kwa wazao wote; si kwa wale wa torati tu, ila na kwa wale wa imani ya Ibrahimu; aliye baba yetu sisi sote;"}, {"r": "Waebrania 11:30", "t": "Kwa imani kuta za Yeriko zikaanguka, zilipokwisha kuzungukwa siku saba."}, {"r": "1 Wathesalonike 1:7", "t": "Hata mkawa kielelezo kwa watu wote waaminio katika Makedonia, na katika Akaya."}, {"r": "1 Timotheo 5:16", "t": "Mwanamke aaminiye, akiwa ana wajane, na awasaidie mwenyewe, Kanisa lisilemewe; ili liwasaidie wale walio wajane kweli kweli."}, {"r": "1 Timotheo 4:9", "t": "Ni neno la kuaminiwa, tena lastahili kukubalika kabisa;"}, {"r": "1 Wakorintho 10:27", "t": "Na mtu asiyeamini akiwaalika, nanyi mnataka kwenda, kuleni kila kitu kiwekwacho mbele yenu bila kuulizauliza, kwa ajili ya dhamiri."}, {"r": "1 Wakorintho 1:21", "t": "Kwa maana katika hekima ya Mungu, dunia isipopata kumjua Mungu kwa hekima yake, Mungu alipenda kuwaokoa waaminio kwa upuzi wa lile neno linalohubiriwa."}, {"r": "Matendo ya Mitume 15:7", "t": "Na baada ya hoja nyingi Petro akasimama, akawaambia, Ndugu zangu, ninyi mnajua ya kuwa tangu siku za kwanza Mungu alichagua miongoni mwenu ya kwamba Mataifa walisikie neno la Injili kwa kinywa changu, na kuliamini."}, {"r": "Wafilipi 1:6", "t": "Nami niliaminilo ndilo hili, ya kwamba yeye aliyeanza kazi njema mioyoni mwenu ataimaliza hata siku ya Kristo Yesu;"}, {"r": "Waefeso 3:17", "t": "Kristo akae mioyoni mwenu kwa imani mkiwa na shina na msingi katika upendo;"}, {"r": "1 Wathesalonike 1:3", "t": "Wala hatuachi kuikumbuka kazi yenu ya imani, na taabu yenu ya upendo, na saburi yenu ya tumaini lililo katika Bwana wetu Yesu Kristo, mbele za Mungu Baba yetu."}, {"r": "Mathayo 9:22", "t": "Yesu akageuka, akamwona, akamwambia, Jipe moyo mkuu, binti yangu; imani yako imekuponya. Yule mwanamke akapona tangu saa ile."}, {"r": "Luka 12:28", "t": "Basi, ikiwa Mungu huvika hivi majani ya kondeni, yaliyopo leo na kesho hutupwa kalibuni, je! Hatawatendea ninyi zaidi, enyi wa imani haba?"}, {"r": "Zaburi 78:8", "t": "Naam, wasiwe kama baba zao, Kizazi cha ukaidi na uasi. Kizazi kisichojitengeneza moyo, Wala roho yake haikuwa amini kwa Mungu."}, {"r": "1 Wakorintho 3:5", "t": "Basi Apolo ni nani? Na Paulo ni nani? Ni wahudumu ambao kwao mliamini; na kila mtu kama Bwana alivyompa."}, {"r": "Mathayo 17:17", "t": "Yesu akajibu, akasema, Enyi kizazi kisichoamini, kilichopotoka, nitakaa pamoja nanyi hata lini? Nitachukuliana nanyi hata lini? Mleteni huku kwangu."}, {"r": "Yohana 16:9", "t": "Kwa habari ya dhambi, kwa sababu hawaniamini mimi;"}, {"r": "1 Wathesalonike 3:5", "t": "Kwa hiyo mimi nami nilipokuwa siwezi kuvumilia tena, nalituma mtu ili niijue imani yenu, asije yule mjaribu akawajaribu, na taabu yetu ikawa haina faida."}, {"r": "Warumi 10:8", "t": "Lakini yanenaje? Lile neno li karibu nawe, katika kinywa chako, na katika moyo wako; yaani, ni lile neno la imani tulihubirilo."}, {"r": "Mathayo 8:10", "t": "Yesu aliposikia hayo, alistaajabu, akawaambia wale waliomfuata, Amin, nawaambieni, Sijaona imani kubwa namna hii, kwa ye yote katika Israeli."}, {"r": "Tito 1:1", "t": "Paulo, mtumwa wa Mungu, na mtume wa Yesu Kristo; kwa ajili ya imani ya wateule wa Mungu, na ujuzi wa kweli ile iletayo utauwa;"}, {"r": "1 Wathesalonike 3:7", "t": "Kwa sababu hiyo, ndugu, tulifarijiwa kwa habari zenu, katika msiba na dhiki yetu yote, kwa imani yenu."}, {"r": "Waebrania 4:2", "t": "Maana ni kweli, sisi nasi tumehubiriwa habari njema vile vile kama hao. Lakini neno lile lililosikiwa halikuwafaa hao, kwa sababu halikuchanganyika na imani ndani yao waliosikia."}, {"r": "Marko 2:5", "t": "Naye Yesu, alipoiona imani yao, akamwambia yule mwenye kupooza, Mwanangu, umesamehewa dhambi zako."}, {"r": "Isaya 28:16", "t": "kwa ajili ya hayo Bwana, MUNGU, asema hivi, Tazama, naweka jiwe katika Sayuni, liwe msingi, jiwe lililojaribiwa, jiwe la pembeni lenye thamani, msingi ulio imara; yeye aaminiye hatafanya haraka."}, {"r": "1 Wakorintho 14:24", "t": "Lakini wote wakihutubu, kisha akaingia mtu asiyeamini, au mjinga, abainishwa na wote, ahukumiwa na wote;"}, {"r": "Warumi 14:23", "t": "Lakini aliye na shaka, kama akila, amehukumiwa kuwa ana hatia, kwa maana hakula kwa imani. Na kila tendo lisilotoka katika imani ni dhambi."}, {"r": "Matendo ya Mitume 15:11", "t": "Bali twaamini kwamba tutaokoka kwa neema ya Bwana Yesu vile vile kama wao."}, {"r": "Yakobo 2:5", "t": "Ndugu zangu wapenzi, sikilizeni, Je! Mungu hakuwachagua maskini wa dunia wawe matajiri wa imani na warithi wa ufalme aliowaahidia wampendao?"}, {"r": "1 Wathesalonike 2:10", "t": "Ninyi ni mashahidi, na Mungu pia, jinsi tulivyokaa kwenu ninyi mnaoamini, kwa utakatifu, na kwa haki, bila kulaumiwa;"}, {"r": "Marko 9:19", "t": "Akawajibu, akasema, Enyi kizazi kisichoamini, nikae nanyi hata lini? Nichukuliane nanyi hata lini? Mleteni kwangu."}, {"r": "1 Timotheo 3:13", "t": "Kwa maana watendao vema kazi ya shemasi hujipatia daraja nzuri, na ujasiri mwingi katika imani iliyo katika Kristo Yesu."}, {"r": "Yakobo 2:14", "t": "Ndugu zangu, yafaa nini, mtu akisema ya kwamba anayo imani, lakini hana matendo? Je! Ile imani yaweza kumwokoa?"}, {"r": "Yohana 20:8", "t": "Basi ndipo alipoingia naye yule mwanafunzi mwingine aliyekuwa wa kwanza wa kufika kaburini, akaona na kuamini."}, {"r": "1 Yohana 5:13", "t": "Nimewaandikia ninyi mambo hayo, ili mjue ya kuwa mna uzima wa milele, ninyi mnaoliamini Jina la Mwana wa Mungu."}, {"r": "Marko 6:6", "t": "Akastaajabu kwa sababu ya kutokuamini kwao. Akazungukazunguka katika vile vijiji, akifundisha."}, {"r": "Warumi 3:28", "t": "Basi, twaona ya kuwa mwanadamu huhesabiwa haki kwa imani pasipo matendo ya sheria."}, {"r": "Yakobo 2:20", "t": "Lakini wataka kujua, wewe mwanadamu usiye kitu, kwamba imani pasipo matendo haizai?"}, {"r": "Matendo ya Mitume 17:4", "t": "Wengine miongoni mwao wakaamini, wakashikamana na Paulo na Sila; na Wayunani waliomcha Mungu, wengi sana, na wanawake wenye cheo si wachache."}, {"r": "Wagalatia 3:12", "t": "Na torati haikuja kwa imani, bali, Ayatendaye hayo ataishi katika hayo."}, {"r": "Ayubu 12:20", "t": "Huondoa matamko ya hao walioaminiwa, Na kuondoa fahamu za wazee."}, {"r": "1 Wakorintho 9:17", "t": "Maana nikiitenda kazi hii kwa hiari yangu nina thawabu; ila ikiwa si kwa hiari yangu, nimeaminiwa uwakili."}, {"r": "Yohana 20:27", "t": "Kisha akamwambia Tomaso, Lete hapa kidole chako; uitazame mikono yangu; ulete na mkono wako uutie ubavuni mwangu, wala usiwe asiyeamini, bali aaminiye."}, {"r": "2 Wathesalonike 2:12", "t": "ili wahukumiwe wote ambao hawakuiamini kweli, bali walikuwa wakijifurahisha katika udhalimu."}, {"r": "1 Wathesalonike 4:14", "t": "Maana, ikiwa twaamini ya kwamba Yesu alikufa akafufuka, vivyo hivyo na hao waliolala katika Yesu, Mungu atawaleta pamoja naye."}, {"r": "Wafilipi 3:9", "t": "tena nionekane katika yeye, nisiwe na haki yangu mwenyewe ipatikanayo kwa sheria, bali ile ipatikanayo kwa imani iliyo katika Kristo, haki ile itokayo kwa Mungu, kwa imani;"}, {"r": "Waebrania 3:19", "t": "Basi twaona ya kuwa hawakuweza kuingia kwa sababu ya kutokuamini kwao."}, {"r": "Waebrania 13:7", "t": "Wakumbukeni wale waliokuwa wakiwaongoza, waliowaambia neno la Mungu; tena, kwa kuuchunguza sana mwisho wa mwenendo wao, iigeni imani yao."}, {"r": "2 Timotheo 1:13", "t": "Shika kielelezo cha maneno yenye uzima uliyoyasikia kwangu, katika imani na upendo ulio katika Kristo Yesu."}, {"r": "1 Wakorintho 15:17", "t": "Na kama Kristo hakufufuka, imani yenu ni bure; mngalimo katika dhambi zenu."}, {"r": "Warumi 3:22", "t": "ni haki ya Mungu iliyo kwa njia ya imani katika Yesu Kristo kwa wote waaminio. Maana hakuna tofauti;"}, {"r": "Warumi 9:30", "t": "Tuseme nini, basi? Ya kwamba watu wa Mataifa, wasioifuata haki, walipata haki; lakini ni ile haki iliyo ya imani;"}, {"r": "2 Timotheo 2:11", "t": "Ni neno la kuaminiwa. Kwa maana, Kama tukifa pamoja naye, tutaishi pamoja naye pia;"}, {"r": "Zaburi 93:5", "t": "Shuhuda zako ni amini sana; Utakatifu ndio uifaao nyumba yako, Ee Bwana, milele na milele."}, {"r": "Warumi 1:16", "t": "Kwa maana siionei haya Injili; kwa sababu ni uweza wa Mungu uuletao wokovu, kwa kila aaminiye, kwa Myahudi kwanza, na kwa Myunani pia."}, {"r": "Wagalatia 6:10", "t": "Kwa hiyo kadiri tupatavyo nafasi na tuwatendee watu wote mema; na hasa jamaa ya waaminio."}, {"r": "Matendo ya Mitume 17:12", "t": "Basi watu wengi miongoni mwao wakaamini, na wanawake wa Kiyunani wenye cheo, na wanaume si wachache."}, {"r": "Tito 1:6", "t": "ikiwa mtu hakushitakiwa neno, naye ni mume wa mke mmoja, ana watoto waaminio, wasioshitakiwa kuwa ni wafisadi wala wasiotii."}, {"r": "Wagalatia 3:22", "t": "Lakini andiko limeyafunga yote chini ya nguvu ya dhambi, makusudi hao waaminio wapewe ile ahadi kwa imani ya Yesu Kristo."}, {"r": "Waebrania 11:20", "t": "Kwa imani Isaka akawabariki Yakobo na Esau, hata katika habari ya mambo yatakayokuwa baadaye."}, {"r": "1 Wakorintho 13:7", "t": "huvumilia yote; huamini yote; hutumaini yote; hustahimili yote."}, {"r": "1 Wakorintho 15:11", "t": "Basi, kama ni mimi, kama ni wale, ndivyo tuhubirivyo, na ndivyo mlivyoamini."}, {"r": "1 Timotheo 2:7", "t": "Nami kwa ajili ya huo naliwekwa niwe mhubiri na mtume, (nasema kweli, sisemi uongo), mwalimu wa Mataifa katika imani na kweli."}, {"r": "Warumi 1:12", "t": "yaani, tufarijiane mimi na ninyi, kila mtu kwa imani ya mwenzake, yenu na yangu."}, {"r": "Luka 24:25", "t": "Akawaambia, Enyi msiofahamu, wenye mioyo mizito ya kuamini yote waliyoyasema manabii!"}, {"r": "2 Wathesalonike 2:11", "t": "Kwa hiyo Mungu awaletea nguvu ya upotevu, wauamini uongo;"}, {"r": "2 Wathesalonike 1:11", "t": "Kwa hiyo twawaombea ninyi sikuzote, ili Mungu wetu awahesabu kuwa mmekustahili kuitwa kwenu, akatimiza kila haja ya wema na kila kazi ya imani kwa nguvu;"}, {"r": "Matendo ya Mitume 6:5", "t": "Neno hili likapendeza machoni pa mkutano wote; wakamchagua Stefano, mtu aliyejaa imani na Roho Mtakatifu, na Filipo, na Prokoro, na Nikanori, na Timoni, na Parmena, na Nikolao mwongofu wa Antiokia;"}, {"r": "Zaburi 106:24", "t": "Wakaidharau nchi ile ya kupendeza, Wala hawakuliamini neno lake."}, {"r": "Wagalatia 1:23", "t": "ila wamesikia tu ya kwamba huyo aliyetuudhi hapo kwanza, sasa anaihubiri imani ile aliyoiharibu zamani."}, {"r": "1 Timotheo 1:14", "t": "Na neema ya Bwana wetu ilizidi sana, pamoja na imani na pendo lililo katika Kristo Yesu."}, {"r": "Luka 24:41", "t": "Basi walipokuwa hawajaamini kwa furaha, huku wakistaajabu, aliwaambia, Mna chakula cho chote hapa?"}, {"r": "Luka 5:20", "t": "Naye alipoiona imani yao, alimwambia, Ee rafiki, umesamehewa dhambi zako."}, {"r": "Yohana 2:24", "t": "Lakini Yesu hakujiaminisha kwao; kwa kuwa yeye aliwajua wote;"}, {"r": "Warumi 3:27", "t": "Ku wapi, basi, kujisifu? Kumefungiwa nje. Kwa sheria ya namna gani? Kwa sheria ya matendo? La! Bali kwa sheria ya imani."}, {"r": "2 Wathesalonike 2:13", "t": "Lakini imetupasa sisi kumshukuru Mungu sikuzote kwa ajili yenu, ndugu mliopendwa na Bwana, kwa kuwa Mungu amewachagua tangu mwanzo mpate wokovu, katika kutakaswa na Roho, na kuiamini kweli;"}, {"r": "Matendo ya Mitume 19:18", "t": "Na wengi wa wale walioamini wakaja wakaungama, wakidhihirisha matendo yao."}, {"r": "Ufunuo wa Yohana 22:6", "t": "Kisha akaniambia, Maneno haya ni amini na kweli. Naye Bwana, Mungu wa roho za manabii, alimtuma malaika wake kuwaonyesha watumwa wake mambo ambayo hayana budi kuwako upesi."}, {"r": "Yohana 6:35", "t": "Yesu akawaambia, Mimi ndimi chakula cha uzima; yeye ajaye kwangu hataona njaa kabisa, naye aniaminiye hataona kiu kamwe."}, {"r": "Yakobo 2:1", "t": "Ndugu zangu, imani ya Bwana wetu Yesu Kristo, Bwana wa utukufu, msiwe nayo kwa kupendelea watu."}, {"r": "Yohana 5:46", "t": "Kwa maana kama mngalimwamini Musa, mngeniamini mimi; kwa sababu yeye aliandika habari zangu."}, {"r": "Yohana 4:53", "t": "Basi babaye akafahamu ya kuwa ni saa ile ile aliyoambiwa na Yesu, Mwanao yu hai. Akaamini yeye na wote wa nyumbani mwake."}, {"r": "2 Timotheo 2:18", "t": "walioikosa ile kweli, wakisema ya kwamba kiyama imekwisha kuwapo, hata kuipindua imani ya watu kadha wa kadha."}, {"r": "Wagalatia 3:5", "t": "Basi, yeye awapaye Roho na kufanya miujiza kati yenu, je! Afanya hayo kwa matendo ya sheria, au kwa kusikia kunakotokana na imani?"}, {"r": "Marko 10:52", "t": "Yesu akamwambia, Enenda zako, imani yako imekuponya. Mara akapata kuona; akamfuata njiani."}, {"r": "Yohana 10:38", "t": "lakini nikizitenda, ijapokuwa hamniamini mimi, ziaminini zile kazi; mpate kujua na kufahamu ya kuwa Baba yu ndani yangu, nami ni ndani ya Baba."}, {"r": "Marko 16:16", "t": "Aaminiye na kubatizwa ataokoka; asiyeamini, atahukumiwa."}, {"r": "Wakolosai 2:7", "t": "wenye shina na wenye kujengwa katika yeye; mmefanywa imara kwa imani, kama mlivyofundishwa; mkizidi kutoa shukrani."}, {"r": "1 Yohana 5:10", "t": "Yeye amwaminiye Mwana wa Mungu anao huo ushuhuda ndani yake. Asiyemwamini Mungu amemfanya kuwa mwongo, kwa kuwa hakuuamini huo ushuhuda ambao Mungu amemshuhudia Mwanawe."}, {"r": "Luka 8:12", "t": "Wale wa karibu na njia ndio wasikiao, kisha huja Ibilisi akaliondoa hilo neno mioyoni mwao, wasije wakaamini na kuokoka."}, {"r": "Yohana 20:31", "t": "Lakini hizi zimeandikwa ili mpate kuamini ya kwamba Yesu ndiye Kristo, Mwana wa Mungu; na kwa kuamini mwe na uzima kwa jina lake."}, {"r": "Warumi 14:2", "t": "Mtu mmoja anayo imani, anakula vyote; lakini yeye aliye dhaifu hula mboga."}, {"r": "Wagalatia 5:6", "t": "Maana katika Kristo Yesu kutahiriwa hakufai neno, wala kutokutahiriwa, bali imani itendayo kazi kwa upendo."}, {"r": "2 Timotheo 2:22", "t": "Lakini zikimbie tamaa za ujanani; ukafuate haki, na imani, na upendo, na amani, pamoja na wale wamwitao Bwana kwa moyo safi."}, {"r": "Warumi 12:6", "t": "Basi kwa kuwa tuna karama zilizo mbalimbali, kwa kadiri ya neema mliyopewa; ikiwa unabii, tutoe unabii kwa kadiri ya imani;"}, {"r": "Warumi 1:8", "t": "Kwanza namshukuru Mungu wangu katika Yesu Kristo kwa ajili yenu nyote, kwa kuwa imani yenu inahubiriwa katika dunia nzima."}, {"r": "Matendo ya Mitume 8:13", "t": "Na yeye Simoni mwenyewe aliamini akabatizwa, akashikamana na Filipo; akashangaa alipoziona ishara na miujiza mikubwa inayotendeka."}, {"r": "1 Wakorintho 7:13", "t": "Na mwanamke, ambaye ana mume asiyeamini, na mume huyo anakubali kukaa naye, asimwache mumewe."}, {"r": "1 Wakorintho 7:15", "t": "Lakini yule asiyeamini akiondoka, na aondoke. Hapo huyo ndugu mume au ndugu mke hafungiki. Lakini Mungu ametuita katika amani."}, {"r": "Mathayo 14:31", "t": "Mara Yesu akanyosha mkono wake, akamshika, akamwambia, Ewe mwenye imani haba, mbona uliona shaka?"}, {"r": "1 Yohana 4:1", "t": "Wapenzi, msiiamini kila roho, bali zijaribuni hizo roho, kwamba zimetokana na Mungu; kwa sababu manabii wa uongo wengi wametokea duniani."}, {"r": "2 Wakorintho 1:24", "t": "Si kwamba tunatawala imani yenu; bali tu wasaidizi wa furaha yenu; maana kwa imani yenu mnasimama."}, {"r": "Wagalatia 3:11", "t": "Ni dhahiri ya kwamba hakuna mtu ahesabiwaye haki mbele za Mungu katika sheria; kwa sababu Mwenye haki ataishi kwa imani."}, {"r": "Matendo ya Mitume 28:24", "t": "Wengine waliamini yale yaliyonenwa, wengine hawakuyaamini."}, {"r": "Mathayo 13:58", "t": "Wala hakufanya miujiza mingi huko, kwa sababu ya kutokuamini kwao."}, {"r": "Warumi 15:13", "t": "Basi Mungu wa tumaini na awajaze ninyi furaha yote na amani katika kuamini, mpate kuzidi sana kuwa na tumaini, katika nguvu za Roho Mtakatifu."}, {"r": "Warumi 5:2", "t": "ambaye kwa yeye tumepata kwa njia ya imani kuifikia neema hii ambayo mnasimama ndani yake; na kufurahi katika tumaini la utukufu wa Mungu."}, {"r": "Luka 9:41", "t": "Yesu akajibu akasema, Enyi kizazi kisicho na imani, kilichopotoka, nitakaa nanyi na kuwachukulia hata lini? Mlete mwanao hapa."}, {"r": "Marko 16:14", "t": "Baadaye akaonekana na wale kumi na mmoja walipokuwa wakila, akawakemea kwa kutokuamini kwao na ugumu wa mioyo yao, kwa kuwa hawakuwasadiki wale waliomwona alipofufuka katika wafu."}, {"r": "1 Wakorintho 2:5", "t": "ili imani yenu isiwe katika hekima ya wanadamu, bali katika nguvu za Mungu."}, {"r": "Matendo ya Mitume 26:18", "t": "uwafumbue macho yao, na kuwageuza waiache giza na kuielekea nuru, waziache na nguvu za Shetani na kumwelekea Mungu; kisha wapate msamaha wa dhambi zao, na urithi miongoni mwao waliotakaswa kwa imani iliyo kwangu mimi."}, {"r": "Warumi 14:1", "t": "Yeye aliye dhaifu wa imani, mkaribisheni, walakini msimhukumu mawazo yake."}, {"r": "Yohana 13:19", "t": "Tangu sasa nawaambia kabla hayajatukia, ili yatakapotukia mpate kuamini ya kuwa mimi ndiye."}, {"r": "Yohana 10:37", "t": "Kama sizitendi kazi za Baba yangu, msiniamini;"}, {"r": "1 Yohana 4:16", "t": "Nasi tumelifahamu pendo alilo nalo Mungu kwetu sisi, na kuliamini. Mungu ni upendo, naye akaaye katika pendo, hukaa ndani ya Mungu, na Mungu hukaa ndani yake."}, {"r": "Wagalatia 3:23", "t": "Lakini kabla ya kuja ile imani tulikuwa tumewekwa chini ya sheria, tumefungwa mpaka ije ile imani itakayofunuliwa."}, {"r": "Yohana 4:48", "t": "Basi Yesu akamwambia, Msipoona ishara na maajabu hamtaamini kabisa?"}, {"r": "Warumi 1:5", "t": "ambaye katika yeye tulipokea neema na utume ili mataifa yote wapate kujitiisha kwa imani, kwa ajili ya jina lake;"}, {"r": "Isaya 43:10", "t": "Ninyi ni mashahidi wangu, asema Bwana, na mtumishi niliyemchagua; mpate kujua, na kuniamini, na kufahamu ya kuwa mimi ndiye; kabla yangu hakuumbwa Mungu awaye yote, wala baada yangu mimi hatakuwapo mwingine."}, {"r": "2 Wakorintho 13:5", "t": "Jijaribuni wenyewe kwamba mmekuwa katika imani; jithibitisheni wenyewe. Au hamjijui wenyewe, kwamba Yesu Kristo yu ndani yenu? Isipokuwa mmekataliwa."}, {"r": "Tito 3:8", "t": "Ni neno la kuaminiwa; na mambo hayo nataka uyanene kwa nguvu, ili wale waliomwamini Mungu wakumbuke kudumu katika matendo mema. Hayo ni mazuri, tena yana faida kwa wanadamu."}, {"r": "Waebrania 11:24", "t": "Kwa imani Musa alipokuwa mtu mzima, akakataa kuitwa mwana wa binti Farao;"}, {"r": "Yohana 11:26", "t": "naye kila aishiye na kuniamini hatakufa kabisa hata milele. Je! Unayasadiki hayo?"}, {"r": "Wagalatia 2:16", "t": "hali tukijua ya kuwa mwanadamu hahesabiwi haki kwa matendo ya sheria, bali kwa imani ya Kristo Yesu; sisi tulimwamini Kristo Yesu ili tuhesabiwe haki kwa imani ya Kristo, wala si kwa matendo ya sheria; maana kwa matendo ya sheria hakuna mwenye mwili atakayehesabiwa haki."}, {"r": "Marko 11:23", "t": "Amin, nawaambia, Ye yote atakayeuambia mlima huu, Ng'oka ukatupwe baharini, wala asione shaka moyoni mwake, ila aamini kwamba hayo asemayo yametukia, yatakuwa yake."}, {"r": "Yakobo 5:15", "t": "Na kule kuomba kwa imani kutamwokoa mgonjwa yule, na Bwana atamwinua; hata ikiwa amefanya dhambi, atasamehewa."}, {"r": "Warumi 4:5", "t": "Lakini kwa mtu asiyefanya kazi, bali anamwamini yeye ambaye amhesabia haki asiyekuwa mtauwa, imani yake mtu huyo imehesabiwa kuwa haki."}, {"r": "Yohana 2:23", "t": "Hata alipokuwapo Yerusalemu kwenye sikukuu wakati wa Pasaka, watu wengi waliamini jina lake, walipoziona ishara zake alizozifanya."}, {"r": "Zaburi 78:32", "t": "Pamoja na hayo wakazidi kutenda dhambi, Wala hawakuyaamini matendo yake ya ajabu."}, {"r": "Matendo ya Mitume 5:14", "t": "walioamini wakazidi kuongezeka kwa Bwana, wengi, wanaume na wanawake;"}, {"r": "Habakuki 1:5", "t": "Angalieni, enyi mlio kati ya mataifa, katazameni, kastaajabuni sana; kwa maana mimi natenda tendo siku zenu, ambalo hamtaliamini hata mkiambiwa."}, {"r": "2 Timotheo 3:15", "t": "na ya kuwa tangu utoto umeyajua maandiko matakatifu, ambayo yaweza kukuhekimisha hata upate wokovu kwa imani iliyo katika Kristo Yesu."}, {"r": "Yohana 14:12", "t": "Amin, amin, nawaambieni, Yeye aniaminiye mimi, kazi nizifanyazo mimi, yeye naye atazifanya; naam, na kubwa kuliko hizo atafanya, kwa kuwa mimi naenda kwa Baba."}, {"r": "Warumi 4:13", "t": "Kwa maana ahadi ile ya kwamba atakuwa mrithi wa ulimwengu alipewa Ibrahimu na uzao wake, si kwa sheria bali kwa haki aliyohesabiwa kwa imani."}, {"r": "Yohana 6:30", "t": "Wakamwambia, Unafanya ishara gani basi, ili tuione tukakuamini? Unatenda kazi gani?"}, {"r": "Yohana 5:44", "t": "Mwawezaje kuamini ninyi mnaopokeana utukufu ninyi kwa ninyi, na utukufu ule utokao kwa Mungu aliye wa pekee hamwutafuti?"}, {"r": "Mathayo 8:26", "t": "Akawaambia, Mbona mmekuwa waoga, enyi wa imani haba? Mara akaondoka, akazikemea pepo na bahari; kukawa shwari kuu."}, {"r": "1 Wathesalonike 2:13", "t": "Kwa sababu hiyo sisi nasi twamshukuru Mungu bila kukoma, kwa kuwa, mlipopata lile neno la ujumbe la Mungu mlilolisikia kwetu, mlilipokea si kama neno la wanadamu, bali kama neno la Mungu; na ndivyo lilivyo kweli kweli; litendalo kazi pia ndani yenu ninyi mnaoamini."}, {"r": "1 Wakorintho 13:13", "t": "Basi, sasa inadumu imani, tumaini, upendo, haya matatu; na katika hayo lililo kuu ni upendo."}, {"r": "Luka 18:42", "t": "Yesu akamwambia, Upewe kuona; imani yako imekuponya."}, {"r": "Mathayo 21:21", "t": "Yesu akajibu, akawaambia, Amin, nawaambia Mkiwa na imani, msipokuwa na shaka, mtafanya si hilo la mtini tu, lakini hata mkiuambia mlima huu, Ng'oka, ukatupwe baharini, litatendeka."}, {"r": "1 Wakorintho 15:14", "t": "tena kama Kristo hakufufuka, basi, kuhubiri kwetu ni bure na imani yenu ni bure."}, {"r": "Wagalatia 3:7", "t": "Fahamuni basi, ya kuwa wale walio wa imani, hao ndio wana wa Ibrahimu."}, {"r": "Filemoni 1:5", "t": "nikisikia habari za upendo wako na imani uliyo nayo kwa Bwana Yesu na kwa watakatifu wote;"}, {"r": "1 Yohana 3:23", "t": "Na hii ndiyo amri yake, kwamba tuliamini jina la Mwana wake Yesu Kristo, na kupendana sisi kwa sisi, kama alivyotupa amri."}, {"r": "Yohana 3:15", "t": "ili kila mtu aaminiye awe na uzima wa milele katika yeye."}, {"r": "Waebrania 6:12", "t": "ili msiwe wavivu, bali mkawe wafuasi wa hao wazirithio ahadi kwa imani na uvumilivu."}, {"r": "1 Wathesalonike 3:6", "t": "Lakini Timotheo alipotujia hivi sasa kutoka kwenu, alituletea habari njema za imani yenu na upendo wenu, na ya kwamba mnatukumbuka vema siku zote; mkitamani kutuona sisi vile vile kama sisi kuwaona ninyi."}, {"r": "1 Petro 5:9", "t": "Nanyi mpingeni huyo, mkiwa thabiti katika imani, mkijua ya kuwa mateso yale yale yanatimizwa kwa ndugu zenu walioko duniani."}, {"r": "Wafilipi 2:24", "t": "Nami naamini katika Bwana ya kuwa nitakuja na mimi mwenyewe hivi karibu."}, {"r": "1 Timotheo 4:1", "t": "Basi Roho anena waziwazi ya kwamba nyakati za mwisho wengine watajitenga na imani, wakisikiliza roho zidanganyazo, na mafundisho ya mashetani;"}, {"r": "Waebrania 11:5", "t": "Kwa imani Henoko alihamishwa, asije akaona mauti, wala hakuonekana, kwa sababu Mungu alimhamisha; maana kabla ya kuhamishwa alikuwa ameshuhudiwa kwamba amempendeza Mungu."}, {"r": "Matendo ya Mitume 18:8", "t": "Na Krispo, mkuu wa sinagogi, akamwamini Bwana pamoja na nyumba yake yote. Wakorintho wengi waliposikia, waliamini, wakabatizwa."}, {"r": "Wagalatia 3:25", "t": "Lakini, iwapo imani imekuja, hatupo tena chini ya kiongozi."}, {"r": "Tito 1:4", "t": "kwa Tito, mwanangu hasa katika imani tuishirikiyo. Neema na iwe kwako na amani zitokazo kwa Mungu Baba na kwa Kristo Yesu Mwokozi wetu."}, {"r": "Warumi 4:14", "t": "Maana ikiwa wale wa sheria ndio warithi, imani imekuwa bure, na ahadi imebatilika."}, {"r": "Zaburi 27:13", "t": "Naamini ya kuwa nitauona wema wa Bwana Katika nchi ya walio hai."}, {"r": "Yohana 1:12", "t": "Bali wote waliompokea aliwapa uwezo wa kufanyika watoto wa Mungu, ndio wale waliaminio jina lake;"}, {"r": "1 Wakorintho 7:12", "t": "Lakini watu wengine nawaambia mimi, wala si Bwana, ya kwamba iwapo ndugu mmoja ana mke asiyeamini, na mke huyo anakubali kukaa naye asimwache."}, {"r": "1 Timotheo 5:12", "t": "nao wana hukumu kwa kuwa wameiacha imani yao ya kwanza."}, {"r": "1 Timotheo 6:2", "t": "Na wale walio na bwana waaminio wasiwadharau kwa kuwa ni ndugu; bali afadhali wawatumikie, kwa sababu hao waishirikio faida ya kazi yao wamekuwa wenye imani na kupendwa. Mambo hayo uyafundishe na kuonya."}, {"r": "Tito 2:2", "t": "ya kwamba wazee wawe wenye kiasi, wastahivu, wenye busara, wazima katika imani na katika upendo na katika saburi."}, {"r": "Yohana 12:44", "t": "Naye Yesu akapaza sauti, akasema, Yeye aniaminiye mimi, haniamini mimi bali yeye aliyenipeleka."}, {"r": "Matendo ya Mitume 19:2", "t": "akawauliza, Je! Mlipokea Roho Mtakatifu mlipoamini? Wakamjibu, La, hata kusikia kwamba kuna Roho Mtakatifu hatukusikia."}, {"r": "Waefeso 6:23", "t": "Amani na iwe kwa ndugu, na pendo, pamoja na imani, zitokazo kwa Mungu Baba na kwa Bwana Yesu Kristo."}, {"r": "Waebrania 11:7", "t": "Kwa imani Nuhu akiisha kuonywa na Mungu katika habari za mambo yasiyoonekana bado, kwa jinsi alivyomcha Mungu, aliunda safina, apate kuokoa nyumba yake. Na hivyo akauhukumu makosa ulimwengu, akawa mrithi wa haki ipatikanayo kwa imani."}, {"r": "Ufunuo wa Yohana 21:5", "t": "Na yeye aketiye juu ya kile kiti cha enzi akasema, Tazama, nayafanya yote kuwa mapya. Akaniambia, Andika ya kwamba maneno hayo ni amini na kweli."}, {"r": "1 Petro 1:5", "t": "Nanyi mnalindwa na nguvu za Mungu kwa njia ya imani hata mpate wokovu ulio tayari kufunuliwa wakati wa mwisho."}, {"r": "Waebrania 11:27", "t": "Kwa imani akatoka Misri, asiogope ghadhabu ya mfalme; maana alistahimili kama amwonaye yeye asiyeonekana."}, {"r": "1 Timotheo 1:2", "t": "kwa Timotheo, mwanangu hasa katika imani. Neema na iwe kwako, na rehema, na amani, zitokazo kwa Mungu Baba na kwa Kristo Yesu Bwana wetu."}, {"r": "Waebrania 11:17", "t": "Kwa imani Ibrahimu alipojaribiwa, akamtoa Isaka awe dhabihu; na yeye aliyezipokea hizo ahadi alikuwa akimtoa mwanawe, mzaliwa pekee;"}, {"r": "Luka 8:48", "t": "Akamwambia Binti, imani yako imekuponya; enenda zako na amani."}, {"r": "Matendo ya Mitume 17:34", "t": "Baadhi ya watu wakashikamana naye, wakaamini; katika hao alikuwamo Dionisio, Mwareopago, na mwanamke mmoja jina lake Damari, na watu wengine pamoja na hao."}, {"r": "Matendo ya Mitume 26:27", "t": "Mfalme Agripa, je! Wawaamini manabii? Najua ya kuwa wawaamini."}, {"r": "Waebrania 13:18", "t": "Tuombeeni; maana tunaamini kwamba tuna dhamiri njema, tukitaka kuwa na mwenendo mwema katika mambo yote."}, {"r": "Yohana 3:18", "t": "Amwaminiye yeye hahukumiwi; asiyeamini amekwisha kuhukumiwa; kwa sababu hakuliamini jina la Mwana pekee wa Mungu."}, {"r": "Waebrania 11:29", "t": "Kwa imani wakapita kati ya Bahari ya Shamu, kama katika nchi kavu; Wamisri walipojaribu kufanya vivyo wakatoswa."}, {"r": "Waefeso 4:5", "t": "Bwana mmoja, imani moja, ubatizo mmoja."}, {"r": "Warumi 4:9", "t": "Basi je! Uheri huo ni kwa hao waliotahiriwa, au kwa hao pia wasiotahiriwa? Kwa kuwa twanena ya kwamba kwake Ibrahimu imani yake ilihesabiwa kuwa ni haki."}], "tumaini": [{"r": "1 Wathesalonike 4:13", "t": "Lakini, ndugu, hatutaki msijue habari zao waliolala mauti, msije mkahuzunika kama na wengine wasio na matumaini."}, {"r": "Zaburi 33:22", "t": "Ee Bwana, fadhili zako zikae nasi, Kama vile tulivyokungoja Wewe."}, {"r": "Zaburi 146:5", "t": "Heri ambaye Mungu wa Yakobo ni msaada wake, Na tumaini lake ni kwa Bwana, Mungu wake,"}, {"r": "Warumi 15:4", "t": "Kwa kuwa yote yaliyotangulia kuandikwa yaliandikwa ili kutufundisha sisi; ili kwa saburi na faraja ya maandiko tupate kuwa na tumaini."}, {"r": "Maombolezo 3:21", "t": "Najikumbusha neno hili, Kwa hiyo nina matumaini."}, {"r": "Wakolosai 1:27", "t": "ambao Mungu alipenda kuwajulisha jinsi ulivyo utajiri wa utukufu wa siri hii katika Mataifa, nao ni Kristo ndani yenu, tumaini la utukufu"}, {"r": "Yeremia 29:11", "t": "Maana nayajua mawazo ninayowawazia ninyi, asema Bwana, ni mawazo ya amani wala si ya mabaya, kuwapa ninyi tumaini siku zenu za mwisho."}, {"r": "Tito 1:2", "t": "katika tumaini la uzima wa milele, ambao Mungu asiyeweza kusema uongo aliuahidi tangu milele;"}, {"r": "Zaburi 119:114", "t": "Ndiwe sitara yangu na ngao yangu, Neno lako nimelingojea."}, {"r": "Zaburi 71:5", "t": "Maana ndiwe taraja langu, Ee Bwana MUNGU, Tumaini langu tokea ujana wangu."}, {"r": "Warumi 8:24", "t": "Kwa maana tuliokolewa kwa taraja; lakini kitu kilichotarajiwa kikionekana, hakuna taraja tena. Kwa maana ni nani anayekitarajia kile akionacho?"}, {"r": "Zaburi 39:7", "t": "Na sasa ninangoja nini, Ee Bwana? Matumaini yangu ni kwako."}, {"r": "Tito 2:13", "t": "tukilitazamia tumaini lenye baraka na mafunuo ya utukufu wa Kristo Yesu, Mungu mkuu na Mwokozi wetu;"}, {"r": "Zaburi 130:5", "t": "Nimemngoja Bwana, roho yangu imengoja, Na neno lake nimelitumainia."}, {"r": "Maombolezo 3:25", "t": "Bwana ni mwema kwa hao wamngojeao, Kwa hiyo nafsi imtafutayo."}, {"r": "Warumi 8:25", "t": "Bali tukikitarajia kitu tusichokiona, twakingojea kwa saburi."}, {"r": "Maombolezo 3:22", "t": "Ni huruma za Bwana kwamba hatuangamii, Kwa kuwa rehema zake hazikomi."}, {"r": "Zaburi 42:5", "t": "Nafsi yangu, kwa nini kuinama, Na kufadhaika ndani yangu? Umtumaini Mungu; Kwa maana nitakuja kumsifu, Aliye afya ya uso wangu, Na Mungu wangu."}, {"r": "Zekaria 9:12", "t": "Irudieni ngome, enyi wafungwa wa tumaini; hata hivi leo nasema ya kwamba nitakurudishia maradufu."}, {"r": "Mithali 24:14", "t": "Basi utaijua hekima kuwa tamu kwa nafsi yako; Ikiwa umekwisha kuiona; Ndipo itakapofuata thawabu; Wala tumaini lako halitabatilika."}, {"r": "Zaburi 42:11", "t": "Nafsi yangu, kwa nini kuinama, Na kufadhaika ndani yangu? Umtumaini Mungu; Kwa maana nitakuja kumsifu, Aliye afya ya uso wangu, Na Mungu wangu."}, {"r": "Wafilipi 1:20", "t": "kama vile nilivyotazamia sana, na kutumaini, kwamba sitaaibika kamwe, bali kwa uthabiti wote, kama sikuzote na sasa vivyo hivyo Kristo ataadhimishwa katika mwili wangu; ikiwa kwa maisha yangu, au ikiwa kwa mauti yangu."}, {"r": "Isaya 40:31", "t": "bali wao wamngojeao Bwana watapata nguvu mpya; watapanda juu kwa mbawa kama tai; watapiga mbio, wala hawatachoka; watakwenda kwa miguu, wala hawatazimia."}, {"r": "Mithali 23:18", "t": "Maana bila shaka iko thawabu; Na tumaini lako halitabatilika."}, {"r": "1 Wathesalonike 5:8", "t": "Lakini sisi tulio wa mchana, tuwe na kiasi, hali tukijivika kifuani imani na upendo, na chapeo yetu iwe tumaini la wokovu."}, {"r": "Warumi 5:5", "t": "na tumaini halitahayarishi; kwa maana pendo la Mungu limekwisha kumiminwa katika mioyo yetu na Roho Mtakatifu tuliyepewa sisi."}, {"r": "1 Petro 1:3", "t": "Ahimidiwe Mungu, Baba wa Bwana wetu Yesu Kristo, ambaye kwa rehema zake nyingi alituzaa mara ya pili ili tupate tumaini lenye uzima kwa kufufuka kwake Yesu Kristo katika wafu;"}, {"r": "1 Petro 3:15", "t": "Mwe tayari siku zote kumjibu kila mtu awaulizaye habari za tumaini lililo ndani yenu; lakini kwa upole na kwa hofu."}, {"r": "Maombolezo 3:24", "t": "Bwana ndiye fungu langu, husema nafsi yangu, Kwa hiyo nitamtumaini yeye."}, {"r": "Waebrania 11:1", "t": "Basi imani ni kuwa na hakika ya mambo yatarajiwayo, ni bayana ya mambo yasiyoonekana."}, {"r": "Waebrania 6:19", "t": "tuliyo nayo kama nanga ya roho, yenye salama, yenye nguvu, yaingiayo hata mle mlimo ndani ya pazia,"}, {"r": "Yeremia 17:7", "t": "Amebarikiwa mtu yule anayemtegemea Bwana, Ambaye Bwana ni tumaini lake."}, {"r": "Ayubu 11:18", "t": "Nawe utakuwa salama, kwa sababu kuna matumaini; Naam, utatafutatafuta kando yako, na kupumzika katika salama."}, {"r": "Waebrania 10:23", "t": "Na mlishike sana ungamo la tumaini letu, lisigeuke; maana yeye aliyeahidi ni mwaminifu;"}, {"r": "Zaburi 31:24", "t": "Iweni hodari, mpige moyo konde, Ninyi nyote mnaomngoja Bwana."}, {"r": "Warumi 12:12", "t": "kwa tumaini, mkifurahi; katika dhiki, mkisubiri; katika kusali, mkidumu;"}, {"r": "Yeremia 17:8", "t": "Maana atakuwa kama mti uliopandwa kando ya maji, Uenezao mizizi yake karibu na mto; Hautaona hofu wakati wa hari ujapo, Bali jani lake litakuwa bichi; Wala hautahangaika mwaka wa uchache wa mvua, Wala hautaacha kuzaa matunda."}, {"r": "Warumi 15:13", "t": "Basi Mungu wa tumaini na awajaze ninyi furaha yote na amani katika kuamini, mpate kuzidi sana kuwa na tumaini, katika nguvu za Roho Mtakatifu."}, {"r": "Zaburi 22:4", "t": "Baba zetu walikutumaini Wewe, Walitumaini, na Wewe ukawaokoa."}, {"r": "Isaya 47:10", "t": "Maana umeutumainia ubaya wako; umesema, Hapana anionaye; hekima yako, na maarifa yako yamekupotosha, nawe umesema moyoni mwako, Mimi ndiye, wala hapana mwingine zaidi yangu mimi."}, {"r": "Isaya 20:5", "t": "Nao watafadhaika, na kuona haya kwa ajili ya Kushi, matumaini yao, na Misri, utukufu wao."}, {"r": "Luka 6:34", "t": "Na mkiwakopesha watu huku mkitumaini kupata kitu kwao, mwaonyesha fadhili gani? Hata wenye dhambi huwakopesha wenye dhambi, ili warudishiwe vile vile."}, {"r": "Yeremia 29:31", "t": "Uwapelekee habari watu wote waliohamishwa, kusema, Bwana asema hivi, katika habari za Shemaya, Mnehelami; Kwa sababu Shemaya amewatabiria ninyi, lakini sikumtuma mimi, naye amewatumainisha neno la uongo;"}, {"r": "Zaburi 59:9", "t": "Ee nguvu zangu, nitakungoja Wewe, Maana Mungu ndiye aliye ngome yangu"}, {"r": "2 Wakorintho 3:12", "t": "Basi, kwa kuwa mna taraja la namna hii, twatumia ujasiri mwingi;"}, {"r": "Zaburi 146:3", "t": "Msiwatumainie wakuu, Wala binadamu ambaye hakuna wokovu kwake."}, {"r": "Zaburi 71:14", "t": "Nami nitatumaini daima, Nitazidi kuongeza sifa zake zote."}, {"r": "Isaya 42:17", "t": "Watarudishwa nyuma, wataaibishwa sana, hao wanaotumainia sanamu za mawe, na kuziambia sanamu za madini, Ninyi ndinyi miungu yetu."}, {"r": "Isaya 50:10", "t": "Ni nani miongoni mwenu amchaye Bwana, aitiiye sauti ya mtumishi wake? Yeye aendaye katika giza, wala hana nuru, naye alitumainia jina la Bwana, na kumtegemea Mungu wake."}, {"r": "Habakuki 3:16", "t": "Nikasikia, na tumbo langu likatetemeka, Midomo yangu ikatikisika kwa sauti ile; Ubovu ukaingia mifupani mwangu, Nikatetemeka katika mahali pangu; Ili nipate kuingoja ile siku ya dhiki, Kundi lao washambuliao wakweapo juu ya watu."}, {"r": "1 Petro 1:13", "t": "Kwa hiyo vifungeni viuno vya nia zenu, na kuwa na kiasi; mkiitumainia kwa utimilifu ile neema mtakayoletewa katika ufunuo wake Yesu Kristo."}, {"r": "Yeremia 28:15", "t": "Kisha nabii Yeremia akamwambia nabii Hanania, Sikia sasa, Ee Hanania; Bwana hakukutuma; lakini unawatumainisha watu hawa maneno ya uongo."}, {"r": "Zaburi 69:20", "t": "Laumu imenivunja moyo, Nami ninaugua sana. Nikangoja aje wa kunihurumia, wala hakuna; Na wa kunifariji, wala sikumwona mtu."}, {"r": "Matendo ya Mitume 23:6", "t": "Paulo alipotambua ya kuwa sehemu moja ni Masadukayo, na sehemu ya pili ni Mafarisayo, akapaza sauti yake katika ile baraza, Ndugu zangu, mimi ni Farisayo mwana wa Farisayo; mimi ninahukumiwa kwa ajili ya tumaini la ufufuo wa wafu."}, {"r": "Ayubu 4:6", "t": "Je! Dini yako siyo mataraja yako, Na matumaini yako si huo uelekevu wa njia zako?"}, {"r": "Zaburi 119:42", "t": "Nami nitamjibu neno anilaumuye, Kwa maana nalitumainia neno lako."}, {"r": "Isaya 30:18", "t": "Kwa ajili ya hayo Bwana atangoja, ili awaonee huruma, na kwa ajili ya hayo atatukuzwa, ili awarehemu; kwa maana Bwana ni Mungu wa hukumu; heri wote wamngojao."}, {"r": "Zaburi 69:6", "t": "Wanaokungoja Wewe wasiaibishwe, Kwa ajili yangu, Bwana, MUNGU wa majeshi. Wanaokutafuta Wewe wasifedheheshwe, Kwa ajili yangu, Ee Mungu wa Israeli."}, {"r": "Zaburi 119:147", "t": "Kutangulia mapambazuko naliomba msaada, Naliyangojea maneno yako kwa tumaini."}, {"r": "Wafilipi 2:19", "t": "Walakini natumaini katika Bwana Yesu kumtuma Timotheo afike kwenu karibu, nifarijiwe na mimi, nikiijua hali yenu."}, {"r": "Zaburi 115:8", "t": "Wazifanyao watafanana nazo, Kila mmoja anayezitumainia."}, {"r": "1 Yohana 3:3", "t": "Na kila mwenye matumaini haya katika yeye hujitakasa, kama yeye alivyo mtakatifu."}, {"r": "2 Wakorintho 10:7", "t": "Yaangalieni yaliyo mbele ya macho yenu. Mtu akijitumainia mwenyewe ya kuwa ni mtu wa Kristo, na afikiri hivi pia nafsini mwake, ya kwamba kama yeye alivyo mtu wa Kristo, vivyo hivyo na sisi."}, {"r": "2 Wakorintho 9:4", "t": "kusudi, wakija Wamakedonia pamoja nami, na kuwakuta hamjawa tayari, tusije tukatahayarika sisi, (tusiseme ninyi), katika hali hiyo ya kutumaini."}, {"r": "Yeremia 31:17", "t": "Tena liko tumaini kwa siku zako za mwisho, asema Bwana; na watoto wako watarejea hata mpaka wao wenyewe."}, {"r": "Matendo ya Mitume 16:19", "t": "Basi bwana zake walipoona ya kuwa tumaini la faida yao limewapotea, wakawakamata Paulo na Sila, wakawakokota mpaka sokoni mbele ya wakuu wa mji;"}, {"r": "Zaburi 78:22", "t": "Kwa kuwa hawakumwamini Mungu, Wala hawakuutumainia wokovu wake."}, {"r": "Ayubu 24:22", "t": "Lakini Mungu huwadumisha wenye uwezo kwa nguvu zake; Huinuka, wasiokuwa na tumaini la kuishi."}, {"r": "Waefeso 1:12", "t": "Nasi katika huyo tupate kuwa sifa ya utukufu wake, sisi tuliotangulia kumwekea Kristo tumaini letu."}, {"r": "Isaya 31:1", "t": "Ole wao watelemkao kwenda Misri wapate msaada, na kutegemea farasi; watumainio magari kwa kuwa ni mengi, na wapanda farasi kwa kuwa ni hodari sana; lakini hawamwangalii Mtakatifu wa Israeli, wala hawamtafuti Bwana!"}, {"r": "Waebrania 6:11", "t": "Nasi twataka sana kila mmoja wenu aidhihirishe bidii ile ile, kwa utimilifu wa matumaini hata mwisho;"}, {"r": "Matendo ya Mitume 20:23", "t": "isipokuwa Roho Mtakatifu mji kwa mji hunishuhudia akisema, ya kwamba vifungo na dhiki vyaningoja."}, {"r": "Ayubu 32:4", "t": "Basi huyo Elihu alikuwa anangoja ili anene na Ayubu, kwa sababu hao wengine walikuwa wazee kuliko yeye."}, {"r": "Sefania 3:12", "t": "Lakini nitasaza ndani yako watu walioonewa na maskini, nao watalitumainia jina la Bwana."}, {"r": "Mithali 3:26", "t": "Kwa kuwa Bwana atakuwa tumaini lako, Naye atakulinda mguu wako usinaswe."}, {"r": "Yeremia 13:25", "t": "Hiyo ndiyo kura yako, fungu lako ulilopimiwa na mimi, asema Bwana; kwa kuwa umenisahau, na kuutumainia uongo."}, {"r": "Wagalatia 5:5", "t": "Maana sisi kwa Roho tunalitazamia tumaini la haki kwa njia ya imani."}, {"r": "Mithali 14:32", "t": "Mtu mbaya husukumwa chini katika kutenda mabaya kwake; Bali mwenye haki ana matumaini katika kufa kwake."}, {"r": "Wafilipi 1:25", "t": "Nami nikitumaini hayo, najua ya kuwa nitakaa na kudumu pamoja nanyi, ili mpate kuendelea na kufurahi katika imani;"}, {"r": "2 Wakorintho 8:22", "t": "Nasi pamoja nao tumemtuma ndugu yetu tuliyemwona mara nyingi katika mambo mengi kuwa ana bidii, na sasa ana bidii zaidi sana kwa sababu ya tumaini kuu alilo nalo kwenu."}, {"r": "Ayubu 14:7", "t": "Kwani yako matumaini ya mti, ya kuwa ukikatwa utachipuka tena, Wala machipukizi yake hayatakoma."}, {"r": "Isaya 20:6", "t": "Na mwenyeji wa nchi ya pwani atasema katika siku hiyo, Angalia, haya ndiyo yaliyowapata watu wale tuliowatumaini, ambao tuliwakimbilia watuokoe na mfalme wa Ashuru; na sisi je! Twawezaje kupona?"}, {"r": "Isaya 57:10", "t": "Ulikuwa umechoka kwa ajili ya urefu wa njia yako; lakini hukusema, Hapana matumaini; ulipata kuhuishwa nguvu zako; kwa sababu hiyo hukuugua."}, {"r": "Ayubu 17:15", "t": "Basi, tumaini langu li wapi? Na tumaini langu, ni nani atakayeliona?"}, {"r": "Warumi 5:2", "t": "ambaye kwa yeye tumepata kwa njia ya imani kuifikia neema hii ambayo mnasimama ndani yake; na kufurahi katika tumaini la utukufu wa Mungu."}, {"r": "1 Wathesalonike 2:8", "t": "Vivyo hivyo nasi tukiwatumaini kwa upendo mwingi, tuliona furaha kuwapa, si Injili ya Mungu tu, bali na roho zetu pia, kwa sababu mmekuwa wapendwa wetu."}, {"r": "1 Samueli 1:23", "t": "Elkana, mumewe, akamwambia, Haya, fanya uonavyo vema; ngoja hata utakapomwachisha maziwa; Bwana na alithibitishe neno lake tu. Basi yule mwanamke akangoja, akamnyonyesha mtoto wake, hata akamwachisha maziwa."}, {"r": "Mithali 19:18", "t": "Mrudi mwanao, kwa maana liko tumaini; Wala usiikaze nafsi yako kwa kuangamia kwake."}, {"r": "2 Wakorintho 1:7", "t": "Na tumaini letu kwa ajili yenu ni imara, tukijua ya kuwa kama vile mlivyo washiriki wa yale mateso, vivyo hivyo mmekuwa washiriki wa zile faraja."}, {"r": "Isaya 30:2", "t": "waendao kutelemkia Misri wala hawakuuliza kinywani mwangu; ili wajitie nguvu kwa nguvu za Farao, na kutumainia kivuli cha Misri."}, {"r": "Maombolezo 3:29", "t": "Na atie kinywa chake mavumbini; Ikiwa yamkini liko tumaini."}, {"r": "Mithali 11:7", "t": "Mtu mwovu atakapokufa, taraja lake lapotea; Na matumaini ya uovu huangamia."}, {"r": "Zaburi 13:5", "t": "Nami nimezitumainia fadhili zako; Moyo wangu na uufurahie wokovu wako."}, {"r": "Ayubu 19:10", "t": "Amenibomoa pande zote, nami nimetoweka; Na tumaini langu ameling'oa kama mti."}, {"r": "Zaburi 78:7", "t": "Wamwekee Mungu tumaini lao. Wala wasiyasahau matendo ya Mungu, Bali wazishike amri zake."}, {"r": "Luka 24:21", "t": "Nasi tulikuwa tukitumaini ya kuwa yeye ndiye atakayewakomboa Israeli. Zaidi ya hayo yote, leo ni siku ya tatu tangu yalipotendeka mambo hayo;"}, {"r": "Isaya 30:12", "t": "Basi kwa ajili ya hayo Mtakatifu wa Israeli asema hivi, Kwa sababu mwalidharau neno hili, na kutumainia jeuri na ukaidi, na kuyategemea hayo;"}, {"r": "Hosea 10:13", "t": "Mmelima dhuluma, mmevuna uovu; mmekula matunda ya uongo; kwa maana uliitumainia njia yako, na wingi wa mashujaa wako."}, {"r": "Yeremia 50:7", "t": "Watu wote waliowaona wamewala; na adui zao walisema, Sisi hatuna hatia, kwa kuwa hao wametenda dhambi juu ya Bwana, aliye kao la haki, yaani, Bwana, tumaini la baba zao."}, {"r": "Mithali 10:28", "t": "Matumaini yao wenye haki yatakuwa furaha; Bali kutaraji kwao wasio haki kutapotea."}, {"r": "Zaburi 119:49", "t": "Likumbuke neno ulilomwambia mtumishi wako, Kwa sababu umenitumainisha."}, {"r": "Ayubu 7:6", "t": "Siku zangu hupita upesi kuliko chombo cha kufumia, Nazo zapita pasipokuwa na matumaini."}, {"r": "Zaburi 25:3", "t": "Naam, wakungojao hawataaibika hata mmoja; Wataaibika watendao uhaini bila sababu."}, {"r": "Zaburi 62:5", "t": "Nafsi yangu, umngoje Mungu peke yake kwa kimya. Tumaini langu hutoka kwake."}, {"r": "Wakolosai 1:5", "t": "kwa sababu ya tumaini mlilowekewa akiba mbinguni; ambalo habari zake mlizisikia zamani kwa neno la kweli ya Injili;"}, {"r": "Yeremia 14:8", "t": "Wewe uliye tumaini la Israeli, wewe uliye Mwokozi wake wakati wa taabu, kwa nini wewe umekuwa kama mtu akaaye katika nchi, hali ya mgeni, na kama mtu mwenye kusafiri, ageukaye upande ili kukaa usiku mmoja tu?"}, {"r": "Zaburi 9:18", "t": "Kwa maana mhitaji hatasahauliwa daima; Matumaini ya wanyonge hayatapotea milele."}, {"r": "Waefeso 1:18", "t": "macho ya mioyo yenu yatiwe nuru, mjue tumaini la mwito wake jinsi lilivyo; na utajiri wa utukufu wa urithi wake katika watakatifu jinsi ulivyo;"}, {"r": "Zaburi 25:21", "t": "Ukamilifu na unyofu zinihifadhi, Maana nakungoja Wewe."}, {"r": "Zaburi 56:3", "t": "Siku ya hofu yangu nitakutumaini Wewe;"}, {"r": "Yeremia 17:13", "t": "Ee Bwana, tumaini la Israeli, wote wakuachao watatahayarika. Wao watakaojitenga nami wataandikwa katika mchanga, kwa sababu wamemwacha Bwana, kisima cha maji yaliyo hai."}, {"r": "Warumi 5:4", "t": "na kazi ya saburi ni uthabiti wa moyo; na kazi ya uthabiti wa moyo ni tumaini;"}, {"r": "2 Wakorintho 10:15", "t": "wala hatujisifu zaidi ya kadiri yetu, yaani, katika taabu za watu wengine; bali tukiwa na tumaini ya kwamba, imani yenu ikuapo, tutakuzwa kwenu kwa kadiri ya kipimo chetu, na kupata ziada;"}, {"r": "Matendo ya Mitume 24:15", "t": "Nina tumaini kwa Mungu, ambalo hata hao nao wanalitazamia, ya kwamba kutakuwa na ufufuo wa wafu, wenye haki na wasio haki pia."}, {"r": "Zaburi 9:10", "t": "Nao wakujuao jina lako wakutumaini Wewe, Maana Wewe, Bwana hukuwaacha wakutafutao."}, {"r": "Wagalatia 5:10", "t": "Nina matumaini kwenu katika Bwana, ya kwamba hamtakuwa na nia ya namna nyingine. Lakini yeye anayewafadhaisha atachukua hukumu yake, awaye yote."}, {"r": "Mathayo 12:21", "t": "Na jina lake Mataifa watalitumainia."}, {"r": "Isaya 36:4", "t": "Yule amiri akawaambia, Haya, mwambieni Hezekia, kwamba mfalme mkuu, mfalme wa Ashuru, asema hivi, Ni tumaini gani hili unalolitumainia?"}, {"r": "Isaya 5:2", "t": "Akafanya handaki kulizunguka pande zote, Akatoa mawe yake, Akapanda ndani yake mzabibu ulio mzuri, Akajenga mnara katikati yake, Akachimba shinikizo ndani yake; Akatumaini ya kuwa utazaa zabibu, Nao ukazaa zabibumwitu."}, {"r": "1 Timotheo 5:5", "t": "Basi yeye aliye mjane kweli kweli, ameachwa peke yake, huyo amemwekea Mungu tumaini lake, naye hudumu katika maombi na sala mchana na usiku."}, {"r": "Mithali 21:22", "t": "Mwenye hekima huupandia mji wao wenye nguvu; Na kuziangusha nguvu za tumaini lao."}, {"r": "Hosea 2:15", "t": "Nami nitampa mashamba yake ya mizabibu toka huko, na bonde la Akori kuwa mlango wa tumaini; naye ataniitikia huko, kama siku zile za ujana wake, na kama siku ile alipopanda kutoka nchi ya Misri."}, {"r": "Isaya 30:15", "t": "Kwa maana Bwana MUNGU, Mtakatifu wa Israeli, asema hivi, Kwa kurudi na kustarehe mtaokolewa; nguvu zenu zitakuwa katika kutulia na kutumaini; lakini hamkukubali."}, {"r": "1 Wathesalonike 1:3", "t": "Wala hatuachi kuikumbuka kazi yenu ya imani, na taabu yenu ya upendo, na saburi yenu ya tumaini lililo katika Bwana wetu Yesu Kristo, mbele za Mungu Baba yetu."}, {"r": "Waebrania 6:18", "t": "ili kwa vitu viwili visivyoweza kubadilika, ambavyo katika hivyo Mungu hawezi kusema uongo, tupate faraja iliyo imara, sisi tuliokimbilia kuyashika matumaini yale yawekwayo mbele yetu;"}, {"r": "Zaburi 52:8", "t": "Bali mimi ni kama mzeituni Umeao katika nyumba ya Mungu. Nazitumainia fadhili za Mungu milele na milele."}, {"r": "Yeremia 18:12", "t": "Lakini wao wasema, Hapana tumaini lo lote; maana sisi tutafuata mawazo yetu wenyewe, nasi tutatenda kila mmoja wetu kwa kuufuata ushupavu wa moyo wake mbaya."}, {"r": "1 Wakorintho 9:10", "t": "Au yamkini anena hayo kwa ajili yetu? Naam, yaliandikwa kwa ajili yetu; kwa kuwa alimaye nafaka ni haki yake kulima kwa matumaini, naye apuraye nafaka ni haki yake kutumaini kupata sehemu yake."}, {"r": "Mithali 14:26", "t": "Kumcha Bwana ni tumaini imara; Watoto wake watakuwa na kimbilio."}, {"r": "1 Petro 1:21", "t": "ambao kwa yeye mmekuwa wenye kumwamini Mungu, aliyemfufua katika wafu akampa utukufu; hata imani yenu na tumaini lenu liwe kwa Mungu."}, {"r": "Yeremia 49:4", "t": "Mbona unajisifu kwa sababu ya mabonde, bonde lako litiririkalo, Ee binti mwenye kuasi? Utumainiaye hazina zako, ukisema, Ni nani atakayenijilia?"}, {"r": "Ayubu 14:19", "t": "Maji mengi huyapunguza mawe; Mafuriko yake huuchukua mchanga wa nchi; Nawe matumaini ya wanadamu wayaangamiza."}, {"r": "2 Wakorintho 8:5", "t": "Tena walitenda hivi si kama tulivyotumaini tu, bali kwanza walijitoa nafsi zao kwa Bwana; na kwetu pia, kwa mapenzi ya Mungu."}, {"r": "Zaburi 104:27", "t": "Hao wote wanakungoja Wewe, Uwape chakula chao kwa wakati wake."}, {"r": "2 Wakorintho 2:3", "t": "Nami naliwaandikia neno lilo hilo, ili nijapo nisitiwe huzuni na wale ambao ilinipasa kuwafurahia; nikiwatumaini ninyi nyote kwamba furaha yangu ni yenu nyote pia."}, {"r": "Maombolezo 4:17", "t": "Macho yetu yamechoka Kwa kuutazamia bure msaada wetu; Katika kungoja kwetu tumengojea taifa Lisiloweza kutuokoa."}, {"r": "Zaburi 135:18", "t": "Wazifanyao watafanana nazo, Na kila mmoja anayezitumainia."}, {"r": "Isaya 30:3", "t": "Basi, nguvu za Farao zitakuwa aibu yenu, na kutumainia kivuli cha Misri kutakuwa kufadhaika kwenu."}, {"r": "1 Wathesalonike 2:19", "t": "Maana tumaini letu, au furaha yetu, au taji ya kujionea fahari, ni nini? Je! Si ninyi, mbele za Bwana wetu Yesu, wakati wa kuja kwake?"}, {"r": "Zaburi 49:6", "t": "Wa hao wanaozitumainia mali zao, Na kujisifia wingi wa utajiri wao;"}, {"r": "Zaburi 143:8", "t": "Unifanye kusikia fadhili zako asubuhi, Kwa maana nimekutumaini Wewe. Unijulishe njia nitakayoiendea, Kwa maana nakuinulia nafsi yangu."}, {"r": "Matendo ya Mitume 27:33", "t": "Na kulipokuwa kukipambauka Paulo akawasihi wote wale chakula, akisema, Leo ni siku ya kumi na nne kungoja na kufunga, hamkula kitu cho chote."}, {"r": "Mithali 28:26", "t": "Mwenye kujitumainia moyo wake ni mjinga; Bali yeye aendaye kwa busara ataokolewa."}, {"r": "Mika 7:5", "t": "Msimwamini rafiki, msimwekee kiongozi tumaini; ilinde milango ya midomo ya kinywa chako ili mkeo alalaye kifuani mwako asijue habari."}, {"r": "Isaya 51:5", "t": "Haki yangu i karibu, wokovu wangu umekuwa wazi, na mikono yangu itawahukumu kabila za watu; visiwa vitaningoja, navyo vitautumainia mkono wangu."}, {"r": "Tito 3:7", "t": "ili tukihesabiwa haki kwa neema yake, tupate kufanywa warithi wa uzima wa milele, kama lilivyo tumaini letu."}, {"r": "Mithali 22:19", "t": "Ili matumaini yako uyaweke kwa Bwana, leo nimekujulisha wewe haya, naam, wewe."}, {"r": "Yeremia 49:11", "t": "Waache watoto wako wasio na baba, mimi nitawahifadhi hai, na wajane wako na wanitumaini mimi."}, {"r": "Zaburi 118:8", "t": "Ni heri kumkimbilia Bwana Kuliko kuwatumainia wanadamu."}, {"r": "Isaya 32:17", "t": "Na kazi ya haki itakuwa amani; na mazao ya haki yatakuwa ni utulivu na matumaini daima."}, {"r": "2 Wakorintho 13:6", "t": "Lakini natumaini kama mtajua ya kuwa sisi hatukukataliwa."}, {"r": "Waebrania 3:6", "t": "bali Kristo, kama mwana, juu ya nyumba ya Mungu; ambaye nyumba yake ni sisi, kama tukishikamana sana na ujasiri wetu na fahari ya taraja letu mpaka mwisho."}, {"r": "Ayubu 8:14", "t": "Uthabiti wake utavunjika, Na matumaini yake huwa ni nyuzi za buibui."}, {"r": "Zaburi 119:116", "t": "Unitegemeze sawasawa na ahadi yako, nikaishi, Wala usiniache niyaaibikie matumaini yangu."}, {"r": "2 Wakorintho 1:15", "t": "Nami nikiwa na tumaini hilo nalitaka kufika kwenu hapo kwanza, ili mpate karama ya pili;"}, {"r": "Isaya 36:6", "t": "Tazama, unaitumainia fimbo ya mwanzi huu uliopondeka, yaani, Misri, ambayo, mtu akitegemea juu yake, humwingia mkononi na kumchoma; ndivyo alivyo Farao, mfalme wa Misri, kwa wote wamtumainio."}, {"r": "Zaburi 31:14", "t": "Lakini mimi nakutumaini Wewe, Bwana, Nimesema, Wewe ndiwe Mungu wangu."}, {"r": "Yeremia 7:8", "t": "Angalieni, mnatumainia maneno ya uongo, yasiyoweza kufaidia."}, {"r": "Ayubu 29:21", "t": "Watu walitega masikio kunisikiliza, na kungoja, Wakanyamaa kimya wapate sikia mashauri yangu."}, {"r": "Wafilipi 3:3", "t": "Maana sisi tu tohara, tumwabuduo Mungu kwa Roho, na kuona fahari juu ya Kristo Yesu, wala hatuutumainii mwili."}, {"r": "Wafilipi 2:23", "t": "Basi, natumaini kumtuma huyo mara, hapo nitakapojua yatakayonipata."}, {"r": "Zekaria 9:5", "t": "Ashkeloni ataona haya na kuogopa; Gaza pia, naye atafadhaika sana; na Ekroni, kwa maana taraja lake litatahayarika; na mfalme ataangamia toka Gaza, na Ashkeloni atakuwa hana watu."}, {"r": "Zaburi 16:9", "t": "Kwa hiyo moyo wangu unafurahi, Nao utukufu wangu unashangilia, Naam, mwili wangu nao utakaa kwa kutumaini."}, {"r": "Luka 6:35", "t": "Bali wapendeni adui zenu, tendeni mema, na kukopesha msitumaini kupata malipo, na thawabu yenu itakuwa nyingi; nanyi mtakuwa wana wa Aliye juu, kwa kuwa yeye ni mwema kwa wasiomshukuru, na waovu."}, {"r": "Zaburi 33:21", "t": "Maana mioyo yetu itamfurahia, Kwa kuwa tumelitumainia jina lake takatifu."}, {"r": "Zaburi 118:9", "t": "Ni heri kumkimbilia Bwana. Kuliko kuwatumainia wakuu."}, {"r": "Ayubu 27:8", "t": "Kwani tumaini la mpotovu ni nini, ingawa ajipatia faida, Hapo Mungu amwondoleapo roho yake?"}, {"r": "Isaya 33:2", "t": "Ee Bwana, uturehemu; tumekungoja wewe; uwe wewe mkono wetu"}, {"r": "Zaburi 52:7", "t": "Kumbe! Huyu ndiye mtu yule, Asiyemfanya Mungu kuwa nguvu zake. Aliutumainia wingi wa mali zake, Na kujifanya hodari kwa madhara yake."}, {"r": "Wafilipi 3:4", "t": "Walakini mimi ningeweza kuutumainia mwili. Mtu ye yote akijiona kuwa anayo sababu ya kuutumainia mwili, mimi zaidi."}, {"r": "Isaya 36:9", "t": "Wawezaje, basi, kurudisha nyuma uso wa akida mmoja wa watumishi walio wadogo wa bwana wangu, na kuitumainia Misri upewe magari na farasi?"}, {"r": "Isaya 12:2", "t": "Tazama, Mungu ndiye wokovu wangu; Nitatumaini wala sitaogopa; Maana Bwana YEHOVA ni nguvu zangu na wimbo wangu; Naye amekuwa wokovu wangu."}, {"r": "Zaburi 86:2", "t": "Unihifadhi nafsi yangu, Maana mimi ni mcha Mungu. Wewe uliye Mungu wangu, Umwokoe mtumishi wako anayekutumaini."}, {"r": "Waefeso 3:12", "t": "Katika yeye tunao ujasiri na uwezo wa kukaribia katika tumaini kwa njia ya kumwamini."}, {"r": "Yeremia 7:4", "t": "Msitumainie maneno ya uongo, mkisema, Hekalu la Bwana, Hekalu la Bwana, Hekalu la Bwana ndiyo haya."}, {"r": "1 Timotheo 6:17", "t": "Walio matajiri wa ulimwengu wa sasa uwaagize wasijivune, wala wasiutumainie utajiri usio yakini, bali wamtumaini Mungu atupaye vitu vyote kwa wingi ili tuvitumie kwa furaha."}, {"r": "Zaburi 55:23", "t": "Nawe, Ee Mungu, utawatelemsha, Walifikilie shimo la uharibifu; Watu wa damu na hila hawataishi nusu ya siku zao, Bali mimi nitakutumaini Wewe."}, {"r": "Matendo ya Mitume 28:20", "t": "Basi kwa ajili ya hayo, nimewaita mje kunitazama na kusema nami; kwa maana nimefungwa kwa mnyororo huu kwa ajili ya tumaini la Israeli."}, {"r": "1 Wakorintho 13:7", "t": "huvumilia yote; huamini yote; hutumaini yote; hustahimili yote."}, {"r": "Isaya 26:3", "t": "Utamlinda yeye ambaye moyo wake umekutegemea Katika amani kamilifu, kwa kuwa anakutumaini."}, {"r": "Yeremia 2:25", "t": "Zuia mguu wako usikose kiatu, na koo yako isiwe na kiu; lakini wewe ulisema, Hapana matumaini kabisa; la, maana nimewapenda wageni, nami nitawafuata."}, {"r": "1 Petro 3:20", "t": "watu wasiotii hapo zamani, uvumilivu wa Mungu ulipokuwa ukingoja, siku za Nuhu, safina ilipokuwa ikitengenezwa; ambamo ndani yake wachache, yaani, watu wanane, waliokoka kwa maji."}, {"r": "Maombolezo 3:18", "t": "Nikasema, Nguvu zangu zimepotea, Na tumaini langu kwa Bwana."}, {"r": "Ayubu 8:13", "t": "Ndivyo ulivyo mwisho wa hao wamsahauo Mungu; Na matumaini yake huyo mbaya huangamia;"}, {"r": "Ayubu 6:20", "t": "Wametahayari kwa sababu walitumaini; Wakaja huku, nao walifadhaika."}, {"r": "Yakobo 5:7", "t": "Kwa hiyo ndugu, vumilieni, hata kuja kwake Bwana. Tazama, mkulima hungoja mazao ya nchi yaliyo ya thamani, huvumilia kwa ajili yake hata yatakapopata mvua ya kwanza na ya mwisho."}, {"r": "Isaya 26:8", "t": "Naam, katika njia ya hukumu zako Sisi tumekungoja, Ee Bwana; Shauku ya nafsi zetu inaelekea Jina lako na ukumbusho wako."}, {"r": "Matendo ya Mitume 2:26", "t": "Kwa hiyo moyo wangu ukapendezewa, ulimi wangu ukafurahi; Tena mwili wangu nao utakaa katika matumaini."}, {"r": "Waefeso 2:12", "t": "kwamba zamani zile mlikuwa hamna Kristo, mmefarakana na jamii ya Israeli, wageni wasio wa maagano ya ahadi ile. Mlikuwa hamna tumaini, hamna Mungu duniani."}, {"r": "Ayubu 31:24", "t": "Ikiwa nimeifanya dhahabu kuwa tumaini langu, Na kuiambia dhahabu safi, Wewe u tegemeo langu;"}, {"r": "Isaya 57:13", "t": "Utakapolia, na wakuponye hao uliowakusanya; lakini upepo utawachukua; uvuvio tu utawachukulia mbali; lakini yeye anayenitumaini ataimiliki nchi, na kuurithi mlima wangu mtakatifu."}, {"r": "Wakolosai 1:23", "t": "mkidumu tu katika ile imani, hali mmewekwa juu ya msingi, mkawa imara; msipogeuzwa na kuliacha tumaini la Injili mliyosikia habari zake, iliyohubiriwa katika viumbe vyote vilivyo chini ya mbingu; ambayo mimi Paulo nalikuwa mhudumu wake."}, {"r": "Ayubu 18:14", "t": "Atang'olewa katika hema yake aliyokuwa akiitumaini; Naye atapelekwa kwake mfalme wa utisho."}, {"r": "Isaya 5:7", "t": "Kwa maana shamba la mizabibu la Bwana wa majeshi ndilo nyumba ya Israeli, na watu wa Yuda ni mche wake wa kupendeza; akatumaini kuona hukumu ya haki, na kumbe! Aliona dhuluma; alitumaini kuona haki, na kumbe! Alisikia kilio."}, {"r": "Zaburi 130:6", "t": "Nafsi yangu inamngoja Bwana, Kuliko walinzi waingojavyo asubuhi, Naam, walinzi waingojao asubuhi."}, {"r": "Yeremia 48:7", "t": "Maana, kwa kuwa umeyatumainia matendo yako, na hazina zako, wewe nawe utatwaliwa; na Kemoshi atatoka aende katika uhamisho, makuhani wake na wakuu wake pamoja."}, {"r": "Ayubu 5:16", "t": "Basi hivi huyo maskini ana matumaini, Na uovu hufumba kinywa chake."}, {"r": "Isaya 5:4", "t": "Je! Ni kazi gani iliyoweza kutendeka ndani ya shamba langu la mizabibu nisiyoitenda? Basi, nilipotumaini ya kuwa litazaa zabibu, mbona lilizaa zabibumwitu?"}, {"r": "2 Wakorintho 3:4", "t": "Na tumaini hilo tunalo mbele za Mungu kwa njia ya Kristo."}, {"r": "Mhubiri 9:4", "t": "Kwa kuwa liko tumaini kwa yule aliyeambatana na wote walio hai; (maana ni afadhali mbwa aliye hai kuliko simba aliyekufa);"}, {"r": "Zaburi 40:4", "t": "Heri aliyemfanya Bwana kuwa tumaini lake, Wala hakuwaelekea wenye kiburi, Wala hao wanaogeukia uongo."}, {"r": "Yeremia 7:14", "t": "basi, nitaitenda nyumba hii, iitwayo kwa jina langu, mnayoitumainia, na mahali hapa nilipowapa ninyi na baba zenu, kama nilivyopatenda Shilo."}, {"r": "Waebrania 7:19", "t": "(kwa maana ile sheria haikukamilisha neno); na pamoja na hayo kuliingizwa matumaini yaliyo mazuri zaidi, ambayo kwa hayo twamkaribia Mungu."}, {"r": "Ayubu 13:15", "t": "Tazama, ataniua; sina tumaini;"}, {"r": "Yeremia 48:13", "t": "Na Moabu ataona haya kwa ajili ya Kemoshi, kama nyumba ya Israeli ilivyoona haya kwa ajili ya Betheli, matumaini yao."}, {"r": "Zaburi 84:12", "t": "Ee Bwana wa majeshi, Heri mwanadamu anayekutumaini Wewe."}, {"r": "Ayubu 11:20", "t": "Lakini macho ya waovu yataingia kiwi, Nao hawatakuwa na njia ya kukimbilia, Na matumaini yao yatakuwa ni kutoa roho."}, {"r": "Waefeso 4:4", "t": "Mwili mmoja, na Roho mmoja, kama na mlivyoitwa katika tumaini moja la wito wenu."}, {"r": "Matendo ya Mitume 26:7", "t": "ambayo kabila zetu kumi na mbili wanataraji kuifikia, wakimwabudu Mungu kwa bidii mchana na usiku. Nami ninashitakiwa na Wayahudi kwa ajili ya tumaini hilo, Ee Mfalme."}, {"r": "Habakuki 2:18", "t": "Sanamu ya kuchora yafaa nini, hata yeye aliyeifanya ameichora? Sanamu ya kuyeyuka, nayo ni mwalimu wa uongo, yafaa nini, hata yeye aliyeifanya aiwekee tumaini lake, na kufanya sanamu zisizoweza kusema?"}, {"r": "Zaburi 38:15", "t": "Kwa kuwa nakungoja Wewe, Bwana, Wewe utajibu, Ee Bwana, Mungu wangu."}, {"r": "2 Wakorintho 5:11", "t": "Basi tukiijua hofu ya Bwana, twawavuta wanadamu; lakini tumedhihirishwa mbele za Mungu. Nami natumaini ya kuwa tumedhihirishwa katika dhamiri zenu pia."}, {"r": "Zaburi 62:10", "t": "Msiitumainie dhuluma, Wala msijivune kwa unyang'anyi; Mali izidipo msiiangalie sana moyoni."}, {"r": "1 Timotheo 1:1", "t": "Paulo, mtume wa Kristo Yesu, kwa amri ya Mungu Mwokozi wetu na Kristo Yesu, taraja letu;"}, {"r": "1 Wakorintho 13:13", "t": "Basi, sasa inadumu imani, tumaini, upendo, haya matatu; na katika hayo lililo kuu ni upendo."}, {"r": "Yohana 5:3", "t": "Ndani ya hayo jamii kubwa ya wagonjwa walikuwa wamelala, vipofu, viwete, nao waliopooza, [wakingoja maji yachemke."}], "usalama": [{"r": "Zaburi 23:4", "t": "Naam, nijapopita kati ya bonde la uvuli wa mauti, Sitaogopa mabaya; Kwa maana Wewe upo pamoja nami, Gongo lako na fimbo yako vyanifariji."}, {"r": "Warumi 8:31", "t": "Basi, tuseme nini juu ya hayo? Mungu akiwapo upande wetu, ni nani aliye juu yetu?"}, {"r": "Mithali 18:10", "t": "Jina la Bwana ni ngome imara; Mwenye haki huikimbilia, akawa salama."}, {"r": "Waebrania 13:6", "t": "Hata twathubutu kusema, Bwana ndiye anisaidiaye, sitaogopa; Mwanadamu atanitenda nini?"}, {"r": "Mithali 29:25", "t": "Kuwaogopa wanadamu huleta mtego; Bali amtumainiye Bwana atakuwa salama."}, {"r": "Nahumu 1:7", "t": "Bwana ni mwema, ni ngome siku ya taabu; naye huwajua hao wamkimbiliao."}, {"r": "Zaburi 125:2", "t": "Kama milima inavyouzunguka Yerusalemu, Ndivyo Bwana anavyowazunguka watu wake, Tangu sasa na hata milele."}, {"r": "Isaya 12:2", "t": "Tazama, Mungu ndiye wokovu wangu; Nitatumaini wala sitaogopa; Maana Bwana YEHOVA ni nguvu zangu na wimbo wangu; Naye amekuwa wokovu wangu."}, {"r": "Zaburi 56:3", "t": "Siku ya hofu yangu nitakutumaini Wewe;"}, {"r": "Zaburi 9:9", "t": "Bwana atakuwa ngome kwake aliyeonewa, Naam, ngome kwa nyakati za shida."}, {"r": "Yohana 14:27", "t": "Amani nawaachieni; amani yangu nawapa; niwapavyo mimi sivyo kama ulimwengu utoavyo. Msifadhaike mioyoni mwenu, wala msiwe na woga."}, {"r": "2 Timotheo 1:7", "t": "Maana Mungu hakutupa roho ya woga, bali ya nguvu na ya upendo na ya moyo wa kiasi."}, {"r": "Zaburi 4:8", "t": "Katika amani nitajilaza na kupata usingizi mara, Maana Wewe, Bwana, peke yako, Ndiwe unijaliaye kukaa salama."}, {"r": "Isaya 41:10", "t": "usiogope, kwa maana mimi ni pamoja nawe; usifadhaike, kwa maana mimi ni Mungu wako; nitakutia nguvu, naam, nitakusaidia, naam, nitakushika kwa mkono wa kuume wa haki yangu."}, {"r": "Mithali 1:33", "t": "Bali kila anisikilizaye atakaa salama, Naye atatulia bila kuogopa mabaya."}, {"r": "Kumbukumbu la Torati 31:6", "t": "Iweni hodari na moyo wa ushujaa, msiogope wala msiwahofu; kwa maana Bwana, Mungu wako, yeye ndiye anayekwenda pamoja nawe, hatakupungukia wala kukuacha."}, {"r": "Isaya 43:1", "t": "Lakini sasa, Bwana aliyekuhuluku, Ee Yakobo, yeye aliyekuumba, Ee Israeli, asema hivi, Usiogope, maana nimekukomboa; nimekuita kwa jina lako, wewe u wangu."}, {"r": "Zaburi 34:7", "t": "Malaika wa Bwana hufanya kituo, Akiwazungukia wamchao na kuwaokoa."}, {"r": "Zaburi 18:2", "t": "Bwana ni jabali langu, na boma langu, na mwokozi wangu, Mungu wangu, mwamba wangu ninayemkimbilia, Ngao yangu, na pembe ya wokovu wangu, na ngome yangu."}, {"r": "Mithali 3:24", "t": "Ulalapo hutaona hofu; Naam, utalala na usingizi wako utakuwa mtamu."}, {"r": "Zaburi 16:8", "t": "Nimemweka Bwana mbele yangu daima, Kwa kuwa yuko kuumeni kwangu, sitaondoshwa."}, {"r": "Isaya 26:3", "t": "Utamlinda yeye ambaye moyo wake umekutegemea Katika amani kamilifu, kwa kuwa anakutumaini."}, {"r": "Zaburi 138:7", "t": "Nijapokwenda kati ya shida utanihuisha, Utanyosha mkono juu ya hasira ya adui zangu, Na mkono wako wa kuume utaniokoa."}, {"r": "Warumi 8:38", "t": "Kwa maana nimekwisha kujua hakika ya kwamba, wala mauti, wala uzima, wala malaika, wala wenye mamlaka, wala yaliyopo, wala yatakayokuwapo, wala wenye uwezo,"}, {"r": "Zaburi 121:8", "t": "Bwana atakulinda utokapo na uingiapo, Tangu sasa na hata milele."}, {"r": "Zaburi 62:6", "t": "Yeye tu ndiye mwamba wangu na wokovu wangu, Ngome yangu, sitatikisika sana."}, {"r": "Kumbukumbu la Torati 31:8", "t": "Naye Bwana, yeye ndiye atakayekutangulia, atakuwa pamoja nawe, hatakupungukia wala kukuacha; usiogope wala usifadhaike."}, {"r": "Mathayo 6:26", "t": "Waangalieni ndege wa angani, ya kwamba hawapandi, wala hawavuni, wala hawakusanyi ghalani; na Baba yenu wa mbinguni huwalisha hao. Ninyi je! Si bora kupita hao?"}, {"r": "Zaburi 46:2", "t": "Kwa hiyo hatutaogopa ijapobadilika nchi, Ijapotetemeka milima moyoni mwa bahari."}, {"r": "Isaya 54:17", "t": "Kila silaha itakayofanyika juu yako haitafanikiwa na kila ulimi utakaoinuka juu yako katika hukumu utauhukumu kuwa mkosa. Huu ndio urithi wa watumishi wa Bwana, na haki yao inayotoka kwangu mimi, asema Bwana."}, {"r": "Yohana 10:29", "t": "Baba yangu aliyenipa hao ni mkuu kuliko wote; wala hakuna mtu awezaye kuwapokonya katika mkono wa Baba yangu."}, {"r": "Isaya 40:29", "t": "Huwapa nguvu wazimiao, humwongezea nguvu yeye asiyekuwa na uwezo."}, {"r": "Warumi 8:39", "t": "wala yaliyo juu, wala yaliyo chini, wala kiumbe kinginecho chote hakitaweza kututenga na upendo wa Mungu ulio katika Kristo Yesu Bwana wetu."}, {"r": "Zaburi 62:2", "t": "Yeye tu ndiye mwamba wangu na wokovu wangu, Ngome yangu, sitatikisika sana."}, {"r": "2 Timotheo 4:18", "t": "Bwana ataniokoa na kila neno baya, na kunihifadhi hata nifike ufalme wake wa mbinguni. Utukufu una Yeye milele na milele. Amina."}, {"r": "Mithali 14:26", "t": "Kumcha Bwana ni tumaini imara; Watoto wake watakuwa na kimbilio."}, {"r": "Zaburi 27:5", "t": "Mradi atanisitiri bandani mwake siku ya mabaya, Atanisitiri katika sitara ya hema yake, Na kuniinua juu ya mwamba."}, {"r": "Zaburi 91:4", "t": "Kwa manyoya yake atakufunika, Chini ya mbawa zake utapata kimbilio; Uaminifu wake ni ngao na kigao."}, {"r": "Zaburi 121:7", "t": "Bwana atakulinda na mabaya yote, Atakulinda nafsi yako."}, {"r": "Zaburi 46:1", "t": "Mungu kwetu sisi ni kimbilio na nguvu, Msaada utakaoonekana tele wakati wa mateso."}, {"r": "Zaburi 57:1", "t": "Unirehemu, Ee Mungu, unirehemu mimi, Maana nafsi yangu imekukimbilia Wewe. Nitaukimbilia uvuli wa mbawa zako, Hata misiba hii itakapopita."}, {"r": "Isaya 43:2", "t": "Upitapo katika maji mengi nitakuwa pamoja nawe; na katika mito, haitakugharikisha; uendapo katika moto, hutateketea; wala mwali wa moto hautakuunguza."}, {"r": "Zaburi 118:6", "t": "Bwana yuko upande wangu, sitaogopa; Mwanadamu atanitenda nini?"}, {"r": "Mathayo 10:31", "t": "Msiogope basi; bora ninyi kuliko mashomoro wengi."}, {"r": "Luka 12:7", "t": "Lakini hata nywele za vichwa vyenu zimehesabiwa zote. Msiogope basi, bora ninyi kuliko mashomoro wengi."}, {"r": "Zaburi 91:1", "t": "Aketiye mahali pa siri pake Aliye juu Atakaa katika uvuli wake Mwenyezi."}, {"r": "Zaburi 121:1", "t": "Nitayainua macho yangu niitazame milima, Msaada wangu utatoka wapi?"}, {"r": "Mathayo 28:20", "t": "na kuwafundisha kuyashika yote niliyowaamuru ninyi; na tazama, mimi nipo pamoja nanyi siku zote, hata ukamilifu wa dahari."}, {"r": "Zaburi 121:2", "t": "Msaada wangu u katika Bwana, Aliyezifanya mbingu na nchi."}, {"r": "Mathayo 10:29", "t": "Je! Mashomoro wawili hawauzwi kwa senti moja? Wala hata mmoja haanguki chini asipojua Baba yenu;"}, {"r": "Yoshua 1:9", "t": "Je! Si mimi niliyekuamuru? Uwe hodari na moyo wa ushujaa; usiogope wala usifadhaike; kwa kuwa Bwana, Mungu wako, yu pamoja nawe kila uendako."}, {"r": "Zaburi 91:11", "t": "Kwa kuwa atakuagizia malaika zake Wakulinde katika njia zako zote."}, {"r": "Zaburi 32:7", "t": "Ndiwe sitara yangu, utanihifadhi na mateso, Utanizungusha nyimbo za wokovu."}, {"r": "Kumbukumbu la Torati 33:27", "t": "Mungu wa milele ndiye makazi yako, Na mikono ya milele i chini yako. Na mbele yako amemsukumia mbali adui; Akasema, Angamiza."}, {"r": "Zaburi 91:2", "t": "Nitasema, Bwana ndiye kimbilio langu na ngome yangu, Mungu wangu nitakayemtumaini."}, {"r": "1 Petro 5:7", "t": "huku mkimtwika yeye fadhaa zenu zote, kwa maana yeye hujishughulisha sana kwa mambo yenu."}, {"r": "Yohana 10:28", "t": "Nami nawapa uzima wa milele; wala hawatapotea kamwe; wala hakuna mtu atakayewapokonya katika mkono wangu."}, {"r": "Zaburi 61:3", "t": "Kwa maana ulikuwa kimbilio langu, Ngome yenye nguvu adui asinipate."}, {"r": "Zaburi 56:4", "t": "Kwa msaada wa MUNGU nitalisifu neno lake. Nimemtumaini Mungu, sitaogopa; Mwenye mwili atanitenda nini?"}, {"r": "2 Wathesalonike 3:3", "t": "Lakini Bwana ni mwaminifu, atakayewafanya imara na kuwalinda na yule mwovu."}, {"r": "Zaburi 27:1", "t": "Bwana ni nuru yangu na wokovu wangu, Nimwogope nani? Bwana ni ngome ya uzima wangu, Nimhofu nani?"}, {"r": "Zaburi 106:8", "t": "Lakini akawaokoa kwa ajili ya jina lake, Ayadhihirishe matendo yake makuu."}, {"r": "Zekaria 10:6", "t": "Nami nitaitia nguvu nyumba ya Yuda, nami nitaiokoa nyumba ya Yusufu, nami nitawarudisha, kwa maana nawaonea rehema; nao watakuwa kana kwamba sikuwatupa; kwa maana mimi ni Bwana, Mungu wao, nami nitawasikia."}, {"r": "Zaburi 141:10", "t": "Wabaya na waanguke katika nyavu zao wenyewe, Pindi mimi ninapopita salama."}, {"r": "Isaya 29:7", "t": "Na wingi wa mataifa wapiganao na Arieli, wote wapiganao naye na ngome yake, nao wamwudhio, watakuwa kama ndoto, na maono ya usiku."}, {"r": "Zaburi 105:41", "t": "Akaufunua mwamba, kukabubujika maji, Yakapita pakavuni kama mto."}, {"r": "Luka 7:50", "t": "Akamwambia yule mwanamke, Imani yako imekuokoa, enenda zako kwa amani."}, {"r": "1 Timotheo 4:16", "t": "Jitunze nafsi yako, na mafundisho yako. Dumu katika mambo hayo; maana kwa kufanya hivyo utajiokoa nafsi yako na wale wakusikiao pia."}, {"r": "Mithali 19:16", "t": "Yeye aihifadhiye amri huihifadhi nafsi yake; Bali yeye asiyeziangalia njia zake atakufa."}, {"r": "Zekaria 9:3", "t": "Na Tiro alijijengea ngome, akakusanya fedha kama mchanga, dhahabu safi kama matope ya njia kuu."}, {"r": "Luka 19:10", "t": "Kwa kuwa Mwana wa Adamu alikuja kutafuta na kuokoa kile kilichopotea."}, {"r": "Zaburi 57:3", "t": "Atapeleka toka mbinguni na kuniokoa, Atukanapo yule atakaye kunimeza. Mungu atazipeleka Fadhili zake na kweli yake"}, {"r": "Amosi 2:14", "t": "Naye apigaye mbio atapotewa na kimbilio; Wala aliye hodari hataongeza nguvu zake; Wala shujaa hatajiokoa nafsi yake;"}, {"r": "Isaya 37:12", "t": "Je! Miungu ya mataifa, ambao baba zangu waliwaangamiza, wamewaokoa? Gozani, na Harani, na Resefu, na wana wa Adini waliokuwa katika Telasari?"}, {"r": "2 Timotheo 3:11", "t": "na upendo, na saburi; tena na adha zangu na mateso, mambo yaliyonipata katika Antiokia, katika Ikonio, na katika Listra, kila namna ya adha niliyoistahimili, naye Bwana aliniokoa katika hayo yote."}, {"r": "Mithali 4:6", "t": "Usimwache, naye atakuhifadhi; Umpende, naye atakulinda."}, {"r": "Zaburi 71:3", "t": "Uwe kwangu mwamba wa makazi yangu, Nitakakokwenda sikuzote. Umeamuru niokolewe, Ndiwe genge langu na ngome yangu."}, {"r": "Matendo ya Mitume 22:24", "t": "yule jemadari akaamuru aletwe ndani ya ngome, akisema aulizwe habari zake kwa kupigwa mijeledi, ili ajue sababu hata wakampigia kelele namna hii."}, {"r": "Mithali 30:5", "t": "Kila neno la Mungu limehakikishwa; Yeye ni ngao yao wamwaminio."}, {"r": "Zaburi 46:7", "t": "Bwana wa majeshi yu pamoja nasi, Mungu wa Yakobo ni ngome yetu."}, {"r": "Yeremia 39:17", "t": "Lakini nitakuokoa wewe katika siku hiyo, asema Bwana; wala hutatiwa katika mikono ya watu wale unaowaogopa."}, {"r": "Zaburi 59:11", "t": "Usiwaue, watu wangu wasije wakasahau; Uwatawanye kwa uweza wako, Na kuwaangamiza, Ee Bwana, ngao yetu."}, {"r": "Marko 6:50", "t": "kwa kuwa wote walimwona, wakafadhaika. Mara akasema nao, akawaambia, Changamkeni; ni mimi, msiogope."}, {"r": "Ufunuo wa Yohana 3:10", "t": "Kwa kuwa umelishika neno la subira yangu, mimi nami nitakulinda, utoke katika saa ya kuharibiwa iliyo tayari kuujilia ulimwengu wote, kuwajaribu wakaao juu ya nchi."}, {"r": "Luka 11:21", "t": "Mtu mwenye nguvu aliyejifunga silaha zake, alindapo nyumba yake, vitu vyake vi salama;"}, {"r": "Mhubiri 9:14", "t": "Palikuwa na mji mdogo, na watu ndani yake walikuwa wachache; akaja mfalme mkuu juu yake, akauhusuru, akajenga ngome kubwa ili kuupiga."}, {"r": "Zaburi 18:31", "t": "Maana ni nani aliye Mungu ila Bwana? Ni nani aliye mwamba ila Mungu wetu?"}, {"r": "Isaya 42:22", "t": "Lakini watu hawa ni watu walioibiwa na kutekwa; wote wamenaswa katika mashimo, wamefichwa katika magereza; wamekuwa mawindo, wala hapana aokoaye; wamekuwa mateka, wala hapana asemaye, Rudisha."}, {"r": "Marko 16:8", "t": "Wakatoka nje, wakakimbia kutoka kaburini; kwa maana wameingia tetemeko na ushangao; wala hawakumwambia mtu neno, maana waliogopa. ["}, {"r": "Yeremia 5:3", "t": "Ee Bwana, macho yako je! Hayaangalii uaminifu? Umewapiga, lakini hawakuhuzunika; umewakomesha, lakini wamekataa kurudiwa wamefanya nyuso zao kuwa ngumu kuliko mwamba wamekataa kurudi."}, {"r": "Isaya 44:8", "t": "Msiogope wala msifanye hofu; je! Sikukuhubiri haya zamani na kuyaonyesha? Na ninyi ni mashahidi wangu. Je! Yuko Mungu zaidi yangu mimi? Hakika hapana Mwamba; mimi sijui mwingine."}, {"r": "Zekaria 3:2", "t": "Bwana akamwambia Shetani, Bwana na akukemee Ewe Shetani; naam, Bwana, aliyechagua Yerusalemu, na akukemee; je! Hiki si kinga kilichotolewa motoni?"}, {"r": "Isaya 44:2", "t": "Bwana, aliyekufanya, na kukuumba toka tumboni, yeye atakayekusaidia, asema hivi; Usiogope, Ee Yakobo, mtumishi wangu; na wewe, Yeshuruni, niliyekuchagua."}, {"r": "Isaya 49:8", "t": "Bwana asema hivi, Wakati uliokubalika nimekujibu, na siku ya wokovu nimekusaidia; nami nitakuhifadhi, nitakutoa uwe agano la watu hawa, ili kuiinua nchi hii, na kuwarithisha urithi uliokuwa ukiwa;"}, {"r": "Ayubu 11:18", "t": "Nawe utakuwa salama, kwa sababu kuna matumaini; Naam, utatafutatafuta kando yako, na kupumzika katika salama."}, {"r": "Zaburi 31:23", "t": "Mpendeni Bwana, Ninyi nyote mlio watauwa wake. Bwana huwahifadhi waaminifu, Humlipa atendaye kiburi malipo tele."}, {"r": "Zaburi 46:11", "t": "Bwana wa majeshi yu pamoja nasi, Mungu wa Yakobo ni ngome yetu."}, {"r": "Mhubiri 7:12", "t": "Kwa maana hekima ni ulinzi, kama vile fedha ilivyo ulinzi; na ubora wa maarifa ni ya kwamba hekima humhifadhi yeye aliye nayo."}, {"r": "Waebrania 11:7", "t": "Kwa imani Nuhu akiisha kuonywa na Mungu katika habari za mambo yasiyoonekana bado, kwa jinsi alivyomcha Mungu, aliunda safina, apate kuokoa nyumba yake. Na hivyo akauhukumu makosa ulimwengu, akawa mrithi wa haki ipatikanayo kwa imani."}, {"r": "Matendo ya Mitume 5:23", "t": "wakisema, Gereza tumeikuta imefungwa salama, nao walinzi wamesimama mbele ya mlango; lakini tulipoufungua hatukukuta mtu ndani."}, {"r": "Mithali 11:15", "t": "Amdhaminiye mgeni hakosi ataumia; Achukiaye mambo ya dhamana yu salama."}, {"r": "Ayubu 10:7", "t": "Ujapojua ya kuwa mimi si mwovu; Wala hapana awezaye kuokoa na mkono wako?"}, {"r": "Matendo ya Mitume 26:17", "t": "nikikuokoa na watu wako, na watu wa Mataifa, ambao nakutuma kwao;"}, {"r": "Zaburi 44:5", "t": "Kwa nguvu zako tutawaangusha watesi wetu; Kwa jina lako tutawakanyaga watupingao."}, {"r": "Tito 2:11", "t": "Maana neema ya Mungu iwaokoayo wanadamu wote imefunuliwa;"}, {"r": "Mithali 20:22", "t": "Usiseme, Mimi nitalipa mabaya; Mngojee Bwana, naye atakuokoa."}, {"r": "Zekaria 9:15", "t": "Bwana wa majeshi atawalinda; Nao watakula na kuyakanyaga mawe ya teo; Nao watakunywa na kufanya kelele kama kwa divai; Nao watajazwa kama mabakuli, kama pembe za madhabahu."}, {"r": "Hesabu 4:16", "t": "Na ulinzi wake Eleazari mwana wa Haruni kuhani utakuwa ni kuyaangalia mafuta kwa nuru, na uvumba mzuri, na sadaka ya unga ya daima, na mafuta ya kupaka, tena ulinzi wa hiyo maskani yote, na wa vitu vyote vilivyo ndani yake, mahali patakatifu, na vyombo vyake."}, {"r": "Isaya 32:2", "t": "Na mwanadamu atakuwa kama mahali pa kujificha na upepo, na mahali pa kujisitiri na dhoruba; kama mito ya maji mahali pakavu, kama kivuli cha mwamba mkubwa katika nchi yenye uchovu."}, {"r": "Isaya 59:18", "t": "Kadiri ya matendo yao, kwa kadiri iyo hiyo atawalipa, ukali kwao wampingao, malipo kwa adui zake; naye atavirudishia visiwa malipo."}, {"r": "Zaburi 86:2", "t": "Unihifadhi nafsi yangu, Maana mimi ni mcha Mungu. Wewe uliye Mungu wangu, Umwokoe mtumishi wako anayekutumaini."}, {"r": "Isaya 17:3", "t": "Na ngome ya Efraimu itakomeshwa, na ufalme wa Dameski, na mabaki ya Shamu; watakuwa kama utukufu wa wana wa Israeli, asema Bwana wa majeshi."}, {"r": "Ayubu 26:2", "t": "Jinsi ulivyomsaidia huyo asiye na uwezo! Jinsi ulivyouokoa mkono usio na nguvu!"}, {"r": "Zaburi 140:4", "t": "Ee Bwana, unilinde na mikono ya mtu asiye haki; Unihifadhi na mtu wa jeuri; Waliowaza kuzipotosha hatua zangu."}, {"r": "Amosi 5:9", "t": "yeye aletaye uharibifu wa ghafula juu yao walio hodari, hata uharibifu uipate ngome."}, {"r": "Wafilipi 4:7", "t": "Na amani ya Mungu, ipitayo akili zote, itawahifadhi mioyo yenu na nia zenu katika Kristo Yesu."}, {"r": "Zaburi 48:3", "t": "Mungu katika majumba yake Amejijulisha kuwa ngome."}, {"r": "Zekaria 12:8", "t": "Katika siku hiyo Bwana atawalinda wenyeji wa Yerusalemu; na yeye aliye dhaifu miongoni mwao atakuwa kama Daudi siku hiyo; nayo nyumba ya Daudi itakuwa kama Mungu, kama malaika wa Bwana mbele yao."}, {"r": "Zaburi 3:3", "t": "Na Wewe, Bwana, U ngao yangu pande zote, Utukufu wangu na mwinua kichwa changu."}, {"r": "Zekaria 12:7", "t": "Naye Bwana ataziokoa hema za Yuda kwanza, ili utukufu wa nyumba ya Daudi, na utukufu wa wenyeji wa Yerusalemu, usipate kutukuzwa kuliko Yuda."}, {"r": "Mathayo 16:25", "t": "Kwa kuwa mtu atakaye kuiokoa nafsi yake, ataipoteza; na mtu atakayepoteza nafsi yake kwa ajili yangu, ataiona."}, {"r": "Zaburi 28:8", "t": "Bwana ni nguvu za watu wake, Naye ni ngome ya wokovu kwa masihi"}, {"r": "Nahumu 3:12", "t": "Ngome zako zote zitakuwa kama mitini yenye tini zilizoiva kwanza; ikitikisika zaanguka katika kinywa chake alaye."}, {"r": "Isaya 33:16", "t": "Huyu ndiye atakayekaa juu; majabali ni ngome yake; atapewa chakula chake; maji yake hayatakoma."}, {"r": "Yeremia 12:5", "t": "Ikiwa umepiga mbio pamoja na hao waendao kwa miguu, nao wamekuchosha, basi wawezaje kushindana na farasi? Na ujapokuwa katika nchi ya amani u salama, lakini utafanyaje hapo katika kiburi cha Yordani?"}, {"r": "Zekaria 12:6", "t": "Siku hiyo nitawafanya wakuu wa Yuda kuwa kama kigae chenye moto katika kuni, na kama kinga cha moto katika miganda; nao watateketeza watu wa kila kabila, wawazungukao pande zote, upande wa mkono wa kuume na upande wa mkono wa kushoto; na baada ya haya Yerusalemu utakaa mahali pake, naam, hapo Yerusalemu."}, {"r": "Zaburi 28:7", "t": "Bwana ni nguvu zangu na ngao yangu. Moyo wangu umemtumaini, Nami nimesaidiwa; Basi, moyo wangu unashangilia, Na kwa wimbo wangu nitamshukuru."}, {"r": "Ayubu 5:24", "t": "Nawe utajua ya kwamba hema yako ina salama; Na zizi lako utaliaua, wala usikose kitu."}, {"r": "1 Mambo ya Nyakati 23:32", "t": "tena walinde ulinzi wa hema ya kukutania, na ulinzi wa patakatifu, na ulinzi wa wana wa Haruni, ndugu zao, katika utumishi wa nyumba ya Bwana."}, {"r": "1 Wakorintho 1:21", "t": "Kwa maana katika hekima ya Mungu, dunia isipopata kumjua Mungu kwa hekima yake, Mungu alipenda kuwaokoa waaminio kwa upuzi wa lile neno linalohubiriwa."}, {"r": "Amosi 6:12", "t": "Je! Farasi watapiga mbio juu ya mwamba? Je! Mtu atalima na ng'ombe huko? Hata mmegeuza hukumu kuwa uchungu, na matunda ya haki kuwa pakanga;"}, {"r": "Zaburi 62:8", "t": "Enyi watu, mtumainini sikuzote, Ifunueni mioyo yenu mbele zake; Mungu ndiye kimbilio letu."}, {"r": "Ayubu 29:2", "t": "Laiti ningekuwa kama nilivyokuwa katika miezi ya kale, Kama katika siku hizo Mungu aliponilinda;"}, {"r": "Mathayo 27:65", "t": "Pilato akawaambia, Mna askari; nendeni mkalilinde salama kadiri mjuavyo."}, {"r": "Isaya 51:1", "t": "Nisikilizeni, ninyi mnaoifuatia haki; ninyi mnaomtafuta Bwana; uangalieni mwamba ule ambao mlitolewa kwa kuchongwa, na tundu la shimo ambalo mlitolewa kwa kuchimbuliwa."}, {"r": "Hesabu 1:53", "t": "Lakini Walawi watapanga hema zao kuizunguka maskani ya ushahidi pande zote, ili zisiwe hasira juu ya mkutano wa wana wa Israeli; kisha Walawi wataulinda ulinzi wa hiyo maskani ya ushahidi."}, {"r": "Zaburi 81:16", "t": "Naam, ningewalisha kwa unono wa ngano, Ningewashibisha kwa asali itokayo mwambani."}, {"r": "Ufunuo wa Yohana 2:10", "t": "Usiogope mambo yatakayokupata; tazama, huyo Ibilisi atawatupa baadhi yenu gerezani ili mjaribiwe, nanyi mtakuwa na dhiki siku kumi. Uwe mwaminifu hata kufa, nami nitakupa taji ya uzima."}, {"r": "Zaburi 28:1", "t": "Ee Bwana, nitakuita Wewe, mwamba wangu, Usiwe kwangu kama kiziwi. Nisije nikafanana nao washukao shimoni, Ikiwa umeninyamalia."}, {"r": "Hesabu 3:38", "t": "Na hao watakaopanga mbele ya maskani upande wa mashariki, mbele ya hema ya kukutania upande wa kuelekea maawio ya jua, watakuwa hawa, Musa na Haruni na wanawe, wenye kulinda ulinzi wa mahali patakatifu, yaani, huo ulinzi wa wana wa Israeli; na mgeni atakayekaribia atauawa."}, {"r": "Mithali 5:2", "t": "Upate kuilinda busara, Na midomo yako iyahifadhi maarifa."}, {"r": "Wimbo Ulio Bora 1:6", "t": "Msinichunguze kwa kuwa ni mweusimweusi, Kwa sababu jua limeniunguza. Wana wa mamangu walinikasirikia, Waliniweka niwe mlinzi wa mashamba ya mizabibu; Bali shamba langu mwenyewe sikulilinda."}, {"r": "Nahumu 3:11", "t": "Tena utalewa, utafichwa; tena utatafuta ngome kwa sababu ya adui."}, {"r": "Ayubu 39:28", "t": "Hukaa jabalini, ndiko kwenye malazi yake, Juu ya genge la jabali, na ngomeni."}, {"r": "Hesabu 8:26", "t": "lakini watatumika pamoja na ndugu zao katika hema ya kukutania, kushika ulinzi, lakini wasitumike katika huo utumishi tena. Ndivyo utakavyowafanyia Walawi katika mambo ya ulinzi wao."}, {"r": "Isaya 23:14", "t": "Pigeni yowe, enyi merikebu za Tarshishi; maana ngome yenu imefanywa ukiwa."}, {"r": "Isaya 45:20", "t": "Jikusanyeni mje; na kukaribia pamoja, ninyi wa mataifa mliookoka; hawana maarifa wale wachukuao mti wa sanamu yao ya kuchonga; wamwombao mungu asiyeweza kuokoa."}, {"r": "Hesabu 31:30", "t": "Na katika hiyo nusu ya wana wa Israeli utatwaa mmoja atakayetolewa katika kila hamsini, katika wanadamu, na katika ng'ombe, na katika punda, na katika kondoo, maana, katika wanyama wote, ukawape Walawi, hao walindao ulinzi wa maskani ya Bwana."}, {"r": "Yeremia 33:16", "t": "Katika siku zile Yuda ataokolewa, na Yerusalemu utakaa salama, na jina lake atakaloitwa ni hili, Bwana ni haki yetu."}, {"r": "Maombolezo 5:8", "t": "Watumwa wanatutawala; Hakuna mtu wa kutuokoa na mikono yao."}, {"r": "Yeremia 32:37", "t": "Tazama, nitawakusanya, na kuwatoa katika nchi zote nilikowafukuza, katika hasira yangu, na uchungu wangu, na ghadhabu yangu nyingi; nami nitawaleta tena hata mahali hapa, nami nitawakalisha salama salimini;"}, {"r": "Sefania 1:18", "t": "Fedha yao wala dhahabu yao havitaweza kuwaokoa katika siku ile ya ghadhabu ya Bwana; bali nchi yote pia itateketezwa kwa moto wa wivu wake; maana atawakomesha watu wote wakaao katika nchi hii, naam, ukomo wa kutisha."}, {"r": "Isaya 54:4", "t": "Usiogope; maana hutatahayarika; wala usifadhaike; maana hutaaibishwa; kwa kuwa utaisahau aibu ya ujana wako, pia mashutumu ya ujane wako hutayakumbuka tena."}, {"r": "Isaya 21:5", "t": "Wanaandika meza, wanaweka ulinzi, wanakula, wanakunywa. Simameni, enyi wakuu, itieni ngao mafuta."}, {"r": "Ezekieli 44:16", "t": "wataingia patakatifu pangu, nao wataikaribia meza yangu, ili kunihudumia, nao watalinda ulinzi wangu."}, {"r": "Amosi 4:11", "t": "Baadhi yenu nimewaangamiza, kama hapo Mungu alipoiangamiza Sodoma na Gomora, nanyi mkawa kama kinga kilichonyakuliwa motoni; lakini hamkunirudia mimi, asema Bwana."}, {"r": "Mathayo 27:41", "t": "Kadhalika na wale wakuu wa makuhani wakamdhihaki pamoja na waandishi na wazee, wakisema, Aliokoa wengine, hawezi kujiokoa mwenyewe."}, {"r": "Zaburi 81:7", "t": "Katika shida uliniita nikakuokoa; Nalikuitikia katika sitara ya radi; Nalikujaribu penye maji ya Meriba."}, {"r": "Luka 4:36", "t": "Mshangao ukawashika wote, wakasemezana wakisema, Ni neno gani hili, maana awaamuru pepo wachafu kwa uwezo na nguvu, nao hutoka."}, {"r": "Danieli 3:17", "t": "Kama ni hivyo, Mungu wetu tunayemtumikia aweza kutuokoa na tanuru ile iwakayo moto; naye atatuokoa na mkono wako, Ee mfalme."}, {"r": "1 Yohana 5:18", "t": "Twajua ya kuwa kila mtu aliyezaliwa na Mungu hatendi dhambi; bali yeye aliyezaliwa na Mungu hujilinda, wala yule mwovu hamgusi."}, {"r": "Ayubu 12:6", "t": "Hema za wapokonyi hufanikiwa, Na hao wamkasirishao Mungu hukaa salama; Mikononi mwao Mungu huleta vitu vingi."}, {"r": "Zekaria 14:11", "t": "Na watu watakaa ndani yake, wala hakutakuwako laana tena; lakini Yerusalemu utakaa salama."}, {"r": "Isaya 47:14", "t": "Tazama, watakuwa kama mabua makavu; moto utawateketeza; hawatajiokoa na nguvu za mwali wa moto; hautakuwa kaa la kukota moto, wala moto wa kukaa karibu nao."}, {"r": "Luka 6:48", "t": "Mfano wake ni mtu ajengaye nyumba, na kuchimba chini sana, na kuweka msingi juu ya mwamba; na kulipokuja gharika, mto uliishukia nyumba ile kwa nguvu, usiweze kuitikisa; kwa kuwa imejengwa vizuri."}, {"r": "Hesabu 18:5", "t": "Nanyi mtashika ulinzi wa patakatifu, na ulinzi wa madhabahu, isiwe ghadhabu juu ya wana wa Israeli tena."}, {"r": "Yohana 17:12", "t": "Nilipokuwapo pamoja nao, mimi naliwalinda kwa jina lako ulilonipa, nikawatunza; wala hapana mmojawapo wao aliyepotea, ila yule mwana wa upotevu, ili andiko litimie."}, {"r": "2 Samueli 22:3", "t": "Mungu wa mwamba wangu, nitamwamini yeye; Ngao yangu, na pembe ya wokovu wangu, mnara wangu, na makimbilio yangu; Mwokozi wangu, waniokoa na jeuri."}, {"r": "Zaburi 114:8", "t": "Augeuza mwamba kuwa ziwa la maji, Jiwe gumu kuwa chemchemi."}, {"r": "Isaya 19:20", "t": "Nayo itakuwa ishara na ushuhuda kwa Bwana wa majeshi katika nchi ya Misri; kwa maana watamlilia Bwana kwa sababu ya watu wawaoneao, naye atawapelekea mwokozi mwenye kuwatetea, naye atawaokoa."}, {"r": "Zaburi 25:21", "t": "Ukamilifu na unyofu zinihifadhi, Maana nakungoja Wewe."}, {"r": "Zaburi 116:6", "t": "Bwana huwalinda wasio na hila; Nalidhilika, akaniokoa."}, {"r": "Luka 23:53", "t": "Akaushusha, akauzinga sanda ya kitani, akauweka katika kaburi lililochongwa mwambani, ambalo hajalazwa mtu bado ndani yake."}, {"r": "Mithali 16:17", "t": "Njia kuu ya mwenye haki ni kujitenga na uovu; Yeye ashikaye njia yake huihifadhi nafsi yake."}, {"r": "Mithali 2:12", "t": "Ili kukuokoa na njia ya uovu, Na watu wanenao yaliyopotoka;"}, {"r": "Ayubu 5:11", "t": "Awainuaye juu hao walio chini; Na hao waombolezao hukuzwa wawe salama."}, {"r": "Yeremia 31:10", "t": "Lisikieni neno la Bwana, enyi mataifa, litangazeni visiwani mbali; mkaseme, Aliyemtawanya Israeli atamkusanya, na kumlinda, kama mchungaji alindavyo kundi lake."}, {"r": "Zaburi 69:22", "t": "Meza yao mbele yao na iwe mtego; Naam, wakiwa salama na iwe tanzi."}, {"r": "Mithali 10:2", "t": "Hazina za uovu hazifaidii kitu; Bali haki huokoa na mauti."}, {"r": "2 Samueli 22:44", "t": "Nawe umeniokoa na mashindano ya watu wangu; Umenihifadhi niwe kichwa cha mataifa; Watu nisiowajua watanitumikia."}, {"r": "Zaburi 91:9", "t": "Kwa kuwa Wewe Bwana ndiwe kimbilio langu; Umemfanya Aliye juu kuwa makao yako."}, {"r": "Ezekieli 34:27", "t": "Na mti wa kondeni utazaa matunda yake, nayo ardhi itatoa mazao yake, nao watakuwa salama katika nchi yao; nao watajua ya kuwa mimi ndimi Bwana, nitakapovunja vifungo vya kongwa lao, na kuwaokoa katika mikono ya watu wale waliowatumikisha."}, {"r": "Esta 2:3", "t": "naye mfalme aweke wasimamizi katika majimbo yote ya ufalme wake, ili wakusanye pamoja mabikira vijana wazuri wote waende Shushani ngomeni, kwenye nyumba ya wanawake mikononi mwa Hegai, msimamiziwanyumba wa mfalme, mwenye kuwalinda wanawake; tena wapewe vifaa vya utakaso."}, {"r": "2 Petro 2:9", "t": "basi, Bwana ajua kuwaokoa watauwa na majaribu, na kuwaweka wasio haki katika hali ya adhabu hata siku ya hukumu;"}, {"r": "Hesabu 3:8", "t": "Nao watavitunza vyombo vyote vya hema ya kukutania, na kulinda ulinzi wa wana wa Israeli, ili watumike utumishi wa maskani."}, {"r": "Yeremia 49:11", "t": "Waache watoto wako wasio na baba, mimi nitawahifadhi hai, na wajane wako na wanitumaini mimi."}, {"r": "Zaburi 55:16", "t": "Nami nitamwita Mungu, Na Bwana ataniokoa;"}, {"r": "Mhubiri 12:11", "t": "Maneno yao wenye hekima huwa mfano wa michokoo; na kama misumari iliyogongomewa sana; ndivyo yalivyo maneno yao walio wakuu wa makusanyiko, ambayo yatoka kwa mchungaji mmoja."}, {"r": "Hesabu 3:28", "t": "Kama hesabu ya waume wote, tangu umri wa mwezi mmoja na zaidi, walikuwa elfu nane na mia sita, wenye kuulinda ulinzi wa mahali patakatifu."}, {"r": "Zaburi 78:19", "t": "Naam, walimwamba Mungu, wakasema, Je! Mungu aweza kuandika meza jangwani?"}, {"r": "Isaya 17:10", "t": "Maana umemsahau Mungu wa wokovu wako, wala hukuukumbuka mwamba wa ngome yako; kwa sababu hiyo ulipanda mashamba yapendezayo, na kutia ndani yake mizabibu migeni."}, {"r": "Isaya 38:6", "t": "Nami nitakuokoa wewe, na mji huu, na mkono wa mfalme wa Ashuru, nami nitaulinda mji huu."}, {"r": "Mithali 11:4", "t": "Mali hazifaidii kitu siku ya ghadhabu; Bali haki huokoa na mauti."}, {"r": "Zaburi 68:20", "t": "Mungu kwetu sisi ni Mungu wa kuokoa; Na njia za kutoka mautini zina YEHOVA Bwana."}, {"r": "Hesabu 31:47", "t": "na katika hiyo nusu iliyokuwa ya wana wa Israeli, Musa akatwaa mmoja aliyetolewa katika kila hamsini, wa binadamu na wa wanyama, akawapa Walawi, waliolinda ulinzi wa maskani ya Bwana; kama Bwana alivyomwagiza Musa."}, {"r": "Zekaria 12:4", "t": "Katika siku hiyo, asema Bwana, nitamtia kila farasi ushangao, na yeye ampandaye nitamtia wazimu; nami nitaifunulia nyumba ya Yuda macho yangu, nami nitamtia upofu kila farasi wa hizo kabila za watu."}, {"r": "Zaburi 36:6", "t": "Haki yako ni kama milima ya Mungu, Hukumu zako ni vilindi vikuu, Ee Bwana, unawaokoa wanadamu na wanyama."}, {"r": "Mathayo 7:25", "t": "mvua ikanyesha, mafuriko yakaja, pepo zikavuma, zikaipiga nyumba ile, isianguke; kwa maana misingi yake imewekwa juu ya mwamba."}, {"r": "Mithali 3:26", "t": "Kwa kuwa Bwana atakuwa tumaini lako, Naye atakulinda mguu wako usinaswe."}, {"r": "Maombolezo 2:5", "t": "Bwana amekuwa mfano wa adui, Amemmeza Israeli; Ameyameza majumba yake yote, Ameziharibu ngome zake; Tena amemzidishia binti Yuda Matanga na maombolezo."}, {"r": "2 Mambo ya Nyakati 32:15", "t": "Basi sasa asiwadanganye Hezekia, wala asiwashawishi kwa hayo, wala msimwamini; kwa kuwa hapana mungu wa taifa lo lote, wala wa ufalme wo wote, aliyeweza kuwaokoa watu wake na mkono wangu, au na mkono wa baba zangu; sembuse Mungu wenu atawaokoaje ninyi na mkono wangu?"}, {"r": "Yakobo 5:20", "t": "jueni ya kuwa yeye amrejezaye mwenye dhambi hata atoke katika njia ya upotevu, ataokoa roho na mauti, na kufunika wingi wa dhambi."}, {"r": "1 Petro 3:21", "t": "Mfano wa mambo hayo ni ubatizo, unaowaokoa ninyi pia siku hizi; (siyo kuwekea mbali uchafu wa mwili, bali jibu la dhamiri safi mbele za Mungu), kwa kufufuka kwake Yesu Kristo."}, {"r": "Zaburi 35:2", "t": "Uishike ngao na kigao, Usimame unisaidie."}, {"r": "Zaburi 78:20", "t": "Tazama, aliupiga mwamba; Maji yakabubujika, ikafurika mito. Pia aweza kutupa chakula? Atawaandalia watu wake nyama?"}, {"r": "Esta 1:5", "t": "Hata siku hizo zilipotimia, mfalme akawafanyia karamu watu wote waliokuwapo huko Shushani ngomeni, wakubwa kwa wadogo, muda wa siku saba, katika behewa la bustani ya ngome ya mfalme."}, {"r": "Mambo ya Walawi 8:35", "t": "Nanyi mtakaa mlangoni pa hema ya kukutania muda wa siku saba mchana na usiku, na kuulinda ulinzi wa Bwana ili kwamba msife; kwani ndivyo nilivyoagizwa."}, {"r": "Mithali 10:9", "t": "Aendaye kwa unyofu huenda salama; Bali apotoshaye njia zake atajulikana."}, {"r": "1 Petro 3:14", "t": "Lakini mjapoteswa kwa sababu ya haki mna heri. Msiogope kutisha kwao, wala msifadhaike; bali mtakaseni Kristo Bwana mioyoni mwenu."}, {"r": "Isaya 63:9", "t": "Katika mateso yao yote yeye aliteswa, na malaika wa uso wake akawaokoa; kwa mapenzi yake, na huruma zake, aliwakomboa mwenyewe; akawainua, akawachukua siku zote za kale."}, {"r": "Zaburi 62:7", "t": "Kwa Mungu wokovu wangu, Na utukufu wangu; Mwamba wa nguvu zangu, Na kimbilio langu ni kwa Mungu."}, {"r": "Zaburi 97:10", "t": "Enyi mmpendao Bwana, uchukieni uovu; Huwalinda nafsi zao watauwa wake, Na kuwaokoa na mkono wa wasio haki."}, {"r": "Isaya 43:13", "t": "Naam, tangu siku ya leo, mimi ndiye; wala hapana awezaye kuokoa katika mkono wangu; mimi nitatenda kazi, naye ni nani awezaye kuizuia?"}, {"r": "Mwanzo 45:7", "t": "Mungu alinipeleka mbele yenu kuwahifadhia masazo katika nchi, na kuwaokoa ninyi kwa wokovu mkuu."}, {"r": "Isaya 26:4", "t": "Mtumainini Bwana siku zote Maana Bwana YEHOVA ni mwamba wa milele."}, {"r": "Zaburi 40:11", "t": "Nawe, Bwana, usinizuilie rehema zako, Fadhili zako na kweli yako na zinihifadhi daima."}, {"r": "Mathayo 16:12", "t": "Ndipo walipofahamu ya kuwa hakuwaambia kujilinda na chachu ya mkate, bali na mafundisho ya Mafarisayo na Masadukayo."}, {"r": "Isaya 25:12", "t": "Na boma la ngome ya kuta zako ameliinamisha, na kulilaza chini, na kulitupa chini hata mavumbini."}, {"r": "Zekaria 8:15", "t": "vivyo hivyo nimeazimia katika siku hizi kuutendea Yerusalemu mema, na nyumba ya Yuda pia; msiogope."}, {"r": "Mithali 2:8", "t": "Apate kuyalinda mapito ya hukumu, Na kuhifadhi njia ya watakatifu wake."}, {"r": "Hesabu 20:8", "t": "Twaa ile fimbo, ukawakusanye mkutano, wewe na Haruni ndugu yako, ukauambie mwamba mbele ya macho yao utoe maji yake, nawe utawatokezea maji katika mwamba, na hivyo utawanywesha maji mkutano na wanyama wao."}, {"r": "Zaburi 145:20", "t": "Bwana huwahifadhi wote wampendao, Na wote wasio haki atawaangamiza."}, {"r": "Waebrania 10:39", "t": "Lakini sisi hatumo miongoni mwao wasitao na kupotea, bali tumo miongoni mwa hao walio na imani ya kutuokoa roho zetu."}, {"r": "Yeremia 11:12", "t": "Ndipo miji ya Yuda, na wenyeji wa Yerusalemu, watakwenda na kuwalilia miungu wawafukiziao uvumba; lakini hawatawaokoa hata kidogo wakati wa taabu yao."}, {"r": "Zaburi 119:117", "t": "Unisaidie nami nitakuwa salama, Nami nitaziangalia amri zako daima."}, {"r": "Mika 5:8", "t": "Na hayo mabaki ya Yakobo yatakuwa kati ya mataifa, kati ya kabila nyingi, mfano wa simba kati ya wanyama wa msituni, kama mwanasimba kati ya makundi ya kondoo, ambaye, akiwa anapita katikati, hukanyagakanyaga na kuraruararua, wala hakuna wa kuokoa."}, {"r": "Yeremia 51:30", "t": "Mashujaa wa Babeli wameacha kupigana; Wanakaa katika ngome zao; Ushujaa wao umewapungukia; Wamekuwa kama wanawake; Makao yake yameteketea; Makomeo yake yamevunjika."}, {"r": "Mithali 24:12", "t": "Ukisema, Sisi hatukujua hayo; Je! Yeye aipimaye mioyo siye afahamuye? Naye ailindaye nafsi yako siye ajuaye? Je! Hatamlipa kila mtu sawasawa na kazi yake?"}, {"r": "Zaburi 115:10", "t": "Enyi mlango wa Haruni, mtumainini Bwana; Yeye ni msaada wao na ngao yao."}, {"r": "Mithali 22:18", "t": "maana ni vizuri kuyahifadhi ndani yako, hali yakithibitika pamoja midomoni mwako."}, {"r": "Hesabu 3:7", "t": "Nao wataulinda ulinzi wake, na ulinzi wa mkutano wote mbele ya hema ya kukutania, ili watumike utumishi wa maskani."}, {"r": "Yoeli 2:21", "t": "Ee nchi, usiogope; furahi na kushangilia; kwa kuwa Bwana ametenda mambo makuu."}, {"r": "Isaya 44:20", "t": "Hula majivu; moyo uliodanganyika umempotosha, asiweze kuiokoa nafsi yake, wala kusema, Je! Sio uongo mkononi mwangu?"}, {"r": "Yeremia 30:10", "t": "Kwa sababu hiyo usiogope, Ee Yakobo, mtumishi wangu, asema Bwana; wala usifadhaike, Ee Israeli; kwa maana, tazama, nitakuokoa toka mbali, na wazao wako toka nchi ya uhamisho wao; na Yakobo atarudi, naye atatulia na kustarehe, wala hapana mtu atakayemtia hofu."}, {"r": "Zaburi 54:7", "t": "Kwa kuwa limeniokoa na kila taabu; Na jicho langu limeridhika Kwa kuwatazama adui zangu."}, {"r": "Hosea 13:14", "t": "Nitawakomboa na nguvu za kaburi; nitawaokoa na mauti; ewe mauti, ya wapi mapigo yako? Ewe kaburi, ku wapi kuharibu kwako? Kujuta kutafichwa na macho yangu."}, {"r": "Sefania 3:17", "t": "Bwana, Mungu wako, yu katikati yako shujaa awezaye kuokoa; Atakushangilia kwa furaha kuu, Atakutuliza katika upendo wake, Atakufurahia kwa kuimba."}, {"r": "Yohana 6:20", "t": "Naye akawaambia, Ni mimi, msiogope."}, {"r": "Mithali 10:29", "t": "Njia ya Bwana ni kimbilio lake mtu mkamilifu; Bali ni uharibifu kwao watendao maovu."}, {"r": "Isaya 42:6", "t": "Mimi, Bwana, nimekuita katika haki, nami nitakushika mkono, na kukulinda, na kukutoa uwe agano la watu, na nuru ya mataifa;"}, {"r": "1 Samueli 22:23", "t": "Kaa wewe pamoja nami, usiogope; kwa maana yeye atafutaye roho yangu, ndiye atafutaye na roho yako; nawe utakaa kwangu salama."}, {"r": "Mithali 30:19", "t": "Mwendo wa tai katika hewa; Na mwendo wa nyoka juu ya mwamba; Mwendo wa merikebu katikati ya bahari; Na mwendo wa mtu pamoja na msichana."}, {"r": "Ayubu 5:21", "t": "Utafichwa na mapigo ya ulimi; Wala usiogope maangamizo yatakapokuja."}, {"r": "Mithali 4:23", "t": "Linda moyo wako kuliko yote uyalindayo; Maana ndiko zitokako chemchemi za uzima."}, {"r": "Zaburi 18:27", "t": "Maana Wewe utawaokoa watu wanaoonewa, Na macho ya kiburi utayadhili."}, {"r": "Kumbukumbu la Torati 12:10", "t": "Lakini mtakapovuka Yordani na kukaa katika nchi anayowarithisha Bwana, Mungu wenu, akawapeni raha, akiwaokoa na adui zenu pande zote, mkakaa salama;"}, {"r": "Kutoka 18:10", "t": "Kisha Yethro akasema, Na ahimidiwe Bwana aliyewaokoa na mikono ya Wamisri, na mkono wa Farao; aliyewaokoa watu hao watoke mikononi mwa Wamisri."}, {"r": "Hosea 8:14", "t": "Maana Israeli amemsahau Muumba wake, naye amejenga nyumba za enzi; na Yuda ameongeza miji yenye maboma; lakini nitapeleka moto juu ya miji yake, nao utaziteketeza ngome zake."}, {"r": "Zaburi 104:18", "t": "Milima mirefu ndiko waliko mbuzi wa mwitu, Na magenge ni kimbilio la wibari."}, {"r": "Ayubu 19:24", "t": "Yakachorwa katika mwamba milele, Kwa kalamu ya chuma na risasi."}, {"r": "Zaburi 18:46", "t": "Bwana ndiye aliye hai; Na ahimidiwe mwamba wangu; Na atukuzwe Mungu wa wokovu wangu;"}, {"r": "Wimbo Ulio Bora 5:7", "t": "Walinzi wazungukao mjini waliniona, Wakanipiga na kunitia jeraha, Walinzi walindao kuta zake Wakaninyang'anya shela yangu."}, {"r": "Isaya 5:29", "t": "Ngurumo yao itakuwa kama ya simba; Watanguruma kama wanasimba; Naam, watanguruma na kukamata mateka, Na kuyachukua na kwenda zao salama, Wala hakuna mtu atakayeokoa."}, {"r": "Zaburi 106:10", "t": "Akawaokoa na mkono wa mtu aliyewachukia, Na kuwakomboa na mkono wa adui zao."}, {"r": "Yeremia 6:27", "t": "Nimekuweka uwe mnara na ngome kati ya watu wangu; upate kuijua njia yao na kuijaribu."}, {"r": "Zaburi 59:17", "t": "Ee nguvu zangu, nitakuimbia kwa furaha, Maana Mungu ndiye aliye ngome yangu, Mungu wa fadhili zangu."}, {"r": "Zaburi 31:3", "t": "Ndiwe genge langu na ngome yangu; Kwa ajili ya jina lako uniongoze, unichunge."}, {"r": "Zaburi 31:4", "t": "Utanitoa katika wavu walionitegea kwa siri, Maana Wewe ndiwe ngome yangu."}, {"r": "Waebrania 10:27", "t": "bali kuna kuitazamia hukumu yenye kutisha, na ukali wa moto ulio tayari kuwala wao wapingao."}, {"r": "Zaburi 61:2", "t": "Toka mwisho wa nchi nitakulilia nikizimia moyo, Uniongoze juu ya mwamba nisioweza kuupanda."}, {"r": "Yeremia 2:28", "t": "Lakini wako wapi miungu yako ulioifanya? Na wasimame hao, kama wakiweza kukuokoa wakati wa taabu yako; kwa maana hesabu ya miungu yako ni sawasawa na hesabu ya miji yako, Ee Yuda."}, {"r": "Nahumu 3:14", "t": "Teka maji yawe tayari kwa kuzingirwa kwako; Zitie nguvu ngome zako; Ingia katika udongo, yakanyage matope, Itie nguvu tanuru ya kuokea matofali."}, {"r": "Isaya 51:7", "t": "Nisikilizeni, ninyi mjuao haki, watu ambao mioyoni mwenu mna sheria yangu; msiogope matukano ya watu, wala msifadhaike kwa sababu ya dhihaka zao."}, {"r": "Zaburi 119:114", "t": "Ndiwe sitara yangu na ngao yangu, Neno lako nimelingojea."}, {"r": "Wimbo Ulio Bora 8:12", "t": "Shamba langu la mizabibu, lililo langu mimi, li mbele yangu. Basi, Sulemani, wewe uwe na elfu zako, Na hao wayalindao matunda yake wapewe mia mbili."}, {"r": "Ayubu 10:12", "t": "Umenijazi uhai na upendeleo, Na maangalizi yako yameilinda roho yangu."}, {"r": "Yuda 1:6", "t": "Na malaika wasioilinda enzi yao wenyewe, lakini wakayaacha makao yao yaliyowahusu, amewaweka katika vifungo vya milele chini ya giza kwa hukumu ya siku ile kuu."}, {"r": "Yakobo 1:27", "t": "Dini iliyo safi, isiyo na taka mbele za Mungu Baba ni hii, Kwenda kuwatazama yatima na wajane katika dhiki yao, na kujilinda na dunia pasipo mawaa."}, {"r": "2 Wafalme 20:6", "t": "Tena, nitazizidisha siku zako, kiasi cha miaka kumi na mitano, nami nitakuokoa wewe, na mji huu, na mkono wa mfalme wa Ashuru, nami nitaulinda mji huu kwa ajili yangu, na kwa ajili ya Daudi, mtumishi wangu."}, {"r": "1 Wakorintho 9:22", "t": "Kwa wanyonge nalikuwa mnyonge, ili niwapate wanyonge. Nimekuwa hali zote kwa watu wote, ili kwa njia zote nipate kuwaokoa watu."}, {"r": "Isaya 7:4", "t": "ukamwambie, Angalia, ukatulie; usiogope wala usife moyo, kwa sababu ya mikia hii miwili ya vinga hivi vitokavyo moshi; kwa sababu ya hasira kali ya Resini na Shamu, na mwana wa Remalia."}, {"r": "Zaburi 84:9", "t": "Ee Mungu, ngao yetu, uangalie, Umtazame uso masihi"}, {"r": "Zaburi 18:45", "t": "Wageni nao walitepetea, Walitoka katika ngome zao wakitetemeka."}, {"r": "Isaya 47:15", "t": "Ndivyo yatakavyokuwa mambo hayo uliyojitaabisha nayo; wale waliofanya biashara nawe tangu ujana wako watatangatanga mbali nawe, kila mtu akienda zake; hapatakuwa na mtu wa kukuokoa."}, {"r": "Zaburi 73:28", "t": "Nami kumkaribia Mungu ni kwema kwangu; Nimefanya kimbilio kwa Bwana MUNGU, Niyahubiri matendo yako yote."}, {"r": "Isaya 37:35", "t": "Nami nitaulinda mji huu, niuokoe kwa ajili yangu mwenyewe, na kwa ajili ya Daudi, mtumishi wangu."}, {"r": "Zaburi 42:9", "t": "Nitamwambia Mungu, mwamba wangu, Kwa nini umenisahau? Kwa nini ninakwenda nikihuzunika, adui wakinionea?"}, {"r": "Zaburi 89:26", "t": "Yeye ataniita, Wewe baba yangu, Mungu wangu na mwamba wa wokovu wangu."}, {"r": "Zekaria 9:12", "t": "Irudieni ngome, enyi wafungwa wa tumaini; hata hivi leo nasema ya kwamba nitakurudishia maradufu."}, {"r": "Luka 12:32", "t": "Msiogope, enyi kundi dogo; kwa kuwa Baba yenu ameona vema kuwapa ule ufalme."}, {"r": "Matendo ya Mitume 23:24", "t": "Akawaambia kuweka wanyama tayari wampandishe Paulo, na kumchukua salama kwa Feliki liwali."}, {"r": "Isaya 37:33", "t": "Basi, Bwana asema hivi katika habari za mfalme wa Ashuru, Yeye hataingia ndani ya mji huu, wala hatapiga mshale hapa, wala hatakuja mbele yake kwa ngao, wala hatajenga boma juu yake."}, {"r": "Isaya 43:5", "t": "Usiogope; maana mimi ni pamoja nawe; nitaleta wazao wako toka mashariki, nitakukusanya toka magharibi;"}, {"r": "Zaburi 18:43", "t": "Umeniokoa na mashindano ya watu, Umenifanya niwe kichwa cha mataifa. Watu nisiowajua walinitumikia."}, {"r": "Ayubu 40:23", "t": "Tazama, mto ukifurika, yeye hatetemeki; Hujiona yu salama, ijapokuwa Yordani hufurika hata kinywani pake."}, {"r": "Zaburi 55:18", "t": "Ameiokoa nafsi yangu iwe salama, asinikaribie mtu, Maana walioshindana nami walikuwa wengi."}, {"r": "Ayubu 15:26", "t": "Humshambulia na shingo ngumu, Kwa mafundo makubwa ya ngao zake;"}, {"r": "Zaburi 5:11", "t": "Nao wote wanaokukimbilia watafurahi; Watapiga daima kelele za furaha. Kwa kuwa Wewe unawahifadhi, Walipendao jina lako watakufurahia."}, {"r": "Zaburi 115:11", "t": "Enyi mmchao Bwana, mtumainini Bwana; Yeye ni msaada wao na ngao yao."}, {"r": "Isaya 36:20", "t": "Katika miungu yote ya nchi hizi ni nani waliookoa nchi yao na mkono wangu, hata Bwana auokoe Yerusalemu na mkono wangu?"}, {"r": "Mika 5:11", "t": "nami nitaikatilia mbali miji ya nchi yako, na ngome zako zote nitaziangusha;"}, {"r": "Hosea 14:3", "t": "Ashuru hatatuokoa; hatutapanda farasi; wala hatutaiambia tena kazi ya mikono yetu, Ninyi ndinyi miungu yetu; maana kwako wewe wasio na baba hupata rehema."}, {"r": "Mathayo 27:60", "t": "akauweka katika kaburi lake jipya, alilokuwa amelichonga mwambani; akavingirisha jiwe kubwa mbele ya mlango wa kaburi, akaenda zake."}, {"r": "Zekaria 8:7", "t": "Bwana wa majeshi asema hivi, Tazama, nitawaokoa watu wangu toka nchi ya mashariki, na toka nchi ya magharibi;"}, {"r": "Zaburi 22:4", "t": "Baba zetu walikutumaini Wewe, Walitumaini, na Wewe ukawaokoa."}, {"r": "Zaburi 44:7", "t": "Bali Wewe ndiwe uliyetuokoa na watesi wetu; Na watuchukiao umewaaibisha."}, {"r": "Mathayo 9:17", "t": "Wala watu hawatii divai mpya katika viriba vikuukuu; na kama wakitia, vile viriba hupasuka, divai ikamwagika, na viriba vikaharibika; bali hutia divai mpya katika viriba vipya, vikahifadhika vyote."}, {"r": "Yeremia 1:8", "t": "Usiogope kwa sababu ya hao maana mimi nipo pamoja nawe nikuokoe, asema Bwana."}, {"r": "Ezekieli 48:11", "t": "Patakuwa kwa makuhani wa wana wa Sadoki, waliotakasika, walioulinda ulinzi wangu, wasioasi, wana wa Israeli walipoasi, kama Walawi walivyoasi."}, {"r": "Marko 4:5", "t": "Nyingine ikaanguka penye mwamba, pasipokuwa na udongo mwingi; mara ikaota kwa kuwa na udongo haba;"}, {"r": "Isaya 27:3", "t": "Mimi, Bwana, nalilinda, Nitalitia maji kila dakika, Asije mtu akaliharibu; Usiku na mchana nitalilinda."}, {"r": "2 Wakorintho 11:9", "t": "Nami nilipokuwa pamoja nanyi na kuhitaji sikumlemea mtu. Maana hao ndugu waliokuja kutoka Makedonia walinipa kadiri ya mahitaji yangu; nami katika mambo yote najilinda nafsi yangu nisiwalemee hata kidogo; tena najilinda."}, {"r": "Zaburi 49:16", "t": "Usiogope mtu atakapopata utajiri, Na fahari ya nyumba yake itakapozidi."}, {"r": "Zaburi 50:15", "t": "Ukaniite siku ya mateso; Nitakuokoa, na wewe utanitukuza."}, {"r": "2 Wakorintho 1:10", "t": "aliyetuokoa sisi katika mauti kuu namna ile; tena atatuokoa; ambaye tumemtumaini kwamba atazidi kutuokoa;"}, {"r": "Zekaria 3:7", "t": "Bwana wa majeshi asema hivi, Kama ukienda katika njia zangu, na kama ukishika maagizo yangu, ndipo utakapoihukumu nyumba yangu, nawe utazilinda nyua zangu, nami nitakupa nafasi ya kunikaribia kati yao wasimamao karibu."}, {"r": "Zaburi 40:13", "t": "Ee Bwana, uwe radhi kuniokoa, Ee Bwana, unisaidie hima."}, {"r": "Mithali 18:19", "t": "Ndugu aliyechukizwa ni mgumu kuliko mji wa nguvu; Na mashindano ni kama mapingo ya ngome."}, {"r": "Ayubu 21:9", "t": "Nyumba zao zi salama pasina hofu, Wala fimbo ya Mungu haiwapigi."}, {"r": "Yeremia 48:18", "t": "Ee binti ukaaye Diboni, Shuka toka utukufu wako, ukae katika kiu; Maana atekaye Moabu amepanda juu yako, Ameziharibu ngome zako."}, {"r": "Maombolezo 2:2", "t": "Bwana ameyameza makao yote ya Yakobo, Wala hakuona huruma; Ameziangusha ngome za binti Yuda Katika ghadhabu yake; Amezibomoa hata nchi Ameunajisi ufalme na wakuu wake."}, {"r": "Zaburi 71:7", "t": "Nimekuwa kitu cha ajabu kwa watu wengi, Na Wewe ndiwe kimbilio langu la nguvu."}, {"r": "Matendo ya Mitume 3:10", "t": "Wakamtambua, ya kuwa yeye ndiye aliyekuwa akiketi na kuomba sadaka penye mlango Mzuri wa hekalu; wakajaa ushangao wakastaajabia mambo yale yaliyompata."}, {"r": "Yeremia 48:41", "t": "Miji imetwaliwa, ngome zimeshambuliwa, na mioyo ya mashujaa wa Moabu siku hiyo itakuwa kama moyo wa mwanamke katika utungu wake."}, {"r": "Zaburi 59:9", "t": "Ee nguvu zangu, nitakungoja Wewe, Maana Mungu ndiye aliye ngome yangu"}, {"r": "Zaburi 84:11", "t": "Kwa kuwa Bwana, Mungu, ni jua na ngao, Bwana atatoa neema na utukufu. Hatawanyima kitu chema Hao waendao kwa ukamilifu."}, {"r": "Matendo ya Mitume 12:6", "t": "Hata wakati Herode alipotaka kumtoa, usiku ule ule Petro alikuwa analala katikati ya askari wawili, amefungwa minyororo miwili; walinzi mbele ya mlango wakailinda gereza."}, {"r": "Esta 2:8", "t": "Basi ikawa, wakati iliposikiwa amri ya mfalme na mbiu yake, wasichana wengi wakakusanyika huko Shushani ngomeni mikononi mwa Hegai; Esta naye aliingizwa katika nyumba ya mfalme, mikononi mwa Hegai mwenye kuwalinda wanawake."}, {"r": "Zaburi 40:2", "t": "Akanipandisha toka shimo la uharibifu, Toka udongo wa utelezi; Akaisimamisha miguu yangu mwambani, Akaziimarisha hatua zangu."}, {"r": "Zaburi 89:18", "t": "Maana ngao yetu ina Bwana, Na mfalme wetu ni wake Mtakatifu wa Israeli."}, {"r": "2 Timotheo 1:12", "t": "Kwa sababu hiyo nimepatikana na mateso haya, wala sitahayari; kwa maana namjua yeye niliyemwamini, na kusadiki ya kwamba aweza kukilinda kile nilichokiweka amana kwake hata siku ile."}, {"r": "Zaburi 78:35", "t": "Wakakumbuka kuwa Mungu ni mwamba wao, Na Mungu Aliye juu ni mkombozi wao."}, {"r": "Yuda 1:24", "t": "Yeye awezaye kuwalinda ninyi msijikwae, na kuwasimamisha mbele ya utukufu wake bila mawaa katika furaha kuu;"}, {"r": "Marko 15:46", "t": "Naye akanunua sanda ya kitani, akamtelemsha, akamfungia ile sanda, akamweka katika kaburi lililochongwa mwambani; akavingirisha jiwe mbele ya mlango wa kaburi."}, {"r": "Yoeli 2:22", "t": "Msiogope, enyi wanyama wa kondeni; maana malisho ya jangwani yanatoa miche, na huo mti unazaa matunda yake, mtini na mzabibu inatoa nguvu zake."}, {"r": "Yuda 1:1", "t": "Yuda, mtumwa wa Yesu Kristo, ndugu yake Yakobo, kwa hao walioitwa, waliopendwa katika Mungu Baba, na kuhifadhiwa kwa ajili ya Yesu Kristo."}, {"r": "Zaburi 69:35", "t": "Maana Mungu ataiokoa Sayuni, na kuijenga miji ya Yuda, Na watu watakaa ndani yake na kuimiliki."}, {"r": "Zaburi 95:1", "t": "Njoni, tumwimbie Bwana, Tumfanyie shangwe mwamba wa wokovu wetu."}, {"r": "Tito 3:4", "t": "Lakini wema wake Mwokozi wetu Mungu, na upendo wake kwa wanadamu, ulipofunuliwa, alituokoa;"}, {"r": "Luka 5:26", "t": "Ushangao ukawashika wote, wakamtukuza Mungu; wakajaa hofu, wakisema, Leo tumeona mambo ya ajabu."}, {"r": "Malaki 2:7", "t": "Kwa maana yapasa midomo ya kuhani ihifadhi maarifa, tena yawapasa watu kuitafuta sheria kinywani mwake; kwa kuwa yeye ni mjumbe wa Bwana wa majeshi."}, {"r": "Zaburi 16:1", "t": "Mungu, unihifadhi mimi, Kwa maana nakukimbilia Wewe."}, {"r": "Nehemia 12:45", "t": "Wakauangalia ulinzi wa Mungu wao, na ulinzi wa kutakasika, na hao waimbaji na mabawabu vile vile, sawasawa na amri ya Daudi, na ya Sulemani mwanawe."}, {"r": "Ezekieli 44:15", "t": "Lakini makuhani Walawi, wana wa Sadoki, waliolinda ulinzi wa patakatifu pangu, hapo wana wa Israeli walipopotea na kuniacha, hao ndio watakaonikaribia ili kunihudumia; nao watasimama mbele zangu, kunitolea mafuta na damu, asema Bwana MUNGU;"}, {"r": "Wimbo Ulio Bora 4:4", "t": "Shingo yako ni kama mnara wa Daudi, Uliojengwa pa kuwekea silaha; Ngao elfu zimetungikwa juu yake, Zote ni ngao za mashujaa."}, {"r": "Zaburi 89:40", "t": "Umeyabomoa maboma yake yote, Umezifanya ngome zake kuwa magofu."}, {"r": "2 Samueli 22:47", "t": "Bwana ndiye aliye hai; Na ahimidiwe mwamba wangu; Na atukuzwe Mungu wa mwamba wa wokovu wangu;"}, {"r": "Yeremia 12:1", "t": "Wewe u mwenye haki, Ee Bwana, nitetapo nawe, lakini nitasema nawe katika habari ya haki. Mbona njia ya wabaya inasitawi? Mbona wote watendao hila wanakaa salama?"}, {"r": "Zaburi 73:26", "t": "Mwili wangu na moyo wangu hupunguka, Bali Mungu ni mwamba wa moyo wangu Na sehemu yangu milele."}, {"r": "Isaya 43:12", "t": "Nimetangaza habari, nimeokoa, nimeonyesha, na hapakuwa mungu wa kigeni kati yenu; kwa sababu hiyo ninyi ni mashahidi wangu, asema Bwana, nami ni Mungu."}, {"r": "Matendo ya Mitume 11:14", "t": "atakayekuambia maneno ambayo yatakuokoa, wewe na nyumba yako yote."}, {"r": "Mithali 13:3", "t": "Yeye alindaye kinywa chake huilinda nafsi yake; Bali afunuaye midomo yake atapata uharibifu."}, {"r": "1 Mambo ya Nyakati 22:13", "t": "Ndipo utakapofanikiwa, ukiangalia kuzitenda amri, na hukumu, Bwana alizomwagizia Musa juu ya Israeli; uwe hodari, na wa moyo mkuu; usiogope wala usifadhaike."}, {"r": "Mithali 2:11", "t": "Busara itakulinda; Ufahamu utakuhifadhi."}, {"r": "Isaya 14:32", "t": "Wajumbe wa taifa hilo waletewe jibu gani? Ya kuwa Bwana ameiweka misingi ya Sayuni, na ndani yake wale walioonewa katika watu wake wataona kimbilio."}, {"r": "Zaburi 37:39", "t": "Na wokovu wa wenye haki una Bwana; Yeye ni ngome yao wakati wa taabu."}, {"r": "Yoeli 3:16", "t": "Naye Bwana atanguruma toka Sayuni, atatoa sauti yake toka Yerusalemu; na mbingu na nchi zitatetemeka; lakini Bwana atakuwa kimbilio la watu wake, na ngome ya wana wa Israeli."}, {"r": "Zekaria 9:16", "t": "Na Bwana, Mungu wao, atawaokoa siku hiyo, Kama kundi la watu wake; Kwa maana watakuwa kama vito vya taji, Vikimetameta juu ya nchi yake."}, {"r": "Luka 9:56", "t": "Kwa maana Mwana wa Adamu hakuja kuziangamiza roho za watu, bali kuziokoa. Wakaondoka wakaenda mpaka kijiji kingine."}, {"r": "Yeremia 23:6", "t": "Katika siku zake Yuda ataokolewa, na Israeli atakaa salama, na jina lake atakaloitwa ni hili, Bwana ni haki yetu."}, {"r": "Isaya 32:18", "t": "Na watu wangu watakaa katika kao la amani; na katika maskani zilizo salama, na katika mahali pa kupumzikia penye utulivu."}, {"r": "Hesabu 20:10", "t": "Musa na Haruni wakawakusanya kusanyiko mbele ya mwamba, akawaambia, Sikieni sasa, enyi waasi; je! Tuwatokezee maji katika mwamba huu?"}, {"r": "Yeremia 17:5", "t": "Bwana asema hivi, Amelaaniwa mtu yule amtegemeaye mwanadamu, Amfanyaye mwanadamu kuwa kinga yake Na moyoni mwake amemwacha Bwana."}, {"r": "Mathayo 17:7", "t": "Yesu akaja, akawagusa, akasema, Inukeni, wala msiogope."}, {"r": "Habakuki 1:2", "t": "Ee Bwana, nilie hata lini, wewe usitake kusikia? Nakulilia kwa sababu ya udhalimu, ila hutaki kuokoa."}, {"r": "Isaya 13:22", "t": "Na mbwamwitu watalia ndani ya ngome zake; na mbweha ndani ya majumba ya anasa; na wakati wake u karibu kufika, na siku zake hazitaongezeka."}, {"r": "Luka 17:19", "t": "Akamwambia, Inuka, enenda zako, imani yako imekuokoa."}, {"r": "Mithali 12:6", "t": "Maneno ya waovu huotea damu; Bali kinywa cha wanyofu kitawaokoa."}, {"r": "Ayubu 21:32", "t": "Pamoja na hayo atachukuliwa kaburini, Nao watalinda zamu juu ya ziara lake."}, {"r": "Isaya 40:9", "t": "Wewe uuhubiriye Sayuni habari njema, Panda juu ya mlima mrefu; Wewe uuhubiriye Yerusalemu habari njema, Paza sauti kwa nguvu; Paza sauti yako, usiogope; Iambie miji ya Yuda, Tazameni, Mungu wenu."}, {"r": "Ayubu 24:23", "t": "Huwapa kuwa na salama, nao wapumzika kwayo; Na macho yake ya juu ya njia zao."}, {"r": "Zaburi 7:10", "t": "Ngao yangu ina Mungu, Awaokoaye wanyofu wa moyo."}, {"r": "Luka 8:6", "t": "Nyingine zikaanguka penye mwamba; zilipoanza kumea zikakauka kwa kukosa rutuba."}, {"r": "Waefeso 4:3", "t": "na kujitahidi kuuhifadhi umoja wa Roho katika kifungo cha amani."}, {"r": "Isaya 1:24", "t": "Kwa hiyo, asema Bwana, Bwana wa majeshi, Mwenye enzi, wa Israeli, Nitapata faraja kwa hao wanipingao, nitatwaa kisasi kwa adui zangu;"}, {"r": "Ayubu 28:9", "t": "Huunyoshea mwamba wa gumegume mkono wake; Huipindua milima hata misingi yake."}, {"r": "Zaburi 136:24", "t": "Akatuokoa na watesi wetu; Kwa maana fadhili zake ni za milele."}, {"r": "Yakobo 1:21", "t": "Kwa hiyo wekeeni mbali uchafu wote na ubaya uzidio, na kupokea kwa upole neno lile lililopandwa ndani, liwezalo kuziokoa roho zenu."}, {"r": "Yeremia 46:3", "t": "Tengenezeni kigao na ngao, mkakaribie ili kupigana."}, {"r": "Zaburi 34:18", "t": "Bwana yu karibu nao waliovunjika moyo, Na waliopondeka roho huwaokoa."}, {"r": "Zaburi 73:27", "t": "Maana wajitengao nawe watapotea; Umewaangamiza wote waliokuacha Wewe."}, {"r": "Luka 8:13", "t": "Na wale penye mwamba ndio wale ambao wasikiapo hulipokea lile neno kwa furaha; nao hawana mizizi, huamini kitambo kidogo, na wakati wa kujaribiwa hujitenga."}, {"r": "Mathayo 14:27", "t": "Mara Yesu alinena, akawaambia, Jipeni moyo ni mimi; msiogope."}, {"r": "Hesabu 3:32", "t": "Na Eleazari mwana wa Haruni kuhani atakuwa mkuu wa hao wakuu wa Walawi, naye atawasimamia hao walindao ulinzi wa mahali patakatifu."}, {"r": "Zaburi 127:1", "t": "Bwana asipoijenga nyumba Waijengao wafanya kazi bure. Bwana asipoulinda mji Yeye aulindaye akesha bure."}, {"r": "Zaburi 7:4", "t": "Ikiwa nimemlipa mabaya Yeye aliyekaa kwangu salama; (Hasha! Nimemponya yeye Aliyekuwa mtesi wangu bila sababu;)"}, {"r": "Isaya 29:3", "t": "Nami nitapiga kimo juu yako pande zote, nitakuhusuru kwa ngome, nami nitajenga maboma yakuzunguke."}, {"r": "Waamuzi 9:49", "t": "Basi watu hao wote vivyo wakakata kila mtu tawi lake, wakamwandama Abimeleki, wakayaweka hayo matawi pale ngomeni, na kuiteketeza moto hiyo ngome juu yao; basi hivyo watu wote wa hiyo buruji ya Shekemu wakafa, walipata kama watu elfu, waume kwa wake."}, {"r": "Isaya 23:11", "t": "Amenyosha mkono wake juu ya bahari, amezitikisa falme; Bwana ametoa amri katika habari za Kanaani, kuziangamiza ngome zake."}, {"r": "Yeremia 4:6", "t": "Twekeni bendera kuelekea Sayuni; kimbieni mpate kuwa salama, msikawie; kwa maana nitaleta mabaya toka kaskazini, na maangamivu makuu."}, {"r": "Luka 2:8", "t": "Na katika nchi ile ile walikuwako wachungaji wakikaa makondeni na kulinda kundi lao kwa zamu usiku."}, {"r": "Mathayo 18:11", "t": "[Kwa maana Mwana wa Adamu alikuja kukiokoa kilichopotea.]"}, {"r": "Zaburi 142:5", "t": "Bwana, nimekuita nikasema, Ndiwe kimbilio langu, Fungu langu katika nchi ya walio hai."}, {"r": "Yeremia 4:17", "t": "Kama watu walindao shamba, wameuzunguka wauhusuru; kwa sababu ameniasi mimi, asema Bwana."}, {"r": "Mathayo 7:24", "t": "Basi kila asikiaye hayo maneno yangu, na kuyafanya, atafananishwa na mtu mwenye akili, aliyejenga nyumba yake juu ya mwamba;"}, {"r": "2 Mambo ya Nyakati 9:15", "t": "Mfalme Sulemani akafanya ngao mia mbili za dhahabu iliyofuliwa; ngao moja hupata shekeli mia sita za dhahabu iliyofuliwa."}, {"r": "Zekaria 11:6", "t": "Maana mimi sitawahurumia tena wenyeji wa nchi hii, asema Bwana; bali, tazama, nitawatia, kila mmoja wao, mikononi mwa mwenzake, na mikononi mwa mfalme; nao wataipiga hiyo nchi, wala mimi sitawaokoa mikononi mwao."}, {"r": "Habakuki 1:10", "t": "Naam, huwadhihaki wafalme, na wakuu ni kitu cha kudharauliwa kwake; huidharau kila ngome; kwa maana hufanya chungu ya mavumbi, na kuitwaa."}, {"r": "Marko 14:44", "t": "Na yule anayemsaliti alikuwa amewapa ishara, akisema, Nitakayembusu, huyo ndiye; mkamateni, mkamchukue salama."}, {"r": "Wakolosai 1:13", "t": "Naye alituokoa katika nguvu za giza, akatuhamisha na kutuingiza katika ufalme wa Mwana wa pendo lake;"}, {"r": "Zaburi 109:19", "t": "Na iwe kwake kama vazi ajivikalo, Na kama mshipi ajifungao daima."}, {"r": "Zaburi 145:19", "t": "Atawafanyia wamchao matakwa yao, Naye atakisikia kilio chao na kuwaokoa."}, {"r": "Kumbukumbu la Torati 1:21", "t": "Tazama, Bwana, Mungu wako, ameiweka nchi mbele yako; haya panda, itamalaki, kama Bwana, Mungu wa baba zako, alivyokuambia; usiogope wala usifadhaike."}, {"r": "Matendo ya Mitume 23:32", "t": "hata asubuhi wakawaacha wale wapanda farasi waende pamoja naye, nao wakarudi zao ngomeni."}, {"r": "Yeremia 17:17", "t": "Usiwe sababu ya hofu kuu kwangu mimi; wewe ndiwe uliye kimbilio langu siku ya uovu."}, {"r": "Isaya 49:6", "t": "naam, asema hivi, Ni neno dogo sana wewe kuwa mtumishi wangu ili kuziinua kabila za Yakobo, na kuwarejeza watu wa Israeli waliohifadhiwa; zaidi ya hayo nitakutoa uwe nuru ya mataifa, upate kuwa wokovu wangu hata miisho ya dunia."}, {"r": "Luka 5:9", "t": "Maana alishikwa na ushangao, yeye na wote waliokuwa pamoja naye, kwa sababu ya wingi wa samaki walioupata;"}, {"r": "1 Mambo ya Nyakati 28:20", "t": "Kisha Daudi akamwambia Sulemani mwanawe, Uwe hodari, mwenye moyo mkuu, ukatende hivyo; usiogope wala usifadhaike; kwa kuwa Bwana, Mungu, Mungu wangu, yu pamoja nawe; yeye hatakupungukia wala kukuacha, hata itakapomalizika kazi yote ya huo utumishi wa nyumba ya Bwana."}, {"r": "Hesabu 18:3", "t": "Nao watashika ulinzi kwa amri yako, na ulinzi wa Hema yote; lakini wasikaribie vyombo vya patakatifu, wala madhabahu, wasife, wao pamoja na ninyi."}, {"r": "Amosi 2:15", "t": "Wala apindaye upinde hatasimama; Wala aliye mwepesi wa miguu hataokoka; Wala apandaye farasi hatajiokoa nafsi yake;"}, {"r": "Mithali 2:7", "t": "Huwawekea wanyofu akiba ya hekima kamili; Yeye ni ngao kwao waendao kwa ukamilifu;"}, {"r": "Isaya 28:17", "t": "Nami nitafanya hukumu kuwa ndiyo kanuni, na haki kuwa ndiyo timazi; na mvua ya mawe itachukulia mbali hilo kimbilio la maneno ya uongo, na maji yatapagharikisha mahali pa kujisitiri."}, {"r": "Ayubu 40:14", "t": "Ndipo mimi nami nitazikiri habari zako, Ya kuwa mkono wako wa kuume waweza kukuokoa."}, {"r": "1 Wakorintho 7:19", "t": "Kutahiriwa si kitu, na kutokutahiriwa si kitu bali kuzihifadhi amri za Mungu."}, {"r": "Matendo ya Mitume 23:16", "t": "Mjomba wake Paulo akasikia habari za kuotea kwao, akaenda akaingia ndani ya ngome akampasha Paulo habari."}, {"r": "Zaburi 14:6", "t": "Mnalitia aibu shauri la mtu mnyonge, Bali Bwana ndiye aliye kimbilio lake."}, {"r": "Mathayo 27:66", "t": "Wakaenda, wakalilinda kaburi salama, kwa kulitia lile jiwe muhuri, pamoja na wale askari walinzi."}, {"r": "1 Wathesalonike 5:3", "t": "Wakati wasemapo, Kuna amani na salama, ndipo uharibifu uwajiapo kwa ghafula, kama vile utungu umjiavyo mwenye mimba, wala hakika hawataokolewa."}, {"r": "Isaya 8:14", "t": "Naye atakuwa ni mahali patakatifu; bali ni jiwe la kujikwaza na mwamba wa kujikwaa kwa nyumba za Israeli zote mbili, na mtego na tanzi kwa wenyeji wa Yerusalemu."}, {"r": "Zaburi 146:9", "t": "Bwana huwahifadhi wageni; Huwategemeza yatima na mjane; Bali njia ya wasio haki huipotosha."}, {"r": "Mithali 4:4", "t": "Naye akanifundisha, akaniambia, Moyo wako uyahifadhi maneno yangu; Shika amri zangu ukaishi."}, {"r": "Isaya 38:17", "t": "Tazama; nalikuwa na uchungu mwingi kwa ajili ya amani yangu; Lakini kwa kunipenda umeniokoa na shimo la uharibifu; Kwa maana umezitupa dhambi zangu zote nyuma yako."}, {"r": "2 Mambo ya Nyakati 32:14", "t": "Ni yupi miongoni mwa miungu ya mataifa wale walioharibiwa kabisa na baba zangu, aliyeweza kuwaokoa watu wake na mkono wangu, hata Mungu wenu aweze kuwaokoa ninyi na mkono wangu?"}, {"r": "Zaburi 31:2", "t": "Unitegee sikio lako, uniokoe hima. Uwe kwangu mwamba wa nguvu, Nyumba yenye maboma ya kuniokoa."}, {"r": "Matendo ya Mitume 27:4", "t": "Kutoka huko tukatweka, tukasafiri chini ya Kipro ili kuukinga upepo, kwa maana pepo zilikuwa za mbisho."}, {"r": "Amosi 6:1", "t": "Ole wao wanaostarehe katika Sayuni, na hao wanaokaa salama katika mlima wa Samaria, watu mashuhuri wa taifa lililo la kwanza, ambao nyumba ya Israeli huwaendea."}, {"r": "Zaburi 59:16", "t": "Nami nitaziimba nguvu zako asubuhi, Nitaziimba fadhili zako kwa furaha. Kwa kuwa ndiwe uliyekuwa ngome yangu, Na makimbilio siku ya shida yangu."}, {"r": "1 Wathesalonike 1:10", "t": "na kumngojea Mwanawe kutoka mbinguni, ambaye alimfufua katika wafu, naye ni Yesu, mwenye kutuokoa na ghadhabu itakayokuja."}, {"r": "Isaya 10:24", "t": "Kwa hiyo Bwana, Bwana wa majeshi, asema hivi, Enyi watu wangu mkaao katika Sayuni, msiogope Ashuru, ingawa akupiga kwa fimbo, na kuliinua gongo lake juu yako, kwa namna ya Kimisri."}, {"r": "Yeremia 15:21", "t": "Nami nitakuokoa na mkono wa watu wabaya, nami nitakukomboa katika mkono wao wenye kutisha."}, {"r": "Isaya 46:4", "t": "na hata uzee wenu mimi ndiye, na hata wakati wenu wa mvi nitawachukueni; nimefanya, nami nitachukua; naam, nitachukua na kuokoa."}, {"r": "Waamuzi 18:7", "t": "Ndipo hao watu watano wakaenda zao, wakafika Laisha, wakawaona wale watu waliokuwamo ndani yake, jinsi walivyokaa salama salimini kwa mfano wa walivyokaa hao Wasidoni, wenye starehe na hifadhi, kwa maana hapakuwa na mtu katika nchi hiyo aliyekuwa na amri, aliyeweza kuwatweza katika neno lo lote, nao walikuwa wa mbali na hao Wasidoni, wala hawakuwa na shughuli na mtu ye yote."}, {"r": "Isaya 47:8", "t": "Sasa, basi, sikia haya, wewe upendaye anasa, ukaaye na kujiona salama, wewe usemaye moyoni mwako, Mimi ndiye, wala hapana mwingine zaidi yangu mimi; sitaketi mfano wa mjane, wala sitajua kufiwa na watoto;"}, {"r": "Waebrania 7:25", "t": "Naye, kwa sababu hii, aweza kuwaokoa kabisa wao wamjiao Mungu kwa yeye; maana yu hai sikuzote ili awaombee."}, {"r": "Yeremia 46:28", "t": "Usiogope wewe, Ee Yakobo, mtumishi wangu, asema Bwana; kwa maana mimi ni pamoja nawe; maana nitawakomesha kabisa mataifa yote huko nilikokufukuza, bali sitakukomesha wewe kabisa; lakini nitakurudi kwa hukumu, wala sitakuacha bila adhabu."}, {"r": "Zaburi 37:40", "t": "Naye Bwana huwasaidia na kuwaopoa; Huwaopoa na wasio haki na kuwaokoa; Kwa kuwa wamemtumaini Yeye."}, {"r": "Isaya 41:14", "t": "Usiogope, Yakobo uliye mdudu, nanyi watu wa Israeli; mimi nitakusaidia, asema Bwana, na mkombozi wako ni Mtakatifu wa Israeli."}, {"r": "1 Wafalme 10:16", "t": "Mfalme Sulemani akafanya ngao mia mbili za dhahabu iliyofuliwa; kila ngao moja ilipata shekeli mia sita za dhahabu."}, {"r": "Yeremia 46:27", "t": "Lakini usiogope wewe, Ee Yakobo, mtumishi wangu; wala usifadhaike, Ee Israeli; kwa maana, tazama, nitakuokoa toka mbali, na wazao wako toka nchi ya uhamisho wao; na Yakobo atarudi, naye atatulia na kustarehe, wala hapana mtu atakayemtia hofu."}, {"r": "Matendo ya Mitume 23:10", "t": "Ugomvi mkubwa ulipotokea, yule jemadari akachelea Paulo asije akararuliwa nao, akaamuru askari washuke na kumwondoa kwa nguvu mikononi mwao, na kumleta ndani ya ngome."}, {"r": "Zaburi 47:9", "t": "Wakuu wa watu wamekusanyika, Wawe watu wa Mungu wa Ibrahimu. Maana ngao za dunia zina Mungu, Ametukuka sana."}, {"r": "Wakolosai 2:14", "t": "akiisha kuifuta ile hati iliyoandikwa ya kutushitaki kwa hukumu zake, iliyokuwa na uadui kwetu; akaiondoa isiwepo tena, akaigongomea msalabani;"}, {"r": "Zaburi 91:3", "t": "Maana Yeye atakuokoa na mtego wa mwindaji, Na katika tauni iharibuyo."}, {"r": "Isaya 36:19", "t": "Wako wapi miungu ya Hamathi na ya Arpadi? Wako wapi miungu ya Sefarvaimu? Je! Wameiokoa Samaria na mkono wangu?"}, {"r": "Isaya 36:18", "t": "Jihadharini, asije Hezekia akawadanganya, akisema, Bwana atatuokoa. Je! Yuko mungu mmoja wa mataifa aliyewaokoa watu wake na mkono wa mfalme wa Ashuru?"}, {"r": "Mithali 3:23", "t": "Ndipo utakapokwenda katika njia yako salama, Wala mguu wako hautakwaa."}, {"r": "Mathayo 27:64", "t": "Basi amuru kwamba kaburi lilindwe salama hata siku ya tatu; wasije wanafunzi wake wakamwiba, na kuwaambia watu, Amefufuka katika wafu; na udanganyifu wa mwisho utapita ule wa kwanza."}, {"r": "Zaburi 78:53", "t": "Hao akawachukua salama wala hawakuogopa, Bali bahari iliwafunikiza adui zao."}, {"r": "Yeremia 14:9", "t": "Kwa nini wewe umekuwa kama mtu aliyesituka, kama shujaa asiyeweza kuokoa? Lakini wewe, Bwana, u katikati yetu, nasi tunaitwa kwa jina lako; usituache."}, {"r": "1 Samueli 12:11", "t": "Bwana akawatuma Yerubaali, na Baraka, na Yeftha, na Samweli, akawaokoa ninyi na mikono ya adui zenu pande zote, nanyi mkakaa salama."}, {"r": "Matendo ya Mitume 27:44", "t": "nao waliosalia, hawa juu ya mbao na hawa juu ya vitu vingine vya merikebu. Na hivyo watu wote wakapata kuifikilia nchi kavu salama."}, {"r": "Ayubu 21:23", "t": "Mmoja hufa katika nguvu zake kamili, Mwenye kukaa salama na kustarehe;"}, {"r": "2 Wakorintho 11:32", "t": "Huko Dameski liwali wa mfalme Areta alikuwa akiulinda mji wa Wadameski, ili kunikamata;"}, {"r": "Zaburi 121:3", "t": "Asiuache mguu wako usogezwe; Asisinzie akulindaye;"}, {"r": "Zaburi 94:22", "t": "Lakini Bwana amekuwa ngome kwangu, Na Mungu wangu mwamba wangu wa kukimbilia."}, {"r": "Isaya 8:12", "t": "Msiseme, Ni fitina, katika habari za mambo yote ambayo watu hawa watasema, Ni fitina; msihofu kwa hofu yao, wala msiogope."}, {"r": "Zekaria 8:13", "t": "Kisha itakuwa, kama vile mlivyokuwa laana katika mataifa, Ee nyumba ya Yuda, na nyumba ya Israeli, ndivyo nitakavyowaokoa, nanyi mtakuwa baraka; msiogope, lakini mikono yenu na iwe hodari."}, {"r": "Yeremia 1:17", "t": "Haya basi, wewe jifunge viuno, ukaondoke ukawaambie maneno yote niliyokuamuru; usifadhaike kwa ajili yao, nisije nikakufadhaisha wewe mbele yao."}, {"r": "Isaya 31:5", "t": "Kama ndege warukao, Bwana wa majeshi ataulinda Yerusalemu; ataulinda na kuuokoa, atapita juu yake na kuuhifadhi."}, {"r": "Yeremia 6:1", "t": "Kimbieni mpate kuwa salama, enyi wana wa Benyamini; tokeni katika Yerusalemu, pigeni tarumbeta katika Tekoa, simamisheni ishara juu ya Bethhakeremu; kwa maana mabaya yanachungulia toka kaskazini, na uharibifu mkuu."}, {"r": "Isaya 14:30", "t": "Nao walio maskini kabisa watakula, Na wahitaji watajilaza salama; Nami nitatia shina lako kwa njaa, Na mabaki yako watauawa."}, {"r": "Zaburi 33:20", "t": "Nafsi zetu zinamngoja Bwana; Yeye ndiye msaada wetu na ngao yetu."}, {"r": "Yeremia 8:21", "t": "Kwa sababu ya maumivu ya binti ya watu wangu nimeumia mimi; nimevaa kaniki; ushangao umenishika."}, {"r": "Isaya 21:8", "t": "Ndipo akalia kama simba, Ee Bwana, mimi nasimama daima juu ya mnara wakati wa mchana, na kila usiku ninakaa katika zamu ya ulinzi wangu."}, {"r": "Zaburi 76:9", "t": "Mungu aliposimama ili kuhukumu Na kuwaokoa wapole wa dunia wote pia."}, {"r": "Zaburi 137:9", "t": "Heri yeye atakayewakamata wadogo wako, Na kuwaseta wao juu ya mwamba."}, {"r": "Warumi 1:18", "t": "Kwa maana ghadhabu ya Mungu imedhihirishwa kutoka mbinguni juu ya uasi wote na uovu wa wanadamu waipingao kweli kwa uovu."}, {"r": "Hosea 13:10", "t": "Yuko wapi sasa mfalme wako, apate kukuokoa katika miji yako yote? Na hao waamuzi wako, uliowanena hivi, Nipe mfalme na wakuu?"}, {"r": "Zaburi 5:12", "t": "Kwa maana Wewe utambariki mwenye haki; Bwana, utamzungushia radhi kama ngao."}, {"r": "Mithali 6:22", "t": "Uendapo yatakuongoza, ulalapo yatakulinda, Na uamkapo yatazungumza nawe."}, {"r": "Matendo ya Mitume 21:37", "t": "Naye alipokuwa analetwa ndani ya ngome, Paulo akamwambia jemadari, Nina ruhusa nikuambie neno? Naye akasema, Je! Unajua Kiyunani?"}, {"r": "Yohana 12:15", "t": "Usiogope, binti Sayuni; tazama, Mfalme wako anakuja, amepanda mwanapunda."}, {"r": "Zaburi 17:7", "t": "Dhihirisha fadhili zako za ajabu Wewe uwaokoaye wanaokukimbilia; Kwa mkono wako wa kuume Uwaokoe nao wanaowaondokea."}, {"r": "Mithali 3:25", "t": "Usiogope hofu ya ghafula, Wala uharibifu wa waovu utakapofika."}, {"r": "Isaya 23:4", "t": "Tahayari, Ee Sidoni; kwa maana bahari imenena, hiyo ngome ya bahari ilisema, Sikuona utungu, wala sikuzaa, wala sikulea vijana, wala sikulea wanawali."}, {"r": "Isaya 48:21", "t": "Wala hawakuona kiu alipowaongoza jangwani; Alitoa maji katika mwamba kwa ajili yao; Pia akaupasua mwamba, maji yakatoka kwa nguvu."}, {"r": "Isaya 36:15", "t": "wala msimwache Hezekia kuwatia moyo wa kumtumaini Bwana; akisema, Bwana bila shaka atatuokoa, mji huu hautatiwa katika mkono wa mfalme wa Ashuru."}, {"r": "Ayubu 13:12", "t": "Matamko yenu ya hekima ni mithali ya majivu, Ngome zenu ni ngome za udongo."}, {"r": "Ayubu 36:6", "t": "Hauhifadhi uhai wa waovu; Lakini huwapa wateswao haki yao."}, {"r": "Mithali 4:21", "t": "Zisiondoke machoni pako; Uzihifadhi ndani ya moyo wako."}, {"r": "Marko 5:42", "t": "Mara akasimama yule kijana, akaenda; maana alikuwa amepata umri wa miaka kumi na miwili. Mara wakashangaa mshangao mkuu."}, {"r": "Zaburi 18:17", "t": "Akaniokoa na adui yangu mwenye nguvu, Na wale walionichukia, Maana walikuwa na nguvu kuliko mimi."}, {"r": "Ufunuo wa Yohana 18:2", "t": "Akalia kwa sauti kuu, akisema, Umeanguka, umeanguka Babeli ule mkuu; umekuwa maskani ya mashetani, na ngome ya kila roho mchafu, na ngome ya kila ndege mchafu mwenye kuchukiza;"}, {"r": "Ezekieli 14:20", "t": "wajapokuwamo ndani yake Nuhu, na Danieli, na Ayubu, kama mimi niishivyo, asema Bwana MUNGU, hawataokoa wana wala binti; watajiokoa nafsi zao tu kwa haki yao."}, {"r": "Zaburi 34:20", "t": "Huihifadhi mifupa yake yote, Haukuvunjika hata mmoja."}, {"r": "Ayubu 5:19", "t": "Yeye atakuokoa na mateso sita; Naam, hata katika saba hapana uovu utakaokugusa."}, {"r": "Yeremia 52:4", "t": "Ikawa, katika mwaka wa kenda wa kumiliki kwake, katika mwezi wa kumi, na siku ya kumi ya mwezi huo, Nebukadreza, mfalme wa Babeli, akaja, yeye na jeshi lake lote, juu ya Yerusalemu, akapanga hema zake juu yake; nao wakajenga ngome juu yake pande zote."}, {"r": "Matendo ya Mitume 21:34", "t": "Wengine katika makutano wakapiga kelele wakisema hivi, na wengine hivi. Basi alipokuwa hawezi kupata hakika ya habari kwa sababu ya zile kelele, akatoa amri aletwe ndani ya ngome."}, {"r": "Isaya 36:14", "t": "Mfalme asema hivi; Hezekia asiwadanganye, kwa maana hataweza kuwaokoa;"}, {"r": "Mithali 3:29", "t": "Usiwaze mabaya juu ya jirani yako, Ambaye anakaa karibu nawe na kujiona salama."}, {"r": "Isaya 35:4", "t": "Waambieni walio na moyo wa hofu, Jipeni moyo, msiogope; tazama, Mungu wenu atakuja na kisasi, na malipo ya Mungu; atakuja na kuwaokoa ninyi."}, {"r": "1 Mambo ya Nyakati 26:16", "t": "Ya Shupimu na Hosa upande wa magharibi, langoni pa Shalekethi, hapo penye daraja ya kupandia, ulinzi kwa ulinzi."}, {"r": "Mhubiri 9:15", "t": "Basi, kulionekana humo mtu maskini mwenye hekima, naye kwa hekima yake akauokoa mji ule lakini hata hivyo hapakuwa na mtu ye yote aliyemkumbuka yule mtu maskini."}, {"r": "Isaya 31:9", "t": "Na mwamba wake utatoweka kwa sababu ya hofu, nao wakuu wake wataionea bendera hofu kuu, asema Bwana, ambaye moto wake u katika Sayuni, na tanuru yake katika Yerusalemu."}, {"r": "Zaburi 142:4", "t": "Utazame mkono wa kuume ukaone, Kwa maana sina mtu anijuaye. Makimbilio yamenipotea, Hakuna wa kunitunza roho."}, {"r": "1 Wakorintho 16:9", "t": "kwa maana nimefunguliwa mlango mkubwa wa kufaa sana, na wako wengi wanipingao."}, {"r": "Isaya 59:1", "t": "Tazama, mkono wa Bwana haukupunguka, hata usiweze kuokoa wala sikio lake si zito, hata lisiweze kusikia;"}, {"r": "Maombolezo 4:17", "t": "Macho yetu yamechoka Kwa kuutazamia bure msaada wetu; Katika kungoja kwetu tumengojea taifa Lisiloweza kutuokoa."}, {"r": "1 Samueli 17:37", "t": "Daudi akasema, Bwana aliyeniokoa na makucha ya simba, na makucha ya dubu, ataniokoa na mkono wa Mfilisti huyu. Sauli akamwambia Daudi, Enenda, na Bwana atakuwa pamoja nawe."}, {"r": "Zaburi 12:5", "t": "Kwa ajili ya kuonewa kwao wanyonge, Kwa ajili ya kuugua kwao wahitaji, Sasa nitasimama, asema Bwana, Nitamweka salama yeye wanayemfyonya."}, {"r": "Isaya 41:3", "t": "Awafuatia, apita salama hata kwa njia asiyoikanyaga kamwe kwa miguu yake."}, {"r": "2 Samueli 8:14", "t": "Akaweka askari wenye kulinda ngome katika Edomu; katikati ya Edomu yote akaweka ngome, na Waedomi wote wakawa watumwa wa Daudi. Naye Bwana akampa Daudi kushinda kila alikokwenda."}, {"r": "Ezekieli 28:26", "t": "Nao watakaa humo salama; naam, watajenga nyumba, na kupanda mashamba ya mizabibu, na kukaa salama; nitakapokuwa nimetekeleza hukumu zangu juu ya watu wote, wanaowatenda mambo ya jeuri pande zote; nao watajua ya kuwa mimi ndimi Bwana, Mungu wao."}, {"r": "Zaburi 102:3", "t": "Maana siku zangu zinatoweka kama moshi, Na mifupa yangu inateketea kama kinga."}, {"r": "Zaburi 18:30", "t": "Mungu, njia yake ni kamilifu, Ahadi ya Bwana imehakikishwa, Yeye ndiye ngao yao. Wote wanaomkimbilia."}, {"r": "Zaburi 18:35", "t": "Nawe umenipa ngao ya wokovu wako, Mkono wako wa kuume umenitegemeza, Na unyenyekevu wako umenikuza."}, {"r": "2 Mambo ya Nyakati 32:17", "t": "Tena akaandika waraka, kumtukana Bwana, Mungu wa Israeli, na kumwambia, akisema, Kama vile miungu ya mataifa wa nchi isivyowaokoa watu wao na mkono wangu, vivyo hivyo Mungu wa Hezekia hatawaokoa watu wake na mkono wangu."}, {"r": "Zaburi 72:13", "t": "Atamhurumia aliye dhaifu na maskini, Na nafsi za wahitaji ataziokoa."}, {"r": "1 Wakorintho 10:4", "t": "wote wakanywa kinywaji kile kile cha roho; kwa maana waliunywea mwamba wa roho uliowafuata; na mwamba ule ulikuwa ni Kristo."}, {"r": "Mithali 11:6", "t": "Haki yao wenye haki itawaokoa; Bali wafanyao fitina watanaswa kwa hila yao wenyewe."}, {"r": "Zaburi 115:9", "t": "Enyi Israeli, mtumainini Bwana; Yeye ni msaada wao na ngao yao."}, {"r": "Isaya 25:4", "t": "Maana umekuwa ngome ya maskini, Ngome ya mhitaji katika dhiki yake, Mahali pa kukimbilia wakati wa tufani, Kivuli wakati wa hari; Wakati uvumapo upepo wa watu watishao, Kama dhoruba ipigayo ukuta."}, {"r": "Warumi 11:14", "t": "nipate kuwatia wivu walio damu moja na mimi na kuwaokoa baadhi yao."}, {"r": "Hosea 12:13", "t": "Na kwa nabii Bwana alimtoa Israeli katika Misri, Na kwa mkono wa nabii alihifadhiwa."}]};
